-- ============================================================================
-- HUNTER — SCRIPT UNIFICADO PARA EXECUÇÃO NO SQL EDITOR DO SUPABASE
-- ============================================================================
-- Versão: 1.7.0.7
-- Este script aplica todas as atualizações de infraestrutura pendentes:
-- 1. Adiciona o valor 'instalador' ao enum hunter_role
-- 2. Garante colunas de endereço, chave pix e repasse em profiles
-- 3. Garante colunas de agendamento e instalador em clientes
-- 4. Garante tabela de instalações técnicas e políticas RLS
-- 5. Atualiza o trigger handle_new_user com suporte ao GoTrue auth.identities
-- 6. Atualiza as RPCs administrativas completas
-- 7. Executa o BACKFILL de identidades para destravar o login de clientes
-- ============================================================================

-- 1. ADICIONAR VALORES AO ENUM hunter_role (DEVE RODAR FORA DE BLOCO DO)
ALTER TYPE public.hunter_role ADD VALUE IF NOT EXISTS 'instalador';
ALTER TYPE public.hunter_role ADD VALUE IF NOT EXISTS 'revendedor';
ALTER TYPE public.hunter_role ADD VALUE IF NOT EXISTS 'vendedor';

-- 2. COLUNAS TÉCNICAS EM PUBLIC.PROFILES
DO $$ BEGIN
  ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS valor_por_instalacao NUMERIC(10,2) DEFAULT 0.00;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS chave_pix TEXT;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS endereco_instalacao TEXT;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

-- 3. COLUNAS TÉCNICAS EM PUBLIC.CLIENTES
DO $$ BEGIN
  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS instalador_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS data_agendamento DATE;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS hora_agendamento TEXT;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS status_agendamento TEXT DEFAULT 'aguardando_agendamento';
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

CREATE INDEX IF NOT EXISTS idx_clientes_instalador ON public.clientes(instalador_id);
CREATE INDEX IF NOT EXISTS idx_clientes_agendamento ON public.clientes(status_agendamento);

-- 4. TABELA DE INSTALAÇÕES TÉCNICAS
CREATE TABLE IF NOT EXISTS public.instalacoes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  instalador_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE RESTRICT,
  veiculo_id UUID REFERENCES public.veiculos(id) ON DELETE SET NULL,
  placa TEXT NOT NULL,
  marca TEXT NOT NULL,
  modelo TEXT NOT NULL,
  ano INT,
  cor TEXT,
  km_instalacao INT NOT NULL DEFAULT 0,
  rastreador_imei TEXT NOT NULL,
  rastreador_modelo TEXT DEFAULT 'J16 4G',
  chip_iccid TEXT,
  chip_operadora TEXT,
  posicao_instalacao TEXT,
  status TEXT NOT NULL DEFAULT 'nao_instalado' CHECK (status IN ('nao_instalado', 'concluida_com_pendencia', 'concluida')),
  motivo_pendencia_recusa TEXT,
  observacoes TEXT,
  valor_instalacao NUMERIC(10,2) NOT NULL DEFAULT 0.00,
  status_pagamento TEXT NOT NULL DEFAULT 'pendente' CHECK (status_pagamento IN ('pendente', 'pago')),
  pago_em TIMESTAMPTZ,
  pago_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  comprovante_pagamento TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  concluida_at TIMESTAMPTZ
);

ALTER TABLE public.instalacoes ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  CREATE POLICY "SuperAdmin e Admins gerenciam instalacoes" ON public.instalacoes
    FOR ALL TO authenticated
    USING (public.is_adm())
    WITH CHECK (public.is_adm());
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE POLICY "Instaladores acessam estritamente suas proprias instalacoes" ON public.instalacoes
    FOR ALL TO authenticated
    USING (instalador_id = auth.uid())
    WITH CHECK (instalador_id = auth.uid());
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- 5. TRIGGER HANDLE_NEW_USER COM AUTH.IDENTITIES (GOTRUE V2)
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_role_str TEXT;
  v_role public.hunter_role;
  v_nome TEXT;
BEGIN
  IF LOWER(NEW.email) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br') THEN
    v_role := 'superadmin'::public.hunter_role;
    v_nome := COALESCE(NEW.raw_user_meta_data->>'nome', 'SuperADM');
  ELSE
    v_role_str := COALESCE(NEW.raw_user_meta_data->>'role', 'cliente');
    BEGIN
      v_role := v_role_str::public.hunter_role;
    EXCEPTION WHEN OTHERS THEN
      v_role := 'cliente'::public.hunter_role;
    END;
    v_nome := COALESCE(NEW.raw_user_meta_data->>'nome', split_part(NEW.email, '@', 1));
  END IF;

  INSERT INTO public.profiles (id, nome, email, role, ativo)
  VALUES (NEW.id, v_nome, LOWER(NEW.email), v_role, TRUE)
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      email = EXCLUDED.email,
      role = CASE 
        WHEN LOWER(EXCLUDED.email) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br') THEN 'superadmin'::public.hunter_role 
        ELSE EXCLUDED.role 
      END;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, v_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  -- GoTrue auth.identities
  IF NOT EXISTS (
    SELECT 1 FROM auth.identities 
    WHERE (provider = 'email' AND provider_id = NEW.id::text)
       OR user_id = NEW.id
  ) THEN
    BEGIN
      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id,
        last_sign_in_at, created_at, updated_at
      ) VALUES (
        NEW.id::text, NEW.id,
        jsonb_build_object('sub', NEW.id::text, 'email', LOWER(NEW.email)),
        'email', NEW.id::text,
        now(), now(), now()
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  ELSE
    BEGIN
      UPDATE auth.identities
      SET identity_data = jsonb_build_object('sub', NEW.id::text, 'email', LOWER(NEW.email)),
          updated_at = now()
      WHERE user_id = NEW.id AND provider = 'email';
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

