DROP FUNCTION IF EXISTS public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[]);
DROP FUNCTION IF EXISTS public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[], NUMERIC, TEXT, TEXT);

-- 7. RPC ADMIN_CADASTRAR_USUARIO
CREATE OR REPLACE FUNCTION public.admin_cadastrar_usuario(
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_role public.hunter_role,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_novo_user_id UUID;
  v_mod TEXT;
  v_email_limpo TEXT := LOWER(trim(p_email));
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem criar novos usuarios.';
  END IF;

  IF v_email_limpo IS NULL OR v_email_limpo = '' THEN
    RAISE EXCEPTION 'O e-mail e obrigatorio.';
  END IF;

  IF p_senha IS NULL OR length(p_senha) < 6 THEN
    RAISE EXCEPTION 'A senha deve conter no minimo 6 caracteres.';
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_limpo) THEN
    RAISE EXCEPTION 'Ja existe um usuario cadastrado com este e-mail.';
  END IF;

  v_novo_user_id := gen_random_uuid();

  INSERT INTO auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, recovery_sent_at, last_sign_in_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token
  ) VALUES (
    v_novo_user_id,
    '00000000-0000-0000-0000-000000000000',
    'authenticated',
    'authenticated',
    v_email_limpo,
    extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
    now(), now(), now(),
    '{"provider":"email","providers":["email"]}',
    jsonb_build_object('nome', trim(p_nome), 'role', p_role),
    now(), now(),
    '', '', '', ''
  );

  -- auth.identities
  IF NOT EXISTS (
    SELECT 1 FROM auth.identities 
    WHERE (provider = 'email' AND provider_id = v_novo_user_id::text)
       OR user_id = v_novo_user_id
  ) THEN
    BEGIN
      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id,
        last_sign_in_at, created_at, updated_at
      ) VALUES (
        v_novo_user_id::text, v_novo_user_id,
        jsonb_build_object('sub', v_novo_user_id::text, 'email', v_email_limpo),
        'email', v_novo_user_id::text,
        now(), now(), now()
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  INSERT INTO public.profiles (id, nome, email, role, valor_por_instalacao, chave_pix, endereco_instalacao, ativo)
  VALUES (v_novo_user_id, trim(p_nome), v_email_limpo, p_role, p_valor_por_instalacao, p_chave_pix, p_endereco_instalacao, TRUE)
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      role = EXCLUDED.role,
      valor_por_instalacao = EXCLUDED.valor_por_instalacao,
      chave_pix = EXCLUDED.chave_pix,
      endereco_instalacao = EXCLUDED.endereco_instalacao,
      ativo = TRUE,
      updated_at = now();

  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_novo_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  IF p_role = 'instalador' THEN
    p_modulos := ARRAY['instalacao'];
  END IF;

  IF p_modulos IS NOT NULL THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_novo_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Usuario criado com sucesso.',
    'user_id', v_novo_user_id
  );
END;
$$;

-- 8. RPC ADMIN_ATUALIZAR_USUARIO
CREATE OR REPLACE FUNCTION public.admin_atualizar_usuario(
  p_usuario_id UUID,
  p_nome TEXT,
  p_role public.hunter_role,
  p_ativo BOOLEAN,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_mod TEXT;
  v_email_atual TEXT;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar usuarios.';
  END IF;

  IF p_usuario_id = '00000000-0000-0000-0000-000000000001'::UUID THEN
    RAISE EXCEPTION 'A conta SuperAdmin Mestre e imutavel e protegida por seguranca cibernetica.';
  END IF;

  SELECT email INTO v_email_atual FROM auth.users WHERE id = p_usuario_id;
  IF LOWER(v_email_atual) = 'novaes@adm.28bpm.local' THEN
    RAISE EXCEPTION 'A conta novaes@adm.28bpm.local e blindada contra rebaixamento ou alteracao.';
  END IF;

  UPDATE public.profiles
  SET nome = trim(p_nome),
      role = p_role,
      ativo = p_ativo,
      valor_por_instalacao = p_valor_por_instalacao,
      chave_pix = p_chave_pix,
      endereco_instalacao = p_endereco_instalacao,
      updated_at = now()
  WHERE id = p_usuario_id;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (p_usuario_id, p_role)
  ON CONFLICT (user_id, role) DO UPDATE SET role = EXCLUDED.role;

  UPDATE auth.users
  SET raw_user_meta_data = jsonb_build_object('nome', trim(p_nome), 'role', p_role),
      email_confirmed_at = COALESCE(email_confirmed_at, now()),
      updated_at = now()
  WHERE id = p_usuario_id;

  IF NOT EXISTS (
    SELECT 1 FROM auth.identities 
    WHERE (provider = 'email' AND provider_id = p_usuario_id::text)
       OR user_id = p_usuario_id
  ) THEN
    BEGIN
      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id,
        last_sign_in_at, created_at, updated_at
      ) VALUES (
        p_usuario_id::text, p_usuario_id,
        jsonb_build_object('sub', p_usuario_id::text, 'email', LOWER(v_email_atual)),
        'email', p_usuario_id::text,
        now(), now(), now()
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  IF p_role = 'instalador' THEN
    p_modulos := ARRAY['instalacao'];
  END IF;

  UPDATE public.user_module_access
  SET ativo = FALSE
  WHERE user_id = p_usuario_id;

  IF p_modulos IS NOT NULL THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (p_usuario_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Usuario atualizado com sucesso.'
  );
END;
$$;

-- 9. RPC ADMIN_CADASTRAR_CLIENTE_COMPLETO
CREATE OR REPLACE FUNCTION public.admin_cadastrar_cliente_completo(
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_criar_usuario BOOLEAN DEFAULT TRUE,
  p_senha TEXT DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca_modelo TEXT DEFAULT NULL,
  p_km_inicial INT DEFAULT 0,
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID := NULL;
  v_cliente_id UUID;
  v_mod TEXT;
  v_modulos TEXT[];
  v_email_limpo TEXT := LOWER(trim(p_email));
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  IF p_criar_usuario THEN
    IF v_email_limpo IS NULL OR v_email_limpo = '' THEN
      RAISE EXCEPTION 'O e-mail e obrigatorio para liberar acesso ao sistema.';
    END IF;

    IF p_senha IS NULL OR length(p_senha) < 6 THEN
      RAISE EXCEPTION 'A senha inicial de acesso deve conter no minimo 6 caracteres.';
    END IF;

    IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_limpo) THEN
      RAISE EXCEPTION 'Ja existe um usuario cadastrado no sistema com este e-mail.';
    END IF;

    v_user_id := gen_random_uuid();

    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, recovery_sent_at, last_sign_in_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, email_change, email_change_token_new, recovery_token
    ) VALUES (
      v_user_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      v_email_limpo,
      extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}',
      jsonb_build_object('nome', trim(p_nome), 'role', 'cliente'),
      now(), now(),
      '', '', '', ''
    );

    IF NOT EXISTS (
      SELECT 1 FROM auth.identities 
      WHERE (provider = 'email' AND provider_id = v_user_id::text)
         OR user_id = v_user_id
    ) THEN
      BEGIN
        INSERT INTO auth.identities (
          id, user_id, identity_data, provider, provider_id,
          last_sign_in_at, created_at, updated_at
        ) VALUES (
          v_user_id::text, v_user_id,
          jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
          'email', v_user_id::text,
          now(), now(), now()
        );
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END IF;

    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (v_user_id, trim(p_nome), v_email_limpo, 'cliente', TRUE)
    ON CONFLICT (id) DO UPDATE
    SET nome = EXCLUDED.nome,
        email = EXCLUDED.email,
        role = 'cliente',
        ativo = TRUE,
        updated_at = now();

    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, 'cliente')
    ON CONFLICT (user_id, role) DO NOTHING;

    IF p_plano = 'basico' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades'];
    ELSIF p_plano = 'pro' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    ELSE
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao', 'central-seguranca'];
    END IF;

    FOREACH v_mod IN ARRAY v_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  v_cliente_id := gen_random_uuid();
  INSERT INTO public.clientes (
    id, user_id, instalador_id, nome_razao_social, documento, email, telefone,
    plano, status, status_agendamento, dia_vencimento, valor_mensalidade,
    dias_historico_plano, dias_retencao_banco, created_at, updated_at
  ) VALUES (
    v_cliente_id, v_user_id, p_instalador_id, trim(p_nome),
    NULLIF(trim(p_documento), ''), NULLIF(v_email_limpo, ''), NULLIF(trim(p_telefone), ''),
    p_plano, 'aguardando_instalacao', 'aguardando_agendamento',
    COALESCE(p_dia_vencimento, 10), COALESCE(p_valor_mensalidade, 79.90),
    COALESCE(p_dias_historico, 7), COALESCE(p_dias_retencao, 10),
    now(), now()
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Cliente cadastrado com sucesso. Status: aguardando instalacao.',
    'cliente_id', v_cliente_id,
    'user_id', v_user_id,
    'instalador_id', p_instalador_id
  );
END;
$$;

-- 10. RPC ADMIN_ATUALIZAR_CLIENTE_COMPLETO
CREATE OR REPLACE FUNCTION public.admin_atualizar_cliente_completo(
  p_cliente_id UUID,
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_status public.status_cliente DEFAULT 'ativo',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_senha TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID;
  v_email_antigo TEXT;
  v_mod TEXT;
  v_modulos TEXT[];
  v_email_limpo TEXT := LOWER(trim(p_email));
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  IF p_cliente_id IS NULL THEN
    RAISE EXCEPTION 'ID do cliente e obrigatorio.';
  END IF;

  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  SELECT user_id, email INTO v_user_id, v_email_antigo
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  IF v_user_id IS NULL AND v_email_limpo IS NOT NULL AND v_email_limpo <> '' AND p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
    SELECT id INTO v_user_id FROM auth.users WHERE LOWER(email) = v_email_limpo;

    IF v_user_id IS NULL THEN
      v_user_id := gen_random_uuid();
      INSERT INTO auth.users (
        id, instance_id, aud, role, email, encrypted_password,
        email_confirmed_at, recovery_sent_at, last_sign_in_at,
        raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
        confirmation_token, email_change, email_change_token_new, recovery_token
      ) VALUES (
        v_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
        v_email_limpo, extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
        now(), now(), now(),
        '{"provider":"email","providers":["email"]}',
        jsonb_build_object('nome', trim(p_nome), 'role', 'cliente'),
        now(), now(), '', '', '', ''
      );

      IF NOT EXISTS (
        SELECT 1 FROM auth.identities 
        WHERE (provider = 'email' AND provider_id = v_user_id::text)
           OR user_id = v_user_id
      ) THEN
        BEGIN
          INSERT INTO auth.identities (
            id, user_id, identity_data, provider, provider_id,
            last_sign_in_at, created_at, updated_at
          ) VALUES (
            v_user_id::text, v_user_id,
            jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
            'email', v_user_id::text,
            now(), now(), now()
          );
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      END IF;
    ELSE
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          email_confirmed_at = COALESCE(email_confirmed_at, now()),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.identities
      SET identity_data = jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
          updated_at = now()
      WHERE user_id = v_user_id AND provider = 'email';
    END IF;

    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (v_user_id, trim(p_nome), v_email_limpo, 'cliente', (p_status = 'ativo' OR p_status = 'aguardando_instalacao'))
    ON CONFLICT (id) DO UPDATE
    SET nome = EXCLUDED.nome,
        email = EXCLUDED.email,
        role = 'cliente',
        ativo = EXCLUDED.ativo,
        updated_at = now();

    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, 'cliente')
    ON CONFLICT (user_id, role) DO NOTHING;

  ELSIF v_user_id IS NOT NULL THEN
    IF v_email_limpo IS NOT NULL AND v_email_limpo <> '' THEN
      UPDATE auth.users
      SET email = v_email_limpo,
          raw_user_meta_data = jsonb_build_object('nome', trim(p_nome), 'role', 'cliente'),
          email_confirmed_at = COALESCE(email_confirmed_at, now()),
          updated_at = now()
      WHERE id = v_user_id;

      IF NOT EXISTS (
        SELECT 1 FROM auth.identities 
        WHERE (provider = 'email' AND provider_id = v_user_id::text)
           OR user_id = v_user_id
      ) THEN
        BEGIN
          INSERT INTO auth.identities (
            id, user_id, identity_data, provider, provider_id,
            last_sign_in_at, created_at, updated_at
          ) VALUES (
            v_user_id::text, v_user_id,
            jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
            'email', v_user_id::text,
            now(), now(), now()
          );
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      ELSE
        UPDATE auth.identities
        SET identity_data = jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
            updated_at = now()
        WHERE user_id = v_user_id AND provider = 'email';
      END IF;
    END IF;

    IF p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          email_confirmed_at = COALESCE(email_confirmed_at, now()),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    UPDATE public.profiles
    SET nome = trim(p_nome),
        email = COALESCE(NULLIF(v_email_limpo, ''), email),
        ativo = (p_status = 'ativo' OR p_status = 'aguardando_instalacao'),
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  UPDATE public.clientes
  SET user_id = COALESCE(v_user_id, user_id),
      instalador_id = p_instalador_id,
      nome_razao_social = trim(p_nome),
      documento = NULLIF(trim(p_documento), ''),
      email = NULLIF(v_email_limpo, ''),
      telefone = NULLIF(trim(p_telefone), ''),
      plano = p_plano,
      status = p_status,
      dia_vencimento = COALESCE(p_dia_vencimento, dia_vencimento),
      valor_mensalidade = COALESCE(p_valor_mensalidade, valor_mensalidade),
      dias_historico_plano = COALESCE(p_dias_historico, dias_historico_plano),
      dias_retencao_banco = COALESCE(p_dias_retencao, dias_retencao_banco),
      updated_at = now()
  WHERE id = p_cliente_id;

  IF v_user_id IS NOT NULL THEN
    IF p_plano = 'basico' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades'];
    ELSIF p_plano = 'pro' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    ELSE
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao', 'central-seguranca'];
    END IF;

    UPDATE public.user_module_access
    SET ativo = FALSE
    WHERE user_id = v_user_id;

    FOREACH v_mod IN ARRAY v_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Cliente atualizado com sucesso.',
    'cliente_id', p_cliente_id,
    'user_id', v_user_id,
    'instalador_id', p_instalador_id
  );
END;
$$;

-- 11. RPC INSTALADOR_DEFINIR_AGENDAMENTO
CREATE OR REPLACE FUNCTION public.instalador_definir_agendamento(
  p_cliente_id UUID,
  p_data DATE,
  p_hora TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_instalador_id UUID;
  v_cliente_nome TEXT;
BEGIN
  SELECT instalador_id, nome_razao_social INTO v_instalador_id, v_cliente_nome
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  IF v_caller_id <> v_instalador_id AND NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas o instalador atribuido ou administrador podem agendar este atendimento.';
  END IF;

  IF p_data IS NULL THEN
    RAISE EXCEPTION 'A data do agendamento e obrigatoria.';
  END IF;

  IF p_hora IS NULL OR trim(p_hora) = '' THEN
    RAISE EXCEPTION 'O horario do agendamento e obrigatorio.';
  END IF;

  UPDATE public.clientes
  SET data_agendamento = p_data,
      hora_agendamento = trim(p_hora),
      status_agendamento = 'agendado',
      updated_at = now()
  WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Agendamento confirmado para o cliente ' || v_cliente_nome || ' em ' || to_char(p_data, 'DD/MM/YYYY') || ' as ' || trim(p_hora) || '.',
    'cliente_id', p_cliente_id,
    'data', p_data,
    'hora', trim(p_hora)
  );
END;
$$;

-- 12. BACKFILL DE IDENTIDADES GOTRUE E CONFIRMAÇÃO DE EMAIL
UPDATE auth.users
SET email_confirmed_at = COALESCE(email_confirmed_at, now()),
    updated_at = now()
WHERE email_confirmed_at IS NULL;

DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN 
    SELECT u.id, u.email 
    FROM auth.users u
    WHERE NOT EXISTS (
      SELECT 1 FROM auth.identities i 
      WHERE (i.provider = 'email' AND i.provider_id = u.id::text)
         OR i.user_id = u.id
    )
  LOOP
    BEGIN
      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id,
        last_sign_in_at, created_at, updated_at
      ) VALUES (
        r.id::text, r.id,
        jsonb_build_object('sub', r.id::text, 'email', LOWER(r.email)),
        'email', r.id::text,
        now(), now(), now()
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
END $$;

-- Garantir coluna telefone na tabela public.profiles para listagem de instaladores
DO $$ BEGIN
  ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS telefone TEXT;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

-- Garantir colunas na tabela public.veiculos para integracao com instalacoes
DO $$ BEGIN
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS rastreador_imei TEXT;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS status_operacional TEXT DEFAULT 'estacionado';
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

CREATE INDEX IF NOT EXISTS idx_veiculos_rastreador_imei ON public.veiculos(rastreador_imei);

-- RPC salvar_atendimento_instalacao com auto-provisionamento de IMEI e Chips
CREATE OR REPLACE FUNCTION public.salvar_atendimento_instalacao(
  p_instalacao_id UUID DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca TEXT DEFAULT NULL,
  p_modelo TEXT DEFAULT NULL,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_km_instalacao INT DEFAULT 0,
  p_rastreador_imei TEXT DEFAULT NULL,
  p_rastreador_modelo TEXT DEFAULT 'J16 4G',
  p_chip_iccid TEXT DEFAULT NULL,
  p_chip_operadora TEXT DEFAULT NULL,
  p_posicao_instalacao TEXT DEFAULT NULL,
  p_status TEXT DEFAULT 'nao_instalado',
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_instalador_id UUID;
  v_instalacao_id UUID;
  v_veiculo_id UUID := NULL;
  v_rastreador_id UUID := NULL;
  v_chip_id UUID := NULL;
  v_placa_limpa TEXT;
  v_imei_limpo TEXT;
  v_iccid_limpo TEXT;
  v_cliente_instalador_id UUID := NULL;
  v_valor_unitario NUMERIC(10,2) := 0.00;
  v_concluida_at TIMESTAMPTZ := NULL;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autenticado.';
  END IF;

  IF p_status NOT IN ('nao_instalado', 'concluida_com_pendencia', 'concluida') THEN
    RAISE EXCEPTION 'Status de instalacao invalido: %', p_status;
  END IF;

  IF p_status IN ('nao_instalado', 'concluida_com_pendencia') AND (p_motivo IS NULL OR trim(p_motivo) = '') THEN
    RAISE EXCEPTION 'E obrigatorio informar o motivo para status de pendencia ou nao instalado.';
  END IF;

  v_placa_limpa := UPPER(trim(p_placa));
  v_imei_limpo := NULLIF(trim(p_rastreador_imei), '');
  v_iccid_limpo := NULLIF(trim(p_chip_iccid), '');

  IF p_status = 'concluida' AND (v_imei_limpo IS NULL OR v_imei_limpo = '') THEN
    RAISE EXCEPTION 'O IMEI do rastreador e obrigatorio para concluir a instalacao.';
  END IF;

  IF v_iccid_limpo IS NOT NULL THEN
    SELECT id INTO v_chip_id FROM public.chips WHERE iccid = v_iccid_limpo LIMIT 1;
    IF v_chip_id IS NULL THEN
      INSERT INTO public.chips (iccid, operadora, status)
      VALUES (v_iccid_limpo, COALESCE(NULLIF(trim(p_chip_operadora), ''), 'Vivo'), 'ativo')
      RETURNING id INTO v_chip_id;
    END IF;
  END IF;

  IF v_imei_limpo IS NOT NULL THEN
    SELECT id INTO v_rastreador_id FROM public.rastreadores WHERE imei = v_imei_limpo LIMIT 1;
    IF v_rastreador_id IS NULL THEN
      INSERT INTO public.rastreadores (imei, modelo, chip_id, status)
      VALUES (
        v_imei_limpo,
        COALESCE(NULLIF(trim(p_rastreador_modelo), ''), 'J16 4G'),
        v_chip_id,
        CASE WHEN p_status = 'concluida' THEN 'instalado'::public.status_rastreador ELSE 'estoque'::public.status_rastreador END
      ) RETURNING id INTO v_rastreador_id;
    ELSE
      UPDATE public.rastreadores
      SET
        status = CASE WHEN p_status = 'concluida' THEN 'instalado'::public.status_rastreador ELSE status END,
        modelo = COALESCE(NULLIF(trim(p_rastreador_modelo), ''), modelo),
        chip_id = COALESCE(v_chip_id, chip_id),
        updated_at = NOW()
      WHERE id = v_rastreador_id;
    END IF;
  END IF;

  IF p_cliente_id IS NOT NULL THEN
    SELECT instalador_id INTO v_cliente_instalador_id FROM public.clientes WHERE id = p_cliente_id;
  END IF;

  IF p_instalacao_id IS NULL THEN
    IF v_cliente_instalador_id IS NOT NULL THEN
      v_instalador_id := v_cliente_instalador_id;
    ELSE
      v_instalador_id := v_user_id;
    END IF;

    SELECT COALESCE(valor_por_instalacao, 0.00) INTO v_valor_unitario FROM public.profiles WHERE id = v_instalador_id;
    IF p_status = 'concluida' THEN v_concluida_at := NOW(); END IF;

    INSERT INTO public.instalacoes (
      instalador_id, cliente_id, placa, marca, modelo, ano, cor, km_instalacao,
      rastreador_imei, rastreador_modelo, chip_iccid, chip_operadora,
      posicao_instalacao, status, motivo_pendencia_recusa, observacoes,
      valor_instalacao, concluida_at
    ) VALUES (
      v_instalador_id, p_cliente_id, v_placa_limpa, p_marca, p_modelo, p_ano, p_cor, p_km_instalacao,
      COALESCE(v_imei_limpo, 'SEM-IMEI'), COALESCE(NULLIF(trim(p_rastreador_modelo), ''), 'J16 4G'),
      v_iccid_limpo, p_chip_operadora, p_posicao_instalacao, p_status, p_motivo, p_observacoes,
      v_valor_unitario, v_concluida_at
    ) RETURNING id INTO v_instalacao_id;
  ELSE
    v_instalacao_id := p_instalacao_id;
    SELECT instalador_id, concluida_at, veiculo_id INTO v_instalador_id, v_concluida_at, v_veiculo_id
    FROM public.instalacoes WHERE id = v_instalacao_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Instalacao nao encontrada.'; END IF;

    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN v_concluida_at := NOW(); END IF;

    UPDATE public.instalacoes
    SET
      cliente_id = COALESCE(p_cliente_id, cliente_id),
      placa = COALESCE(v_placa_limpa, placa),
      marca = COALESCE(p_marca, marca),
      modelo = COALESCE(p_modelo, modelo),
      ano = COALESCE(p_ano, ano),
      cor = COALESCE(p_cor, cor),
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
      rastreador_modelo = COALESCE(NULLIF(trim(p_rastreador_modelo), ''), rastreador_modelo),
      chip_iccid = COALESCE(v_iccid_limpo, chip_iccid),
      chip_operadora = COALESCE(p_chip_operadora, chip_operadora),
      posicao_instalacao = COALESCE(p_posicao_instalacao, posicao_instalacao),
      status = p_status,
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      updated_at = NOW()
    WHERE id = v_instalacao_id;
  END IF;

  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id, instalador_id, status_atendimento, motivo, observacoes, km_no_atendimento
  ) VALUES (
    v_instalacao_id, v_user_id, p_status, p_motivo, p_observacoes, p_km_instalacao
  );

  IF p_status = 'concluida' THEN
    SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;

    IF v_veiculo_id IS NULL THEN
      INSERT INTO public.veiculos (
        cliente_id, placa, marca_modelo, ano, cor, odometro_km,
        rastreador_id, rastreador_imei, status_operacional, ativo
      ) VALUES (
        p_cliente_id, v_placa_limpa, format('%s %s', p_marca, p_modelo), p_ano, p_cor, p_km_instalacao,
        v_rastreador_id, v_imei_limpo, 'estacionado', TRUE
      ) RETURNING id INTO v_veiculo_id;

      BEGIN
        PERFORM public.inicializar_itens_manutencao_veiculo(v_veiculo_id, p_km_instalacao);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    ELSE
      UPDATE public.veiculos
      SET
        cliente_id = COALESCE(p_cliente_id, cliente_id),
        odometro_km = GREATEST(odometro_km, p_km_instalacao),
        rastreador_id = COALESCE(v_rastreador_id, rastreador_id),
        rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
        status_operacional = 'estacionado',
        ativo = TRUE,
        updated_at = NOW()
      WHERE id = v_veiculo_id;
    END IF;

    UPDATE public.instalacoes SET veiculo_id = v_veiculo_id WHERE id = v_instalacao_id;

    IF p_cliente_id IS NOT NULL THEN
      UPDATE public.clientes
      SET status = 'ativo', status_agendamento = 'concluido', updated_at = NOW()
      WHERE id = p_cliente_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'instalacao_id', v_instalacao_id,
    'status', p_status,
    'veiculo_id', v_veiculo_id,
    'rastreador_id', v_rastreador_id,
    'rastreador_imei', v_imei_limpo
  );
END;
$$;

NOTIFY pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Gestão Individual de Veículos e Pendência de Instalação
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. RPC para Bloquear ou Desbloquear Veículo Individualmente
CREATE OR REPLACE FUNCTION public.admin_bloquear_desbloquear_veiculo(
  p_veiculo_id UUID,
  p_bloquear BOOLEAN
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_placa TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;
    IF v_role NOT IN ('superadmin', 'operador') THEN
      RAISE EXCEPTION 'Apenas administradores e operadores podem alterar o bloqueio de veículos.';
    END IF;
  END IF;

  SELECT placa INTO v_placa FROM public.veiculos WHERE id = p_veiculo_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veículo não encontrado.';
  END IF;

  UPDATE public.veiculos
  SET
    bloqueado = p_bloquear,
    updated_at = NOW()
  WHERE id = p_veiculo_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo_id', p_veiculo_id,
    'placa', v_placa,
    'bloqueado', p_bloquear,
    'mensagem', CASE WHEN p_bloquear THEN 'Veículo bloqueado com sucesso.' ELSE 'Veículo desbloqueado com sucesso.' END
  );
END;
$$;

-- 2. RPC para Editar Dados Cadastrais de Veículo Individualmente
CREATE OR REPLACE FUNCTION public.admin_editar_veiculo(
  p_veiculo_id UUID,
  p_placa TEXT,
  p_marca_modelo TEXT,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_placa_limpa TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;
    IF v_role NOT IN ('superadmin', 'operador') THEN
      RAISE EXCEPTION 'Apenas administradores e operadores podem editar veículos.';
    END IF;
  END IF;

  v_placa_limpa := UPPER(trim(p_placa));
  IF v_placa_limpa IS NULL OR v_placa_limpa = '' THEN
    RAISE EXCEPTION 'A placa do veículo é obrigatória.';
  END IF;

  IF p_marca_modelo IS NULL OR trim(p_marca_modelo) = '' THEN
    RAISE EXCEPTION 'A marca e modelo do veículo são obrigatórios.';
  END IF;

  IF EXISTS (SELECT 1 FROM public.veiculos WHERE placa = v_placa_limpa AND id <> p_veiculo_id) THEN
    RAISE EXCEPTION 'Esta placa já está cadastrada em outro veículo.';
  END IF;

  UPDATE public.veiculos
  SET
    placa = v_placa_limpa,
    marca_modelo = trim(p_marca_modelo),
    ano = p_ano,
    cor = NULLIF(trim(p_cor), ''),
    updated_at = NOW()
  WHERE id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veículo não encontrado.';
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo_id', p_veiculo_id,
    'placa', v_placa_limpa,
    'mensagem', 'Dados do veículo atualizados com sucesso.'
  );
END;
$$;

-- 3. RPC para Excluir Veículo com Segurança e Desvinculação Atômica
CREATE OR REPLACE FUNCTION public.admin_excluir_veiculo(
  p_veiculo_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_placa TEXT;
  v_cliente_id UUID;
  v_rastreador_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;
    IF v_role NOT IN ('superadmin', 'adm', 'operador') THEN
      RAISE EXCEPTION 'Apenas administradores e operadores podem excluir veículos.';
    END IF;
  END IF;

  SELECT placa, cliente_id, rastreador_id INTO v_placa, v_cliente_id, v_rastreador_id
  FROM public.veiculos
  WHERE id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veículo não encontrado.';
  END IF;

  -- 1.1 Libera rastreador vinculado, se houver
  IF v_rastreador_id IS NOT NULL THEN
    UPDATE public.rastreadores
    SET veiculo_id = NULL, status = 'estoque'
    WHERE id = v_rastreador_id;
  END IF;
  UPDATE public.rastreadores
  SET veiculo_id = NULL, status = 'estoque'
  WHERE veiculo_id = p_veiculo_id;

  -- 1.2 Limpa abastecimentos e despesas com FK RESTRICT
  DELETE FROM public.motorista_abastecimentos WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.motorista_despesas WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.motorista_veiculos WHERE veiculo_id = p_veiculo_id;

  -- 1.3 Desvincula instalações
  UPDATE public.instalacoes
  SET veiculo_id = NULL
  WHERE veiculo_id = p_veiculo_id;

  -- 1.4 Desvincula movimentações de estoque, atendimentos, trajetos e whatsapp
  UPDATE public.estoque_movimentacoes
  SET veiculo_id = NULL
  WHERE veiculo_id = p_veiculo_id;

  UPDATE public.atendimentos
  SET veiculo_id = NULL
  WHERE veiculo_id = p_veiculo_id;

  UPDATE public.trajetos_salvos
  SET veiculo_id = NULL
  WHERE veiculo_id = p_veiculo_id;

  UPDATE public.whatsapp_mensagens_fila
  SET veiculo_id = NULL
  WHERE veiculo_id = p_veiculo_id;

  -- 1.5 Limpa tabelas com FK em cascata explícita
  DELETE FROM public.alertas_telemetria_cooldown WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.telemetria_posicoes WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.viagens_trajetos WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.eventos_veiculo WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.compartilhamentos_temporarios WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.compartilhamentos_acessos WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.areas_seguras WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.horarios_utilizacao WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.regras_veiculo WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.rotas_monitoradas WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.alertas_seguranca WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.agendamentos_manutencao WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.planos_manutencao_preventiva WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.notificacoes_configuracoes WHERE veiculo_id = p_veiculo_id;
  DELETE FROM public.veiculo_convidados WHERE veiculo_id = p_veiculo_id;

  -- 1.6 Deleta o veículo
  DELETE FROM public.veiculos WHERE id = p_veiculo_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo_id', p_veiculo_id,
    'cliente_id', v_cliente_id,
    'placa', v_placa,
    'mensagem', 'Veículo excluído com sucesso.'
  );
END;
$$;

-- 4. RPC para Gerar Pendência de Instalação para o Instalador
CREATE OR REPLACE FUNCTION public.admin_gerar_pendencia_instalacao_cliente(
  p_cliente_id UUID,
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_cliente RECORD;
  v_tem_veiculo_ativo BOOLEAN := false;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;
    IF v_role NOT IN ('superadmin', 'operador') THEN
      RAISE EXCEPTION 'Apenas administradores e operadores podem gerar pendência de instalação.';
    END IF;
  END IF;

  SELECT * INTO v_cliente FROM public.clientes WHERE id = p_cliente_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.veiculos
    WHERE cliente_id = p_cliente_id AND ativo = true AND rastreador_id IS NOT NULL
  ) INTO v_tem_veiculo_ativo;

  UPDATE public.clientes
  SET
    instalador_id = COALESCE(p_instalador_id, instalador_id),
    status_agendamento = 'aguardando_agendamento',
    data_agendamento = NULL,
    hora_agendamento = NULL,
    status = CASE WHEN v_tem_veiculo_ativo THEN status ELSE 'aguardando_instalacao' END,
    updated_at = NOW()
  WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'cliente_id', p_cliente_id,
    'status_agendamento', 'aguardando_agendamento',
    'mensagem', 'Pendência de instalação gerada com sucesso para o instalador.'
  );
END;
$$;

-- 8. GERACAO E ADMINISTRACAO DE MENSALIDADES (v1.5.5.3)
CREATE OR REPLACE FUNCTION public.admin_atualizar_status_mensalidades_vencidas()
RETURNS INT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_afetados INT := 0;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar status de mensalidades.';
  END IF;

  UPDATE public.mensalidades
  SET status = 'vencido',
      updated_at = NOW()
  WHERE status = 'pendente'
    AND data_vencimento < CURRENT_DATE;

  GET DIAGNOSTICS v_afetados = ROW_COUNT;
  RETURN v_afetados;
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_gerar_mensalidades_mes(
  p_mes INT,
  p_ano INT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente RECORD;
  v_dia_max INT;
  v_dia_final INT;
  v_data_venc DATE;
  v_status_inicial public.status_mensalidade;
  v_total_clientes INT := 0;
  v_geradas INT := 0;
  v_ja_existentes INT := 0;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem gerar mensalidades em lote.';
  END IF;

  IF p_mes < 1 OR p_mes > 12 THEN
    RAISE EXCEPTION 'Mes de referencia invalido: deve estar entre 1 e 12.';
  END IF;

  IF p_ano < 2024 OR p_ano > 2099 THEN
    RAISE EXCEPTION 'Ano de referencia invalido.';
  END IF;

  v_dia_max := EXTRACT(DAY FROM (DATE_TRUNC('month', make_date(p_ano, p_mes, 1)) + INTERVAL '1 month - 1 day'))::INT;

  FOR v_cliente IN
    SELECT id, dia_vencimento, valor_mensalidade, nome_razao_social
    FROM public.clientes
    WHERE status <> 'bloqueado'
      AND valor_mensalidade > 0
  LOOP
    v_total_clientes := v_total_clientes + 1;
    v_dia_final := LEAST(COALESCE(v_cliente.dia_vencimento, 10), v_dia_max);
    v_data_venc := make_date(p_ano, p_mes, v_dia_final);

    IF v_data_venc < CURRENT_DATE THEN
      v_status_inicial := 'vencido';
    ELSE
      v_status_inicial := 'pendente';
    END IF;

    INSERT INTO public.mensalidades (
      cliente_id,
      mes_referencia,
      ano_referencia,
      valor,
      data_vencimento,
      status,
      created_at,
      updated_at
    ) VALUES (
      v_cliente.id,
      p_mes,
      p_ano,
      v_cliente.valor_mensalidade,
      v_data_venc,
      v_status_inicial,
      NOW(),
      NOW()
    )
    ON CONFLICT (cliente_id, mes_referencia, ano_referencia) DO NOTHING;

    IF FOUND THEN
      v_geradas := v_geradas + 1;
    ELSE
      v_ja_existentes := v_ja_existentes + 1;
    END IF;
  END LOOP;

  INSERT INTO public.system_activity_logs (
    user_id,
    acao,
    detalhe,
    created_at
  ) VALUES (
    auth.uid(),
    'GERACAO_MENSALIDADES_LOTE',
    'Competencia: ' || LPAD(p_mes::TEXT, 2, '0') || '/' || p_ano::TEXT ||
    ' | Geradas: ' || v_geradas::TEXT ||
    ' | Ja existentes: ' || v_ja_existentes::TEXT ||
    ' | Total clientes aptos: ' || v_total_clientes::TEXT,
    NOW()
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'mes_referencia', p_mes,
    'ano_referencia', p_ano,
    'geradas', v_geradas,
    'ja_existentes', v_ja_existentes,
    'total_clientes', v_total_clientes
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_atualizar_status_mensalidades_vencidas() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_gerar_mensalidades_mes(INT, INT) TO authenticated;

-- 9. MODULO FINANCEIRO INTEGRADO E LEDGER (v1.5.5.4)
DO $$ BEGIN
  CREATE TYPE public.tipo_transacao_financeira AS ENUM ('entrada', 'saida');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE public.status_transacao_financeira AS ENUM ('pendente', 'concluido', 'cancelado');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE public.categoria_transacao_financeira AS ENUM (
    'mensalidade',
    'repasse_instalador',
    'chips_conectividade',
    'infraestrutura_servidores',
    'aquisicao_equipamentos',
    'material_consumo',
    'despesa_administrativa',
    'receita_avulsa',
    'outros'
  );
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

CREATE TABLE IF NOT EXISTS public.transacoes_financeiras (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tipo public.tipo_transacao_financeira NOT NULL,
  categoria public.categoria_transacao_financeira NOT NULL DEFAULT 'outros',
  descricao TEXT NOT NULL,
  valor NUMERIC(10, 2) NOT NULL CHECK (valor > 0),
  data_competencia DATE NOT NULL DEFAULT CURRENT_DATE,
  data_vencimento DATE,
  data_pagamento TIMESTAMPTZ,
  status public.status_transacao_financeira NOT NULL DEFAULT 'pendente',
  mensalidade_id UUID REFERENCES public.mensalidades(id) ON DELETE CASCADE,
  instalacao_id UUID REFERENCES public.instalacoes(id) ON DELETE CASCADE,
  cliente_id UUID REFERENCES public.clientes(id) ON DELETE SET NULL,
  instalador_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  comprovante_url TEXT,
  observacoes TEXT,
  created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_transacao_mensalidade UNIQUE (mensalidade_id),
  CONSTRAINT uq_transacao_instalacao UNIQUE (instalacao_id)
);

CREATE INDEX IF NOT EXISTS idx_transacoes_data_competencia ON public.transacoes_financeiras(data_competencia DESC);
CREATE INDEX IF NOT EXISTS idx_transacoes_tipo_status ON public.transacoes_financeiras(tipo, status);
CREATE INDEX IF NOT EXISTS idx_transacoes_categoria ON public.transacoes_financeiras(categoria);

ALTER TABLE public.transacoes_financeiras ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Admins gerenciam transacoes financeiras" ON public.transacoes_financeiras;
CREATE POLICY "Admins gerenciam transacoes financeiras"
ON public.transacoes_financeiras FOR ALL TO authenticated
USING (public.is_adm())
WITH CHECK (public.is_adm());

-- Trigger para sincronizacao de mensalidades
CREATE OR REPLACE FUNCTION public.trg_sync_mensalidade_transacao()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente_nome TEXT;
  v_status_trans public.status_transacao_financeira;
  v_desc TEXT;
BEGIN
  SELECT nome_razao_social INTO v_cliente_nome
  FROM public.clientes WHERE id = NEW.cliente_id;

  v_desc := 'Mensalidade ' || LPAD(NEW.mes_referencia::TEXT, 2, '0') || '/' || NEW.ano_referencia::TEXT ||
            ' - ' || COALESCE(v_cliente_nome, 'Cliente');

  IF NEW.status = 'pago' THEN
    v_status_trans := 'concluido';
  ELSE
    v_status_trans := 'pendente';
  END IF;

  INSERT INTO public.transacoes_financeiras (
    tipo, categoria, descricao, valor, data_competencia, data_vencimento,
    data_pagamento, status, mensalidade_id, cliente_id, comprovante_url, updated_at
  ) VALUES (
    'entrada', 'mensalidade', v_desc, NEW.valor,
    make_date(NEW.ano_referencia, NEW.mes_referencia, 1),
    NEW.data_vencimento, NEW.data_pagamento, v_status_trans,
    NEW.id, NEW.cliente_id, NEW.comprovante_url, NOW()
  )
  ON CONFLICT (mensalidade_id) DO UPDATE SET
    valor = EXCLUDED.valor,
    descricao = EXCLUDED.descricao,
    data_vencimento = EXCLUDED.data_vencimento,
    data_pagamento = EXCLUDED.data_pagamento,
    status = EXCLUDED.status,
    comprovante_url = EXCLUDED.comprovante_url,
    updated_at = NOW();

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_mensalidade_transacao ON public.mensalidades;
CREATE TRIGGER trg_sync_mensalidade_transacao
AFTER INSERT OR UPDATE ON public.mensalidades
FOR EACH ROW EXECUTE FUNCTION public.trg_sync_mensalidade_transacao();

-- Trigger para sincronizacao de instalacoes (repasses)
CREATE OR REPLACE FUNCTION public.trg_sync_instalacao_transacao()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_instalador_nome TEXT;
  v_cliente_nome TEXT;
  v_status_trans public.status_transacao_financeira;
  v_desc TEXT;
BEGIN
  IF NEW.valor_repasse IS NULL OR NEW.valor_repasse <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT nome INTO v_instalador_nome FROM public.profiles WHERE id = NEW.instalador_id;
  SELECT c.nome_razao_social INTO v_cliente_nome
  FROM public.veiculos v
  JOIN public.clientes c ON v.cliente_id = c.id
  WHERE v.id = NEW.veiculo_id;

  v_desc := 'Repasse Instalador (' || COALESCE(v_instalador_nome, 'Tecnico') || ') - Veiculo Cliente ' || COALESCE(v_cliente_nome, '');

  IF NEW.status_pagamento = 'pago' THEN
    v_status_trans := 'concluido';
  ELSE
    v_status_trans := 'pendente';
  END IF;

  INSERT INTO public.transacoes_financeiras (
    tipo, categoria, descricao, valor, data_competencia, data_vencimento,
    data_pagamento, status, instalacao_id, instalador_id, comprovante_url, updated_at
  ) VALUES (
    'saida', 'repasse_instalador', v_desc, NEW.valor_repasse,
    COALESCE(NEW.data_instalacao::DATE, CURRENT_DATE),
    COALESCE(NEW.data_instalacao::DATE, CURRENT_DATE),
    NEW.data_pagamento_repasse, v_status_trans,
    NEW.id, NEW.instalador_id, NEW.comprovante_pagamento_url, NOW()
  )
  ON CONFLICT (instalacao_id) DO UPDATE SET
    valor = EXCLUDED.valor,
    descricao = EXCLUDED.descricao,
    data_pagamento = EXCLUDED.data_pagamento,
    status = EXCLUDED.status,
    comprovante_url = EXCLUDED.comprovante_url,
    updated_at = NOW();

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_instalacao_transacao ON public.instalacoes;
CREATE TRIGGER trg_sync_instalacao_transacao
AFTER INSERT OR UPDATE ON public.instalacoes
FOR EACH ROW EXECUTE FUNCTION public.trg_sync_instalacao_transacao();

-- ============================================================================
-- EXPURGO DE VEÍCULOS FICTÍCIOS E DADOS DE TESTE (FROTA HUNTER OPERACIONAL)
-- ============================================================================
DO $$
DECLARE
  v_fake_ids UUID[];
BEGIN
  SELECT ARRAY_AGG(id) INTO v_fake_ids
  FROM public.veiculos
  WHERE placa IN ('HTR4G16', 'HUN1T26')
     OR marca_modelo ILIKE '%Frota Hunter%'
     OR marca_modelo ILIKE '%Simula%';

  IF v_fake_ids IS NOT NULL AND array_length(v_fake_ids, 1) > 0 THEN
    DELETE FROM public.telemetria_posicoes WHERE veiculo_id = ANY(v_fake_ids);
    DELETE FROM public.viagens_trajetos WHERE veiculo_id = ANY(v_fake_ids);
    DELETE FROM public.alertas_seguranca WHERE veiculo_id = ANY(v_fake_ids);
    DELETE FROM public.itens_manutencao_preventiva WHERE veiculo_id = ANY(v_fake_ids);
    DELETE FROM public.veiculos WHERE id = ANY(v_fake_ids);
  END IF;

  DELETE FROM public.clientes WHERE nome_razao_social ILIKE '%Frota Hunter%';
END $$;

-- ============================================================================
-- HARMONIZAÇÃO DE CONSTRAINTS: TRANSAÇÕES FINANCEIRAS (DESPESAS E RECEITAS)
-- ============================================================================
DO $$
BEGIN
  -- Se as colunas forem enums restritivos, converte com segurança para TEXT
  IF EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'transacoes_financeiras' 
      AND column_name = 'tipo' AND data_type = 'USER-DEFINED'
  ) THEN
    ALTER TABLE public.transacoes_financeiras ALTER COLUMN tipo TYPE TEXT USING tipo::TEXT;
  END IF;

  IF EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'transacoes_financeiras' 
      AND column_name = 'status' AND data_type = 'USER-DEFINED'
  ) THEN
    ALTER TABLE public.transacoes_financeiras ALTER COLUMN status TYPE TEXT USING status::TEXT;
  END IF;

  -- Dropar constraints antigas caso existam
  IF EXISTS (
    SELECT 1 FROM information_schema.table_constraints 
    WHERE constraint_name = 'transacoes_financeiras_tipo_check' 
      AND table_name = 'transacoes_financeiras'
  ) THEN
    ALTER TABLE public.transacoes_financeiras DROP CONSTRAINT transacoes_financeiras_tipo_check;
  END IF;

  ALTER TABLE public.transacoes_financeiras 
    ADD CONSTRAINT transacoes_financeiras_tipo_check 
    CHECK (tipo IN ('receita', 'despesa', 'entrada', 'saida'));

  IF EXISTS (
    SELECT 1 FROM information_schema.table_constraints 
    WHERE constraint_name = 'transacoes_financeiras_status_check' 
      AND table_name = 'transacoes_financeiras'
  ) THEN
    ALTER TABLE public.transacoes_financeiras DROP CONSTRAINT transacoes_financeiras_status_check;
  END IF;

  ALTER TABLE public.transacoes_financeiras 
    ADD CONSTRAINT transacoes_financeiras_status_check 
    CHECK (status IN ('pendente', 'pago', 'concluido', 'cancelado', 'estornado'));
END $$;

-- ============================================================================
-- HUNTER — CORREÇÃO DE RLS: MANUTENÇÃO PREVENTIVA DO CLIENTE (FOR ALL)
-- ============================================================================
-- Permite que o cliente proprietário do veículo possa criar, editar e excluir
-- os itens de manutenção e revisões do seu próprio carro.
DROP POLICY IF EXISTS "Planos manutencao visiveis para o cliente do veiculo" ON public.planos_manutencao_preventiva;
DROP POLICY IF EXISTS "Planos manutencao gerenciados pelo cliente do veiculo" ON public.planos_manutencao_preventiva;

CREATE POLICY "Planos manutencao gerenciados pelo cliente do veiculo"
ON public.planos_manutencao_preventiva FOR ALL TO authenticated
USING (
  veiculo_id IN (
    SELECT v.id FROM public.veiculos v
    JOIN public.clientes c ON v.cliente_id = c.id
    WHERE c.user_id = auth.uid()
  )
)
WITH CHECK (
  veiculo_id IN (
    SELECT v.id FROM public.veiculos v
    JOIN public.clientes c ON v.cliente_id = c.id
    WHERE c.user_id = auth.uid()
  )
);

DROP POLICY IF EXISTS "Agendamentos clientes visualizam e criam" ON public.agendamentos_manutencao;
DROP POLICY IF EXISTS "Clientes visualizam e criam seus agendamentos" ON public.agendamentos_manutencao;
CREATE POLICY "Clientes visualizam e gerenciam seus agendamentos"
ON public.agendamentos_manutencao FOR ALL TO authenticated
USING (
  cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
)
WITH CHECK (
  cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
);

NOTIFY pgrst, 'reload schema';

-- ============================================================================
-- HUNTER — TABELA DE TRAJETOS SALVOS (BANCO DE DADOS SUPABASE COM RLS)
-- ============================================================================
-- Permite que clientes e operadores salvem até 5 trajetos inteligentes favoritos
-- diretamente no Banco de Dados com isolamento total por RLS.

CREATE TABLE IF NOT EXISTS public.trajetos_salvos (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  cliente_id UUID REFERENCES public.clientes(id) ON DELETE CASCADE,
  veiculo_id UUID REFERENCES public.veiculos(id) ON DELETE SET NULL,
  nome TEXT NOT NULL,
  retornar_ao_ponto_saida BOOLEAN NOT NULL DEFAULT false,
  saida JSONB NOT NULL,
  paradas JSONB NOT NULL DEFAULT '[]'::jsonb,
  chegada JSONB NOT NULL,
  distancia_km NUMERIC(8,2) NOT NULL DEFAULT 0,
  duracao_minutos INTEGER NOT NULL DEFAULT 0,
  trechos JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.trajetos_salvos ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Usuarios gerenciam seus proprios trajetos salvos" ON public.trajetos_salvos;
CREATE POLICY "Usuarios gerenciam seus proprios trajetos salvos"
ON public.trajetos_salvos FOR ALL TO authenticated
USING (user_id = auth.uid())
WITH CHECK (user_id = auth.uid());

CREATE OR REPLACE FUNCTION public.check_limite_trajetos_salvos()
RETURNS TRIGGER AS $$
DECLARE
  qtd INTEGER;
BEGIN
  SELECT COUNT(*) INTO qtd
  FROM public.trajetos_salvos
  WHERE user_id = NEW.user_id;

  IF qtd >= 5 AND (TG_OP = 'INSERT') THEN
    RAISE EXCEPTION 'Limite maximo de 5 trajetos salvos atingido. Exclua um trajeto antes de salvar um novo.';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_limite_trajetos_salvos ON public.trajetos_salvos;
CREATE TRIGGER trg_check_limite_trajetos_salvos
BEFORE INSERT ON public.trajetos_salvos
FOR EACH ROW
EXECUTE FUNCTION public.check_limite_trajetos_salvos();

ALTER PUBLICATION supabase_realtime ADD TABLE public.trajetos_salvos;

NOTIFY pgrst, 'reload schema';



-- 2. TABELAS DO SISTEMA DE PROTEÇÃO E COMPARTILHAMENTO TEMPORÁRIO

-- 2.1 Áreas Seguras / Cercas Pessoais (Geofence)
CREATE TABLE IF NOT EXISTS public.areas_seguras (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  veiculo_id UUID REFERENCES public.veiculos(id) ON DELETE CASCADE,
  cliente_id UUID REFERENCES public.clientes(id) ON DELETE CASCADE,
  nome TEXT NOT NULL,
  tipo TEXT NOT NULL DEFAULT 'outro',
  latitude DOUBLE PRECISION NOT NULL,
  longitude DOUBLE PRECISION NOT NULL,
