CREATE OR REPLACE FUNCTION public.solicitar_retirada_rastreador(
  p_veiculo_id UUID,
  p_instalador_id UUID,
  p_valor_retirada NUMERIC DEFAULT 0.00,
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_veiculo RECORD;
  v_nova_os_id UUID;
  v_valor_final NUMERIC(10,2);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autenticado.';
  END IF;

  SELECT v.id, v.cliente_id, v.placa, v.marca_modelo, v.ano, v.cor, v.odometro_km,
         v.rastreador_id, v.rastreador_imei, r.chip_id, c.iccid, c.operadora
  INTO v_veiculo
  FROM public.veiculos v
  LEFT JOIN public.rastreadores r ON r.id = v.rastreador_id
  LEFT JOIN public.chips c ON c.id = r.chip_id
  WHERE v.id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veiculo nao encontrado para retirada.';
  END IF;

  IF v_veiculo.rastreador_imei IS NULL AND v_veiculo.rastreador_id IS NULL THEN
    RAISE EXCEPTION 'O veiculo selecionado nao possui rastreador vinculado para retirada.';
  END IF;

  v_valor_final := GREATEST(COALESCE(p_valor_retirada, 0.00), 0.00);

  INSERT INTO public.instalacoes (
    instalador_id,
    cliente_id,
    veiculo_id,
    tipo_servico,
    placa,
    marca,
    modelo,
    ano,
    cor,
    km_instalacao,
    rastreador_imei,
    chip_iccid,
    chip_operadora,
    status,
    motivo_pendencia_recusa,
    observacoes,
    valor_instalacao,
    status_pagamento
  ) VALUES (
    p_instalador_id,
    v_veiculo.cliente_id,
    v_veiculo.id,
    'retirada',
    v_veiculo.placa,
    SPLIT_PART(COALESCE(v_veiculo.marca_modelo, 'Veiculo'), ' ', 1),
    COALESCE(SUBSTRING(v_veiculo.marca_modelo FROM ' +(.*)'), 'Modelo'),
    v_veiculo.ano,
    v_veiculo.cor,
    COALESCE(v_veiculo.odometro_km, 0),
    COALESCE(v_veiculo.rastreador_imei, 'A CONFERIR'),
    v_veiculo.iccid,
    v_veiculo.operadora,
    'nao_instalado',
    p_motivo,
    p_observacoes,
    v_valor_final,
    'pendente'
  )
  RETURNING id INTO v_nova_os_id;

  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_nova_os_id,
    v_user_id,
    'nao_instalado',
    p_motivo,
    COALESCE(p_observacoes, 'Ordem de retirada emitida pela gestao Hunter.'),
    COALESCE(v_veiculo.odometro_km, 0)
  );

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'instalacao_id', v_nova_os_id,
    'tipo_servico', 'retirada'
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.solicitar_remanejamento_rastreador(
  p_veiculo_origem_id UUID,
  p_cliente_destino_id UUID,
  p_novo_veiculo_placa TEXT,
  p_novo_veiculo_marca TEXT,
  p_novo_veiculo_modelo TEXT,
  p_novo_veiculo_ano INT DEFAULT NULL,
  p_novo_veiculo_cor TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL,
  p_valor_retirada NUMERIC DEFAULT 0.00,
  p_valor_instalacao NUMERIC DEFAULT 350.00,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_origem RECORD;
  v_os_retirada_id UUID;
  v_os_instalacao_id UUID;
  v_placa_nova TEXT;
  v_valor_retirada_final NUMERIC(10,2);
  v_valor_instalacao_final NUMERIC(10,2);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autenticado.';
  END IF;

  v_placa_nova := UPPER(TRIM(p_novo_veiculo_placa));
  IF v_placa_nova IS NULL OR v_placa_nova = '' THEN
    RAISE EXCEPTION 'A placa do novo veiculo e obrigatoria.';
  END IF;

  SELECT v.id, v.cliente_id, v.placa, v.marca_modelo, v.ano, v.cor, v.odometro_km,
         v.rastreador_id, v.rastreador_imei, r.chip_id, c.iccid, c.operadora
  INTO v_origem
  FROM public.veiculos v
  LEFT JOIN public.rastreadores r ON r.id = v.rastreador_id
  LEFT JOIN public.chips c ON c.id = r.chip_id
  WHERE v.id = p_veiculo_origem_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veiculo de origem nao encontrado.';
  END IF;

  IF v_origem.rastreador_imei IS NULL AND v_origem.rastreador_id IS NULL THEN
    RAISE EXCEPTION 'O veiculo de origem nao possui rastreador para remanejamento.';
  END IF;

  v_valor_retirada_final := GREATEST(COALESCE(p_valor_retirada, 0.00), 0.00);
  v_valor_instalacao_final := GREATEST(COALESCE(p_valor_instalacao, 0.00), 0.00);

  INSERT INTO public.instalacoes (
    instalador_id,
    cliente_id,
    veiculo_id,
    tipo_servico,
    placa,
    marca,
    modelo,
    ano,
    cor,
    km_instalacao,
    rastreador_imei,
    chip_iccid,
    chip_operadora,
    status,
    motivo_pendencia_recusa,
    observacoes,
    valor_instalacao,
    status_pagamento
  ) VALUES (
    p_instalador_id,
    v_origem.cliente_id,
    v_origem.id,
    'retirada',
    v_origem.placa,
    SPLIT_PART(COALESCE(v_origem.marca_modelo, 'Veiculo'), ' ', 1),
    COALESCE(SUBSTRING(v_origem.marca_modelo FROM ' +(.*)'), 'Modelo'),
    v_origem.ano,
    v_origem.cor,
    COALESCE(v_origem.odometro_km, 0),
    COALESCE(v_origem.rastreador_imei, 'A CONFERIR'),
    v_origem.iccid,
    v_origem.operadora,
    'nao_instalado',
    'Remanejamento para novo veiculo: ' || v_placa_nova,
    p_observacoes,
    v_valor_retirada_final,
    'pendente'
  )
  RETURNING id INTO v_os_retirada_id;

  INSERT INTO public.instalacoes (
    instalador_id,
    cliente_id,
    veiculo_id,
    tipo_servico,
    placa,
    marca,
    modelo,
    ano,
    cor,
    km_instalacao,
    rastreador_imei,
    chip_iccid,
    chip_operadora,
    status,
    motivo_pendencia_recusa,
    observacoes,
    valor_instalacao,
    status_pagamento,
    ordem_vinculada_id
  ) VALUES (
    p_instalador_id,
    COALESCE(p_cliente_destino_id, v_origem.cliente_id),
    NULL,
    'instalacao',
    v_placa_nova,
    TRIM(p_novo_veiculo_marca),
    TRIM(p_novo_veiculo_modelo),
    p_novo_veiculo_ano,
    p_novo_veiculo_cor,
    0,
    COALESCE(v_origem.rastreador_imei, 'A CONFERIR'),
    v_origem.iccid,
    v_origem.operadora,
    'nao_instalado',
    'Aguardando conclusao da retirada do veiculo ' || v_origem.placa,
    p_observacoes,
    v_valor_instalacao_final,
    'pendente',
    v_os_retirada_id
  )
  RETURNING id INTO v_os_instalacao_id;

  UPDATE public.instalacoes
  SET ordem_vinculada_id = v_os_instalacao_id
  WHERE id = v_os_retirada_id;

  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_os_retirada_id,
    v_user_id,
    'nao_instalado',
    'Remanejamento / Troca de Veiculo',
    'Ordem de retirada gerada em conjunto com a instalacao da placa ' || v_placa_nova,
    COALESCE(v_origem.odometro_km, 0)
  );

  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_os_instalacao_id,
    v_user_id,
    'nao_instalado',
    'Remanejamento / Troca de Veiculo',
    'Ordem de instalacao gerada em conjunto com a retirada da placa ' || v_origem.placa,
    0
  );

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'ordem_retirada_id', v_os_retirada_id,
    'ordem_instalacao_id', v_os_instalacao_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.salvar_atendimento_instalacao(
  p_instalacao_id UUID DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca TEXT DEFAULT NULL,
  p_modelo TEXT DEFAULT NULL,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_km_instalacao INT DEFAULT 0,
  p_rastreador_imei TEXT DEFAULT NULL,
  p_rastreador_modelo TEXT DEFAULT 'J16 4G',
  p_chip_iccid TEXT DEFAULT NULL,
  p_chip_operadora TEXT DEFAULT NULL,
  p_posicao_instalacao TEXT DEFAULT NULL,
  p_status TEXT DEFAULT 'nao_instalado',
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL,
  p_bloqueador_instalado BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_instalador_id UUID;
  v_instalacao_id UUID;
  v_veiculo_id UUID := NULL;
  v_rastreador_id UUID := NULL;
  v_chip_id UUID := NULL;
  v_placa_limpa TEXT;
  v_imei_limpo TEXT;
  v_iccid_limpo TEXT;
  v_cliente_instalador_id UUID := NULL;
  v_valor_unitario NUMERIC(10,2) := 0.00;
  v_concluida_at TIMESTAMPTZ := NULL;
  v_bloqueador BOOLEAN := COALESCE(p_bloqueador_instalado, TRUE);
  v_tipo_servico TEXT := 'instalacao';
  v_ordem RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autenticado.';
  END IF;

  IF p_status NOT IN ('nao_instalado', 'concluida_com_pendencia', 'concluida') THEN
    RAISE EXCEPTION 'Status de atendimento invalido: %', p_status;
  END IF;

  IF p_status IN ('nao_instalado', 'concluida_com_pendencia') AND (p_motivo IS NULL OR TRIM(p_motivo) = '') THEN
    RAISE EXCEPTION 'E obrigatorio informar o motivo para status de pendencia ou nao executado.';
  END IF;

  v_placa_limpa := UPPER(TRIM(p_placa));
  v_imei_limpo := NULLIF(TRIM(p_rastreador_imei), '');
  v_iccid_limpo := NULLIF(TRIM(p_chip_iccid), '');

  IF p_status = 'concluida' AND (v_imei_limpo IS NULL OR v_imei_limpo = '') THEN
    RAISE EXCEPTION 'O IMEI do rastreador e obrigatorio para concluir o atendimento.';
  END IF;

  IF p_instalacao_id IS NOT NULL THEN
    SELECT * INTO v_ordem FROM public.instalacoes WHERE id = p_instalacao_id;
    IF FOUND THEN
      v_tipo_servico := COALESCE(v_ordem.tipo_servico, 'instalacao');
      v_instalacao_id := v_ordem.id;
      v_veiculo_id := v_ordem.veiculo_id;
    END IF;
  END IF;

  IF v_tipo_servico = 'retirada' THEN
    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      status = p_status,
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      updated_at = NOW()
    WHERE id = v_instalacao_id;

    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes,
      km_no_atendimento
    ) VALUES (
      v_instalacao_id,
      v_user_id,
      p_status,
      p_motivo,
      p_observacoes,
      p_km_instalacao
    );

    IF p_status = 'concluida' THEN
      IF v_veiculo_id IS NULL AND v_placa_limpa IS NOT NULL THEN
        SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;
      END IF;

      IF v_veiculo_id IS NOT NULL THEN
        UPDATE public.veiculos
        SET
          rastreador_id = NULL,
          rastreador_imei = NULL,
          ativo = FALSE,
          status_operacional = 'desinstalado',
          odometro_km = GREATEST(odometro_km, p_km_instalacao),
          updated_at = NOW()
        WHERE id = v_veiculo_id;
      END IF;

      IF v_imei_limpo IS NOT NULL THEN
        UPDATE public.rastreadores
        SET
          veiculo_id = NULL,
          status = 'estoque'::public.status_rastreador,
          updated_at = NOW()
        WHERE imei = v_imei_limpo;
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'sucesso', TRUE,
      'tipo_servico', 'retirada',
      'instalacao_id', v_instalacao_id,
      'veiculo_id', v_veiculo_id
    );
  END IF;

  IF v_iccid_limpo IS NOT NULL THEN
    SELECT id INTO v_chip_id FROM public.chips WHERE iccid = v_iccid_limpo LIMIT 1;
    IF v_chip_id IS NULL THEN
      INSERT INTO public.chips (iccid, operadora, status)
      VALUES (v_iccid_limpo, COALESCE(NULLIF(TRIM(p_chip_operadora), ''), 'Vivo'), 'ativo')
      RETURNING id INTO v_chip_id;
    END IF;
  END IF;

  IF v_imei_limpo IS NOT NULL THEN
    SELECT id INTO v_rastreador_id FROM public.rastreadores WHERE imei = v_imei_limpo LIMIT 1;
    IF v_rastreador_id IS NULL THEN
      INSERT INTO public.rastreadores (imei, modelo, chip_id, status)
      VALUES (
        v_imei_limpo, 
        COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), 'J16 4G'), 
        v_chip_id, 
        CASE WHEN p_status = 'concluida' THEN 'instalado'::public.status_rastreador ELSE 'estoque'::public.status_rastreador END
      )
      RETURNING id INTO v_rastreador_id;
    ELSE
      UPDATE public.rastreadores
      SET
        chip_id = COALESCE(v_chip_id, chip_id),
        modelo = COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), modelo),
        status = CASE WHEN p_status = 'concluida' THEN 'instalado'::public.status_rastreador ELSE status END,
        updated_at = NOW()
      WHERE id = v_rastreador_id;
    END IF;
  END IF;

  IF p_instalacao_id IS NULL THEN
    SELECT id INTO v_instalador_id FROM public.profiles WHERE id = v_user_id AND role = 'instalador';
    IF v_instalador_id IS NULL THEN
      SELECT instalador_id INTO v_instalador_id FROM public.clientes WHERE id = p_cliente_id;
      IF v_instalador_id IS NULL THEN
        SELECT id INTO v_instalador_id FROM public.profiles WHERE role = 'instalador' AND ativo = TRUE LIMIT 1;
      END IF;
    END IF;

    IF v_instalador_id IS NULL THEN
      RAISE EXCEPTION 'Nao foi possivel determinar o instalador credenciado.';
    END IF;

    SELECT valor_por_instalacao INTO v_valor_unitario FROM public.profiles WHERE id = v_instalador_id;
    v_valor_unitario := COALESCE(v_valor_unitario, 350.00);

    IF p_status = 'concluida' THEN
      v_concluida_at := NOW();
    END IF;

    INSERT INTO public.instalacoes (
      instalador_id,
      cliente_id,
      placa,
      marca,
      modelo,
      ano,
      cor,
      km_instalacao,
      rastreador_imei,
      rastreador_modelo,
      chip_iccid,
      chip_operadora,
      posicao_instalacao,
      status,
      motivo_pendencia_recusa,
      observacoes,
      valor_instalacao,
      concluida_at,
      bloqueador_instalado
    ) VALUES (
      v_instalador_id,
      p_cliente_id,
      v_placa_limpa,
      p_marca,
      p_modelo,
      p_ano,
      p_cor,
      p_km_instalacao,
      v_imei_limpo,
      COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), 'J16 4G'),
      v_iccid_limpo,
      p_chip_operadora,
      p_posicao_instalacao,
      p_status,
      p_motivo,
      p_observacoes,
      v_valor_unitario,
      v_concluida_at,
      v_bloqueador
    )
    RETURNING id INTO v_instalacao_id;
  ELSE
    v_instalacao_id := p_instalacao_id;

    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      cliente_id = COALESCE(p_cliente_id, cliente_id),
      placa = COALESCE(v_placa_limpa, placa),
      marca = COALESCE(p_marca, marca),
      modelo = COALESCE(p_modelo, modelo),
      ano = COALESCE(p_ano, ano),
      cor = COALESCE(p_cor, cor),
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
      rastreador_modelo = COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), rastreador_modelo),
      chip_iccid = COALESCE(v_iccid_limpo, chip_iccid),
      chip_operadora = COALESCE(p_chip_operadora, chip_operadora),
      posicao_instalacao = COALESCE(p_posicao_instalacao, posicao_instalacao),
      status = p_status,
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      bloqueador_instalado = v_bloqueador,
      updated_at = NOW()
    WHERE id = v_instalacao_id;
  END IF;

  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_instalacao_id,
    v_user_id,
    p_status,
    p_motivo,
    p_observacoes,
    p_km_instalacao
  );

  IF p_status = 'concluida' THEN
    SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;

    IF v_veiculo_id IS NULL THEN
      INSERT INTO public.veiculos (
        cliente_id,
        placa,
        marca_modelo,
        ano,
        cor,
        odometro_km,
        rastreador_id,
        rastreador_imei,
        status_operacional,
        ativo,
        bloqueador_instalado
      ) VALUES (
        p_cliente_id,
        v_placa_limpa,
        FORMAT('%s %s', p_marca, p_modelo),
        p_ano,
        p_cor,
        p_km_instalacao,
        v_rastreador_id,
        v_imei_limpo,
        'estacionado',
        TRUE,
        v_bloqueador
      ) RETURNING id INTO v_veiculo_id;

      BEGIN
        PERFORM public.inicializar_itens_manutencao_veiculo(v_veiculo_id, p_km_instalacao);
      EXCEPTION
        WHEN OTHERS THEN NULL;
      END;
    ELSE
      UPDATE public.veiculos
      SET
        cliente_id = COALESCE(p_cliente_id, cliente_id),
        odometro_km = GREATEST(odometro_km, p_km_instalacao),
        rastreador_id = COALESCE(v_rastreador_id, rastreador_id),
        rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
        status_operacional = 'estacionado',
        ativo = TRUE,
        bloqueador_instalado = v_bloqueador,
        updated_at = NOW()
      WHERE id = v_veiculo_id;
    END IF;

    IF v_rastreador_id IS NOT NULL AND v_veiculo_id IS NOT NULL THEN
      UPDATE public.rastreadores
      SET
        veiculo_id = v_veiculo_id,
        status = 'instalado'::public.status_rastreador,
        updated_at = NOW()
      WHERE id = v_rastreador_id;
    END IF;

    UPDATE public.instalacoes
    SET veiculo_id = v_veiculo_id
    WHERE id = v_instalacao_id AND (veiculo_id IS NULL OR veiculo_id <> v_veiculo_id);

    IF p_cliente_id IS NOT NULL THEN
      UPDATE public.clientes
      SET
        status = 'ativo',
        status_agendamento = 'concluido',
        updated_at = NOW()
      WHERE id = p_cliente_id AND status <> 'ativo';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'tipo_servico', 'instalacao',
    'instalacao_id', v_instalacao_id,
    'veiculo_id', v_veiculo_id,
    'bloqueador_instalado', v_bloqueador
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.solicitar_retirada_rastreador TO authenticated;
GRANT EXECUTE ON FUNCTION public.solicitar_remanejamento_rastreador TO authenticated;
GRANT EXECUTE ON FUNCTION public.salvar_atendimento_instalacao TO authenticated;

-- =========================================================================
-- HUNTER: Retorno Automático de Kit e Materiais ao Estoque na Retirada
-- =========================================================================
CREATE OR REPLACE FUNCTION public.obter_itens_instalados_veiculo(p_veiculo_id UUID)
RETURNS TABLE (
  item_id UUID,
  nome TEXT,
  codigo_sku TEXT,
  unidade_medida TEXT,
  quantidade_instalada NUMERIC,
  custo_unitario NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  SELECT 
    m.item_id,
    i.nome,
    i.codigo_sku,
    i.unidade_medida,
    SUM(CASE WHEN m.tipo = 'saida_instalacao' THEN m.quantidade WHEN m.tipo = 'estorno_instalacao' THEN -m.quantidade ELSE 0 END)::NUMERIC AS quantidade_instalada,
    COALESCE(MAX(m.custo_unitario), i.custo_medio_unitario)::NUMERIC AS custo_unitario
  FROM public.estoque_movimentacoes m
  JOIN public.estoque_itens i ON i.id = m.item_id
  WHERE m.veiculo_id = p_veiculo_id
  GROUP BY m.item_id, i.nome, i.codigo_sku, i.unidade_medida, i.custo_medio_unitario
  HAVING SUM(CASE WHEN m.tipo = 'saida_instalacao' THEN m.quantidade WHEN m.tipo = 'estorno_instalacao' THEN -m.quantidade ELSE 0 END) > 0;
END;
$$;

-- =========================================================================
-- HUNTER: Convite de Uso Único e Auto-Cadastro de Instalador Técnico
-- =========================================================================
CREATE TABLE IF NOT EXISTS public.convites_instalador (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  token UUID UNIQUE NOT NULL DEFAULT gen_random_uuid(),
  criado_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  usado BOOLEAN NOT NULL DEFAULT FALSE,
  usado_em TIMESTAMPTZ,
  usado_por_user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  expira_em TIMESTAMPTZ NOT NULL DEFAULT (NOW() + INTERVAL '7 days'),
  observacoes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.convites_instalador ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Operadores e administradores podem gerenciar convites" ON public.convites_instalador;
CREATE POLICY "Operadores e administradores podem gerenciar convites"
  ON public.convites_instalador
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.role IN ('superadmin', 'adm', 'operador')
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.role IN ('superadmin', 'adm', 'operador')
    )
  );

DROP POLICY IF EXISTS "Leitura pública de token de convite válido" ON public.convites_instalador;
CREATE POLICY "Leitura pública de token de convite válido"
  ON public.convites_instalador
  FOR SELECT
  TO public
  USING (usado = FALSE AND expira_em > NOW());

CREATE OR REPLACE FUNCTION public.gerar_convite_instalador(p_observacoes TEXT DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_novo_token UUID;
  v_convite_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autorizado. Faca login no sistema.';
  END IF;

  SELECT role INTO v_role FROM public.profiles WHERE id = v_user_id;
  IF v_role NOT IN ('superadmin', 'adm', 'operador') THEN
    RAISE EXCEPTION 'Apenas operadores e administradores podem gerar links de convite para instalador.';
  END IF;

  INSERT INTO public.convites_instalador (
    criado_por,
    observacoes
  ) VALUES (
    v_user_id,
    p_observacoes
  )
  RETURNING id, token INTO v_convite_id, v_novo_token;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'convite_id', v_convite_id,
    'token', v_novo_token,
    'expira_em', (NOW() + INTERVAL '7 days')
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.validar_convite_instalador(p_token UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
  v_convite RECORD;
BEGIN
  IF p_token IS NULL THEN
    RETURN jsonb_build_object('valido', FALSE, 'mensagem', 'Link de convite invalido.');
  END IF;

  SELECT * INTO v_convite FROM public.convites_instalador WHERE token = p_token;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valido', FALSE, 'mensagem', 'Link de convite nao encontrado ou inexistente.');
  END IF;

  IF v_convite.usado THEN
    RETURN jsonb_build_object('valido', FALSE, 'mensagem', 'Este link de convite ja foi utilizado anteriormente e nao pode ser reutilizado.');
  END IF;

  IF v_convite.expira_em <= NOW() THEN
    RETURN jsonb_build_object('valido', FALSE, 'mensagem', 'Este link de convite expirou o prazo limite de validade.');
  END IF;

  RETURN jsonb_build_object(
    'valido', TRUE,
    'mensagem', 'Convite valido para auto-cadastro de instalador tecnico.',
    'token', v_convite.token,
    'expira_em', v_convite.expira_em
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.cadastrar_instalador_por_convite(
  p_token UUID,
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_telefone TEXT DEFAULT NULL,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
  v_convite RECORD;
  v_user_id UUID;
  v_encrypted_pw TEXT;
  v_email_limpo TEXT;
  v_nome_limpo TEXT;
BEGIN
  IF p_token IS NULL THEN
    RAISE EXCEPTION 'Token de convite obrigatorio.';
  END IF;

  SELECT * INTO v_convite 
  FROM public.convites_instalador 
  WHERE token = p_token 
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Link de convite nao encontrado.';
  END IF;

  IF v_convite.usado THEN
    RAISE EXCEPTION 'Este link de convite ja foi utilizado. Solicite um novo link a administracao.';
  END IF;

  IF v_convite.expira_em <= NOW() THEN
    RAISE EXCEPTION 'Este link de convite expirou.';
  END IF;

  v_nome_limpo := TRIM(p_nome);
  v_email_limpo := LOWER(TRIM(p_email));

  IF v_nome_limpo IS NULL OR v_nome_limpo = '' THEN
    RAISE EXCEPTION 'Nome completo e obrigatorio.';
  END IF;

  IF v_email_limpo IS NULL OR v_email_limpo = '' THEN
    RAISE EXCEPTION 'E-mail e obrigatorio.';
  END IF;

  IF p_senha IS NULL OR LENGTH(p_senha) < 6 THEN
    RAISE EXCEPTION 'A senha deve conter no minimo 6 caracteres.';
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE email = v_email_limpo) THEN
    RAISE EXCEPTION 'Este e-mail ja esta cadastrado no sistema.';
  END IF;

  v_encrypted_pw := crypt(p_senha, gen_salt('bf'));
  v_user_id := gen_random_uuid();

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    v_user_id,
    'authenticated',
    'authenticated',
    v_email_limpo,
    v_encrypted_pw,
    NOW(),
    '{"provider":"email","providers":["email"]}'::JSONB,
    jsonb_build_object(
      'nome', v_nome_limpo,
      'role', 'instalador',
      'telefone', p_telefone
    ),
    NOW(),
    NOW()
  );

  INSERT INTO public.profiles (
    id, nome, email, role, ativo,
    telefone, chave_pix, endereco_instalacao,
    valor_por_instalacao, created_at, updated_at
  ) VALUES (
    v_user_id,
    v_nome_limpo,
    v_email_limpo,
    'instalador',
    FALSE,
    p_telefone,
    p_chave_pix,
    p_endereco_instalacao,
    50.00,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE
  SET
    role = 'instalador',
    ativo = FALSE,
    telefone = EXCLUDED.telefone,
    chave_pix = EXCLUDED.chave_pix,
    endereco_instalacao = EXCLUDED.endereco_instalacao,
    updated_at = NOW();

  INSERT INTO public.user_module_access (user_id, module, ativo)
  VALUES (v_user_id, 'instalacao', TRUE)
  ON CONFLICT (user_id, module) DO NOTHING;

  UPDATE public.convites_instalador
  SET
    usado = TRUE,
    usado_em = NOW(),
    usado_por_user_id = v_user_id
  WHERE id = v_convite.id;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'mensagem', 'Cadastro realizado com sucesso! Sua conta foi enviada para analise e aguarda habilitacao pela administracao.',
    'user_id', v_user_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.gerar_convite_instalador TO authenticated;
GRANT EXECUTE ON FUNCTION public.validar_convite_instalador TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.cadastrar_instalador_por_convite TO anon, authenticated;
