-- ==============================================================================
-- MODO DE PRIVACIDADE CANÔNICA DO HUNTER (PRIVACIDADE ON POR PADRÃO)
-- Blindagem: Somente SuperADM (novaes@adm.28bpm.local) pode desativar
-- ==============================================================================
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'clientes' AND column_name = 'privacidade_localizacao'
    ) THEN
        ALTER TABLE public.clientes ADD COLUMN privacidade_localizacao BOOLEAN NOT NULL DEFAULT true;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'veiculos' AND column_name = 'privacidade_localizacao'
    ) THEN
        ALTER TABLE public.veiculos ADD COLUMN privacidade_localizacao BOOLEAN NOT NULL DEFAULT true;
    END IF;
END $$;

UPDATE public.clientes SET privacidade_localizacao = true WHERE privacidade_localizacao IS NULL;
UPDATE public.veiculos SET privacidade_localizacao = true WHERE privacidade_localizacao IS NULL;

CREATE OR REPLACE FUNCTION public.fn_blindar_privacidade_superadm()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_user_email TEXT;
    v_is_superadm BOOLEAN := FALSE;
    v_is_cliente_titular BOOLEAN := FALSE;
    v_cliente_user_id UUID;
BEGIN
    IF NOT (OLD.privacidade_localizacao = TRUE AND NEW.privacidade_localizacao = FALSE) THEN
        RETURN NEW;
    END IF;

    v_user_id := auth.uid();
    v_user_email := auth.jwt() ->> 'email';

    -- 1. SuperADM imutável
    IF v_user_email = 'novaes@adm.28bpm.local' THEN
        v_is_superadm := TRUE;
    ELSE
        SELECT (role = 'superadmin') INTO v_is_superadm
        FROM public.profiles
        WHERE id = v_user_id;
    END IF;

    IF COALESCE(v_is_superadm, FALSE) THEN
        RETURN NEW;
    END IF;

    -- 2. Cliente titular do registro
    IF TG_TABLE_NAME = 'clientes' THEN
        IF OLD.user_id IS NOT NULL AND OLD.user_id = v_user_id THEN
            v_is_cliente_titular := TRUE;
        END IF;
    ELSIF TG_TABLE_NAME = 'veiculos' THEN
        IF OLD.cliente_id IS NOT NULL THEN
            SELECT user_id INTO v_cliente_user_id
            FROM public.clientes
            WHERE id = OLD.cliente_id;

            IF v_cliente_user_id IS NOT NULL AND v_cliente_user_id = v_user_id THEN
                v_is_cliente_titular := TRUE;
            END IF;
        END IF;
    END IF;

    IF COALESCE(v_is_cliente_titular, FALSE) THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Acesso Negado: Apenas o SuperADM ou o Cliente titular possuem autorização para desmarcar a privacidade de localização do veículo.'
        USING ERRCODE = '42501';

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_blindar_privacidade_clientes ON public.clientes;
CREATE TRIGGER trg_blindar_privacidade_clientes
    BEFORE UPDATE OF privacidade_localizacao ON public.clientes
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_blindar_privacidade_superadm();

DROP TRIGGER IF EXISTS trg_blindar_privacidade_veiculos ON public.veiculos;
CREATE TRIGGER trg_blindar_privacidade_veiculos
    BEFORE UPDATE OF privacidade_localizacao ON public.veiculos
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_blindar_privacidade_superadm();

CREATE OR REPLACE FUNCTION public.fn_sync_privacidade_cliente_veiculos()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    IF NEW.privacidade_localizacao IS DISTINCT FROM OLD.privacidade_localizacao THEN
        UPDATE public.veiculos
        SET privacidade_localizacao = NEW.privacidade_localizacao
        WHERE cliente_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_privacidade_cliente_veiculos ON public.clientes;
CREATE TRIGGER trg_sync_privacidade_cliente_veiculos
    AFTER UPDATE OF privacidade_localizacao ON public.clientes
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_sync_privacidade_cliente_veiculos();

CREATE OR REPLACE FUNCTION public.fn_herdar_privacidade_cliente_novo_veiculo()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_privacidade_cliente BOOLEAN;
BEGIN
    IF NEW.cliente_id IS NOT NULL THEN
        SELECT privacidade_localizacao INTO v_privacidade_cliente
        FROM public.clientes
        WHERE id = NEW.cliente_id;

        IF v_privacidade_cliente IS NOT NULL THEN
            NEW.privacidade_localizacao := v_privacidade_cliente;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_herdar_privacidade_cliente_novo_veiculo ON public.veiculos;
CREATE TRIGGER trg_herdar_privacidade_cliente_novo_veiculo
    BEFORE INSERT ON public.veiculos
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_herdar_privacidade_cliente_novo_veiculo();

-- 2026-09-26: ALTERACAO DE E-MAIL E BLINDAGEM DO SUPERADM CONTRA REGRESSAO DE PRIVILEGIO
DROP FUNCTION IF EXISTS public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[], NUMERIC, TEXT, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[], NUMERIC, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[], NUMERIC, TEXT);
DROP FUNCTION IF EXISTS public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[]);

CREATE OR REPLACE FUNCTION public.admin_atualizar_usuario(
  p_usuario_id UUID,
  p_nome TEXT,
  p_role public.hunter_role,
  p_ativo BOOLEAN,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_mod TEXT;
  v_email_atual TEXT;
  v_email_novo TEXT;
  v_role_atual public.hunter_role;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar usuarios.';
  END IF;

  SELECT email INTO v_email_atual FROM auth.users WHERE id = p_usuario_id;
  SELECT role INTO v_role_atual FROM public.profiles WHERE id = p_usuario_id;

  -- Blindagem canonica do SuperADM (novaes@adm.28bpm.local e novaes@oficial.tec.br):
  IF LOWER(COALESCE(v_email_atual, '')) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br')
     OR p_usuario_id = '00000000-0000-0000-0000-000000000001'::UUID 
     OR v_role_atual = 'superadmin' THEN
    
    UPDATE public.profiles
    SET nome = trim(p_nome),
        role = 'superadmin',
        ativo = TRUE,
        updated_at = now()
    WHERE id = p_usuario_id;

    UPDATE auth.users
    SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome), 'role', 'superadmin'),
        email_confirmed_at = COALESCE(email_confirmed_at, now()),
        updated_at = now()
    WHERE id = p_usuario_id;

    -- Concede todos os modulos da governanca
    DELETE FROM public.user_module_access WHERE user_id = p_usuario_id;
    INSERT INTO public.user_module_access (user_id, module, ativo)
    SELECT p_usuario_id, m, TRUE
    FROM unnest(ARRAY[
      'monitor-gps', 'atendimento', 'clientes', 'rastreadores', 'dispositivos', 
      'instalacao', 'manutencao', 'mensalidades', 'financeiro', 'estoque', 
      'whatsapp', 'temas', 'usuarios'
    ]) AS m;

    RETURN jsonb_build_object(
      'success', TRUE,
      'message', 'Perfil SuperADM atualizado com sucesso. Privilegios e governanca mantidos integralmente.'
    );
  END IF;

  -- Proibição absoluta: apenas os dois emails oficiais podem ser SuperADM
  IF p_role = 'superadmin' THEN
    RAISE EXCEPTION 'Apenas as contas oficiais de governanca (novaes@adm.28bpm.local e novaes@oficial.tec.br) podem ser SuperADM.';
  END IF;

  -- Para outros usuarios: processa alteracao de e-mail se informada
  v_email_novo := LOWER(trim(COALESCE(p_email, v_email_atual)));
  IF v_email_novo IS NOT NULL AND v_email_novo <> '' AND v_email_novo <> LOWER(COALESCE(v_email_atual, '')) THEN
    IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_novo AND id <> p_usuario_id) THEN
      RAISE EXCEPTION 'O e-mail informado ja esta em uso por outro usuario.';
    END IF;

    UPDATE auth.users
    SET email = v_email_novo,
        raw_user_meta_data = raw_user_meta_data || jsonb_build_object('email', v_email_novo),
        updated_at = now()
    WHERE id = p_usuario_id;

    UPDATE auth.identities
    SET identity_data = jsonb_set(identity_data, '{email}', to_jsonb(v_email_novo)),
        provider_id = v_email_novo
    WHERE user_id = p_usuario_id AND provider = 'email';
  END IF;

  UPDATE public.profiles
  SET nome = trim(p_nome),
      email = v_email_novo,
      role = p_role,
      ativo = p_ativo,
      valor_por_instalacao = p_valor_por_instalacao,
      chave_pix = p_chave_pix,
      endereco_instalacao = p_endereco_instalacao,
      updated_at = now()
  WHERE id = p_usuario_id;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (p_usuario_id, p_role)
  ON CONFLICT (user_id, role) DO UPDATE SET role = EXCLUDED.role;

  UPDATE auth.users
  SET raw_user_meta_data = jsonb_build_object('nome', trim(p_nome), 'role', p_role),
      email_confirmed_at = COALESCE(email_confirmed_at, now()),
      updated_at = now()
  WHERE id = p_usuario_id;

  DELETE FROM public.user_module_access WHERE user_id = p_usuario_id;
  IF p_role = 'superadmin' OR p_role = 'adm' THEN
    INSERT INTO public.user_module_access (user_id, module, ativo)
    SELECT p_usuario_id, m, TRUE
    FROM unnest(ARRAY[
      'monitor-gps', 'atendimento', 'clientes', 'rastreadores', 'dispositivos', 
      'instalacao', 'manutencao', 'mensalidades', 'financeiro', 'estoque', 
      'whatsapp', 'temas', 'usuarios'
    ]) AS m;
  ELSIF p_role = 'instalador' THEN
    INSERT INTO public.user_module_access (user_id, module, ativo)
    VALUES (p_usuario_id, 'instalacao', TRUE);
  ELSIF p_modulos IS NOT NULL AND array_length(p_modulos, 1) > 0 THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (p_usuario_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('success', TRUE, 'message', 'Usuario e acessos atualizados com sucesso.');
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_atualizar_cliente_completo(
  p_cliente_id UUID,
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_status public.status_cliente DEFAULT 'aguardando_instalacao',
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_senha TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL,
  p_meses_contrato INT DEFAULT 12,
  p_data_inicio_contrato DATE DEFAULT CURRENT_DATE,
  p_tipo_renovacao TEXT DEFAULT 'mesma_vigencia',
  p_meses_renovacao INT DEFAULT 12,
  p_foro_comarca TEXT DEFAULT 'Volta Redonda/RJ',
  p_gerar_parcelas_ausentes BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID;
  v_email_antigo TEXT;
  v_email_limpo TEXT := LOWER(trim(COALESCE(p_email, '')));
  v_meses_c INT;
  v_data_inicio DATE;
  v_data_fim DATE;
  v_resultado_parcelas JSONB;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  IF p_cliente_id IS NULL THEN
    RAISE EXCEPTION 'ID do cliente e obrigatorio.';
  END IF;

  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  SELECT user_id, email, data_inicio_contrato INTO v_user_id, v_email_antigo, v_data_inicio
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  v_meses_c := GREATEST(1, COALESCE(p_meses_contrato, 12));
  v_data_inicio := COALESCE(p_data_inicio_contrato, v_data_inicio, CURRENT_DATE);
  v_data_fim := (v_data_inicio + (v_meses_c || ' months')::INTERVAL)::DATE;

  -- Se o cliente ja possui usuario cadastrado em auth.users:
  IF v_user_id IS NOT NULL THEN
    IF v_email_limpo <> '' AND v_email_limpo <> LOWER(COALESCE(v_email_antigo, '')) THEN
      IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_limpo AND id <> v_user_id) THEN
        RAISE EXCEPTION 'O e-mail informado ja esta em uso por outro usuario.';
      END IF;

      UPDATE auth.users
      SET email = v_email_limpo,
          raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome), 'email', v_email_limpo),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE public.profiles
      SET email = v_email_limpo,
          nome = trim(p_nome),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.identities
      SET identity_data = jsonb_set(identity_data, '{email}', to_jsonb(v_email_limpo)),
          provider_id = v_email_limpo
      WHERE user_id = v_user_id AND provider = 'email';
    ELSE
      UPDATE public.profiles
      SET nome = trim(p_nome),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.users
      SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    IF p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

  ELSIF v_email_limpo <> '' AND p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
    SELECT id INTO v_user_id FROM auth.users WHERE LOWER(email) = v_email_limpo;
    IF v_user_id IS NULL THEN
      v_user_id := gen_random_uuid();
      INSERT INTO auth.users (
        id, instance_id, aud, role, email, encrypted_password,
        email_confirmed_at, recovery_sent_at, last_sign_in_at,
        raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
        confirmation_token, email_change, email_change_token_new, recovery_token
      ) VALUES (
        v_user_id,
        '00000000-0000-0000-0000-000000000000',
        'authenticated',
        'authenticated',
        v_email_limpo,
        extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
        now(), now(), now(),
        '{"provider":"email","providers":["email"]}',
        jsonb_build_object('nome', trim(p_nome), 'role', 'cliente', 'email', v_email_limpo),
        now(), now(),
        '', '', '', ''
      );

      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id, last_sign_in_at, created_at, updated_at
      ) VALUES (
        gen_random_uuid(),
        v_user_id,
        jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
        'email',
        v_email_limpo,
        now(), now(), now()
      );

      INSERT INTO public.profiles (id, nome, email, role, ativo, created_at, updated_at)
      VALUES (v_user_id, trim(p_nome), v_email_limpo, 'cliente', TRUE, now(), now())
      ON CONFLICT (id) DO UPDATE SET
        nome = trim(p_nome),
        email = v_email_limpo,
        role = 'cliente',
        ativo = TRUE,
        updated_at = now();

      INSERT INTO public.user_roles (user_id, role)
      VALUES (v_user_id, 'cliente')
      ON CONFLICT (user_id, role) DO UPDATE SET role = 'cliente';

      INSERT INTO public.user_module_access (user_id, module, ativo)
      SELECT v_user_id, m, TRUE
      FROM unnest(ARRAY['monitor-gps', 'manutencao', 'mensalidades', 'atendimento']) AS m
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END IF;
  END IF;

  UPDATE public.clientes
  SET nome_razao_social = trim(p_nome),
      documento = NULLIF(trim(p_documento), ''),
      email = NULLIF(v_email_limpo, ''),
      telefone = NULLIF(trim(p_telefone), ''),
      user_id = COALESCE(user_id, v_user_id),
      plano = p_plano,
      status = p_status,
      dia_vencimento = COALESCE(p_dia_vencimento, dia_vencimento),
      valor_mensalidade = COALESCE(p_valor_mensalidade, valor_mensalidade),
      dias_historico_plano = COALESCE(p_dias_historico, dias_historico_plano),
      dias_retencao_banco = COALESCE(p_dias_retencao, dias_retencao_banco),
      instalador_id = p_instalador_id,
      meses_contrato = v_meses_c,
      data_inicio_contrato = v_data_inicio,
      data_fim_contrato = v_data_fim,
      tipo_renovacao = COALESCE(p_tipo_renovacao, tipo_renovacao),
      meses_renovacao = COALESCE(p_meses_renovacao, meses_renovacao),
      foro_comarca = COALESCE(p_foro_comarca, 'Volta Redonda/RJ'),
      updated_at = now()
  WHERE id = p_cliente_id;

  IF p_gerar_parcelas_ausentes THEN
    v_resultado_parcelas := public.admin_gerar_parcelas_contrato(p_cliente_id);
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Dados do cliente e credenciais atualizados com sucesso.',
    'cliente_id', p_cliente_id,
    'user_id', v_user_id,
    'meses_contrato', v_meses_c,
    'data_inicio_contrato', v_data_inicio,
    'data_fim_contrato', v_data_fim,
    'parcelas', v_resultado_parcelas
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_atualizar_usuario TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_atualizar_cliente_completo TO authenticated;

NOTIFY pgrst, 'reload schema';

-- 2026-09-26: BLINDAGEM CANONICA DO EMAIL novaes@oficial.tec.br (SUPERADM INTERCAMBIÁVEL COM novaes@adm.28bpm.local)
CREATE OR REPLACE FUNCTION public.bloquear_mutacao_superadmin()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  IF LOWER(OLD.email) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br') THEN
    IF (TG_OP = 'DELETE') THEN
      RAISE EXCEPTION 'A conta SuperADM e imutavel e nao pode ser excluida.';
    ELSIF (TG_OP = 'UPDATE') THEN
      IF NEW.email <> OLD.email OR NEW.role <> 'superadmin' OR NEW.ativo = FALSE THEN
        RAISE EXCEPTION 'A conta SuperADM nao pode ter seu email, role ou status alterados.';
      END IF;
    END IF;
  ELSE
    -- Nenhuma outra conta pode receber a role de superadmin
    IF (TG_OP = 'UPDATE') THEN
      IF NEW.role = 'superadmin' THEN
        RAISE EXCEPTION 'Apenas os 2 e-mails oficiais de governanca (novaes@adm.28bpm.local e novaes@oficial.tec.br) podem ser SuperADM.';
      END IF;
    END IF;
  END IF;

  IF (TG_OP = 'DELETE') THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_bloquear_mutacao_superadmin ON public.profiles;
CREATE TRIGGER trg_bloquear_mutacao_superadmin
BEFORE UPDATE OR DELETE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION public.bloquear_mutacao_superadmin();

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role public.hunter_role;
  v_nome TEXT;
BEGIN
  IF LOWER(NEW.email) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br') THEN
    v_role := 'superadmin'::public.hunter_role;
    v_nome := COALESCE(NEW.raw_user_meta_data->>'nome', 'SuperADM Novaes');
  ELSE
    v_role := COALESCE(NEW.raw_user_meta_data->>'role', 'cliente')::public.hunter_role;
    v_nome := COALESCE(NEW.raw_user_meta_data->>'nome', split_part(NEW.email, '@', 1));
  END IF;

  INSERT INTO public.profiles (id, nome, email, role, ativo)
  VALUES (NEW.id, v_nome, LOWER(NEW.email), v_role, TRUE)
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      email = EXCLUDED.email,
      role = CASE WHEN LOWER(EXCLUDED.email) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br') THEN 'superadmin'::public.hunter_role ELSE public.profiles.role END;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, v_role)
  ON CONFLICT (user_id, role) DO UPDATE SET role = EXCLUDED.role;

  IF v_role = 'superadmin' THEN
    INSERT INTO public.user_module_access (user_id, module, ativo)
    SELECT NEW.id, m, TRUE
    FROM unnest(ARRAY[
      'monitor-gps', 'atendimento', 'clientes', 'rastreadores', 'dispositivos', 
      'instalacao', 'manutencao', 'mensalidades', 'financeiro', 'estoque', 
      'whatsapp', 'temas', 'usuarios'
    ]) AS m
    ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_excluir_usuario(
  p_user_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_email TEXT;
  v_nome TEXT;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem excluir usuarios.';
  END IF;

  SELECT email, nome INTO v_user_email, v_nome FROM public.profiles WHERE id = p_user_id;

  IF LOWER(v_user_email) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br') OR p_user_id = '00000000-0000-0000-0000-000000000001'::UUID THEN
    RAISE EXCEPTION 'A conta SuperADM e protegida por seguranca cibernetica e nao pode ser excluida.';
  END IF;

  DELETE FROM public.user_module_access WHERE user_id = p_user_id;
  DELETE FROM public.user_roles WHERE user_id = p_user_id;
  DELETE FROM public.profiles WHERE id = p_user_id;
  DELETE FROM auth.identities WHERE user_id = p_user_id;
  DELETE FROM auth.users WHERE id = p_user_id;

  RETURN jsonb_build_object('success', TRUE, 'message', 'Usuario excluido com sucesso.');
END;
$$;

CREATE OR REPLACE FUNCTION public.fn_blindar_privacidade_superadm()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_user_email TEXT;
    v_is_superadm BOOLEAN := FALSE;
    v_is_cliente_titular BOOLEAN := FALSE;
    v_cliente_user_id UUID;
BEGIN
    IF NOT (OLD.privacidade_localizacao = TRUE AND NEW.privacidade_localizacao = FALSE) THEN
        RETURN NEW;
    END IF;

    v_user_id := auth.uid();
    v_user_email := LOWER(COALESCE(auth.jwt() ->> 'email', ''));

    IF v_user_email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br') THEN
        v_is_superadm := TRUE;
    ELSE
        SELECT (role = 'superadmin') INTO v_is_superadm
        FROM public.profiles
        WHERE id = v_user_id;
    END IF;

    IF COALESCE(v_is_superadm, FALSE) THEN
        RETURN NEW;
    END IF;

    IF TG_TABLE_NAME = 'clientes' THEN
        IF OLD.user_id IS NOT NULL AND OLD.user_id = v_user_id THEN
            v_is_cliente_titular := TRUE;
        END IF;
    ELSIF TG_TABLE_NAME = 'veiculos' THEN
        IF OLD.cliente_id IS NOT NULL THEN
            SELECT user_id INTO v_cliente_user_id
            FROM public.clientes
            WHERE id = OLD.cliente_id;

            IF v_cliente_user_id IS NOT NULL AND v_cliente_user_id = v_user_id THEN
                v_is_cliente_titular := TRUE;
            END IF;
        END IF;
    END IF;

    IF COALESCE(v_is_cliente_titular, FALSE) THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Acesso Negado: Apenas o SuperADM ou o Cliente titular possuem autorizacao para desmarcar a privacidade de localizacao do veiculo.'
        USING ERRCODE = '42501';

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.is_adm()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, auth
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = auth.uid() 
      AND (role IN ('superadmin', 'adm') OR email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'))
      AND ativo = TRUE
  )
  OR (LOWER(COALESCE(auth.jwt() ->> 'email', '')) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'));
$$;

NOTIFY pgrst, 'reload schema';

-- ============================================================================
-- HUNTER — NOTIFICAÇÕES NATIVAS E PUSH SINCRONIZADAS VIA BANCO DE DADOS (SUPABASE REALTIME)
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.user_push_subscriptions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  cliente_id UUID REFERENCES public.clientes(id) ON DELETE CASCADE,
  endpoint TEXT NOT NULL UNIQUE,
  p256dh TEXT NOT NULL,
  auth TEXT NOT NULL,
  user_agent TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_user_push_subs_user ON public.user_push_subscriptions(user_id);
CREATE INDEX IF NOT EXISTS idx_user_push_subs_cliente ON public.user_push_subscriptions(cliente_id);

ALTER TABLE public.user_push_subscriptions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Usuarios gerenciam suas proprias inscricoes push" ON public.user_push_subscriptions;
CREATE POLICY "Usuarios gerenciam suas proprias inscricoes push"
  ON public.user_push_subscriptions FOR ALL TO authenticated
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

CREATE TABLE IF NOT EXISTS public.notificacoes_sistema (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  destinatario_user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  destinatario_cliente_id UUID REFERENCES public.clientes(id) ON DELETE CASCADE,
  remetente_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  remetente_nome TEXT,
  dispositivo_origem TEXT,
  titulo TEXT NOT NULL,
  mensagem TEXT NOT NULL,
  tipo TEXT NOT NULL DEFAULT 'alerta',
  url TEXT DEFAULT '/monitor-gps',
  placa TEXT,
  lida BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_notificacoes_dest_user ON public.notificacoes_sistema(destinatario_user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notificacoes_dest_cliente ON public.notificacoes_sistema(destinatario_cliente_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notificacoes_created_at ON public.notificacoes_sistema(created_at DESC);

ALTER TABLE public.notificacoes_sistema ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Usuarios autenticados podem inserir notificacoes" ON public.notificacoes_sistema;
CREATE POLICY "Usuarios autenticados podem inserir notificacoes"
  ON public.notificacoes_sistema FOR INSERT TO authenticated
  WITH CHECK (
    remetente_user_id = auth.uid() OR remetente_user_id IS NULL
  );

DROP POLICY IF EXISTS "Usuarios podem ler suas proprias notificacoes ou administradores leem todas" ON public.notificacoes_sistema;
CREATE POLICY "Usuarios podem ler suas proprias notificacoes ou administradores leem todas"
  ON public.notificacoes_sistema FOR SELECT TO authenticated
  USING (
    destinatario_user_id = auth.uid()
    OR (destinatario_user_id IS NULL AND destinatario_cliente_id IN (
      SELECT id FROM public.clientes WHERE user_id = auth.uid()
    ))
    OR remetente_user_id = auth.uid()
    OR public.is_admin_or_superadmin(auth.uid())
  );

DROP POLICY IF EXISTS "Usuarios podem marcar como lida suas notificacoes" ON public.notificacoes_sistema;
CREATE POLICY "Usuarios podem marcar como lida suas notificacoes"
  ON public.notificacoes_sistema FOR UPDATE TO authenticated
  USING (
    destinatario_user_id = auth.uid()
    OR (destinatario_user_id IS NULL AND destinatario_cliente_id IN (
      SELECT id FROM public.clientes WHERE user_id = auth.uid()
    ))
    OR public.is_admin_or_superadmin(auth.uid())
  )
  WITH CHECK (
    destinatario_user_id = auth.uid()
    OR (destinatario_user_id IS NULL AND destinatario_cliente_id IN (
      SELECT id FROM public.clientes WHERE user_id = auth.uid()
    ))
    OR public.is_admin_or_superadmin(auth.uid())
  );

DO $$
BEGIN
  BEGIN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.notificacoes_sistema;
  EXCEPTION
    WHEN duplicate_object THEN NULL;
  END;

  BEGIN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.user_push_subscriptions;
  EXCEPTION
    WHEN duplicate_object THEN NULL;
  END;
END $$;

CREATE OR REPLACE FUNCTION public.enviar_notificacao_sistema(
  p_destinatario_user_id UUID DEFAULT NULL,
  p_destinatario_cliente_id UUID DEFAULT NULL,
  p_titulo TEXT DEFAULT '🚨 Alerta do Sistema',
  p_mensagem TEXT DEFAULT 'Notificacao do GD Rastreamento',
  p_tipo TEXT DEFAULT 'alerta',
  p_url TEXT DEFAULT '/monitor-gps',
  p_placa TEXT DEFAULT NULL,
  p_dispositivo_origem TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_remetente_id UUID := auth.uid();
  v_remetente_nome TEXT := 'GD Rastreamento';
  v_dest_user UUID := p_destinatario_user_id;
  v_dest_cli UUID := p_destinatario_cliente_id;
  v_notif_id UUID;
BEGIN
  IF v_dest_user IS NULL AND v_dest_cli IS NULL THEN
    v_dest_user := v_remetente_id;
  END IF;

  SELECT nome INTO v_remetente_nome
  FROM public.profiles
  WHERE id = v_remetente_id;

  INSERT INTO public.notificacoes_sistema (
    destinatario_user_id,
    destinatario_cliente_id,
    remetente_user_id,
    remetente_nome,
    dispositivo_origem,
    titulo,
    mensagem,
    tipo,
    url,
    placa
  ) VALUES (
    v_dest_user,
    v_dest_cli,
    v_remetente_id,
    COALESCE(v_remetente_nome, 'Dispositivo Autorizado'),
    p_dispositivo_origem,
    p_titulo,
    p_mensagem,
    p_tipo,
    p_url,
    p_placa
  ) RETURNING id INTO v_notif_id;

  RETURN jsonb_build_object(
    'success', true,
    'notificacao_id', v_notif_id,
    'mensagem', 'Notificacao enviada com sucesso via banco de dados em tempo real.'
  );
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────
-- VISIBILIDADE DE ADMINISTRADORES NO CHAT PARA CLIENTES
-- ─────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.profiles
ADD COLUMN IF NOT EXISTS visivel_no_chat BOOLEAN NOT NULL DEFAULT false;

CREATE OR REPLACE FUNCTION public.alterar_visibilidade_chat(p_visivel BOOLEAN)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE public.profiles
  SET visivel_no_chat = p_visivel,
      updated_at = now()
  WHERE id = auth.uid();

  RETURN true;
END;
$$;

GRANT EXECUTE ON FUNCTION public.alterar_visibilidade_chat(BOOLEAN) TO authenticated;

