ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS bloqueador_instalado BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS bloqueador_instalado BOOLEAN NOT NULL DEFAULT TRUE;
