DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer);

CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id UUID,
  p_rastreador_id UUID,
  p_latitude DOUBLE PRECISION,
  p_longitude DOUBLE PRECISION,
  p_velocidade NUMERIC,
  p_ignicao BOOLEAN,
  p_satelites INT,
  p_rumo INT,
  p_data_hora_gps TIMESTAMPTZ,
  p_inclinacao_graus INT DEFAULT 0,
  p_vibracao_g NUMERIC DEFAULT 0.0,
  p_bateria_veiculo_v NUMERIC DEFAULT NULL,
  p_bateria_rastreador_pct INT DEFAULT NULL,
  p_bateria_rastreador_status TEXT DEFAULT NULL,
  p_sinal_gsm INT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_veiculo RECORD;
  v_dist_metros NUMERIC := 0;
  v_delta_km NUMERIC := 0;
  v_novo_odometro NUMERIC(12, 2);
  v_status_op TEXT;
  v_dlat NUMERIC;
  v_dlon NUMERIC;
  v_a NUMERIC;
BEGIN
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, cliente_id, ultima_atualizacao
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  IF v_veiculo.ultima_latitude IS NOT NULL 
     AND v_veiculo.ultima_longitude IS NOT NULL 
     AND (v_veiculo.ultima_latitude <> 0 OR v_veiculo.ultima_longitude <> 0)
     AND (p_latitude <> 0 OR p_longitude <> 0)
     AND (p_velocidade > 0 OR p_ignicao) THEN
    
    v_dlat := radians(p_latitude - v_veiculo.ultima_latitude);
    v_dlon := radians(p_longitude - v_veiculo.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(v_veiculo.ultima_latitude)) * cos(radians(p_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(1.0 - v_a));

    IF v_dist_metros >= 5.0 AND v_dist_metros < 15000.0 THEN
      v_delta_km := (v_dist_metros / 1000.0);
      v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 2);
    END IF;
  ELSE
    v_delta_km := 0.0;
  END IF;

  v_status_op := CASE
    WHEN p_velocidade > 3 THEN 'em_movimento'
    WHEN p_ignicao THEN 'parado_ligado'
    ELSE 'estacionado'
  END;

  INSERT INTO public.telemetria_posicoes (
    veiculo_id,
    rastreador_id,
    latitude,
    longitude,
    velocidade,
    ignicao,
    odometro,
    satelites,
    rumo,
    data_hora_gps,
    inclinacao_graus,
    vibracao_g,
    bateria_veiculo_v,
    bateria_rastreador_pct,
    bateria_rastreador_status,
    sinal_gsm
  ) VALUES (
    p_veiculo_id,
    p_rastreador_id,
    p_latitude,
    p_longitude,
    p_velocidade,
    p_ignicao,
    v_novo_odometro,
    p_satelites,
    p_rumo,
    p_data_hora_gps,
    p_inclinacao_graus,
    p_vibracao_g,
    p_bateria_veiculo_v,
    p_bateria_rastreador_pct,
    p_bateria_rastreador_status,
    p_sinal_gsm
  );

  UPDATE public.veiculos
  SET
    ultima_latitude = p_latitude,
    ultima_longitude = p_longitude,
    velocidade_atual = p_velocidade,
    ignicao_status = p_ignicao,
    odometro_km = v_novo_odometro,
    satelites = p_satelites,
    rumo = p_rumo,
    inclinacao_graus = p_inclinacao_graus,
    vibracao_g = p_vibracao_g,
    bateria_veiculo_v = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status = COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm = COALESCE(p_sinal_gsm, sinal_gsm),
    status_operacional = v_status_op,
    ultima_atualizacao = p_data_hora_gps,
    updated_at = NOW()
  WHERE id = p_veiculo_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'odometro_anterior', v_veiculo.odometro_km,
    'delta_km', v_delta_km,
    'novo_odometro', v_novo_odometro
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated, service_role, anon;

CREATE OR REPLACE FUNCTION public.verificar_suspeita_jammer(
  p_timeout_minutos INT DEFAULT 10
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_veiculo RECORD;
  v_diff_minutos NUMERIC;
  v_descricao TEXT;
  v_alertas_criados INT := 0;
  v_ultima_notif_at TIMESTAMPTZ;
  v_cliente_user_id UUID;
  v_notif_id UUID;
BEGIN
  FOR v_veiculo IN
    SELECT
      v.id,
      v.cliente_id,
      v.placa,
      v.marca_modelo,
      v.ignicao_status,
      v.velocidade_atual,
      v.ultima_atualizacao,
      v.ultima_latitude,
      v.ultima_longitude,
      EXTRACT(EPOCH FROM (now() - v.ultima_atualizacao)) / 60.0 AS minutos_sem_sinal
    FROM public.veiculos v
    WHERE
      v.ativo = true
      AND v.ultima_atualizacao IS NOT NULL
      AND v.velocidade_atual >= 20
      AND v.ignicao_status = true
      AND (now() - v.ultima_atualizacao) > (p_timeout_minutos * interval '1 minute')
      AND EXISTS (
        SELECT 1
        FROM (
          SELECT tp.ignicao, tp.velocidade
          FROM public.telemetria_posicoes tp
          WHERE tp.veiculo_id = v.id
          ORDER BY tp.data_hora_gps DESC
          LIMIT 1
        ) ult
        WHERE ult.ignicao = true AND ult.velocidade >= 20
      )
  LOOP
    SELECT created_at INTO v_ultima_notif_at
    FROM public.alertas_seguranca
    WHERE
      veiculo_id = v_veiculo.id
      AND tipo = 'suspeita_jammer'
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_ultima_notif_at IS NOT NULL AND
       (now() - v_ultima_notif_at) < interval '15 minutes' THEN
      CONTINUE;
    END IF;

    v_diff_minutos := ROUND(v_veiculo.minutos_sem_sinal::NUMERIC, 1);

    v_descricao := format(
      'Veículo %s (%s) perdeu contato abruptamente enquanto estava em trânsito (%s km/h, ignição ligada). '
      'Ausência de pacotes há %s min sem evento de desligamento normal. '
      'Suspeita de bloqueador de sinal celular/GPS ou sabotagem elétrica.',
      v_veiculo.placa,
      v_veiculo.marca_modelo,
      COALESCE(v_veiculo.velocidade_atual, 0),
      v_diff_minutos
    );

    INSERT INTO public.alertas_seguranca (
      veiculo_id,
      cliente_id,
      tipo,
      gravidade,
      latitude,
      longitude,
      velocidade,
      detalhes,
      reconhecido,
      created_at
    ) VALUES (
      v_veiculo.id,
      v_veiculo.cliente_id,
      'suspeita_jammer',
      'critica',
      COALESCE(v_veiculo.ultima_latitude, 0.0),
      COALESCE(v_veiculo.ultima_longitude, 0.0),
      COALESCE(v_veiculo.velocidade_atual, 0),
      v_descricao,
      false,
      now()
    );

    SELECT user_id INTO v_cliente_user_id
    FROM public.clientes
    WHERE id = v_veiculo.cliente_id
    LIMIT 1;

    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      destinatario_cliente_id,
      titulo,
      mensagem,
      tipo,
      url,
      placa,
      lida,
      created_at
    ) VALUES (
      v_cliente_user_id,
      v_veiculo.cliente_id,
      '🚨 Suspeita de Jammer / Silenciamento Súbito',
      v_descricao,
      'suspeita_jammer',
      '/monitor-gps',
      v_veiculo.placa,
      false,
      now()
    )
    RETURNING id INTO v_notif_id;

    v_alertas_criados := v_alertas_criados + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'sucesso', true,
    'alertas_criados', v_alertas_criados,
    'verificado_em', now()
  );
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[JAMMER-CHECKER] Erro durante verificação de jammers: %', SQLERRM;
  RETURN jsonb_build_object('sucesso', false, 'erro', SQLERRM);
END;
$$;

GRANT EXECUTE ON FUNCTION public.verificar_suspeita_jammer TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

-- ============================================================================
-- MIGRATION: Habilitação de Acesso ao Módulo de Abastecimento/Motorista para Clientes Titulares e Administradores
-- Diretrizes: DJR-NEW · RLS Estrito · Zero Mock · Anti-Polling
-- ============================================================================

-- 1. Atualiza get_meu_perfil_motorista para suportar:
--    a) Motorista cadastrado na tabela motoristas (prioridade operacional)
--    b) Cliente titular na tabela clientes (acesso direto do dono/gestor do veículo)
--    c) SuperADM/ADM/Operador (acesso administrativo ao portal)
CREATE OR REPLACE FUNCTION public.get_meu_perfil_motorista()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_email TEXT;
  v_result JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessao expirada. Faca login novamente.';
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;

  -- Auto-cura: se o motorista foi cadastrado com este e-mail mas user_id ficou divergente
  UPDATE public.motoristas
  SET user_id = v_uid
  WHERE user_id IS DISTINCT FROM v_uid
    AND LOWER(email) = LOWER(v_email)
    AND ativo = TRUE;

  -- 1. Tenta encontrar perfil de motorista direto
  SELECT jsonb_build_object(
    'id',            m.id,
    'nome',          m.nome,
    'email',         m.email,
    'cpf',           m.cpf,
    'telefone',      m.telefone,
    'cnh_numero',    m.cnh_numero,
    'cnh_categoria', m.cnh_categoria,
    'cnh_validade',  m.cnh_validade,
    'cnh_foto_url',  m.cnh_foto_url,
    'acesso_mapa',   m.acesso_mapa,
    'cliente_id',    m.cliente_id,
    'cliente_nome',  c.nome_razao_social
  )
  INTO v_result
  FROM public.motoristas m
  INNER JOIN public.clientes c ON c.id = m.cliente_id
  WHERE m.user_id = v_uid AND m.ativo = TRUE
  LIMIT 1;

  -- 2. Se não encontrou motorista, verifica se o usuário é o próprio CLIENTE titular
  IF v_result IS NULL THEN
    SELECT jsonb_build_object(
      'id',            c.id,
      'nome',          c.nome_razao_social,
      'email',         COALESCE(c.email, v_email),
      'cpf',           c.documento,
      'telefone',      c.telefone,
      'cnh_numero',    NULL,
      'cnh_categoria', NULL,
      'cnh_validade',  NULL,
      'cnh_foto_url',  NULL,
      'acesso_mapa',   TRUE,
      'cliente_id',    c.id,
      'cliente_nome',  c.nome_razao_social
    )
    INTO v_result
    FROM public.clientes c
    WHERE c.user_id = v_uid AND (c.status = 'ativo' OR c.status IS NULL)
    LIMIT 1;
  END IF;

  -- 3. Se for SuperADM / ADM / Operador, provê acesso administrativo
  IF v_result IS NULL AND EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_uid AND role IN ('superadmin','adm','operador')
  ) THEN
    SELECT jsonb_build_object(
      'id',            c.id,
      'nome',          'Gestão (' || c.nome_razao_social || ')',
      'email',         v_email,
      'cpf',           c.documento,
      'telefone',      c.telefone,
      'cnh_numero',    NULL,
      'cnh_categoria', NULL,
      'cnh_validade',  NULL,
      'cnh_foto_url',  NULL,
      'acesso_mapa',   TRUE,
      'cliente_id',    c.id,
      'cliente_nome',  c.nome_razao_social
    )
    INTO v_result
    FROM public.clientes c
    WHERE (c.status = 'ativo' OR c.status IS NULL)
    ORDER BY c.created_at ASC
    LIMIT 1;
  END IF;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Perfil de motorista ou cliente nao encontrado.';
  END IF;

  RETURN v_result;
END;
$$;

-- 2. Atualiza listar_veiculos_portal_motorista para suportar clientes titulares e administradores
CREATE OR REPLACE FUNCTION public.listar_veiculos_portal_motorista()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_motorista_id UUID;
  v_cliente_id UUID;
  v_tem_vinculo BOOLEAN;
  v_result JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  -- 1. Tenta identificar se o usuário é um motorista cadastrado
  SELECT id, cliente_id INTO v_motorista_id, v_cliente_id
  FROM public.motoristas
  WHERE user_id = v_uid AND ativo = TRUE
  LIMIT 1;

  -- 2. Se não for motorista, verifica se é o próprio CLIENTE titular
  IF v_motorista_id IS NULL THEN
    SELECT id INTO v_cliente_id
    FROM public.clientes
    WHERE user_id = v_uid AND (status = 'ativo' OR status IS NULL)
    LIMIT 1;

    -- Se for admin/superadmin e não for cliente direto, busca primeiro cliente ativo
    IF v_cliente_id IS NULL AND EXISTS (
      SELECT 1 FROM public.profiles WHERE id = v_uid AND role IN ('superadmin','adm','operador')
    ) THEN
      SELECT id INTO v_cliente_id FROM public.clientes WHERE (status = 'ativo' OR status IS NULL) ORDER BY created_at ASC LIMIT 1;
    END IF;

    IF v_cliente_id IS NOT NULL THEN
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'id', v.id,
          'motorista_id', NULL,
          'veiculo_id', v.id,
          'ativo', TRUE,
          'created_at', v.created_at,
          'veiculo_placa', v.placa,
          'veiculo_modelo', v.marca_modelo,
          'veiculo_cor', v.cor,
          'odometro_km', COALESCE(v.odometro_km, 0),
          'ultima_latitude', v.ultima_latitude,
          'ultima_longitude', v.ultima_longitude,
          'ignicao_status', COALESCE(v.ignicao_status, FALSE),
          'velocidade_atual', COALESCE(v.velocidade_atual, 0)
        ) ORDER BY v.placa ASC
      ), '[]'::jsonb)
      INTO v_result
      FROM public.veiculos v
      WHERE v.cliente_id = v_cliente_id
        AND v.ativo = TRUE;

      RETURN COALESCE(v_result, '[]'::jsonb);
    END IF;

    RETURN '[]'::jsonb;
  END IF;

  -- 3. Caso seja motorista com vínculos específicos na tabela motorista_veiculos
  SELECT EXISTS (
    SELECT 1 FROM public.motorista_veiculos
    WHERE motorista_id = v_motorista_id AND ativo = TRUE
  ) INTO v_tem_vinculo;

  IF v_tem_vinculo THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', mv.id,
        'motorista_id', mv.motorista_id,
        'veiculo_id', v.id,
        'ativo', mv.ativo,
        'created_at', mv.created_at,
        'veiculo_placa', v.placa,
        'veiculo_modelo', v.marca_modelo,
        'veiculo_cor', v.cor,
        'odometro_km', COALESCE(v.odometro_km, 0),
        'ultima_latitude', v.ultima_latitude,
        'ultima_longitude', v.ultima_longitude,
        'ignicao_status', COALESCE(v.ignicao_status, FALSE),
        'velocidade_atual', COALESCE(v.velocidade_atual, 0)
      ) ORDER BY v.placa ASC
    ), '[]'::jsonb)
    INTO v_result
    FROM public.motorista_veiculos mv
    INNER JOIN public.veiculos v ON v.id = mv.veiculo_id
    WHERE mv.motorista_id = v_motorista_id
      AND mv.ativo = TRUE
      AND v.ativo = TRUE;
  ELSE
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', v.id,
        'motorista_id', v_motorista_id,
        'veiculo_id', v.id,
        'ativo', TRUE,
        'created_at', v.created_at,
        'veiculo_placa', v.placa,
        'veiculo_modelo', v.marca_modelo,
        'veiculo_cor', v.cor,
        'odometro_km', COALESCE(v.odometro_km, 0),
        'ultima_latitude', v.ultima_latitude,
        'ultima_longitude', v.ultima_longitude,
        'ignicao_status', COALESCE(v.ignicao_status, FALSE),
        'velocidade_atual', COALESCE(v.velocidade_atual, 0)
      ) ORDER BY v.placa ASC
    ), '[]'::jsonb)
    INTO v_result
    FROM public.veiculos v
    WHERE v.cliente_id = v_cliente_id
      AND v.ativo = TRUE;
  END IF;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_meu_perfil_motorista TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.listar_veiculos_portal_motorista TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';

-- =============================================================================
-- HUNTER — MOTOR DE ODOMETRIA GPS DE ALTA PRECISÃO FÍSICA (DJR-NEW)
-- Versão da Migração: 20261006093000_hunter_motor_odometria_gps_precisao_estrita.sql
-- =============================================================================
ALTER TABLE public.viagens_trajetos 
ADD COLUMN IF NOT EXISTS distance_raw_km NUMERIC(10, 2) DEFAULT 0.00,
ADD COLUMN IF NOT EXISTS pontos_descartados INT DEFAULT 0;

DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer);

CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id UUID,
  p_rastreador_id UUID DEFAULT NULL,
  p_latitude DOUBLE PRECISION DEFAULT 0.0,
  p_longitude DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade NUMERIC DEFAULT 0,
  p_ignicao BOOLEAN DEFAULT FALSE,
  p_satelites INT DEFAULT 0,
  p_rumo INT DEFAULT 0,
  p_data_hora_gps TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus INT DEFAULT 0,
  p_vibracao_g NUMERIC DEFAULT 0.0,
  p_bateria_veiculo_v NUMERIC DEFAULT NULL,
  p_bateria_rastreador_pct INT DEFAULT NULL,
  p_bateria_rastreador_status TEXT DEFAULT NULL,
  p_sinal_gsm INT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_veiculo RECORD;
  v_ultima_telemetria RECORD;
  v_dist_metros DOUBLE PRECISION := 0.0;
  v_delta_km NUMERIC(12, 4) := 0.0000;
  v_novo_odometro NUMERIC(12, 3);
  v_status_op TEXT;
  v_dlat DOUBLE PRECISION;
  v_dlon DOUBLE PRECISION;
  v_a DOUBLE PRECISION;
  v_delta_sec DOUBLE PRECISION := 0.0;
  v_vel_calculada DOUBLE PRECISION := 0.0;
  v_is_spike BOOLEAN := false;
  v_is_drift BOOLEAN := false;
  v_pontos_descartados INT := 0;
  v_viagem_ativa_id UUID;
  v_raio_local DOUBLE PRECISION := 6374900.0; -- Raio geocêntrico no elipsoide WGS-84 (~22.5°S)
BEGIN
  -- Trava a linha do veículo para evitar concorrência em alta taxa de telemetria
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, cliente_id, ultima_atualizacao
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  -- Busca o último ponto gravado para calcular intervalo de tempo e rejeitar duplicatas/spikes
  SELECT latitude, longitude, data_hora_gps, velocidade
  INTO v_ultima_telemetria
  FROM public.telemetria_posicoes
  WHERE veiculo_id = p_veiculo_id
  ORDER BY data_hora_gps DESC
  LIMIT 1;

  -- ─────────────────────────────────────────────────────────────────────────
  -- CÁLCULO GEODÉSICO ELIPSOIDAL WGS-84 E MOTOR ANTI-DRIFT
  -- ─────────────────────────────────────────────────────────────────────────
  IF v_veiculo.ultima_latitude IS NOT NULL 
     AND v_veiculo.ultima_longitude IS NOT NULL 
     AND (v_veiculo.ultima_latitude <> 0 OR v_veiculo.ultima_longitude <> 0)
     AND (p_latitude <> 0 OR p_longitude <> 0)
     AND p_latitude BETWEEN -90.0 AND 90.0
     AND p_longitude BETWEEN -180.0 AND 180.0 THEN
    
    v_dlat := radians(p_latitude - v_veiculo.ultima_latitude);
    v_dlon := radians(p_longitude - v_veiculo.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(v_veiculo.ultima_latitude)) * cos(radians(p_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := v_raio_local * 2.0 * atan2(sqrt(v_a), sqrt(1.0 - v_a));

    IF v_ultima_telemetria.data_hora_gps IS NOT NULL THEN
      v_delta_sec := EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telemetria.data_hora_gps));
    ELSE
      v_delta_sec := 10.0;
    END IF;

    -- 1. Validação de Outliers / Spikes Físicos
    IF v_delta_sec > 0 THEN
      v_vel_calculada := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calculada > 190.0 AND (p_velocidade IS NULL OR p_velocidade < 150.0) THEN
        v_is_spike := true;
      END IF;
    END IF;

    -- 2. Máquina de Estados Anti-Drift com Histerese
    IF NOT p_ignicao AND p_velocidade <= 2.5 THEN
      v_is_drift := true;
    ELSIF p_velocidade <= 2.5 AND v_dist_metros < 15.0 THEN
      v_is_drift := true;
    END IF;

    -- 3. Acumulação Física Real (Sem Fatores Arbitrários)
    IF NOT v_is_spike AND NOT v_is_drift AND v_dist_metros >= 1.5 AND v_dist_metros < 15000.0 THEN
      v_delta_km := (v_dist_metros / 1000.0)::NUMERIC;
      v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);
    ELSE
      v_delta_km := 0.0000;
      IF v_is_spike OR v_is_drift THEN
        v_pontos_descartados := 1;
      END IF;
    END IF;
  ELSE
    v_delta_km := 0.0000;
  END IF;

  -- Determina status operacional
  v_status_op := CASE
    WHEN p_velocidade > 2.5 THEN 'em_movimento'
    WHEN p_ignicao THEN 'parado_ligado'
    ELSE 'estacionado'
  END;

  -- 1. Insere histórico na tabela telemetria_posicoes
  INSERT INTO public.telemetria_posicoes (
    veiculo_id,
    rastreador_id,
    latitude,
    longitude,
    velocidade,
    ignicao,
    odometro,
    satelites,
    rumo,
    data_hora_gps,
    inclinacao_graus,
    vibracao_g,
    bateria_veiculo_v,
    bateria_rastreador_pct,
    bateria_rastreador_status,
    sinal_gsm
  ) VALUES (
    p_veiculo_id,
    p_rastreador_id,
    p_latitude,
    p_longitude,
    p_velocidade,
    p_ignicao,
    v_novo_odometro,
    p_satelites,
    p_rumo,
    p_data_hora_gps,
    p_inclinacao_graus,
    p_vibracao_g,
    p_bateria_veiculo_v,
    p_bateria_rastreador_pct,
    p_bateria_rastreador_status,
    p_sinal_gsm
  );

  -- 2. Atualiza os dados instantâneos no veículo (dispara Realtime via WebSocket)
  UPDATE public.veiculos
  SET
    ultima_latitude = p_latitude,
    ultima_longitude = p_longitude,
    velocidade_atual = p_velocidade,
    ignicao_status = p_ignicao,
    odometro_km = v_novo_odometro,
    satelites = p_satelites,
    rumo = p_rumo,
    inclinacao_graus = p_inclinacao_graus,
    vibracao_g = p_vibracao_g,
    bateria_veiculo_v = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status = COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm = COALESCE(p_sinal_gsm, sinal_gsm),
    status_operacional = v_status_op,
    ultima_atualizacao = p_data_hora_gps,
    updated_at = NOW()
  WHERE id = p_veiculo_id;

  -- 3. Atualiza quilometragem da viagem em andamento atômica (estritamente a mais recente)
  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 3),
        distance_raw_km = ROUND((COALESCE(distance_raw_km, 0) + (v_dist_metros / 1000.0)::NUMERIC)::NUMERIC, 3),
        pontos_descartados = COALESCE(pontos_descartados, 0) + v_pontos_descartados,
        velocidade_maxima = GREATEST(COALESCE(velocidade_maxima, 0), p_velocidade)
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'odometro_anterior', v_veiculo.odometro_km,
    'delta_km', ROUND(v_delta_km::NUMERIC, 4),
    'novo_odometro', v_novo_odometro,
    'is_drift', v_is_drift,
    'is_spike', v_is_spike
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated, service_role, anon;

-- Gatilho de Autodefesa: fecha automaticamente qualquer viagem em andamento antes de abrir uma nova
CREATE OR REPLACE FUNCTION public.trg_garantir_uma_viagem_em_andamento()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.status = 'em_andamento' THEN
    UPDATE public.viagens_trajetos
    SET status = 'concluido',
        fim_at = COALESCE(NEW.inicio_at, NOW())
    WHERE veiculo_id = NEW.veiculo_id
      AND status = 'em_andamento'
      AND (NEW.id IS NULL OR id <> NEW.id);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_viagens_garantir_uma_ativa ON public.viagens_trajetos;
CREATE TRIGGER trg_viagens_garantir_uma_ativa
BEFORE INSERT ON public.viagens_trajetos
FOR EACH ROW
EXECUTE FUNCTION public.trg_garantir_uma_viagem_em_andamento();

-- Índice Único Parcial: garante a nível físico de tabela apenas 1 viagem em andamento por veículo
DROP INDEX IF EXISTS public.idx_viagens_uma_ativa_por_veiculo;
CREATE UNIQUE INDEX IF NOT EXISTS idx_viagens_uma_ativa_por_veiculo
ON public.viagens_trajetos (veiculo_id)
WHERE status = 'em_andamento';

NOTIFY pgrst, 'reload schema';

-- =============================================================================
-- HUNTER — BLINDAGEM ANTI-DUPLICIDADE DE ABASTECIMENTOS E DESPESAS (DJR-NEW)
-- Versão da Migração: 20261005120000_hunter_anti_duplicidade_abastecimentos_e_despesas.sql
-- =============================================================================
-- 1. Saneamento preventivo: remove duplicidades legadas em motorista_abastecimentos
--    mantendo sempre o registro que contém anexo de NF ou o mais recente.
-- 2. Saneamento preventivo em motorista_despesas.
-- 3. Índices Únicos Parciais no PostgreSQL:
--    - idx_abast_unico_nf: (veiculo_id, UPPER(TRIM(nf_numero))) onde nf_numero não é nulo/vazio.
--    - idx_abast_unico_sem_nf: (veiculo_id, data_abastecimento, km_atual, valor_total, litros) onde nf_numero é nulo/vazio.
--    - idx_despesas_unico_nf: (veiculo_id, UPPER(TRIM(nf_numero))) onde nf_numero não é nulo/vazio.
--    - idx_despesas_unico_sem_nf: (veiculo_id, data_despesa, valor, UPPER(TRIM(descricao))) onde nf_numero é nulo/vazio.
-- 4. Notificação de reload de schema ao PostgREST.
-- =============================================================================

-- 1. Saneamento em motorista_abastecimentos (mantém a linha com anexo ou mais recente)
DELETE FROM public.motorista_abastecimentos a
WHERE a.id IN (
  SELECT id FROM (
    SELECT id,
           ROW_NUMBER() OVER (
             PARTITION BY veiculo_id, UPPER(TRIM(nf_numero))
             ORDER BY (nf_foto_url IS NOT NULL) DESC, created_at DESC
           ) as rn
    FROM public.motorista_abastecimentos
    WHERE nf_numero IS NOT NULL AND TRIM(nf_numero) <> ''
  ) dupes
  WHERE dupes.rn > 1
);

DELETE FROM public.motorista_abastecimentos a
WHERE a.id IN (
  SELECT id FROM (
    SELECT id,
           ROW_NUMBER() OVER (
             PARTITION BY veiculo_id, data_abastecimento, km_atual, valor_total, litros
             ORDER BY (nf_foto_url IS NOT NULL) DESC, created_at DESC
           ) as rn
    FROM public.motorista_abastecimentos
    WHERE nf_numero IS NULL OR TRIM(nf_numero) = ''
  ) dupes
  WHERE dupes.rn > 1
);

-- 2. Saneamento em motorista_despesas
DELETE FROM public.motorista_despesas d
WHERE d.id IN (
  SELECT id FROM (
    SELECT id,
           ROW_NUMBER() OVER (
             PARTITION BY veiculo_id, UPPER(TRIM(nf_numero))
             ORDER BY (nf_foto_url IS NOT NULL) DESC, created_at DESC
           ) as rn
    FROM public.motorista_despesas
    WHERE nf_numero IS NOT NULL AND TRIM(nf_numero) <> ''
  ) dupes
  WHERE dupes.rn > 1
);

DELETE FROM public.motorista_despesas d
WHERE d.id IN (
  SELECT id FROM (
    SELECT id,
           ROW_NUMBER() OVER (
             PARTITION BY veiculo_id, data_despesa, valor, UPPER(TRIM(descricao))
             ORDER BY (nf_foto_url IS NOT NULL) DESC, created_at DESC
           ) as rn
    FROM public.motorista_despesas
    WHERE nf_numero IS NULL OR TRIM(nf_numero) = ''
  ) dupes
  WHERE dupes.rn > 1
);

-- 3. Índices Únicos Parciais no PostgreSQL

-- Abastecimentos com NF informada: apenas 1 por veículo e NF
DROP INDEX IF EXISTS public.idx_abast_unico_nf;
CREATE UNIQUE INDEX IF NOT EXISTS idx_abast_unico_nf
ON public.motorista_abastecimentos (veiculo_id, UPPER(TRIM(nf_numero)))
WHERE nf_numero IS NOT NULL AND TRIM(nf_numero) <> '';

-- Abastecimentos sem NF informada: impede inserção duplicada idêntica (duplo clique / replay)
DROP INDEX IF EXISTS public.idx_abast_unico_sem_nf;
CREATE UNIQUE INDEX IF NOT EXISTS idx_abast_unico_sem_nf
ON public.motorista_abastecimentos (veiculo_id, data_abastecimento, km_atual, valor_total, litros)
WHERE (nf_numero IS NULL OR TRIM(nf_numero) = '') AND km_atual IS NOT NULL;

-- Despesas com NF informada: apenas 1 por veículo e NF
DROP INDEX IF EXISTS public.idx_despesas_unico_nf;
CREATE UNIQUE INDEX IF NOT EXISTS idx_despesas_unico_nf
ON public.motorista_despesas (veiculo_id, UPPER(TRIM(nf_numero)))
WHERE nf_numero IS NOT NULL AND TRIM(nf_numero) <> '';

-- Despesas sem NF informada: impede lançamento duplo com mesmos atributos
DROP INDEX IF EXISTS public.idx_despesas_unico_sem_nf;
CREATE UNIQUE INDEX IF NOT EXISTS idx_despesas_unico_sem_nf
ON public.motorista_despesas (veiculo_id, data_despesa, valor, UPPER(TRIM(descricao)))
WHERE nf_numero IS NULL OR TRIM(nf_numero) = '';

-- 4. Notificar PostgREST
NOTIFY pgrst, 'reload schema';

-- =============================================================================
-- HUNTER — SUPORTE OFICIAL AOS TIPOS DE VEÍCULO 'VAN' E 'AMBULANCIA' (DJR-NEW)
-- Versão da Migração: 20261006150000_hunter_add_van_e_ambulancia_tipo_veiculo.sql
-- =============================================================================
ALTER TABLE public.veiculos DROP CONSTRAINT IF EXISTS chk_tipo_veiculo;
ALTER TABLE public.veiculos ADD CONSTRAINT chk_tipo_veiculo 
CHECK (tipo_veiculo IN ('jetski', 'carro', 'suv', 'camionete', 'van', 'ambulancia', 'caminhao', 'onibus', 'moto', 'quadriciculo', 'triciclo'));

CREATE OR REPLACE FUNCTION public.admin_editar_veiculo(
  p_veiculo_id UUID,
  p_placa TEXT,
  p_marca_modelo TEXT,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_tipo_veiculo TEXT DEFAULT 'carro'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_placa_limpa TEXT;
  v_tipo_sanitizado TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;
    IF v_role NOT IN ('superadmin', 'operador') THEN
      RAISE EXCEPTION 'Apenas administradores e operadores podem editar veículos.';
    END IF;
  END IF;

  v_placa_limpa := UPPER(REGEXP_REPLACE(p_placa, '[^A-Za-z0-9]', '', 'g'));
  IF v_placa_limpa IS NULL OR LENGTH(v_placa_limpa) < 3 THEN
    RAISE EXCEPTION 'Placa inválida para o veículo.';
  END IF;

  v_tipo_sanitizado := LOWER(COALESCE(p_tipo_veiculo, 'carro'));
  IF v_tipo_sanitizado NOT IN ('jetski', 'carro', 'suv', 'camionete', 'van', 'ambulancia', 'caminhao', 'onibus', 'moto', 'quadriciculo', 'triciclo') THEN
    v_tipo_sanitizado := 'carro';
  END IF;

  UPDATE public.veiculos
  SET
    placa = v_placa_limpa,
    marca_modelo = TRIM(p_marca_modelo),
    ano = p_ano,
    cor = TRIM(p_cor),
    tipo_veiculo = v_tipo_sanitizado,
    updated_at = NOW()
  WHERE id = p_veiculo_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo_id', p_veiculo_id,
    'placa', v_placa_limpa,
    'tipo_veiculo', v_tipo_sanitizado,
    'mensagem', 'Dados do veículo atualizados com sucesso.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_editar_veiculo TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_editar_veiculo TO service_role;

NOTIFY pgrst, 'reload schema';

-- =============================================================================
-- MIGRATION: 20261006151500_hunter_fix_bloqueio_admin_schema_e_rpc.sql
-- GD RASTREAMENTO — Correção da RPC e Recarga do Cache de Schema de Bloqueio Admin
-- =============================================================================
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'clientes' AND column_name = 'status_bloqueio_localizacao'
    ) THEN
        ALTER TABLE public.clientes 
        ADD COLUMN status_bloqueio_localizacao TEXT NOT NULL DEFAULT 'automatico'
        CHECK (status_bloqueio_localizacao IN ('automatico', 'bloqueado', 'liberado'));
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'clientes' AND column_name = 'status_bloqueio_acesso'
    ) THEN
        ALTER TABLE public.clientes 
        ADD COLUMN status_bloqueio_acesso TEXT NOT NULL DEFAULT 'automatico'
        CHECK (status_bloqueio_acesso IN ('automatico', 'bloqueado', 'liberado'));
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'clientes' AND column_name = 'motivo_bloqueio_manual'
    ) THEN
        ALTER TABLE public.clientes ADD COLUMN motivo_bloqueio_manual TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'clientes' AND column_name = 'bloqueio_atualizado_em'
    ) THEN
        ALTER TABLE public.clientes ADD COLUMN bloqueio_atualizado_em TIMESTAMPTZ DEFAULT timezone('utc'::text, now());
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'clientes' AND column_name = 'bloqueio_atualizado_por'
    ) THEN
        ALTER TABLE public.clientes ADD COLUMN bloqueio_atualizado_por UUID;
    END IF;
END $$;

CREATE OR REPLACE FUNCTION public.fn_atualizar_timestamp_bloqueio_cliente()
RETURNS TRIGGER AS $$
BEGIN
    IF (OLD.status_bloqueio_localizacao IS DISTINCT FROM NEW.status_bloqueio_localizacao) OR
       (OLD.status_bloqueio_acesso IS DISTINCT FROM NEW.status_bloqueio_acesso) THEN
        NEW.bloqueio_atualizado_em := timezone('utc'::text, now());
        IF auth.uid() IS NOT NULL THEN
            NEW.bloqueio_atualizado_por := auth.uid();
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS trg_atualizar_timestamp_bloqueio_cliente ON public.clientes;
CREATE TRIGGER trg_atualizar_timestamp_bloqueio_cliente
    BEFORE UPDATE ON public.clientes
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_atualizar_timestamp_bloqueio_cliente();

CREATE OR REPLACE FUNCTION public.atualizar_bloqueio_administrativo_cliente(
    p_cliente_id UUID,
    p_status_localizacao TEXT,
    p_status_acesso TEXT,
    p_motivo TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
    v_user_role TEXT;
    v_is_superadmin BOOLEAN;
    v_resp JSONB;
BEGIN
    IF p_status_localizacao NOT IN ('automatico', 'bloqueado', 'liberado') THEN
        RAISE EXCEPTION 'status_localizacao inválido: %', p_status_localizacao;
    END IF;

    IF p_status_acesso NOT IN ('automatico', 'bloqueado', 'liberado') THEN
        RAISE EXCEPTION 'status_acesso inválido: %', p_status_acesso;
    END IF;

    SELECT role::TEXT INTO v_user_role FROM public.profiles WHERE id = auth.uid();
    v_is_superadmin := (auth.jwt() ->> 'email' IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br')) 
                       OR (v_user_role = 'superadmin');

    IF NOT (v_is_superadmin OR v_user_role IN ('adm', 'operador')) THEN
        RAISE EXCEPTION 'Acesso negado: apenas Operador, Administrador ou SuperADM podem alterar o bloqueio administrativo.';
    END IF;

    UPDATE public.clientes
    SET status_bloqueio_localizacao = p_status_localizacao,
        status_bloqueio_acesso = p_status_acesso,
        motivo_bloqueio_manual = p_motivo,
        bloqueio_atualizado_em = timezone('utc'::text, now()),
        bloqueio_atualizado_por = auth.uid(),
        updated_at = timezone('utc'::text, now())
    WHERE id = p_cliente_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cliente não encontrado com ID: %', p_cliente_id;
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'system_activity_logs') THEN
        INSERT INTO public.system_activity_logs (
            usuario_id,
            acao,
            detalhes,
            created_at
        ) VALUES (
            auth.uid(),
            'ALTERAR_BLOQUEIO_ADMINISTRATIVO',
            jsonb_build_object(
                'cliente_id', p_cliente_id,
                'status_localizacao', p_status_localizacao,
                'status_acesso', p_status_acesso,
                'motivo', p_motivo
            ),
            timezone('utc'::text, now())
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'cliente_id', p_cliente_id,
        'status_localizacao', p_status_localizacao,
        'status_acesso', p_status_acesso,
        'motivo', p_motivo
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.atualizar_bloqueio_administrativo_cliente(UUID, TEXT, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.atualizar_bloqueio_administrativo_cliente(UUID, TEXT, TEXT, TEXT) TO service_role;

-- ============================================================================
-- HUNTER — CORREÇÃO: PRIMEIRO ACESSO DO INSTALADOR E AGENDAMENTO DE INSTALAÇÕES
-- ============================================================================
-- 1. Sincronizar perfis de instaladores auto-cadastrados (primeiro_acesso = FALSE)
UPDATE public.profiles
SET primeiro_acesso = FALSE
WHERE id IN (
  SELECT usado_por_user_id 
  FROM public.convites_instalador 
  WHERE usado_por_user_id IS NOT NULL
);

UPDATE public.profiles
SET primeiro_acesso = FALSE
WHERE role = 'instalador'
  AND id IN (
    SELECT id FROM auth.users 
    WHERE raw_user_meta_data->>'convite_token' IS NOT NULL
  );

-- 2. Garantir user_roles e user_module_access para todos os instaladores cadastrados
INSERT INTO public.user_roles (user_id, role)
SELECT id, 'instalador'::public.hunter_role
FROM public.profiles
WHERE role = 'instalador'
ON CONFLICT (user_id, role) DO NOTHING;

INSERT INTO public.user_module_access (user_id, module, ativo)
SELECT id, 'instalacao', TRUE
FROM public.profiles
WHERE role = 'instalador'
ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;

-- 3. Atualizar RPC cadastrar_instalador_por_convite
CREATE OR REPLACE FUNCTION public.cadastrar_instalador_por_convite(
  p_token TEXT,
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_telefone TEXT DEFAULT NULL,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_convite RECORD;
  v_user_id UUID;
  v_nome_limpo TEXT;
  v_email_limpo TEXT;
  v_encrypted_pw TEXT;
BEGIN
  -- 1. Validar e travar o convite
  SELECT * INTO v_convite
  FROM public.convites_instalador
  WHERE token = TRIM(p_token)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Convite nao localizado ou invalido.';
  END IF;

  IF v_convite.usado THEN
    RAISE EXCEPTION 'Este link de convite ja foi utilizado e nao e mais valido.';
  END IF;

  IF v_convite.expira_em < NOW() THEN
    RAISE EXCEPTION 'Este link de convite expirou. Solicite um novo link a administracao.';
  END IF;

  -- 2. Validar Dados
  v_nome_limpo := TRIM(p_nome);
  v_email_limpo := LOWER(TRIM(p_email));

  IF v_nome_limpo IS NULL OR v_nome_limpo = '' THEN
    RAISE EXCEPTION 'Nome completo e obrigatorio.';
  END IF;

  IF v_email_limpo IS NULL OR v_email_limpo = '' THEN
    RAISE EXCEPTION 'E-mail e obrigatorio.';
  END IF;

  IF p_senha IS NULL OR LENGTH(p_senha) < 6 THEN
    RAISE EXCEPTION 'A senha deve conter no minimo 6 caracteres.';
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_limpo) THEN
    RAISE EXCEPTION 'Este e-mail ja esta cadastrado no sistema.';
  END IF;

  -- 3. Gerar Hash de Senha Seguro
  v_encrypted_pw := extensions.crypt(p_senha, extensions.gen_salt('bf'));
  v_user_id := gen_random_uuid();

  -- 4. Criar Conta em auth.users
  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    v_user_id,
    'authenticated',
    'authenticated',
    v_email_limpo,
    v_encrypted_pw,
    NOW(),
    '{"provider":"email","providers":["email"]}'::JSONB,
    jsonb_build_object(
      'nome', v_nome_limpo,
      'role', 'instalador',
      'telefone', p_telefone,
      'convite_token', p_token
    ),
    NOW(),
    NOW()
  );

  INSERT INTO auth.identities (
    id, user_id, identity_data, provider, provider_id, last_sign_in_at, created_at, updated_at
  ) VALUES (
    gen_random_uuid(),
    v_user_id,
    jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
    'email',
    v_email_limpo,
    NOW(), NOW(), NOW()
  )
  ON CONFLICT (provider, provider_id) DO NOTHING;

  -- 5. Criar Perfil em public.profiles: OBRIGATORIAMENTE INATIVO (ativo = false)
  -- Mas primeiro_acesso = FALSE pois ele mesmo definiu a sua senha no convite
  INSERT INTO public.profiles (
    id, nome, email, role, ativo,
    telefone, chave_pix, endereco_instalacao,
    valor_por_instalacao, primeiro_acesso, created_at, updated_at
  ) VALUES (
    v_user_id,
    v_nome_limpo,
    v_email_limpo,
    'instalador',
    FALSE,
    p_telefone,
    p_chave_pix,
    p_endereco_instalacao,
    50.00,
    FALSE,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE
  SET
    role = 'instalador',
    ativo = FALSE,
    primeiro_acesso = FALSE,
    telefone = EXCLUDED.telefone,
    chave_pix = EXCLUDED.chave_pix,
    endereco_instalacao = EXCLUDED.endereco_instalacao,
    updated_at = NOW();

  -- 6. Inserir em user_roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_user_id, 'instalador')
  ON CONFLICT (user_id, role) DO NOTHING;

  -- 7. Liberar Acesso ao Módulo de Instalações
  INSERT INTO public.user_module_access (user_id, module, ativo)
  VALUES (v_user_id, 'instalacao', TRUE)
  ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;

  -- 8. Queimar o Token de Convite (Uso Único Imediato)
  UPDATE public.convites_instalador
  SET
    usado = TRUE,
    usado_em = NOW(),
    usado_por_user_id = v_user_id
  WHERE id = v_convite.id;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'mensagem', 'Cadastro realizado com sucesso! Sua conta foi enviada para analise e aguarda habilitacao pela administracao.',
    'user_id', v_user_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cadastrar_instalador_por_convite TO anon, authenticated;

-- 4. RLS atualizado em public.clientes para permitir que instaladores consultem suas demandas
DROP POLICY IF EXISTS "Instaladores consultam clientes para instalacao" ON public.clientes;
CREATE POLICY "Instaladores consultam clientes para instalacao"
ON public.clientes FOR SELECT TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  instalador_id = auth.uid() OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role IN ('operador', 'instalador')) OR
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'instalador') OR
  EXISTS (SELECT 1 FROM public.instalacoes WHERE cliente_id = public.clientes.id AND instalador_id = auth.uid())
);

-- 5. RLS atualizado em public.veiculos para permitir que instaladores consultem veículos dos clientes vinculados
DROP POLICY IF EXISTS "Instaladores visualizam veiculos para instalacao" ON public.veiculos;
CREATE POLICY "Instaladores visualizam veiculos para instalacao"
ON public.veiculos FOR SELECT TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador') OR
  EXISTS (
    SELECT 1 FROM public.clientes c 
    WHERE c.id = public.veiculos.cliente_id AND c.instalador_id = auth.uid()
  ) OR
  EXISTS (
    SELECT 1 FROM public.instalacoes i 
    WHERE (i.veiculo_id = public.veiculos.id OR i.cliente_id = public.veiculos.cliente_id) 
      AND i.instalador_id = auth.uid()
  )
);

-- 6. Atualizar RPC admin_gerar_pendencia_instalacao_cliente para aceitar papel 'adm'
CREATE OR REPLACE FUNCTION public.admin_gerar_pendencia_instalacao_cliente(
  p_cliente_id UUID,
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_cliente RECORD;
  v_tem_veiculo_ativo BOOLEAN := false;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;
    IF v_role NOT IN ('superadmin', 'adm', 'operador') THEN
      RAISE EXCEPTION 'Apenas administradores e operadores podem gerar pendência de instalação.';
    END IF;
  END IF;

  SELECT * INTO v_cliente FROM public.clientes WHERE id = p_cliente_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.';
  END IF;

  -- Verifica se o cliente possui algum veículo ativo com rastreador
  SELECT EXISTS (
    SELECT 1 FROM public.veiculos
    WHERE cliente_id = p_cliente_id AND ativo = true AND rastreador_id IS NOT NULL
  ) INTO v_tem_veiculo_ativo;

  UPDATE public.clientes
  SET
    instalador_id = COALESCE(p_instalador_id, instalador_id),
    status_agendamento = 'aguardando_agendamento',
    data_agendamento = NULL,
    hora_agendamento = NULL,
    status = CASE WHEN v_tem_veiculo_ativo THEN status ELSE 'aguardando_instalacao' END,
    updated_at = NOW()
  WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'cliente_id', p_cliente_id,
    'status_agendamento', 'aguardando_agendamento',
    'mensagem', 'Pendência de instalação gerada com sucesso para o instalador.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_gerar_pendencia_instalacao_cliente TO authenticated;

-- 7. Atualizar RPC instalador_definir_agendamento para associar instalador_id caso pendente
CREATE OR REPLACE FUNCTION public.instalador_definir_agendamento(
  p_cliente_id UUID,
  p_data DATE,
  p_hora TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_instalador_id UUID;
  v_cliente_nome TEXT;
BEGIN
  -- 1. Obter dados do cliente
  SELECT instalador_id, nome_razao_social INTO v_instalador_id, v_cliente_nome
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  -- Se v_instalador_id estiver nulo no cliente, mas o chamador tiver ordem em instalacoes:
  IF v_instalador_id IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.instalacoes 
      WHERE cliente_id = p_cliente_id AND instalador_id = v_caller_id AND status != 'concluida'
    ) THEN
      v_instalador_id := v_caller_id;
      UPDATE public.clientes SET instalador_id = v_caller_id WHERE id = p_cliente_id;
    END IF;
  END IF;

  -- 2. Verificar se o chamador é o instalador atribuído ou administrador
  IF v_caller_id <> v_instalador_id AND NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas o instalador atribuido ou administrador podem agendar este atendimento.';
  END IF;

  -- 3. Validar data e hora
  IF p_data IS NULL THEN
    RAISE EXCEPTION 'A data do agendamento e obrigatoria.';
  END IF;

  IF p_hora IS NULL OR trim(p_hora) = '' THEN
    RAISE EXCEPTION 'O horario do agendamento e obrigatorio.';
  END IF;

  -- 4. Atualizar o agendamento
  UPDATE public.clientes
  SET data_agendamento = p_data,
      hora_agendamento = trim(p_hora),
      status_agendamento = 'agendado',
      updated_at = now()
  WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Agendamento confirmado para o cliente ' || v_cliente_nome || ' em ' || to_char(p_data, 'DD/MM/YYYY') || ' as ' || trim(p_hora) || '.',
    'cliente_id', p_cliente_id,
    'data', p_data,
    'hora', trim(p_hora)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_definir_agendamento TO authenticated;

-- 8. Atualizar RPC admin_atualizar_cliente_completo para atualizar status_agendamento ao vincular instalador
CREATE OR REPLACE FUNCTION public.admin_atualizar_cliente_completo(
  p_cliente_id UUID,
  p_nome TEXT,
  p_documento TEXT,
  p_email TEXT,
  p_telefone TEXT,
  p_status public.status_cliente,
  p_plano public.plano_cliente,
  p_dia_vencimento INT,
  p_valor_mensalidade NUMERIC,
  p_dias_historico INT,
  p_dias_retencao INT,
  p_senha TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL,
  p_meses_contrato INT DEFAULT 12,
  p_data_inicio_contrato DATE DEFAULT CURRENT_DATE,
  p_tipo_renovacao TEXT DEFAULT 'mesma_vigencia',
  p_meses_renovacao INT DEFAULT 12,
  p_foro_comarca TEXT DEFAULT 'Volta Redonda/RJ',
  p_gerar_parcelas_ausentes BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_email_limpo TEXT := lower(trim(coalesce(p_email, '')));
  v_resultado_parcelas JSONB := '[]'::JSONB;
  v_meses_c INT := COALESCE(p_meses_contrato, 12);
  v_data_inicio DATE := COALESCE(p_data_inicio_contrato, CURRENT_DATE);
  v_data_fim DATE;
  v_status_final public.status_cliente := p_status;
  v_status_agendamento_final TEXT;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar clientes.';
  END IF;

  SELECT user_id, status_agendamento INTO v_user_id, v_status_agendamento_final
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.';
  END IF;

  v_data_fim := v_data_inicio + (v_meses_c || ' months')::INTERVAL;

  -- Se foi atribuído instalador e status de agendamento está pendente ou nulo:
  IF p_instalador_id IS NOT NULL THEN
    IF v_status_agendamento_final IS NULL OR v_status_agendamento_final = 'concluido' THEN
      v_status_agendamento_final := 'aguardando_agendamento';
    END IF;
    -- Se cliente não possui veículos ativos com rastreadores, força status operacional aguardando_instalacao
    IF NOT EXISTS (
      SELECT 1 FROM public.veiculos WHERE cliente_id = p_cliente_id AND ativo = TRUE AND rastreador_id IS NOT NULL
    ) THEN
      v_status_final := 'aguardando_instalacao'::public.status_cliente;
    END IF;
  END IF;

  -- Atualizar credenciais de auth se aplicável
  IF v_user_id IS NOT NULL THEN
    IF v_email_limpo <> '' THEN
      UPDATE auth.users
      SET email = v_email_limpo,
          raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome), 'email', v_email_limpo),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE public.profiles
      SET nome = trim(p_nome),
          email = v_email_limpo,
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.identities
      SET identity_data = jsonb_set(identity_data, '{email}', to_jsonb(v_email_limpo)),
          provider_id = v_email_limpo
      WHERE user_id = v_user_id AND provider = 'email';
    ELSE
      UPDATE public.profiles
      SET nome = trim(p_nome),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.users
      SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    IF p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;
  END IF;

  -- Atualizar registro em public.clientes
  UPDATE public.clientes
  SET nome_razao_social = trim(p_nome),
      documento = NULLIF(trim(p_documento), ''),
      email = NULLIF(v_email_limpo, ''),
      telefone = NULLIF(trim(p_telefone), ''),
      user_id = COALESCE(user_id, v_user_id),
      plano = p_plano,
      status = v_status_final,
      dia_vencimento = COALESCE(p_dia_vencimento, dia_vencimento),
      valor_mensalidade = COALESCE(p_valor_mensalidade, valor_mensalidade),
      dias_historico_plano = COALESCE(p_dias_historico, dias_historico_plano),
      dias_retencao_banco = COALESCE(p_dias_retencao, dias_retencao_banco),
      instalador_id = p_instalador_id,
      status_agendamento = COALESCE(v_status_agendamento_final, status_agendamento),
      meses_contrato = v_meses_c,
      data_inicio_contrato = v_data_inicio,
      data_fim_contrato = v_data_fim,
      tipo_renovacao = COALESCE(p_tipo_renovacao, tipo_renovacao),
      meses_renovacao = COALESCE(p_meses_renovacao, meses_renovacao),
      foro_comarca = COALESCE(p_foro_comarca, 'Volta Redonda/RJ'),
      updated_at = now()
  WHERE id = p_cliente_id;

  IF p_gerar_parcelas_ausentes THEN
    v_resultado_parcelas := public.admin_gerar_parcelas_contrato(p_cliente_id);
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Dados do cliente e credenciais atualizados com sucesso.',
    'cliente_id', p_cliente_id,
    'user_id', v_user_id,
    'meses_contrato', v_meses_c,
    'data_inicio_contrato', v_data_inicio,
    'data_fim_contrato', v_data_fim,
    'parcelas', v_resultado_parcelas
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_atualizar_cliente_completo(UUID, TEXT, TEXT, TEXT, TEXT, public.status_cliente, public.plano_cliente, INT, NUMERIC, INT, INT, TEXT, UUID, INT, DATE, TEXT, INT, TEXT, BOOLEAN) TO authenticated;

NOTIFY pgrst, 'reload schema';

-- ============================================================================
-- HUNTER — FLUXO CANÔNICO DE ESTOQUE DE RASTREADORES, CHIPS E KITS DE INSTALAÇÃO
-- ============================================================================
-- Diretrizes: HUNTER-GUARDIAN e DJR-NEW
-- 1. No cadastro em estoque, cada rastreador físico possui IMEI e pode receber
--    um ICCID (chip) vinculado.
-- 2. Equipamentos só ficam no status 'Liberado para Instalação' se tiverem
--    TANTO o IMEI QUANTO o ICCID cadastrados e vinculados.
-- 3. A quantidade de ICCIDs disponíveis respeita a quantidade de chips em estoque.
-- 4. O operador determina o kit para a instalação escolhendo dentre os habilitados.
-- 5. O instalador confirma o kit recebido lendo o código de barras ou digitando
--    o IMEI do dispositivo em sua posse, confirmando os dados do veículo e gerando
--    a pendência de pagamento no sistema.
-- ============================================================================

-- 1. Aprimorar tabela public.rastreadores
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'rastreadores' AND column_name = 'item_estoque_id'
  ) THEN
    ALTER TABLE public.rastreadores ADD COLUMN item_estoque_id UUID REFERENCES public.estoque_itens(id) ON DELETE SET NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'rastreadores' AND column_name = 'observacoes'
  ) THEN
    ALTER TABLE public.rastreadores ADD COLUMN observacoes TEXT;
  END IF;
END $$;

-- 2. Aprimorar tabela public.chips
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'chips' AND column_name = 'item_estoque_id'
  ) THEN
    ALTER TABLE public.chips ADD COLUMN item_estoque_id UUID REFERENCES public.estoque_itens(id) ON DELETE SET NULL;
  END IF;
END $$;

-- 3. Aprimorar tabela public.instalacoes para custódia e confirmação do kit
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'rastreador_id'
  ) THEN
    ALTER TABLE public.instalacoes ADD COLUMN rastreador_id UUID REFERENCES public.rastreadores(id) ON DELETE SET NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'kit_determinado_em'
  ) THEN
    ALTER TABLE public.instalacoes ADD COLUMN kit_determinado_em TIMESTAMPTZ;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'kit_confirmado_instalador'
  ) THEN
    ALTER TABLE public.instalacoes ADD COLUMN kit_confirmado_instalador BOOLEAN NOT NULL DEFAULT FALSE;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'kit_confirmado_em'
  ) THEN
    ALTER TABLE public.instalacoes ADD COLUMN kit_confirmado_em TIMESTAMPTZ;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'imei_confirmado'
  ) THEN
    ALTER TABLE public.instalacoes ADD COLUMN imei_confirmado TEXT;
  END IF;
END $$;

-- 4. Aprimorar tabela public.clientes para vincular o kit determinado
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'clientes' AND column_name = 'kit_determinado_id'
  ) THEN
    ALTER TABLE public.clientes ADD COLUMN kit_determinado_id UUID REFERENCES public.rastreadores(id) ON DELETE SET NULL;
  END IF;
END $$;

-- 5. Índices de alta performance
CREATE INDEX IF NOT EXISTS idx_rastreadores_chip_status ON public.rastreadores(status, chip_id);
CREATE INDEX IF NOT EXISTS idx_rastreadores_imei_clean ON public.rastreadores(imei);
CREATE INDEX IF NOT EXISTS idx_chips_iccid_clean ON public.chips(iccid);
CREATE INDEX IF NOT EXISTS idx_instalacoes_rastreador ON public.instalacoes(rastreador_id);
CREATE INDEX IF NOT EXISTS idx_clientes_kit_determinado ON public.clientes(kit_determinado_id);

-- 6. RPC: Listar equipamentos habilitados para instalação (IMEI + ICCID)
CREATE OR REPLACE FUNCTION public.listar_equipamentos_habilitados_instalacao()
RETURNS TABLE (
  rastreador_id UUID,
  imei TEXT,
  modelo TEXT,
  chip_id UUID,
  iccid TEXT,
  operadora TEXT,
  linha TEXT,
  status TEXT,
  liberado_instalacao BOOLEAN,
  created_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.id AS rastreador_id,
    r.imei,
    r.modelo,
    c.id AS chip_id,
    c.iccid,
    c.operadora,
    c.linha,
    r.status::TEXT,
    TRUE AS liberado_instalacao,
    r.created_at
  FROM public.rastreadores r
  INNER JOIN public.chips c ON c.id = r.chip_id
  WHERE r.status = 'estoque'
  ORDER BY r.created_at DESC;
END;
$$;

GRANT EXECUTE ON FUNCTION public.listar_equipamentos_habilitados_instalacao() TO authenticated;

-- 7. RPC: Listar todos os dispositivos e chips em estoque (habilitados e pendentes)
CREATE OR REPLACE FUNCTION public.listar_todos_dispositivos_estoque()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_rastreadores JSONB;
  v_chips_disponiveis JSONB;
  v_totais JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', r.id,
    'imei', r.imei,
    'modelo', r.modelo,
    'status', r.status,
    'chip_id', r.chip_id,
    'iccid', c.iccid,
    'operadora', c.operadora,
    'linha', c.linha,
    'liberado_instalacao', (r.chip_id IS NOT NULL AND r.status = 'estoque'),
    'created_at', r.created_at,
    'updated_at', r.updated_at
  ) ORDER BY r.created_at DESC), '[]'::jsonb)
  INTO v_rastreadores
  FROM public.rastreadores r
  LEFT JOIN public.chips c ON c.id = r.chip_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'iccid', c.iccid,
    'operadora', c.operadora,
    'linha', c.linha,
    'status', c.status,
    'created_at', c.created_at
  ) ORDER BY c.created_at DESC), '[]'::jsonb)
  INTO v_chips_disponiveis
  FROM public.chips c
  WHERE c.id NOT IN (
    SELECT DISTINCT r.chip_id 
    FROM public.rastreadores r 
    WHERE r.chip_id IS NOT NULL
  );

  SELECT jsonb_build_object(
    'total_rastreadores', (SELECT COUNT(*) FROM public.rastreadores),
    'rastreadores_em_estoque', (SELECT COUNT(*) FROM public.rastreadores WHERE status = 'estoque'),
    'total_chips', (SELECT COUNT(*) FROM public.chips),
    'chips_disponiveis', (SELECT jsonb_array_length(v_chips_disponiveis)),
    'liberados_para_instalacao', (SELECT COUNT(*) FROM public.rastreadores WHERE status = 'estoque' AND chip_id IS NOT NULL),
    'pendentes_vinculo', (SELECT COUNT(*) FROM public.rastreadores WHERE status = 'estoque' AND chip_id IS NULL)
  ) INTO v_totais;

  RETURN jsonb_build_object(
    'success', true,
    'rastreadores', v_rastreadores,
    'chips_disponiveis', v_chips_disponiveis,
    'totais', v_totais
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.listar_todos_dispositivos_estoque() TO authenticated;

-- 8. RPC: Salvar rastreador com chip (Criar ou Vincular)
CREATE OR REPLACE FUNCTION public.salvar_rastreador_com_chip(
  p_imei TEXT,
  p_modelo TEXT DEFAULT 'J16 4G',
  p_iccid TEXT DEFAULT NULL,
  p_operadora TEXT DEFAULT 'Vivo',
  p_linha TEXT DEFAULT NULL,
  p_rastreador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_imei_limpo TEXT;
  v_iccid_limpo TEXT;
  v_chip_id UUID := NULL;
  v_rastreador_id UUID := p_rastreador_id;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role INTO v_role FROM public.profiles WHERE id = v_user_id LIMIT 1;
    IF v_role NOT IN ('superadmin', 'adm', 'operador') THEN
      RETURN jsonb_build_object('success', false, 'message', 'Permissão negada. Apenas a administração pode gerenciar seriais em estoque.');
    END IF;
  END IF;

  v_imei_limpo := REGEXP_REPLACE(p_imei, '\D', '', 'g');
  IF v_imei_limpo IS NULL OR LENGTH(v_imei_limpo) < 8 THEN
    RETURN jsonb_build_object('success', false, 'message', 'IMEI inválido. Informe um serial numérico válido.');
  END IF;

  IF p_iccid IS NOT NULL AND TRIM(p_iccid) <> '' THEN
    v_iccid_limpo := REGEXP_REPLACE(p_iccid, '\D', '', 'g');
  ELSE
    v_iccid_limpo := NULL;
  END IF;

  IF v_iccid_limpo IS NOT NULL THEN
    SELECT id INTO v_chip_id FROM public.chips WHERE iccid = v_iccid_limpo LIMIT 1;
    IF v_chip_id IS NULL THEN
      INSERT INTO public.chips (iccid, operadora, linha, status)
      VALUES (v_iccid_limpo, COALESCE(NULLIF(TRIM(p_operadora), ''), 'Vivo'), NULLIF(TRIM(p_linha), ''), 'vinculado')
      RETURNING id INTO v_chip_id;
    ELSE
      UPDATE public.chips
      SET 
        operadora = COALESCE(NULLIF(TRIM(p_operadora), ''), operadora),
        linha = COALESCE(NULLIF(TRIM(p_linha), ''), linha),
        status = 'vinculado',
        updated_at = NOW()
      WHERE id = v_chip_id;
    END IF;
  END IF;

  IF v_rastreador_id IS NOT NULL THEN
    UPDATE public.rastreadores
    SET 
      imei = v_imei_limpo,
      modelo = COALESCE(NULLIF(TRIM(p_modelo), ''), modelo),
      chip_id = v_chip_id,
      updated_at = NOW()
    WHERE id = v_rastreador_id;
  ELSE
    SELECT id INTO v_rastreador_id FROM public.rastreadores WHERE imei = v_imei_limpo LIMIT 1;
    IF v_rastreador_id IS NOT NULL THEN
      UPDATE public.rastreadores
      SET 
        modelo = COALESCE(NULLIF(TRIM(p_modelo), ''), modelo),
        chip_id = COALESCE(v_chip_id, chip_id),
        updated_at = NOW()
      WHERE id = v_rastreador_id;
    ELSE
      INSERT INTO public.rastreadores (imei, modelo, chip_id, status)
      VALUES (v_imei_limpo, COALESCE(NULLIF(TRIM(p_modelo), ''), 'J16 4G'), v_chip_id, 'estoque')
      RETURNING id INTO v_rastreador_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Equipamento e chip salvos com sucesso no estoque.',
    'rastreador_id', v_rastreador_id,
    'chip_id', v_chip_id,
    'liberado_instalacao', (v_chip_id IS NOT NULL)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.salvar_rastreador_com_chip(TEXT, TEXT, TEXT, TEXT, TEXT, UUID) TO authenticated;

-- 9. RPC: Desvincular chip de rastreador
CREATE OR REPLACE FUNCTION public.desvincular_chip_rastreador(p_rastreador_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_chip_id UUID;
BEGIN
  SELECT chip_id INTO v_chip_id FROM public.rastreadores WHERE id = p_rastreador_id;
  
  UPDATE public.rastreadores
  SET chip_id = NULL, updated_at = NOW()
  WHERE id = p_rastreador_id;

  IF v_chip_id IS NOT NULL THEN
    UPDATE public.chips
    SET status = 'disponivel', updated_at = NOW()
    WHERE id = v_chip_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Chip desvinculado do rastreador com sucesso.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.desvincular_chip_rastreador(UUID) TO authenticated;

-- 10. RPC: Operador determinar kit para cliente / instalação
CREATE OR REPLACE FUNCTION public.operador_determinar_kit_cliente(
  p_cliente_id UUID,
  p_rastreador_id UUID,
  p_instalacao_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_rastreador RECORD;
  v_instalador_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role INTO v_role FROM public.profiles WHERE id = v_user_id LIMIT 1;
    IF v_role NOT IN ('superadmin', 'adm', 'operador') THEN
      RETURN jsonb_build_object('success', false, 'message', 'Permissão negada. Apenas a administração pode determinar kits de instalação.');
    END IF;
  END IF;

  SELECT r.id, r.imei, r.modelo, r.chip_id, r.status, c.iccid, c.operadora
  INTO v_rastreador
  FROM public.rastreadores r
  INNER JOIN public.chips c ON c.id = r.chip_id
  WHERE r.id = p_rastreador_id;

  IF v_rastreador.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Equipamento selecionado não está habilitado para instalação. Certifique-se de que possui IMEI e ICCID vinculados no estoque.');
  END IF;

  SELECT instalador_id INTO v_instalador_id FROM public.clientes WHERE id = p_cliente_id;

  UPDATE public.clientes
  SET 
    kit_determinado_id = p_rastreador_id,
    status_agendamento = COALESCE(status_agendamento, 'aguardando_agendamento'),
    updated_at = NOW()
  WHERE id = p_cliente_id;

  UPDATE public.rastreadores
  SET status = 'em_instalacao', updated_at = NOW()
  WHERE id = p_rastreador_id;

  IF p_instalacao_id IS NOT NULL THEN
    UPDATE public.instalacoes
    SET 
      rastreador_id = p_rastreador_id,
      rastreador_imei = v_rastreador.imei,
      rastreador_modelo = v_rastreador.modelo,
      chip_iccid = v_rastreador.iccid,
      chip_operadora = v_rastreador.operadora,
      kit_determinado_em = NOW(),
      updated_at = NOW()
    WHERE id = p_instalacao_id;
  ELSE
    UPDATE public.instalacoes
    SET 
      rastreador_id = p_rastreador_id,
      rastreador_imei = v_rastreador.imei,
      rastreador_modelo = v_rastreador.modelo,
      chip_iccid = v_rastreador.iccid,
      chip_operadora = v_rastreador.operadora,
      kit_determinado_em = NOW(),
      updated_at = NOW()
    WHERE cliente_id = p_cliente_id AND status != 'concluida';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Kit determinado com sucesso para o cliente.',
    'imei', v_rastreador.imei,
    'iccid', v_rastreador.iccid,
    'modelo', v_rastreador.modelo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.operador_determinar_kit_cliente(UUID, UUID, UUID) TO authenticated;

-- 11. RPC: Instalador confirmar kit recebido (por código de barras ou digitação)
CREATE OR REPLACE FUNCTION public.instalador_confirmar_kit(
  p_instalacao_id UUID,
  p_imei_conferido TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_inst RECORD;
  v_imei_limpo TEXT;
  v_imei_esperado_limpo TEXT;
BEGIN
  v_user_id := auth.uid();
  v_imei_limpo := REGEXP_REPLACE(p_imei_conferido, '\D', '', 'g');

  IF v_imei_limpo IS NULL OR LENGTH(v_imei_limpo) < 8 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Código IMEI inválido. Aponte a câmera para o código de barras ou digite o número correto.');
  END IF;

  SELECT 
    i.id, i.cliente_id, i.instalador_id, i.status, i.rastreador_id, i.rastreador_imei,
    r.imei AS imei_rastreador_real
  INTO v_inst
  FROM public.instalacoes i
  LEFT JOIN public.rastreadores r ON r.id = i.rastreador_id
  WHERE i.id = p_instalacao_id;

  IF v_inst.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada.');
  END IF;

  v_imei_esperado_limpo := REGEXP_REPLACE(COALESCE(v_inst.imei_rastreador_real, v_inst.rastreador_imei, ''), '\D', '', 'g');

  IF v_imei_esperado_limpo = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Esta demanda ainda não possui um kit determinado pela administração.');
  END IF;

  IF v_imei_limpo <> v_imei_esperado_limpo THEN
    RETURN jsonb_build_object(
      'success', false, 
      'message', 'Divergência de equipamento: o IMEI lido (' || v_imei_limpo || ') não corresponde ao kit determinado pela administração (' || v_imei_esperado_limpo || '). Verifique o aparelho em sua posse.'
    );
  END IF;

  UPDATE public.instalacoes
  SET 
    kit_confirmado_instalador = TRUE,
    kit_confirmado_em = NOW(),
    imei_confirmado = v_imei_limpo,
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Kit físico confirmado com sucesso pelo instalador!',
    'imei', v_imei_limpo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_confirmar_kit(UUID, TEXT) TO authenticated;

-- Recarregar cache de esquemas do PostgREST
NOTIFY pgrst, 'reload schema';

-- ============================================================================
-- 12. SINCRONIZAÇÃO IMEDIATA E ATÔMICA CLIENTE <-> INSTALADOR <-> INSTALAÇÕES
-- ============================================================================

DO $$
BEGIN
  ALTER TABLE public.chips ADD COLUMN IF NOT EXISTS operadora TEXT;
  ALTER TABLE public.chips ADD COLUMN IF NOT EXISTS iccid TEXT;
  ALTER TABLE public.rastreadores ADD COLUMN IF NOT EXISTS chip_id UUID;
  ALTER TABLE public.rastreadores ADD COLUMN IF NOT EXISTS imei TEXT;
  ALTER TABLE public.rastreadores ADD COLUMN IF NOT EXISTS modelo TEXT;

  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS kit_determinado_id UUID;
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS rastreador_id UUID;
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS kit_determinado_em TIMESTAMPTZ;
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS kit_confirmado_instalador BOOLEAN DEFAULT FALSE;
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS kit_confirmado_em TIMESTAMPTZ;
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS imei_confirmado TEXT;
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS data_agendamento DATE;
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS hora_agendamento TEXT;
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS tipo_veiculo TEXT DEFAULT 'carro';
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS tipo_servico TEXT DEFAULT 'instalacao';
  ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS ordem_vinculada_id UUID;
  
  ALTER TABLE public.instalacoes DROP CONSTRAINT IF EXISTS instalacoes_status_check;
  ALTER TABLE public.instalacoes ADD CONSTRAINT instalacoes_status_check 
    CHECK (status IN ('nao_instalado', 'agendada', 'aberta', 'concluida_com_pendencia', 'concluida'));
EXCEPTION WHEN OTHERS THEN
  NULL;
END $$;

DO $$
BEGIN
  ALTER TABLE public.instalacoes ALTER COLUMN valor_instalacao SET DEFAULT 50.00;
  ALTER TABLE public.instalacoes ALTER COLUMN km_instalacao SET DEFAULT 0;
  ALTER TABLE public.instalacoes ALTER COLUMN rastreador_imei DROP NOT NULL;
  ALTER TABLE public.instalacoes ALTER COLUMN placa DROP NOT NULL;
  ALTER TABLE public.instalacoes ALTER COLUMN marca DROP NOT NULL;
  ALTER TABLE public.instalacoes ALTER COLUMN modelo DROP NOT NULL;
EXCEPTION WHEN OTHERS THEN
  NULL;
END $$;

CREATE OR REPLACE FUNCTION public.trg_sync_cliente_instalador_instalacao()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_veiculo_id UUID := NULL;
  v_veiculo_placa TEXT := NULL;
  v_veiculo_modelo TEXT := NULL;
  v_veiculo_tipo TEXT := NULL;
  v_rastreador_id UUID := NULL;
  v_rastreador_imei TEXT := NULL;
  v_rastreador_modelo TEXT := NULL;
  v_chip_iccid TEXT := NULL;
  v_chip_operadora TEXT := NULL;
  v_valor_unitario NUMERIC(10,2) := 50.00;
  v_instalacao_id UUID := NULL;
BEGIN
  IF NEW.instalador_id IS NOT NULL AND (NEW.status_agendamento IS DISTINCT FROM 'concluido' OR NEW.status = 'aguardando_instalacao') THEN
    
    SELECT COALESCE(valor_por_instalacao, 50.00) INTO v_valor_unitario
    FROM public.profiles
    WHERE id = NEW.instalador_id;

    SELECT id INTO v_instalacao_id
    FROM public.instalacoes
    WHERE cliente_id = NEW.id AND status NOT IN ('concluida')
    ORDER BY created_at DESC
    LIMIT 1;

    SELECT id, placa, marca_modelo, tipo_veiculo
    INTO v_veiculo_id, v_veiculo_placa, v_veiculo_modelo, v_veiculo_tipo
    FROM public.veiculos
    WHERE cliente_id = NEW.id
    ORDER BY created_at ASC
    LIMIT 1;

    IF NEW.kit_determinado_id IS NOT NULL THEN
      SELECT r.id, r.imei, r.modelo, c.iccid, c.operadora
      INTO v_rastreador_id, v_rastreador_imei, v_rastreador_modelo, v_chip_iccid, v_chip_operadora
      FROM public.rastreadores r
      LEFT JOIN public.chips c ON c.id = r.chip_id
      WHERE r.id = NEW.kit_determinado_id;
    END IF;

    IF v_instalacao_id IS NOT NULL THEN
      UPDATE public.instalacoes
      SET 
        instalador_id = NEW.instalador_id,
        valor_instalacao = CASE WHEN valor_instalacao <= 0 THEN COALESCE(v_valor_unitario, 50.00) ELSE valor_instalacao END,
        veiculo_id = COALESCE(veiculo_id, v_veiculo_id),
        placa = CASE WHEN placa = 'A DEFINIR' OR placa IS NULL THEN COALESCE(v_veiculo_placa, 'A DEFINIR') ELSE placa END,
        marca = CASE WHEN marca = 'A DEFINIR' OR marca IS NULL THEN 'A DEFINIR' ELSE marca END,
        modelo = CASE WHEN modelo = 'Veículo do Cliente' OR modelo IS NULL THEN COALESCE(v_veiculo_modelo, 'Veículo do Cliente') ELSE modelo END,
        tipo_veiculo = COALESCE(tipo_veiculo, v_veiculo_tipo, 'carro'),
        rastreador_id = COALESCE(rastreador_id, v_rastreador_id),
        rastreador_imei = COALESCE(rastreador_imei, v_rastreador_imei, 'PENDENTE'),
        rastreador_modelo = COALESCE(rastreador_modelo, v_rastreador_modelo, 'J16 4G'),
        chip_iccid = COALESCE(chip_iccid, v_chip_iccid),
        chip_operadora = COALESCE(chip_operadora, v_chip_operadora),
        data_agendamento = COALESCE(NEW.data_agendamento, data_agendamento),
        hora_agendamento = COALESCE(NEW.hora_agendamento, hora_agendamento),
        updated_at = NOW()
      WHERE id = v_instalacao_id;
    ELSE
      INSERT INTO public.instalacoes (
        cliente_id,
        instalador_id,
        veiculo_id,
        placa,
        marca,
        modelo,
        tipo_veiculo,
        rastreador_id,
        rastreador_imei,
        rastreador_modelo,
        chip_iccid,
        chip_operadora,
        status,
        status_pagamento,
        valor_instalacao,
        data_agendamento,
        hora_agendamento,
        observacoes,
        created_at,
        updated_at
      ) VALUES (
        NEW.id,
        NEW.instalador_id,
        v_veiculo_id,
        COALESCE(v_veiculo_placa, 'A DEFINIR'),
        'A DEFINIR',
        COALESCE(v_veiculo_modelo, 'Veículo do Cliente'),
        COALESCE(v_veiculo_tipo, 'carro'),
        v_rastreador_id,
        COALESCE(v_rastreador_imei, 'PENDENTE'),
        COALESCE(v_rastreador_modelo, 'J16 4G'),
        v_chip_iccid,
        v_chip_operadora,
        'agendada',
        'pendente',
        COALESCE(v_valor_unitario, 50.00),
        NEW.data_agendamento,
        NEW.hora_agendamento,
        'Ordem gerada automaticamente pela associação do instalador.',
        NOW(),
        NOW()
      );
    END IF;

  ELSIF NEW.instalador_id IS NULL AND OLD.instalador_id IS NOT NULL THEN
    UPDATE public.instalacoes
    SET instalador_id = NULL, updated_at = NOW()
    WHERE cliente_id = NEW.id AND status NOT IN ('concluida');
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_cliente_instalador_instalacao ON public.clientes;
CREATE TRIGGER trg_sync_cliente_instalador_instalacao
  AFTER INSERT OR UPDATE OF instalador_id, data_agendamento, hora_agendamento, status, status_agendamento, kit_determinado_id
  ON public.clientes
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_sync_cliente_instalador_instalacao();

CREATE OR REPLACE FUNCTION public.trg_sync_veiculo_instalacao()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
BEGIN
  IF NEW.cliente_id IS NOT NULL THEN
    UPDATE public.instalacoes
    SET 
      veiculo_id = NEW.id,
      placa = NEW.placa,
      marca = COALESCE(marca, 'A DEFINIR'),
      modelo = COALESCE(NEW.marca_modelo, modelo, 'Veículo do Cliente'),
      tipo_veiculo = COALESCE(NEW.tipo_veiculo, tipo_veiculo, 'carro'),
      updated_at = NOW()
    WHERE cliente_id = NEW.cliente_id 
      AND status NOT IN ('concluida')
      AND (placa = 'A DEFINIR' OR placa IS NULL OR veiculo_id IS NULL);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_veiculo_instalacao ON public.veiculos;
CREATE TRIGGER trg_sync_veiculo_instalacao
  AFTER INSERT OR UPDATE OF placa, marca_modelo, tipo_veiculo, cliente_id
  ON public.veiculos
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_sync_veiculo_instalacao();

CREATE OR REPLACE FUNCTION public.instalador_obter_minhas_demandas(
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_alvo_id UUID;
  v_ordens JSONB;
  v_agendamentos JSONB;
  v_resumo JSONB;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') THEN
    v_alvo_id := COALESCE(p_instalador_id, v_caller_id);
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', i.id,
      'instalador_id', i.instalador_id,
      'instalador_nome', COALESCE(p.nome, 'Instalador'),
      'instalador_chave_pix', p.chave_pix,
      'cliente_id', i.cliente_id,
      'cliente_nome', COALESCE(c.nome_razao_social, 'Cliente'),
      'cliente_documento', c.documento,
      'cliente_telefone', c.telefone,
      'veiculo_id', i.veiculo_id,
      'placa', COALESCE(i.placa, 'A DEFINIR'),
      'marca', COALESCE(i.marca, 'A DEFINIR'),
      'modelo', COALESCE(i.modelo, 'Veículo do Cliente'),
      'ano', i.ano,
      'cor', i.cor,
      'km_instalacao', COALESCE(i.km_instalacao, 0),
      'rastreador_id', i.rastreador_id,
      'rastreador_imei', COALESCE(i.rastreador_imei, 'PENDENTE'),
      'rastreador_modelo', COALESCE(i.rastreador_modelo, 'J16 4G'),
      'chip_iccid', i.chip_iccid,
      'chip_operadora', i.chip_operadora,
      'posicao_instalacao', i.posicao_instalacao,
      'status', i.status,
      'motivo_pendencia_recusa', i.motivo_pendencia_recusa,
      'observacoes', i.observacoes,
      'valor_instalacao', COALESCE(i.valor_instalacao, 50.00),
      'status_pagamento', COALESCE(i.status_pagamento, 'pendente'),
      'pago_em', i.pago_em,
      'pago_por', i.pago_por,
      'comprovante_pagamento', i.comprovante_pagamento,
      'kit_determinado_em', i.kit_determinado_em,
      'kit_confirmado_instalador', COALESCE(i.kit_confirmado_instalador, FALSE),
      'kit_confirmado_em', i.kit_confirmado_em,
      'imei_confirmado', i.imei_confirmado,
      'data_agendamento', COALESCE(i.data_agendamento, c.data_agendamento),
      'hora_agendamento', COALESCE(i.hora_agendamento, c.hora_agendamento),
      'created_at', i.created_at,
      'updated_at', i.updated_at,
      'concluida_at', i.concluida_at
    ) ORDER BY i.created_at DESC
  ), '[]'::JSONB)
  INTO v_ordens
  FROM public.instalacoes i
  LEFT JOIN public.profiles p ON p.id = i.instalador_id
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR i.instalador_id = v_alvo_id;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'nome_razao_social', c.nome_razao_social,
      'documento', c.documento,
      'telefone', c.telefone,
      'email', c.email,
      'status', c.status,
      'status_agendamento', COALESCE(c.status_agendamento, 'aguardando_agendamento'),
      'data_agendamento', c.data_agendamento,
      'hora_agendamento', c.hora_agendamento,
      'instalador_id', c.instalador_id,
      'instalador', jsonb_build_object(
        'id', p.id,
        'nome', p.nome,
        'endereco_instalacao', p.endereco_instalacao
      ),
      'veiculos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', v.id, 'placa', v.placa, 'modelo', v.marca_modelo))
        FROM public.veiculos v
        WHERE v.cliente_id = c.id
      ), '[]'::JSONB)
    ) ORDER BY c.created_at DESC
  ), '[]'::JSONB)
  INTO v_agendamentos
  FROM public.clientes c
  LEFT JOIN public.profiles p ON p.id = c.instalador_id
  WHERE (
    (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
    OR c.instalador_id = v_alvo_id
  )
  AND (c.status_agendamento IS DISTINCT FROM 'concluido' OR c.status = 'aguardando_instalacao');

  v_resumo := jsonb_build_object(
    'total_ordens', jsonb_array_length(v_ordens),
    'total_agendamentos', jsonb_array_length(v_agendamentos)
  );

  RETURN jsonb_build_object(
    'success', true,
    'ordens', v_ordens,
    'agendamentos', v_agendamentos,
    'resumo', v_resumo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_obter_minhas_demandas(UUID) TO authenticated;

-- Sincronização Retrô Imediata
DO $$
DECLARE
  r RECORD;
  v_veiculo_id UUID;
  v_veiculo_placa TEXT;
  v_veiculo_modelo TEXT;
  v_veiculo_tipo TEXT;
  v_valor NUMERIC(10,2);
  v_rastreador_id UUID;
  v_rastreador_imei TEXT;
  v_rastreador_modelo TEXT;
  v_chip_iccid TEXT;
  v_chip_operadora TEXT;
BEGIN
  FOR r IN (
    SELECT c.id, c.instalador_id, c.data_agendamento, c.hora_agendamento, c.kit_determinado_id
    FROM public.clientes c
    WHERE c.instalador_id IS NOT NULL
      AND (c.status_agendamento IS NULL OR c.status_agendamento <> 'concluido' OR c.status = 'aguardando_instalacao')
      AND NOT EXISTS (
        SELECT 1 FROM public.instalacoes i 
        WHERE i.cliente_id = c.id AND i.status <> 'concluida'
      )
  ) LOOP
    v_veiculo_id := NULL;
    v_veiculo_placa := NULL;
    v_veiculo_modelo := NULL;
    v_veiculo_tipo := NULL;
    v_rastreador_id := NULL;
    v_rastreador_imei := NULL;
    v_rastreador_modelo := NULL;
    v_chip_iccid := NULL;
    v_chip_operadora := NULL;

    SELECT id, placa, marca_modelo, tipo_veiculo
    INTO v_veiculo_id, v_veiculo_placa, v_veiculo_modelo, v_veiculo_tipo
    FROM public.veiculos
    WHERE cliente_id = r.id
    ORDER BY created_at ASC
    LIMIT 1;

    SELECT COALESCE(valor_por_instalacao, 50.00) INTO v_valor
    FROM public.profiles
    WHERE id = r.instalador_id;

    IF r.kit_determinado_id IS NOT NULL THEN
      SELECT rst.id, rst.imei, rst.modelo, cp.iccid, cp.operadora
      INTO v_rastreador_id, v_rastreador_imei, v_rastreador_modelo, v_chip_iccid, v_chip_operadora
      FROM public.rastreadores rst
      LEFT JOIN public.chips cp ON cp.id = rst.chip_id
      WHERE rst.id = r.kit_determinado_id;
    END IF;

    INSERT INTO public.instalacoes (
      cliente_id,
      instalador_id,
      veiculo_id,
      placa,
      marca,
      modelo,
      tipo_veiculo,
      rastreador_id,
      rastreador_imei,
      rastreador_modelo,
      chip_iccid,
      chip_operadora,
      status,
      status_pagamento,
      valor_instalacao,
      data_agendamento,
      hora_agendamento,
      observacoes,
      created_at,
      updated_at
    ) VALUES (
      r.id,
      r.instalador_id,
      v_veiculo_id,
      COALESCE(v_veiculo_placa, 'A DEFINIR'),
      'A DEFINIR',
      COALESCE(v_veiculo_modelo, 'Veículo do Cliente'),
      COALESCE(v_veiculo_tipo, 'carro'),
      v_rastreador_id,
      COALESCE(v_rastreador_imei, 'PENDENTE'),
      COALESCE(v_rastreador_modelo, 'J16 4G'),
      v_chip_iccid,
      v_chip_operadora,
      'agendada',
      'pendente',
      COALESCE(v_valor, 50.00),
      r.data_agendamento,
      r.hora_agendamento,
      'Sincronizado retroativamente da associação existente de instalador no cliente.',
      NOW(),
      NOW()
    );
  END LOOP;
END;
$$;

