-- 2. RPC: Instalador solicita endereço de instalação ao cliente
CREATE OR REPLACE FUNCTION public.instalador_solicitar_endereco_cliente(
  p_instalacao_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_inst RECORD;
  v_cliente_user_id UUID;
  v_instalador_nome TEXT;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT, nome INTO v_role, v_instalador_nome FROM public.profiles WHERE id = v_caller_id;

  SELECT i.*, c.user_id as c_user_id, c.nome_razao_social
  INTO v_inst
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não encontrada.');
  END IF;

  -- Validação de permissão: apenas o instalador atribuído ou adm/operador pode solicitar
  IF v_role NOT IN ('superadmin', 'adm', 'operador') AND v_inst.instalador_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Apenas o técnico responsável pode solicitar o endereço.');
  END IF;

  -- Atualiza a ordem
  UPDATE public.instalacoes
  SET 
    solicita_endereco_cliente = TRUE,
    solicitado_endereco_em = NOW(),
    local_tipo = 'local_veiculo',
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  v_cliente_user_id := v_inst.c_user_id;

  -- 3. Emissão de Notificação Imediata para o Cliente
  IF v_cliente_user_id IS NOT NULL THEN
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      destinatario_cliente_id,
      remetente_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa
    ) VALUES (
      v_cliente_user_id,
      v_inst.cliente_id,
      v_caller_id,
      COALESCE(v_instalador_nome, 'Técnico Instalador'),
      '📍 Informe o Endereço de Instalação',
      'O instalador precisa do endereço onde o veículo ' || v_inst.placa || ' estará para realizar o atendimento presencial.',
      'agendamento',
      '/login',
      v_inst.placa
    );
  END IF;

  -- 4. Notificação para Administradores e Operadores (Acompanhamento em tempo real)
  INSERT INTO public.notificacoes_sistema (
    destinatario_user_id,
    remetente_user_id,
    remetente_nome,
    titulo,
    mensagem,
    tipo,
    url,
    placa
  )
  SELECT 
    p.id,
    v_caller_id,
    COALESCE(v_instalador_nome, 'Técnico Instalador'),
    '📍 Endereço Solicitado ao Cliente',
    'Técnico solicitou endereço de instalação para o veículo ' || v_inst.placa || ' (Cliente: ' || COALESCE(v_inst.nome_razao_social, 'Cliente') || ').',
    'agendamento',
    '/instalacao',
    v_inst.placa
  FROM public.profiles p
  WHERE p.role IN ('superadmin', 'adm', 'operador') AND p.id <> v_caller_id;

  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Solicitação de endereço enviada com sucesso ao cliente e registrada para a central.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_solicitar_endereco_cliente(UUID) TO authenticated;

-- 3. RPC: Cliente informa o endereço onde o veículo estará
CREATE OR REPLACE FUNCTION public.cliente_informar_endereco_instalacao(
  p_instalacao_id UUID,
  p_endereco TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_inst RECORD;
  v_cliente_nome TEXT;
  v_endereco_limpo TEXT;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  v_endereco_limpo := TRIM(p_endereco);
  IF v_endereco_limpo IS NULL OR LENGTH(v_endereco_limpo) < 5 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Por favor, informe o endereço completo para atendimento.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  SELECT i.*, c.user_id as c_user_id, c.nome_razao_social
  INTO v_inst
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não encontrada.');
  END IF;

  -- Validação de permissão: o próprio cliente ou gestor
  IF v_role NOT IN ('superadmin', 'adm', 'operador') AND v_inst.c_user_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Apenas o titular do veículo pode informar este endereço.');
  END IF;

  -- Atualiza a ordem
  UPDATE public.instalacoes
  SET 
    endereco_cliente_informado = v_endereco_limpo,
    local_endereco = v_endereco_limpo,
    local_tipo = 'local_veiculo',
    solicita_endereco_cliente = FALSE,
    endereco_cliente_informado_em = NOW(),
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  v_cliente_nome := COALESCE(v_inst.nome_razao_social, 'Cliente');

  -- 1. Notificação Imediata para o Instalador Técnico Responsável
  IF v_inst.instalador_id IS NOT NULL THEN
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      remetente_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa
    ) VALUES (
      v_inst.instalador_id,
      v_caller_id,
      v_cliente_nome,
      '📍 Endereço de Instalação Recebido',
      'O cliente informou o local para o veículo ' || v_inst.placa || ': ' || v_endereco_limpo || '. Agora você pode confirmar data e horário.',
      'agendamento',
      '/instalacao',
      v_inst.placa
    );
  END IF;

  -- 2. Notificação para Administradores e Operadores
  INSERT INTO public.notificacoes_sistema (
    destinatario_user_id,
    remetente_user_id,
    remetente_nome,
    titulo,
    mensagem,
    tipo,
    url,
    placa
  )
  SELECT 
    p.id,
    v_caller_id,
    v_cliente_nome,
    '📍 Endereço de Instalação Informado',
    v_cliente_nome || ' informou endereço para o veículo ' || v_inst.placa || ': ' || v_endereco_limpo || '.',
    'agendamento',
    '/instalacao',
    v_inst.placa
  FROM public.profiles p
  WHERE p.role IN ('superadmin', 'adm', 'operador') AND p.id <> v_caller_id;

  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Endereço registrado com sucesso! O instalador foi notificado imediatamente para realizar o agendamento.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cliente_informar_endereco_instalacao(UUID, TEXT) TO authenticated;

-- 4. RPC: Obter todos os veículos e respectivas instalações do cliente (INDIVIDUALIZADOS)
CREATE OR REPLACE FUNCTION public.cliente_obter_meus_veiculos_instalacao(
  p_cliente_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_alvo_id UUID;
  v_role TEXT;
  v_cliente_id UUID;
  v_resultado JSONB;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') AND p_cliente_user_id IS NOT NULL THEN
    v_alvo_id := p_cliente_user_id;
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  -- Localiza cliente_id
  SELECT id INTO v_cliente_id FROM public.clientes WHERE user_id = v_alvo_id;
  IF v_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Cadastro de cliente não encontrado.');
  END IF;

  -- Monta JSON com CADA veículo e sua respectiva ordem de instalação
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'instalacao_id', i.id,
      'veiculo_id', COALESCE(i.veiculo_id, v.id),
      'placa', COALESCE(i.placa, v.placa, 'A DEFINIR'),
      'marca', COALESCE(i.marca, v.marca_modelo, 'A DEFINIR'),
      'modelo', COALESCE(i.modelo, v.marca_modelo, 'Veículo'),
      'ano', i.ano,
      'cor', COALESCE(i.cor, v.cor),
      'tipo_veiculo', COALESCE(i.tipo_veiculo, v.tipo_veiculo, 'carro'),
      'status_instalacao', COALESCE(i.status, 'nao_instalado'),
      'data_agendamento', i.data_agendamento,
      'hora_agendamento', i.hora_agendamento,
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', i.local_endereco,
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, FALSE),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'rastreador_imei', i.rastreador_imei,
      'instalador_id', i.instalador_id,
      'instalador_nome', COALESCE(p.nome, 'Técnico em Atribuição'),
      'instalador_telefone', p.telefone,
      'instalador_endereco', p.endereco_instalacao
    ) ORDER BY i.created_at ASC
  ), '[]'::JSONB)
  INTO v_resultado
  FROM public.instalacoes i
  LEFT JOIN public.veiculos v ON v.id = i.veiculo_id
  LEFT JOIN public.profiles p ON p.id = i.instalador_id
  WHERE i.cliente_id = v_cliente_id;

  RETURN jsonb_build_object(
    'success', true,
    'veiculos', v_resultado
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cliente_obter_meus_veiculos_instalacao(UUID) TO authenticated;

-- 5. Atualizar RPC instalador_obter_minhas_demandas para retornar os novos campos
CREATE OR REPLACE FUNCTION public.instalador_obter_minhas_demandas(
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_alvo_id UUID;
  v_ordens JSONB;
  v_agendamentos JSONB;
  v_resumo JSONB;
  v_total_a_receber NUMERIC(10,2) := 0.00;
  v_total_recebido NUMERIC(10,2) := 0.00;
  v_total_agendados_qtd INT := 0;
  v_total_a_agendar_qtd INT := 0;
  v_valor_previsto_agendados NUMERIC(10,2) := 0.00;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') THEN
    v_alvo_id := COALESCE(p_instalador_id, v_caller_id);
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  -- 1. Coletar Ordens da tabela public.instalacoes com campos de local e endereco
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', i.id,
      'instalador_id', i.instalador_id,
      'instalador_nome', COALESCE(p.nome, 'Instalador'),
      'instalador_chave_pix', p.chave_pix,
      'instalador_valor_com_bloqueador', p.valor_instalacao_com_bloqueador,
      'instalador_valor_sem_bloqueador', p.valor_instalacao_sem_bloqueador,
      'cliente_id', i.cliente_id,
      'cliente_nome', COALESCE(c.nome_razao_social, 'Cliente'),
      'cliente_documento', c.documento,
      'cliente_telefone', c.telefone,
      'cliente_plano', c.plano,
      'cliente_tem_fidelidade', c.tem_fidelidade,
      'cliente_regra_horimetro', c.regra_horimetro,
      'veiculo_id', i.veiculo_id,
      'placa', COALESCE(i.placa, 'A DEFINIR'),
      'marca', COALESCE(i.marca, 'A DEFINIR'),
      'modelo', COALESCE(i.modelo, 'Veículo do Cliente'),
      'ano', i.ano,
      'cor', i.cor,
      'tipo_veiculo', COALESCE(i.tipo_veiculo, 'carro'),
      'km_instalacao', COALESCE(i.km_instalacao, 0),
      'horimetro_inicial', COALESCE(i.horimetro_inicial, 0.00),
      'rastreador_id', i.rastreador_id,
      'rastreador_imei', COALESCE(i.rastreador_imei, 'PENDENTE'),
      'rastreador_modelo', COALESCE(i.rastreador_modelo, 'J16 4G'),
      'chip_iccid', i.chip_iccid,
      'chip_operadora', i.chip_operadora,
      'com_bloqueador', COALESCE(i.com_bloqueador, FALSE),
      'tipo_bloqueador', i.tipo_bloqueador,
      'posicao_instalacao', i.posicao_instalacao,
      'posicao_rele', i.posicao_rele,
      'circuito_cortado', i.circuito_cortado,
      'status', i.status,
      'motivo_pendencia_recusa', i.motivo_pendencia_recusa,
      'observacoes', i.observacoes,
      'valor_instalacao', COALESCE(i.valor_instalacao, 50.00),
      'status_pagamento', COALESCE(i.status_pagamento, 'pendente'),
      'pago_em', i.pago_em,
      'pago_por', i.pago_por,
      'comprovante_pagamento', i.comprovante_pagamento,
      'kit_determinado_em', i.kit_determinado_em,
      'kit_confirmado_instalador', COALESCE(i.kit_confirmado_instalador, FALSE),
      'kit_confirmado_em', i.kit_confirmado_em,
      'imei_confirmado', i.imei_confirmado,
      'data_agendamento', COALESCE(i.data_agendamento, c.data_agendamento),
      'hora_agendamento', COALESCE(i.hora_agendamento, c.hora_agendamento),
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', COALESCE(i.local_endereco, p.endereco_instalacao),
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, FALSE),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'foto_placa_url', i.foto_placa_url,
      'foto_rastreador_url', i.foto_rastreador_url,
      'foto_local_instalacao_url', i.foto_local_instalacao_url,
      'foto_bloqueador_url', i.foto_bloqueador_url,
      'fotos_instalacao', i.fotos_instalacao,
      'created_at', i.created_at,
      'updated_at', i.updated_at,
      'concluida_at', i.concluida_at
    ) ORDER BY i.created_at DESC
  ), '[]'::JSONB)
  INTO v_ordens
  FROM public.instalacoes i
  LEFT JOIN public.profiles p ON p.id = i.instalador_id
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR i.instalador_id = v_alvo_id;

  -- 2. Coletar Clientes Agendados ou Aguardando Agendamento
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'nome_razao_social', c.nome_razao_social,
      'documento', c.documento,
      'telefone', c.telefone,
      'email', c.email,
      'status', c.status,
      'plano', c.plano,
      'tem_fidelidade', c.tem_fidelidade,
      'regra_horimetro', c.regra_horimetro,
      'status_agendamento', COALESCE(c.status_agendamento, 'aguardando_agendamento'),
      'data_agendamento', c.data_agendamento,
      'hora_agendamento', c.hora_agendamento,
      'instalador_id', c.instalador_id,
      'instalador', jsonb_build_object(
        'id', p.id,
        'nome', p.nome,
        'endereco_instalacao', p.endereco_instalacao,
        'valor_com_bloqueador', p.valor_instalacao_com_bloqueador,
        'valor_sem_bloqueador', p.valor_instalacao_sem_bloqueador
      ),
      'veiculos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id, 
          'placa', v.placa, 
          'modelo', v.marca_modelo, 
          'tipo_veiculo', v.tipo_veiculo,
          'horimetro_horas', v.horimetro_horas
        ))
        FROM public.veiculos v
        WHERE v.cliente_id = c.id
      ), '[]'::JSONB)
    ) ORDER BY c.created_at DESC
  ), '[]'::JSONB)
  INTO v_agendamentos
  FROM public.clientes c
  LEFT JOIN public.profiles p ON p.id = c.instalador_id
  WHERE (
    (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
    OR c.instalador_id = v_alvo_id
  )
  AND (c.status_agendamento IS DISTINCT FROM 'concluido' OR c.status = 'aguardando_instalacao');

  -- 3. Métricas Financeiras ESTRITAS: A RECEBER APENAS DE INSTALAÇÕES CONCLUÍDAS E PENDENTES DE PAGAMENTO!
  SELECT 
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pendente' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pago' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN valor_instalacao ELSE 0 END), 0.00),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN 1 END),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NULL THEN 1 END)
  INTO 
    v_total_a_receber,
    v_total_recebido,
    v_valor_previsto_agendados,
    v_total_agendados_qtd,
    v_total_a_agendar_qtd
  FROM public.instalacoes
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR instalador_id = v_alvo_id;

  v_resumo := jsonb_build_object(
    'total_ordens', jsonb_array_length(v_ordens),
    'total_agendamentos', jsonb_array_length(v_agendamentos),
    'a_receber', v_total_a_receber,
    'recebido', v_total_recebido,
    'agendados_qtd', v_total_agendados_qtd,
    'a_agendar_qtd', v_total_a_agendar_qtd,
    'valor_previsto_agendados', v_valor_previsto_agendados
  );

  RETURN jsonb_build_object(
    'success', true,
    'ordens', v_ordens,
    'agendamentos', v_agendamentos,
    'resumo', v_resumo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_obter_minhas_demandas(UUID) TO authenticated;

-- 4. RPC: Definir agendamento individual com suporte a local (oficina ou local_veiculo) e notificações imediatas
CREATE OR REPLACE FUNCTION public.instalador_definir_agendamento_instalacao(
  p_instalacao_id UUID,
  p_data DATE,
  p_hora TEXT,
  p_local_tipo TEXT DEFAULT 'oficina',
  p_local_endereco TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_instalador_id UUID;
  v_cliente_id UUID;
  v_cliente_user_id UUID;
  v_placa TEXT;
  v_instalador_nome TEXT;
  v_endereco_final TEXT;
  v_tipo_local TEXT;
BEGIN
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  -- 1. Resgatar instalação alvo e dados do cliente
  SELECT 
    i.instalador_id, 
    i.cliente_id, 
    i.placa,
    c.user_id,
    p.nome,
    p.endereco_instalacao
  INTO 
    v_instalador_id, 
    v_cliente_id, 
    v_placa,
    v_cliente_user_id,
    v_instalador_nome,
    v_endereco_final
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, v_caller_id)
  WHERE i.id = p_instalacao_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Instalação não encontrada.';
  END IF;

  -- Se v_instalador_id estiver nulo, atribuir ao chamador
  IF v_instalador_id IS NULL THEN
    v_instalador_id := v_caller_id;
    UPDATE public.instalacoes SET instalador_id = v_caller_id WHERE id = p_instalacao_id;
  END IF;

  -- 2. Permissão: apenas instalador atribuído ou administrador
  IF v_caller_id <> v_instalador_id AND NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas o instalador atribuído ou administrador podem agendar esta instalação.';
  END IF;

  -- 3. Validações
  IF p_data IS NULL THEN
    RAISE EXCEPTION 'A data do agendamento é obrigatória.';
  END IF;

  IF p_hora IS NULL OR trim(p_hora) = '' THEN
    RAISE EXCEPTION 'O horário do agendamento é obrigatório.';
  END IF;

  v_tipo_local := COALESCE(p_local_tipo, 'oficina');
  IF v_tipo_local = 'local_veiculo' THEN
    v_endereco_final := COALESCE(TRIM(p_local_endereco), v_endereco_final);
  ELSE
    v_endereco_final := COALESCE(TRIM(p_local_endereco), v_endereco_final, 'Oficina Credenciada');
  END IF;

  -- 4. Atualizar ESTRITAMENTE a ordem da instalação do veículo especificado
  UPDATE public.instalacoes
  SET 
    data_agendamento = p_data,
    hora_agendamento = trim(p_hora),
    local_tipo = v_tipo_local,
    local_endereco = v_endereco_final,
    solicita_endereco_cliente = FALSE,
    updated_at = now()
  WHERE id = p_instalacao_id;

  -- 5. Atualizar agendamento do cliente como referência geral
  IF v_cliente_id IS NOT NULL THEN
    UPDATE public.clientes
    SET 
      data_agendamento = p_data,
      hora_agendamento = trim(p_hora),
      status_agendamento = 'agendado',
      updated_at = now()
    WHERE id = v_cliente_id;
  END IF;

  -- 6. Disparar notificação imediata para o Cliente no dispositivo
  IF v_cliente_user_id IS NOT NULL THEN
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      destinatario_cliente_id,
      remetente_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa
    ) VALUES (
      v_cliente_user_id,
      v_cliente_id,
      v_caller_id,
      COALESCE(v_instalador_nome, 'Técnico Instalador'),
      '📅 Instalação Agendada: ' || v_placa,
      'Instalação agendada para ' || to_char(p_data, 'DD/MM/YYYY') || ' às ' || trim(p_hora) || 'h. Local: ' || COALESCE(v_endereco_final, 'A combinar') || '.',
      'agendamento',
      '/login',
      v_placa
    );
  END IF;

  -- 7. Disparar notificação para Administradores e Operadores
  INSERT INTO public.notificacoes_sistema (
    destinatario_user_id,
    remetente_user_id,
    remetente_nome,
    titulo,
    mensagem,
    tipo,
    url,
    placa
  )
  SELECT 
    p.id,
    v_caller_id,
    COALESCE(v_instalador_nome, 'Técnico Instalador'),
    '📅 Veículo Agendado: ' || v_placa,
    'Instalação agendada para ' || to_char(p_data, 'DD/MM/YYYY') || ' às ' || trim(p_hora) || 'h por ' || COALESCE(v_instalador_nome, 'instalador') || '.',
    'agendamento',
    '/instalacao',
    v_placa
  FROM public.profiles p
  WHERE p.role IN ('superadmin', 'adm', 'operador') AND p.id <> v_caller_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Agendamento confirmado com sucesso para o veículo ' || v_placa || '!'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_definir_agendamento_instalacao(UUID, DATE, TEXT, TEXT, TEXT) TO authenticated;

-- Invalidação canônica de cache PostgREST (Zero Schema Cache Error)
NOTIFY pgrst, 'reload schema';

-- ==============================================================================
-- HUNTER: NOTIFICAÇÃO INSTANTÂNEA E ATUALIZAÇÃO REATIVA DE INSTALAÇÃO E KIT NO BD
-- ==============================================================================

-- 1. Garante REPLICA IDENTITY FULL para que o Supabase Realtime propague eventos completos com RLS
ALTER TABLE public.instalacoes REPLICA IDENTITY FULL;
ALTER TABLE public.clientes REPLICA IDENTITY FULL;
ALTER TABLE public.veiculos REPLICA IDENTITY FULL;
ALTER TABLE public.notificacoes_sistema REPLICA IDENTITY FULL;

-- 2. Habilita tabelas na publicação supabase_realtime de forma idempotente
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables 
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'instalacoes'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.instalacoes;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables 
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'notificacoes_sistema'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.notificacoes_sistema;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables 
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'clientes'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.clientes;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables 
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'veiculos'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.veiculos;
  END IF;
END $$;

-- 3. Função de Trigger: Disparar Notificação Instantânea no BD ao atribuir Instalador, Kit ou Concluir Instalação
CREATE OR REPLACE FUNCTION public.trg_notificar_atribuicao_instalacao_kit()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_tem_kit_valido BOOLEAN;
  v_mudou_kit BOOLEAN;
  v_mudou_instalador BOOLEAN;
  v_concluiu_instalacao BOOLEAN;
  v_cliente_user_id UUID;
  v_cliente_nome TEXT;
  v_instalador_nome TEXT;
BEGIN
  -- Identifica o cliente associado
  IF NEW.cliente_id IS NOT NULL THEN
    SELECT user_id, nome_razao_social INTO v_cliente_user_id, v_cliente_nome
    FROM public.clientes
    WHERE id = NEW.cliente_id;
  END IF;

  -- Identifica o instalador associado
  IF NEW.instalador_id IS NOT NULL THEN
    SELECT nome INTO v_instalador_nome
    FROM public.profiles
    WHERE id = NEW.instalador_id;
  END IF;

  v_tem_kit_valido := (
    NEW.rastreador_imei IS NOT NULL 
    AND NEW.rastreador_imei NOT IN ('PENDENTE', 'AGUARDANDO ESTOQUE', 'A DEFINIR', 'SEM RASTREADOR', '')
  );

  v_mudou_instalador := (
    NEW.instalador_id IS NOT NULL 
    AND (TG_OP = 'INSERT' OR OLD.instalador_id IS DISTINCT FROM NEW.instalador_id)
  );

  v_mudou_kit := (
    v_tem_kit_valido 
    AND (TG_OP = 'INSERT' OR OLD.rastreador_imei IS DISTINCT FROM NEW.rastreador_imei)
  );

  v_concluiu_instalacao := (
    NEW.status = 'concluida' 
    AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'concluida')
  );

  -- 3.1. Se o instalador foi atribuído ou alterado
  IF v_mudou_instalador THEN
    -- Notifica o Instalador
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa,
      lida,
      created_at
    ) VALUES (
      NEW.instalador_id,
      'GD Rastreamento — Central Operacional',
      '🔧 Nova Instalação Atribuída: ' || COALESCE(NEW.placa, 'Veículo'),
      'Você foi designado para realizar a instalação do veículo ' || COALESCE(NEW.placa, '') || ' (' || COALESCE(NEW.marca, '') || ' ' || COALESCE(NEW.modelo, '') || '). ' || 
        CASE 
          WHEN v_tem_kit_valido THEN 'Kit de comodato já atribuído: IMEI ' || NEW.rastreador_imei || '.'
          ELSE 'Aguardando liberação de rastreador pelo operador.'
        END,
      'instalacao',
      '/instalacao',
      NEW.placa,
      FALSE,
      NOW()
    );

    -- Notifica o Cliente Titular
    IF v_cliente_user_id IS NOT NULL THEN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa,
        lida,
        created_at
      ) VALUES (
        v_cliente_user_id,
        NEW.cliente_id,
        'GD Rastreamento — Central Operacional',
        '🔧 Técnico Designado para seu Veículo: ' || COALESCE(NEW.placa, 'Veículo'),
        'O técnico credenciado ' || COALESCE(v_instalador_nome, 'especializado') || ' foi designado para o atendimento do seu veículo ' || COALESCE(NEW.placa, '') || ' (' || COALESCE(NEW.marca, '') || ' ' || COALESCE(NEW.modelo, '') || '). ' ||
          CASE 
            WHEN v_tem_kit_valido THEN 'O kit de rastreador já foi vinculado e preparado para agendamento.'
            ELSE 'Em breve alinharemos os detalhes para instalação.'
          END,
        'instalacao',
        '/login',
        NEW.placa,
        FALSE,
        NOW()
      );
    END IF;
  END IF;

  -- 3.2. Se um kit com IMEI real foi atribuído e já há instalador definido (e não foi o mesmo disparo anterior)
  IF v_mudou_kit AND NOT v_mudou_instalador THEN
    IF NEW.instalador_id IS NOT NULL THEN
      -- Notifica o Instalador
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa,
        lida,
        created_at
      ) VALUES (
        NEW.instalador_id,
        'GD Rastreamento — Central Operacional',
        '📦 Kit Rastreador Vinculado: ' || COALESCE(NEW.placa, 'Veículo'),
        'O operador vinculou o rastreador (IMEI ' || NEW.rastreador_imei || ') ao veículo ' || COALESCE(NEW.placa, '') || '. Equipamento disponível para conferência física e agendamento.',
        'instalacao',
        '/instalacao',
        NEW.placa,
        FALSE,
        NOW()
      );
    END IF;

    -- Notifica o Cliente Titular
    IF v_cliente_user_id IS NOT NULL THEN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa,
        lida,
        created_at
      ) VALUES (
        v_cliente_user_id,
        NEW.cliente_id,
        'GD Rastreamento — Central Operacional',
        '📦 Rastreador Preparado: ' || COALESCE(NEW.placa, 'Veículo'),
        'O rastreador foi vinculado ao seu veículo ' || COALESCE(NEW.placa, '') || '. O equipamento já está liberado para o técnico realizar a conferência e o agendamento.',
        'instalacao',
        '/login',
        NEW.placa,
        FALSE,
        NOW()
      );
    END IF;
  END IF;

  -- 3.3. Se a instalação foi concluída com sucesso
  IF v_concluiu_instalacao THEN
    -- Notifica o Cliente Titular com link direto ao Monitor GPS
    IF v_cliente_user_id IS NOT NULL THEN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa,
        lida,
        created_at
      ) VALUES (
        v_cliente_user_id,
        NEW.cliente_id,
        'GD Rastreamento — Central Operacional',
        '🎉 Instalação Concluída: ' || COALESCE(NEW.placa, 'Veículo'),
        'A instalação do rastreador no veículo ' || COALESCE(NEW.placa, '') || ' foi finalizada com sucesso! Seu veículo já está protegido e pronto para acompanhamento em tempo real.',
        'instalacao',
        '/monitor-gps',
        NEW.placa,
        FALSE,
        NOW()
      );
    END IF;

    -- Notifica Administradores e Operadores
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa,
      lida,
      created_at
    )
    SELECT 
      p.id,
      'GD Rastreamento — Central Operacional',
      '✅ Instalação Concluída: ' || COALESCE(NEW.placa, 'Veículo'),
      'O técnico ' || COALESCE(v_instalador_nome, 'instalador') || ' concluiu a instalação do veículo ' || COALESCE(NEW.placa, '') || ' (Cliente: ' || COALESCE(v_cliente_nome, 'Cliente') || ').',
      'instalacao',
      '/instalacao',
      NEW.placa,
      FALSE,
      NOW()
    FROM public.profiles p
    WHERE p.role IN ('superadmin', 'adm', 'operador');
  END IF;

  RETURN NEW;
END;
$$;

-- 4. Anexar o Trigger à Tabela public.instalacoes
DROP TRIGGER IF EXISTS trg_notificar_atribuicao_instalacao_kit ON public.instalacoes;
CREATE TRIGGER trg_notificar_atribuicao_instalacao_kit
  AFTER INSERT OR UPDATE OF instalador_id, rastreador_imei, rastreador_id, status
  ON public.instalacoes
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_notificar_atribuicao_instalacao_kit();

-- 5. Atualizar a RPC instalador_obter_minhas_demandas para incluir clientes cujas ORDENS pertencem ao instalador
CREATE OR REPLACE FUNCTION public.instalador_obter_minhas_demandas(
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_alvo_id UUID;
  v_ordens JSONB;
  v_agendamentos JSONB;
  v_resumo JSONB;
  v_total_a_receber NUMERIC(10,2);
  v_total_recebido NUMERIC(10,2);
  v_total_agendados_qtd INT;
  v_total_a_agendar_qtd INT;
  v_valor_previsto_agendados NUMERIC(10,2);
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') THEN
    v_alvo_id := COALESCE(p_instalador_id, v_caller_id);
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  -- 1. Coletar Ordens de Instalação Atribuídas
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', i.id,
      'cliente_id', i.cliente_id,
      'veiculo_id', i.veiculo_id,
      'instalador_id', i.instalador_id,
      'placa', i.placa,
      'marca', i.marca,
      'modelo', i.modelo,
      'ano', i.ano,
      'cor', i.cor,
      'tipo_veiculo', i.tipo_veiculo,
      'km_instalacao', i.km_instalacao,
      'tipo_servico', i.tipo_servico,
      'valor_instalacao', i.valor_instalacao,
      'status_pagamento', i.status_pagamento,
      'bloqueador_instalado', COALESCE(i.bloqueador_instalado, false),
      'com_bloqueador', COALESCE(i.bloqueador_instalado, false),
      'status', i.status,
      'posicao_instalacao', i.posicao_instalacao,
      'posicaoInstalacao', i.posicao_instalacao,
      'rastreador_id', i.rastreador_id,
      'rastreador_imei', i.rastreador_imei,
      'rastreador_modelo', i.rastreador_modelo,
      'chip_iccid', i.chip_iccid,
      'chip_operadora', i.chip_operadora,
      'data_agendamento', i.data_agendamento,
      'hora_agendamento', i.hora_agendamento,
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', i.local_endereco,
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, false),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'endereco_cliente_informado_em', i.endereco_cliente_informado_em,
      'solicitado_endereco_em', i.solicitado_endereco_em,
      'kit_confirmado_instalador', COALESCE(i.kit_confirmado_instalador, false),
      'kit_confirmado_em', i.kit_confirmado_em,
      'imei_confirmado', i.imei_confirmado,
      'instalador_nome', COALESCE(p.nome, 'Instalador Técnico'),
      'instalador_chave_pix', p.chave_pix,
      'cliente_nome', COALESCE(c.nome_razao_social, 'Cliente'),
      'cliente_telefone', c.telefone,
      'cliente_documento', c.documento,
      'motivo_pendencia_recusa', i.motivo_pendencia_recusa,
      'observacoes', i.observacoes,
      'created_at', i.created_at,
      'updated_at', i.updated_at,
      'concluida_at', i.concluida_at
    ) ORDER BY i.created_at DESC
  ), '[]'::JSONB)
  INTO v_ordens
  FROM public.instalacoes i
  LEFT JOIN public.profiles p ON p.id = i.instalador_id
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR i.instalador_id = v_alvo_id;

  -- 2. Coletar Clientes Agendados ou Aguardando Agendamento
  -- (Inclui clientes onde o instalador_id está no cliente OU em alguma de suas ordens de instalação)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'nome_razao_social', c.nome_razao_social,
      'documento', c.documento,
      'telefone', c.telefone,
      'email', c.email,
      'status', c.status,
      'plano', c.plano,
      'tem_fidelidade', c.tem_fidelidade,
      'regra_horimetro', c.regra_horimetro,
      'status_agendamento', COALESCE(c.status_agendamento, 'aguardando_agendamento'),
      'data_agendamento', c.data_agendamento,
      'hora_agendamento', c.hora_agendamento,
      'instalador_id', COALESCE(c.instalador_id, v_alvo_id),
      'instalador', jsonb_build_object(
        'id', p.id,
        'nome', p.nome,
        'endereco_instalacao', p.endereco_instalacao,
        'valor_com_bloqueador', p.valor_instalacao_com_bloqueador,
        'valor_sem_bloqueador', p.valor_instalacao_sem_bloqueador
      ),
      'veiculos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id, 
          'placa', v.placa, 
          'modelo', v.marca_modelo, 
          'tipo_veiculo', v.tipo_veiculo,
          'horimetro_horas', v.horimetro_horas
        ))
        FROM public.veiculos v
        WHERE v.cliente_id = c.id
      ), '[]'::JSONB)
    ) ORDER BY c.created_at DESC
  ), '[]'::JSONB)
  INTO v_agendamentos
  FROM public.clientes c
  LEFT JOIN public.profiles p ON p.id = COALESCE(c.instalador_id, v_alvo_id)
  WHERE (
    (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
    OR c.instalador_id = v_alvo_id
    OR EXISTS (SELECT 1 FROM public.instalacoes inst WHERE inst.cliente_id = c.id AND inst.instalador_id = v_alvo_id)
  )
  AND (c.status_agendamento IS DISTINCT FROM 'concluido' OR c.status = 'aguardando_instalacao');

  -- 3. Métricas Financeiras ESTRITAS
  SELECT 
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pendente' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pago' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN valor_instalacao ELSE 0 END), 0.00),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN 1 END),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NULL THEN 1 END)
  INTO 
    v_total_a_receber,
    v_total_recebido,
    v_valor_previsto_agendados,
    v_total_agendados_qtd,
    v_total_a_agendar_qtd
  FROM public.instalacoes
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR instalador_id = v_alvo_id;

  v_resumo := jsonb_build_object(
    'total_ordens', jsonb_array_length(v_ordens),
    'total_agendamentos', jsonb_array_length(v_agendamentos),
    'a_receber', v_total_a_receber,
    'recebido', v_total_recebido,
    'agendados_qtd', v_total_agendados_qtd,
    'a_agendar_qtd', v_total_a_agendar_qtd,
    'valor_previsto_agendados', v_valor_previsto_agendados
  );

  RETURN jsonb_build_object(
    'success', true,
    'ordens', v_ordens,
    'agendamentos', v_agendamentos,
    'resumo', v_resumo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_obter_minhas_demandas(UUID) TO authenticated;

-- ==============================================================================
-- CORREÇÃO DEFINITIVA DE CONFERÊNCIA DE IMEI E RPCs DE ENDEREÇO
-- ==============================================================================

-- 1. RPC: Instalador confirmar kit recebido (Sem bloqueio de tamanho mínimo)
CREATE OR REPLACE FUNCTION public.instalador_confirmar_kit(
  p_instalacao_id UUID,
  p_imei_conferido TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_inst RECORD;
  v_conferido_limpo TEXT;
  v_esperado_limpo TEXT;
  v_conferido_digitos TEXT;
  v_esperado_digitos TEXT;
  v_conferido_alnum TEXT;
  v_esperado_alnum TEXT;
  v_confere BOOLEAN := FALSE;
BEGIN
  v_user_id := auth.uid();
  
  IF p_imei_conferido IS NULL OR TRIM(p_imei_conferido) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Informe o código IMEI ou aponte a câmera para o código de barras.');
  END IF;

  SELECT 
    i.id, i.cliente_id, i.instalador_id, i.status, i.rastreador_id, i.rastreador_imei,
    r.imei AS imei_rastreador_real
  INTO v_inst
  FROM public.instalacoes i
  LEFT JOIN public.rastreadores r ON r.id = i.rastreador_id
  WHERE i.id = p_instalacao_id;

  IF v_inst.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada.');
  END IF;

  v_conferido_limpo := UPPER(TRIM(p_imei_conferido));
  v_esperado_limpo := UPPER(TRIM(COALESCE(v_inst.imei_rastreador_real, v_inst.rastreador_imei, '')));
  v_conferido_digitos := REGEXP_REPLACE(p_imei_conferido, '\D', '', 'g');
  v_esperado_digitos := REGEXP_REPLACE(COALESCE(v_inst.imei_rastreador_real, v_inst.rastreador_imei, ''), '\D', '', 'g');
  v_conferido_alnum := REGEXP_REPLACE(v_conferido_limpo, '[^0-9A-Z]', '', 'g');
  v_esperado_alnum := REGEXP_REPLACE(v_esperado_limpo, '[^0-9A-Z]', '', 'g');

  IF v_esperado_limpo = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Esta demanda ainda não possui um kit determinado pela administração.');
  END IF;

  -- Se o valor bater com o IMEI esperado, valida
  IF v_conferido_limpo = v_esperado_limpo THEN
    v_confere := TRUE;
  ELSIF v_conferido_alnum <> '' AND v_esperado_alnum <> '' AND v_conferido_alnum = v_esperado_alnum THEN
    v_confere := TRUE;
  ELSIF v_conferido_digitos <> '' AND v_esperado_digitos <> '' AND v_conferido_digitos = v_esperado_digitos THEN
    v_confere := TRUE;
  END IF;

  IF NOT v_confere THEN
    RETURN jsonb_build_object(
      'success', false, 
      'message', 'Divergência de equipamento: o IMEI digitado/lido (' || p_imei_conferido || ') não corresponde ao kit esperado (' || v_esperado_limpo || '). Verifique o aparelho em sua posse.'
    );
  END IF;

  UPDATE public.instalacoes
  SET 
    kit_confirmado_instalador = TRUE,
    kit_confirmado_em = NOW(),
    imei_confirmado = v_conferido_limpo,
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Kit físico confirmado com sucesso pelo instalador!',
    'imei', v_conferido_limpo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_confirmar_kit(UUID, TEXT) TO authenticated;

-- 2. Garantir colunas em instalacoes
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'solicita_endereco_cliente') THEN
    ALTER TABLE public.instalacoes ADD COLUMN solicita_endereco_cliente BOOLEAN DEFAULT FALSE;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'solicitado_endereco_em') THEN
    ALTER TABLE public.instalacoes ADD COLUMN solicitado_endereco_em TIMESTAMPTZ DEFAULT NULL;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'endereco_cliente_informado') THEN
    ALTER TABLE public.instalacoes ADD COLUMN endereco_cliente_informado TEXT DEFAULT NULL;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'endereco_cliente_informado_em') THEN
    ALTER TABLE public.instalacoes ADD COLUMN endereco_cliente_informado_em TIMESTAMPTZ DEFAULT NULL;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'local_tipo') THEN
    ALTER TABLE public.instalacoes ADD COLUMN local_tipo TEXT DEFAULT 'oficina';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'instalacoes' AND column_name = 'local_endereco') THEN
    ALTER TABLE public.instalacoes ADD COLUMN local_endereco TEXT DEFAULT NULL;
  END IF;
END $$;

-- 3. RPC: Instalador solicita endereço ao cliente
CREATE OR REPLACE FUNCTION public.instalador_solicitar_endereco_cliente(
  p_instalacao_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_inst RECORD;
  v_instalador_nome TEXT;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role, nome INTO v_role, v_instalador_nome FROM public.profiles WHERE id = v_caller_id;

  SELECT 
    i.id, i.cliente_id, i.placa, i.instalador_id, i.status,
    c.user_id AS cliente_user_id, c.nome_razao_social
  INTO v_inst
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id;

  IF v_inst.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada.');
  END IF;

  IF v_role = 'instalador' AND v_inst.instalador_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Permissão negada. Esta instalação pertence a outro profissional.');
  END IF;

  UPDATE public.instalacoes
  SET 
    solicita_endereco_cliente = TRUE,
    solicitado_endereco_em = NOW(),
    local_tipo = 'local_veiculo',
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  IF v_inst.cliente_user_id IS NOT NULL THEN
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      remetente_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa
    ) VALUES (
      v_inst.cliente_user_id,
      v_caller_id,
      COALESCE(v_instalador_nome, 'Técnico Instalador'),
      '📍 Endereço de Atendimento Necessário',
      'O instalador precisa do endereço onde o veículo ' || COALESCE(v_inst.placa, '') || ' estará para realizar o atendimento presencial.',
      'agendamento',
      '/login',
      v_inst.placa
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Solicitação de endereço enviada com sucesso ao cliente!'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_solicitar_endereco_cliente(UUID) TO authenticated;

-- 4. RPC: Cliente informa o endereço
CREATE OR REPLACE FUNCTION public.cliente_informar_endereco_instalacao(
  p_instalacao_id UUID,
  p_endereco TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_inst RECORD;
  v_cliente_nome TEXT;
  v_endereco_limpo TEXT;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  v_endereco_limpo := TRIM(p_endereco);
  IF v_endereco_limpo IS NULL OR v_endereco_limpo = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Informe um endereço válido.');
  END IF;

  SELECT 
    i.id, i.cliente_id, i.placa, i.instalador_id, i.status,
    c.user_id AS cliente_user_id, c.nome_razao_social
  INTO v_inst
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id;

  IF v_inst.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada.');
  END IF;

  v_cliente_nome := COALESCE(v_inst.nome_razao_social, 'Cliente');

  UPDATE public.instalacoes
  SET 
    endereco_cliente_informado = v_endereco_limpo,
    local_endereco = v_endereco_limpo,
    local_tipo = 'local_veiculo',
    solicita_endereco_cliente = FALSE,
    endereco_cliente_informado_em = NOW(),
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  IF v_inst.instalador_id IS NOT NULL THEN
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      remetente_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa
    ) VALUES (
      v_inst.instalador_id,
      v_caller_id,
      v_cliente_nome,
      '📍 Endereço Informado pelo Cliente: ' || COALESCE(v_inst.placa, ''),
      'Cliente informou o endereço: ' || v_endereco_limpo || ' para instalação no veículo ' || COALESCE(v_inst.placa, '') || '.',
      'agendamento',
      '/instalacao',
      v_inst.placa
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Endereço registrado com sucesso! O instalador foi notificado imediatamente.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cliente_informar_endereco_instalacao(UUID, TEXT) TO authenticated;

-- Invalidação canônica de cache PostgREST (Zero Schema Cache Error)
NOTIFY pgrst, 'reload schema';

-- ==============================================================================
-- HUNTER: BLOQUEIO RIGOROSO DE AGENDAMENTO SEM KIT DISPONIBILIZADO
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.instalador_definir_agendamento_instalacao(
  p_instalacao_id UUID,
  p_data DATE,
  p_hora TEXT,
  p_local_tipo TEXT DEFAULT 'oficina',
  p_local_endereco TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_caller_role TEXT;
  v_caller_nome TEXT;
  v_instalador_id UUID;
  v_cliente_id UUID;
  v_cliente_user_id UUID;
  v_placa TEXT;
  v_rastreador_imei TEXT;
  v_instalador_nome TEXT;
  v_endereco_final TEXT;
  v_tipo_local TEXT;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role, nome INTO v_caller_role, v_caller_nome 
  FROM public.profiles 
  WHERE id = v_caller_id;

  -- 1. Resgatar instalação alvo e dados do cliente
  SELECT 
    i.instalador_id, 
    i.cliente_id, 
    i.placa,
    i.rastreador_imei,
    c.user_id,
    p.nome,
    p.endereco_instalacao
  INTO 
    v_instalador_id, 
    v_cliente_id, 
    v_placa,
    v_rastreador_imei,
    v_cliente_user_id,
    v_instalador_nome,
    v_endereco_final
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, v_caller_id)
  WHERE i.id = p_instalacao_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não encontrada.');
  END IF;

  -- 2. Trava de integridade operacional: não é possível agendar sem kit disponibilizado
  IF v_rastreador_imei IS NULL 
     OR TRIM(v_rastreador_imei) = '' 
     OR UPPER(TRIM(v_rastreador_imei)) IN (
       'AGUARDANDO ESTOQUE', 
       'AGUARDANDO_ESTOQUE', 
       'PENDENTE', 
       'A DEFINIR', 
       'A_DEFINIR', 
       'SEM RASTREADOR', 
       'SEM_RASTREADOR', 
       'A CONFERIR', 
       'A_CONFERIR',
       'NENHUM'
     ) THEN
    RETURN jsonb_build_object(
      'success', false, 
      'message', 'Não é possível agendar sem kit disponibilizado para este veículo. O operador deve vincular e disponibilizar o kit antes de definir a data.'
    );
  END IF;

  -- Se v_instalador_id estiver nulo e o chamador for instalador, atribuir ao chamador
  IF v_instalador_id IS NULL THEN
    IF v_caller_role = 'instalador' THEN
      v_instalador_id := v_caller_id;
      UPDATE public.instalacoes SET instalador_id = v_caller_id WHERE id = p_instalacao_id;
    END IF;
  END IF;

  -- 3. Permissão: instalador atribuído ou equipe de operações/administração
  IF v_caller_role = 'instalador' AND v_instalador_id IS NOT NULL AND v_instalador_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Acesso negado: apenas o instalador atribuído ou a equipe de operações podem agendar esta instalação.');
  END IF;

  -- 4. Validações de data e hora
  IF p_data IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'A data do agendamento é obrigatória.');
  END IF;

  IF p_hora IS NULL OR trim(p_hora) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'O horário do agendamento é obrigatório.');
  END IF;

  v_tipo_local := COALESCE(p_local_tipo, 'oficina');
  IF v_tipo_local = 'local_veiculo' THEN
    v_endereco_final := COALESCE(TRIM(p_local_endereco), v_endereco_final);
  ELSE
    v_endereco_final := COALESCE(TRIM(p_local_endereco), v_endereco_final, 'Oficina Credenciada');
  END IF;

  -- 5. Atualizar ordem da instalação do veículo especificado
  UPDATE public.instalacoes
  SET 
    data_agendamento = p_data,
    hora_agendamento = trim(p_hora),
    status = 'agendado',
    local_tipo = v_tipo_local,
    local_endereco = v_endereco_final,
    solicita_endereco_cliente = FALSE,
    updated_at = now()
  WHERE id = p_instalacao_id;

  -- 6. Atualizar status e dados do agendamento no cadastro do cliente
  IF v_cliente_id IS NOT NULL THEN
    UPDATE public.clientes
    SET 
      data_agendamento = p_data,
      hora_agendamento = trim(p_hora),
      status_agendamento = 'agendado',
      updated_at = now()
    WHERE id = v_cliente_id;
  END IF;

  -- 7. Histórico de atendimento técnico (se tabela instalacoes_historico_atendimentos estiver ativa)
  BEGIN
    IF v_instalador_id IS NOT NULL THEN
      INSERT INTO public.instalacoes_historico_atendimentos (
        instalacao_id,
        instalador_id,
        status_atendimento,
        motivo,
        observacoes
      ) VALUES (
        p_instalacao_id,
        v_instalador_id,
        'agendado',
        'Definição de agendamento',
        format('Agendado para %s às %s (%s).', to_char(p_data, 'DD/MM/YYYY'), trim(p_hora), v_endereco_final)
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- 8. Notificação em tempo real para o cliente (com colunas corretas de notificacoes_sistema)
  IF v_cliente_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        v_cliente_user_id,
        v_cliente_id,
        v_caller_id,
        COALESCE(v_instalador_nome, v_caller_nome, 'Técnico Instalador'),
        format('📅 Instalação Agendada: %s', COALESCE(v_placa, 'Veículo')),
        format('A instalação do seu rastreador no veículo %s foi agendada para %s às %s (%s: %s).',
          COALESCE(v_placa, ''),
          to_char(p_data, 'DD/MM/YYYY'),
          trim(p_hora),
          CASE WHEN v_tipo_local = 'local_veiculo' THEN 'Local do Veículo' ELSE 'Oficina' END,
          COALESCE(v_endereco_final, 'Oficina Credenciada')
        ),
        'agendamento',
        '/login',
        v_placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', format('Instalação do veículo %s agendada com sucesso para %s às %s.', COALESCE(v_placa, ''), to_char(p_data, 'DD/MM/YYYY'), trim(p_hora)),
    'instalacao_id', p_instalacao_id,
    'placa', v_placa,
    'data', p_data,
    'hora', trim(p_hora),
    'local_tipo', v_tipo_local,
    'local_endereco', v_endereco_final
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_definir_agendamento_instalacao(UUID, DATE, TEXT, TEXT, TEXT) TO authenticated;

-- ==============================================================================
-- SINCRONIZAÇÃO INSTANTÂNEA EM TEMPO REAL: AGENDAMENTO E NOTIFICAÇÕES (HUNTER-GUARDIAN)
-- ==============================================================================

ALTER TABLE public.instalacoes ADD COLUMN IF NOT EXISTS cliente_user_id UUID;

UPDATE public.instalacoes i
SET cliente_user_id = c.user_id
FROM public.clientes c
WHERE c.id = i.cliente_id AND i.cliente_user_id IS NULL;

CREATE OR REPLACE FUNCTION public.trg_sync_instalacao_cliente_user_id()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.cliente_id IS NOT NULL AND (NEW.cliente_user_id IS NULL OR TG_OP = 'INSERT') THEN
    SELECT user_id INTO NEW.cliente_user_id FROM public.clientes WHERE id = NEW.cliente_id;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_instalacoes_sync_cliente_user_id ON public.instalacoes;
CREATE TRIGGER trg_instalacoes_sync_cliente_user_id
BEFORE INSERT OR UPDATE OF cliente_id ON public.instalacoes
FOR EACH ROW EXECUTE FUNCTION public.trg_sync_instalacao_cliente_user_id();

DROP POLICY IF EXISTS "Clientes visualizam suas proprias ordens de instalacao" ON public.instalacoes;
CREATE POLICY "Clientes visualizam suas proprias ordens de instalacao"
ON public.instalacoes FOR SELECT TO authenticated
USING (
  cliente_user_id = auth.uid()
  OR cliente_id = auth.uid()
  OR cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
);

ALTER TABLE public.instalacoes REPLICA IDENTITY FULL;
ALTER TABLE public.clientes REPLICA IDENTITY FULL;
ALTER TABLE public.notificacoes_sistema REPLICA IDENTITY FULL;

CREATE OR REPLACE FUNCTION public.cliente_obter_meus_veiculos_instalacao(p_cliente_user_id UUID DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  v_uid UUID := COALESCE(p_cliente_user_id, auth.uid());
  v_cliente_id UUID;
  v_lista JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não autenticado.', 'veiculos', '[]'::jsonb);
  END IF;

  SELECT id INTO v_cliente_id FROM public.clientes WHERE user_id = v_uid LIMIT 1;
  IF v_cliente_id IS NULL THEN
    SELECT id INTO v_cliente_id FROM public.clientes WHERE id = v_uid LIMIT 1;
  END IF;

  IF v_cliente_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'veiculos', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'instalacao_id', i.id,
      'veiculo_id', i.veiculo_id,
      'placa', COALESCE(i.placa, 'SEM PLACA'),
      'marca', COALESCE(i.marca, ''),
      'modelo', COALESCE(i.modelo, ''),
      'ano', i.ano,
      'cor', i.cor,
      'tipo_veiculo', COALESCE(i.tipo_veiculo, 'carro'),
      'status_instalacao', COALESCE(i.status, 'nao_instalado'),
      'data_agendamento', i.data_agendamento,
      'hora_agendamento', i.hora_agendamento,
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', i.local_endereco,
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, false),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'rastreador_imei', i.rastreador_imei,
      'instalador_id', i.instalador_id,
      'instalador_nome', p.nome,
      'instalador_telefone', p.telefone,
      'instalador_endereco', p.endereco_instalacao
    ) ORDER BY i.created_at ASC
  ), '[]'::jsonb) INTO v_lista
  FROM public.instalacoes i
  LEFT JOIN public.profiles p ON p.id = i.instalador_id
  WHERE (i.cliente_id = v_cliente_id OR i.cliente_user_id = v_uid);

  RETURN jsonb_build_object(
    'success', true,
    'veiculos', v_lista
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cliente_obter_meus_veiculos_instalacao(UUID) TO authenticated;

CREATE OR REPLACE FUNCTION public.cliente_informar_endereco_instalacao(
  p_instalacao_id UUID,
  p_endereco TEXT
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_cliente_id UUID;
  v_instalador_id UUID;
  v_placa TEXT;
  v_cliente_nome TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não autenticado.');
  END IF;

  SELECT i.cliente_id, i.instalador_id, i.placa, c.nome_razao_social
  INTO v_cliente_id, v_instalador_id, v_placa, v_cliente_nome
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id
    AND (i.cliente_user_id = v_uid OR i.cliente_id = v_uid OR i.cliente_id IN (SELECT id FROM public.clientes WHERE user_id = v_uid));

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada para este cliente.');
  END IF;

  UPDATE public.instalacoes
  SET 
    endereco_cliente_informado = TRIM(p_endereco),
    endereco_cliente_informado_em = now(),
    solicita_endereco_cliente = FALSE,
    local_endereco = TRIM(p_endereco),
    updated_at = now()
  WHERE id = p_instalacao_id;

  IF v_instalador_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        v_instalador_id,
        v_uid,
        COALESCE(v_cliente_nome, 'Cliente'),
        format('📍 Endereço de Instalação: %s', COALESCE(v_placa, 'Veículo')),
        format('O cliente informou o local para instalação do veículo %s: %s.', COALESCE(v_placa, ''), TRIM(p_endereco)),
        'instalacao',
        '/instalacao',
        v_placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Endereço registrado com sucesso. O instalador foi notificado.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cliente_informar_endereco_instalacao(UUID, TEXT) TO authenticated;

-- ==============================================================================
-- NOTIFICAÇÃO IMEDIATA DA EQUIPE OPERAÇÃO/ADM E HISTÓRICO DO CLIENTE
-- ==============================================================================

-- 1. Permissão de SELECT para clientes em seu próprio histórico de atendimento
DROP POLICY IF EXISTS "Historico visivel para clientes de suas ordens" ON public.instalacoes_historico_atendimentos;
CREATE POLICY "Historico visivel para clientes de suas ordens"
ON public.instalacoes_historico_atendimentos FOR SELECT TO authenticated
USING (
  is_admin_or_superadmin(auth.uid())
  OR EXISTS (
    SELECT 1 FROM public.user_roles ur 
    WHERE ur.user_id = auth.uid() AND ur.role = 'operador'::hunter_role
  )
  OR instalador_id = auth.uid()
  OR instalacao_id IN (
    SELECT i.id FROM public.instalacoes i
    WHERE i.cliente_user_id = auth.uid() 
       OR i.cliente_id = auth.uid()
       OR i.cliente_id IN (SELECT c.id FROM public.clientes c WHERE c.user_id = auth.uid())
  )
);

-- 1.1. Permissão de SELECT em notificacoes_sistema para clientes e operadores
DROP POLICY IF EXISTS "Usuarios podem ler suas proprias notificacoes ou administradores leem todas" ON public.notificacoes_sistema;
CREATE POLICY "Usuarios podem ler suas proprias notificacoes ou administradores leem todas"
  ON public.notificacoes_sistema FOR SELECT TO authenticated
  USING (
    destinatario_user_id = auth.uid()
    OR destinatario_cliente_id IN (
      SELECT id FROM public.clientes WHERE user_id = auth.uid()
    )
    OR remetente_user_id = auth.uid()
    OR public.is_admin_or_superadmin(auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.user_roles ur 
      WHERE ur.user_id = auth.uid() AND ur.role = 'operador'::hunter_role
    )
  );

-- 2. Função RPC para notificar todos os operadores e administradores ativos
CREATE OR REPLACE FUNCTION public.notificar_equipe_operacao(
  p_remetente_id UUID,
  p_remetente_nome TEXT,
  p_titulo TEXT,
  p_mensagem TEXT,
  p_tipo TEXT DEFAULT 'instalacao',
  p_url TEXT DEFAULT '/instalacao',
  p_placa TEXT DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN (
    SELECT DISTINCT p.id 
    FROM public.profiles p
    LEFT JOIN public.user_roles ur ON ur.user_id = p.id
    WHERE (p.role IN ('superadmin', 'adm', 'operador') OR ur.role IN ('superadmin', 'adm', 'operador'))
      AND p.ativo = TRUE
      AND p.id <> COALESCE(p_remetente_id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) LOOP
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        r.id,
        NULL, -- Destinatário é estritamente a equipe interna (r.id), NUNCA o cliente
        p_remetente_id,
        p_remetente_nome,
        p_titulo,
        p_mensagem,
        p_tipo,
        p_url,
        p_placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.notificar_equipe_operacao(UUID, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, UUID) TO authenticated;

-- 3. Atualização de instalador_definir_agendamento_instalacao com histórico e aviso à equipe
CREATE OR REPLACE FUNCTION public.instalador_definir_agendamento_instalacao(
  p_instalacao_id UUID,
  p_data DATE,
  p_hora TEXT,
  p_local_tipo TEXT DEFAULT 'oficina'::TEXT,
  p_local_endereco TEXT DEFAULT NULL::TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_caller_role TEXT;
  v_caller_nome TEXT;
  v_instalador_id UUID;
  v_cliente_id UUID;
  v_cliente_user_id UUID;
  v_cliente_nome TEXT;
  v_placa TEXT;
  v_rastreador_imei TEXT;
  v_instalador_nome TEXT;
  v_endereco_final TEXT;
  v_tipo_local TEXT;
  v_tipo_acao TEXT := 'Agendamento';
  v_ja_estava_agendado BOOLEAN := FALSE;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role, nome INTO v_caller_role, v_caller_nome 
  FROM public.profiles 
  WHERE id = v_caller_id;

  SELECT 
    i.instalador_id, 
    i.cliente_id, 
    i.placa,
    i.rastreador_imei,
    i.data_agendamento IS NOT NULL,
    c.user_id,
    c.nome_razao_social,
    p.nome,
    p.endereco_instalacao
  INTO 
    v_instalador_id, 
    v_cliente_id, 
    v_placa, 
    v_rastreador_imei,
    v_ja_estava_agendado,
    v_cliente_user_id,
    v_cliente_nome,
    v_instalador_nome,
    v_endereco_final
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, v_caller_id)
  WHERE i.id = p_instalacao_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não encontrada.');
  END IF;

  IF v_rastreador_imei IS NULL 
     OR TRIM(v_rastreador_imei) = '' 
     OR UPPER(TRIM(v_rastreador_imei)) IN (
       'AGUARDANDO ESTOQUE', 
       'AGUARDANDO_ESTOQUE', 
       'PENDENTE', 
       'A DEFINIR', 
       'A_DEFINIR', 
       'SEM RASTREADOR', 
       'SEM_RASTREADOR', 
       'A CONFERIR', 
       'A_CONFERIR', 
       'NENHUM'
     ) THEN
    RETURN jsonb_build_object(
      'success', false, 
      'message', 'Não é possível agendar sem kit disponibilizado para este veículo. O operador deve vincular e disponibilizar o kit antes de definir a data.'
    );
  END IF;

  IF v_instalador_id IS NULL THEN
    IF v_caller_role = 'instalador' THEN
      v_instalador_id := v_caller_id;
      UPDATE public.instalacoes SET instalador_id = v_caller_id WHERE id = p_instalacao_id;
    END IF;
  END IF;

  IF v_caller_role = 'instalador' AND v_instalador_id IS NOT NULL AND v_instalador_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Acesso negado: apenas o instalador atribuído ou a equipe de operações podem agendar esta instalação.');
  END IF;

  IF p_data IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'A data do agendamento é obrigatória.');
  END IF;

  IF p_hora IS NULL OR TRIM(p_hora) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'O horário do agendamento é obrigatório.');
  END IF;

  v_tipo_local := COALESCE(p_local_tipo, 'oficina');
  IF v_tipo_local = 'local_veiculo' THEN
    v_endereco_final := COALESCE(TRIM(p_local_endereco), v_endereco_final);
  ELSE
    v_endereco_final := COALESCE(TRIM(p_local_endereco), v_endereco_final, 'Oficina Credenciada');
  END IF;

  UPDATE public.instalacoes
  SET 
    data_agendamento = p_data,
    hora_agendamento = TRIM(p_hora),
    status = 'agendada',
    local_tipo = v_tipo_local,
    local_endereco = v_endereco_final,
    solicita_endereco_cliente = FALSE,
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  IF v_cliente_id IS NOT NULL THEN
    UPDATE public.clientes
    SET 
      data_agendamento = p_data,
      hora_agendamento = TRIM(p_hora),
      status_agendamento = 'agendado',
      updated_at = NOW()
    WHERE id = v_cliente_id;
  END IF;

  IF v_ja_estava_agendado THEN
    v_tipo_acao := 'Reagendamento';
  END IF;

  -- Registra no histórico funcional de atendimentos
  BEGIN
    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes
    ) VALUES (
      p_instalacao_id,
      COALESCE(v_instalador_id, v_caller_id),
      'agendada',
      v_tipo_acao,
      format('%s confirmado para %s às %s (%s: %s). Técnico: %s.',
        v_tipo_acao,
        to_char(p_data, 'DD/MM/YYYY'),
        TRIM(p_hora),
        CASE WHEN v_tipo_local = 'local_veiculo' THEN 'Local do Veículo' ELSE 'Oficina' END,
        v_endereco_final,
        COALESCE(v_instalador_nome, v_caller_nome, 'Técnico Responsável')
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Notifica o CLIENTE (apenas 1 notificação atômica)
  IF v_cliente_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        v_cliente_user_id,
        v_cliente_id,
        v_caller_id,
        COALESCE(v_instalador_nome, v_caller_nome, 'Técnico Instalador'),
        format('📅 Instalação %s: %s', CASE WHEN v_ja_estava_agendado THEN 'Reagendada' ELSE 'Agendada' END, COALESCE(v_placa, 'Veículo')),
        format('A instalação do seu rastreador no veículo %s foi %s para %s às %s (%s: %s).',
          COALESCE(v_placa, ''),
          CASE WHEN v_ja_estava_agendado THEN 'reagendada' ELSE 'agendada' END,
          to_char(p_data, 'DD/MM/YYYY'),
          TRIM(p_hora),
          CASE WHEN v_tipo_local = 'local_veiculo' THEN 'Local do Veículo' ELSE 'Oficina' END,
          COALESCE(v_endereco_final, 'Oficina Credenciada')
        ),
        'agendamento',
        '/login',
        v_placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- Notifica imediatamente OPERADORES E ADMINISTRADORES para ciência total
  PERFORM public.notificar_equipe_operacao(
    v_caller_id,
    COALESCE(v_instalador_nome, v_caller_nome, 'Técnico Instalador'),
    format('📅 Instalação %s: %s', CASE WHEN v_ja_estava_agendado THEN 'Reagendada' ELSE 'Agendada' END, COALESCE(v_placa, 'Veículo')),
    format('O técnico %s definiu o agendamento do veículo %s (Cliente: %s) para %s às %s (%s: %s).',
      COALESCE(v_instalador_nome, v_caller_nome, 'Técnico'),
      COALESCE(v_placa, ''),
      COALESCE(v_cliente_nome, 'Cliente'),
      to_char(p_data, 'DD/MM/YYYY'),
      TRIM(p_hora),
      CASE WHEN v_tipo_local = 'local_veiculo' THEN 'Local do Veículo' ELSE 'Oficina' END,
      COALESCE(v_endereco_final, 'Oficina Credenciada')
    ),
    'agendamento',
    '/instalacao',
    v_placa,
    v_cliente_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', format('Instalação do veículo %s agendada com sucesso para %s às %s.', COALESCE(v_placa, ''), to_char(p_data, 'DD/MM/YYYY'), TRIM(p_hora)),
    'instalacao_id', p_instalacao_id,
    'placa', v_placa,
    'data', p_data,
    'hora', TRIM(p_hora),
    'local_tipo', v_tipo_local,
    'local_endereco', v_endereco_final
  );
END;
$$;

-- 4. Atualização de instalador_solicitar_endereco_cliente com histórico e aviso à equipe
CREATE OR REPLACE FUNCTION public.instalador_solicitar_endereco_cliente(p_instalacao_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_role TEXT;
  v_inst RECORD;
  v_instalador_nome TEXT;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role, nome INTO v_role, v_instalador_nome FROM public.profiles WHERE id = v_caller_id;

  SELECT 
    i.id, i.cliente_id, i.placa, i.instalador_id, i.status,
    c.user_id AS cliente_user_id, c.nome_razao_social
  INTO v_inst
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id;

  IF v_inst.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada.');
  END IF;

  IF v_role = 'instalador' AND v_inst.instalador_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Permissão negada. Esta instalação pertence a outro profissional.');
  END IF;

  UPDATE public.instalacoes
  SET 
    solicita_endereco_cliente = TRUE,
    solicitado_endereco_em = NOW(),
    local_tipo = 'local_veiculo',
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  -- Registra no histórico funcional de atendimentos
  BEGIN
    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes
    ) VALUES (
      p_instalacao_id,
      v_caller_id,
      'solicitacao_endereco',
      'Solicitação de Endereço',
      format('Técnico %s solicitou o endereço de atendimento presencial ao cliente para o veículo %s.',
        COALESCE(v_instalador_nome, 'Técnico'),
        COALESCE(v_inst.placa, '')
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Notifica o CLIENTE (apenas 1 notificação atômica)
  IF v_inst.cliente_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        v_inst.cliente_user_id,
        v_inst.cliente_id,
        v_caller_id,
        COALESCE(v_instalador_nome, 'Técnico Instalador'),
        format('📍 Endereço Necessário: %s', COALESCE(v_inst.placa, 'Veículo')),
        format('O técnico precisa do endereço onde o veículo %s estará para realizar a instalação presencial. Acesse para informar.', COALESCE(v_inst.placa, '')),
        'agendamento',
        '/login',
        v_inst.placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- Notifica imediatamente OPERADORES E ADMINISTRADORES
  PERFORM public.notificar_equipe_operacao(
    v_caller_id,
    COALESCE(v_instalador_nome, 'Técnico Instalador'),
    format('📍 Endereço Solicitado: %s', COALESCE(v_inst.placa, 'Veículo')),
    format('O técnico %s solicitou o endereço do veículo %s ao cliente %s para atendimento presencial.',
      COALESCE(v_instalador_nome, 'Técnico'),
      COALESCE(v_inst.placa, ''),
      COALESCE(v_inst.nome_razao_social, 'Cliente')
    ),
    'agendamento',
    '/instalacao',
    v_inst.placa,
    v_inst.cliente_id
  );

  RETURN jsonb_build_object('success', true, 'message', 'Solicitação de endereço enviada ao cliente com sucesso.');
END;
$$;

-- 5. Atualização de cliente_informar_endereco_instalacao com histórico e aviso à equipe
CREATE OR REPLACE FUNCTION public.cliente_informar_endereco_instalacao(
  p_instalacao_id UUID,
  p_endereco TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_cliente_id UUID;
  v_instalador_id UUID;
  v_placa TEXT;
  v_cliente_nome TEXT;
  v_instalador_user_id UUID;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não autenticado.');
  END IF;

  SELECT 
    i.cliente_id, 
    i.instalador_id, 
    i.placa, 
    c.nome_razao_social,
    i.instalador_id
  INTO 
    v_cliente_id, 
    v_instalador_id, 
    v_placa, 
    v_cliente_nome,
    v_instalador_user_id
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id
    AND (i.cliente_user_id = v_uid OR i.cliente_id = v_uid OR i.cliente_id IN (SELECT id FROM public.clientes WHERE user_id = v_uid));

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada para este cliente.');
  END IF;

  UPDATE public.instalacoes
  SET 
    endereco_cliente_informado = TRIM(p_endereco),
    endereco_cliente_informado_em = NOW(),
    solicita_endereco_cliente = FALSE,
    local_endereco = TRIM(p_endereco),
    local_tipo = 'local_veiculo',
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  -- Registra no histórico funcional de atendimentos
  BEGIN
    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes
    ) VALUES (
      p_instalacao_id,
      v_instalador_id,
      'endereco_informado',
      'Endereço Informado pelo Cliente',
      format('Cliente %s informou o endereço de atendimento do veículo %s: %s.',
        COALESCE(v_cliente_nome, 'Cliente'),
        COALESCE(v_placa, ''),
        TRIM(p_endereco)
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Notifica o INSTALADOR (apenas 1 notificação atômica)
  IF v_instalador_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        v_instalador_user_id,
        v_uid,
        COALESCE(v_cliente_nome, 'Cliente'),
        format('📍 Endereço Informado: %s', COALESCE(v_placa, 'Veículo')),
        format('O cliente %s informou o local para o veículo %s: %s. Disponível para agendamento presencial.',
          COALESCE(v_cliente_nome, ''),
          COALESCE(v_placa, ''),
          TRIM(p_endereco)
        ),
        'agendamento',
        '/instalacao',
        v_placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- Notifica imediatamente OPERADORES E ADMINISTRADORES
  PERFORM public.notificar_equipe_operacao(
    v_uid,
    COALESCE(v_cliente_nome, 'Cliente'),
    format('📍 Endereço Informado: %s', COALESCE(v_placa, 'Veículo')),
    format('O cliente %s informou o local para atendimento do veículo %s: %s.',
      COALESCE(v_cliente_nome, 'Cliente'),
      COALESCE(v_placa, ''),
      TRIM(p_endereco)
    ),
    'agendamento',
    '/instalacao',
    v_placa,
    v_cliente_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Endereço registrado com sucesso. O instalador e a central de operações foram notificados.'
  );
END;
$$;

NOTIFY pgrst, 'reload schema';
-- ==============================================================================
-- HUNTER: SINCRONIZAÇÃO ATÔMICA DE TROCA DE INSTALADOR E ANTI-DUPLICAÇÃO DE NOTIFICAÇÕES
-- ==============================================================================

-- 1. Atualizar RPC admin_atualizar_cliente_completo para propagar atomicamente
--    a troca de instalador para todas as ordens de instalação pendentes do cliente
CREATE OR REPLACE FUNCTION public.admin_atualizar_cliente_completo(
  p_cliente_id UUID,
  p_nome TEXT,
  p_documento TEXT,
  p_email TEXT,
  p_telefone TEXT,
  p_status public.status_cliente,
  p_plano public.plano_cliente,
  p_dia_vencimento INT,
  p_valor_mensalidade NUMERIC,
  p_dias_historico INT,
  p_dias_retencao INT,
  p_senha TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL,
  p_meses_contrato INT DEFAULT 12,
  p_data_inicio_contrato DATE DEFAULT CURRENT_DATE,
  p_tipo_renovacao TEXT DEFAULT 'mesma_vigencia',
  p_meses_renovacao INT DEFAULT 12,
  p_foro_comarca TEXT DEFAULT 'Volta Redonda/RJ',
  p_gerar_parcelas_ausentes BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_email_limpo TEXT := lower(trim(coalesce(p_email, '')));
  v_resultado_parcelas JSONB := '[]'::JSONB;
  v_meses_c INT := COALESCE(p_meses_contrato, 12);
  v_data_inicio DATE := COALESCE(p_data_inicio_contrato, CURRENT_DATE);
  v_data_fim DATE;
  v_status_final public.status_cliente := p_status;
  v_status_agendamento_final TEXT;
  r_veiculo RECORD;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar clientes.';
  END IF;

  SELECT user_id, status_agendamento INTO v_user_id, v_status_agendamento_final
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.';
  END IF;

  v_data_fim := v_data_inicio + (v_meses_c || ' months')::INTERVAL;

  -- Se foi atribuído ou alterado instalador:
  IF p_instalador_id IS NOT NULL THEN
    IF v_status_agendamento_final IS NULL OR v_status_agendamento_final = 'concluido' THEN
      v_status_agendamento_final := 'aguardando_agendamento';
    END IF;
    -- Se cliente não possui veículos ativos com rastreadores, força status operacional aguardando_instalacao
    IF NOT EXISTS (
      SELECT 1 FROM public.veiculos WHERE cliente_id = p_cliente_id AND ativo = TRUE AND rastreador_id IS NOT NULL
    ) THEN
      v_status_final := 'aguardando_instalacao'::public.status_cliente;
    END IF;

    -- Sincronização atômica imediata no BD:
    -- Atualiza o instalador_id de todas as ordens de serviço pendentes do cliente
    UPDATE public.instalacoes
    SET instalador_id = p_instalador_id,
        updated_at = NOW()
    WHERE cliente_id = p_cliente_id AND status != 'concluida';

    -- Se o cliente possui veículos cadastrados sem ordem de instalação aberta, cria a ordem para o novo instalador
    FOR r_veiculo IN
      SELECT v.id, v.placa, v.marca, v.modelo, v.ano, v.tipo_veiculo
      FROM public.veiculos v
      WHERE v.cliente_id = p_cliente_id
        AND NOT EXISTS (
          SELECT 1 FROM public.instalacoes i 
          WHERE i.veiculo_id = v.id AND i.status != 'cancelada'
        )
    LOOP
      INSERT INTO public.instalacoes (
        cliente_id,
        veiculo_id,
        placa,
        marca,
        modelo,
        ano,
        tipo_veiculo,
        instalador_id,
        status,
        rastreador_imei,
        created_at,
        updated_at
      ) VALUES (
        p_cliente_id,
        r_veiculo.id,
        r_veiculo.placa,
        r_veiculo.marca,
        r_veiculo.modelo,
        r_veiculo.ano,
        COALESCE(r_veiculo.tipo_veiculo, 'carro'),
        p_instalador_id,
        'aguardando_agendamento',
        'AGUARDANDO ESTOQUE',
        NOW(),
        NOW()
      );
    END LOOP;
  END IF;

  -- Atualizar credenciais de auth se aplicável
  IF v_user_id IS NOT NULL THEN
    IF v_email_limpo <> '' THEN
      UPDATE auth.users
      SET email = v_email_limpo,
          raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome), 'email', v_email_limpo),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE public.profiles
      SET nome = trim(p_nome),
          email = v_email_limpo,
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.identities
      SET identity_data = jsonb_set(identity_data, '{email}', to_jsonb(v_email_limpo)),
          provider_id = v_email_limpo
      WHERE user_id = v_user_id AND provider = 'email';
    ELSE
      UPDATE public.profiles
      SET nome = trim(p_nome),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.users
      SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    IF p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;
  END IF;

  -- Atualizar registro em public.clientes
  UPDATE public.clientes
  SET nome_razao_social = trim(p_nome),
      documento = NULLIF(trim(p_documento), ''),
      email = NULLIF(v_email_limpo, ''),
      telefone = NULLIF(trim(p_telefone), ''),
      user_id = COALESCE(user_id, v_user_id),
      plano = p_plano,
      status = v_status_final,
      dia_vencimento = COALESCE(p_dia_vencimento, dia_vencimento),
      valor_mensalidade = COALESCE(p_valor_mensalidade, valor_mensalidade),
      dias_historico_plano = COALESCE(p_dias_historico, dias_historico_plano),
      dias_retencao_banco = COALESCE(p_dias_retencao, dias_retencao_banco),
      instalador_id = p_instalador_id,
      status_agendamento = COALESCE(v_status_agendamento_final, status_agendamento),
      meses_contrato = v_meses_c,
      data_inicio_contrato = v_data_inicio,
      data_fim_contrato = v_data_fim,
      tipo_renovacao = COALESCE(p_tipo_renovacao, tipo_renovacao),
      meses_renovacao = COALESCE(p_meses_renovacao, meses_renovacao),
      foro_comarca = COALESCE(p_foro_comarca, 'Volta Redonda/RJ'),
      updated_at = now()
  WHERE id = p_cliente_id;

  IF p_gerar_parcelas_ausentes THEN
    v_resultado_parcelas := public.admin_gerar_parcelas_contrato(p_cliente_id);
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Dados do cliente e credenciais atualizados com sucesso.',
    'cliente_id', p_cliente_id,
    'user_id', v_user_id,
    'meses_contrato', v_meses_c,
    'data_inicio_contrato', v_data_inicio,
    'data_fim_contrato', v_data_fim,
    'parcelas', v_resultado_parcelas
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_atualizar_cliente_completo(UUID, TEXT, TEXT, TEXT, TEXT, public.status_cliente, public.plano_cliente, INT, NUMERIC, INT, INT, TEXT, UUID, INT, DATE, TEXT, INT, TEXT, BOOLEAN) TO authenticated;

-- 2. Atualizar o Trigger trg_notificar_atribuicao_instalacao_kit com blindagem anti-duplicação (30 segundos)
CREATE OR REPLACE FUNCTION public.trg_notificar_atribuicao_instalacao_kit()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_tem_kit_valido BOOLEAN;
  v_mudou_kit BOOLEAN;
  v_mudou_instalador BOOLEAN;
  v_concluiu_instalacao BOOLEAN;
  v_cliente_user_id UUID;
  v_cliente_nome TEXT;
  v_instalador_nome TEXT;
BEGIN
  -- Identifica o cliente associado
  IF NEW.cliente_id IS NOT NULL THEN
    SELECT user_id, nome_razao_social INTO v_cliente_user_id, v_cliente_nome
    FROM public.clientes
    WHERE id = NEW.cliente_id;
  END IF;

  -- Identifica o instalador associado
  IF NEW.instalador_id IS NOT NULL THEN
    SELECT nome INTO v_instalador_nome
    FROM public.profiles
    WHERE id = NEW.instalador_id;
  END IF;

  v_tem_kit_valido := (
    NEW.rastreador_imei IS NOT NULL 
    AND NEW.rastreador_imei NOT IN ('PENDENTE', 'AGUARDANDO ESTOQUE', 'A DEFINIR', 'SEM RASTREADOR', '')
  );

  v_mudou_instalador := (
    NEW.instalador_id IS NOT NULL 
    AND (TG_OP = 'INSERT' OR OLD.instalador_id IS DISTINCT FROM NEW.instalador_id)
  );

  v_mudou_kit := (
    v_tem_kit_valido 
    AND (TG_OP = 'INSERT' OR OLD.rastreador_imei IS DISTINCT FROM NEW.rastreador_imei)
  );

  v_concluiu_instalacao := (
    NEW.status = 'concluida' 
    AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'concluida')
  );

  -- 2.1. Se o instalador foi atribuído ou alterado
  IF v_mudou_instalador THEN
    -- Notifica o Instalador (com blindagem anti-duplicação de 30s)
    IF NOT EXISTS (
      SELECT 1 FROM public.notificacoes_sistema
      WHERE destinatario_user_id = NEW.instalador_id
        AND tipo = 'instalacao'
        AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
        AND created_at > NOW() - INTERVAL '30 seconds'
    ) THEN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa,
        lida,
        created_at
      ) VALUES (
        NEW.instalador_id,
        'GD Rastreamento — Central Operacional',
        '🔧 Nova Instalação Atribuída: ' || COALESCE(NEW.placa, 'Veículo'),
        'Você foi designado para realizar a instalação do veículo ' || COALESCE(NEW.placa, '') || ' (' || COALESCE(NEW.marca, '') || ' ' || COALESCE(NEW.modelo, '') || '). ' || 
          CASE 
            WHEN v_tem_kit_valido THEN 'Kit de comodato já atribuído: IMEI ' || NEW.rastreador_imei || '.'
            ELSE 'Aguardando liberação de rastreador pelo operador.'
          END,
        'instalacao',
        '/instalacao',
        NEW.placa,
        FALSE,
        NOW()
      );
    END IF;

    -- Notifica o Cliente Titular (com blindagem anti-duplicação de 30s)
    IF v_cliente_user_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema
        WHERE destinatario_user_id = v_cliente_user_id
          AND tipo = 'instalacao'
          AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
          AND created_at > NOW() - INTERVAL '30 seconds'
      ) THEN
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id,
          destinatario_cliente_id,
          remetente_nome,
          titulo,
          mensagem,
          tipo,
          url,
          placa,
          lida,
          created_at
        ) VALUES (
          v_cliente_user_id,
          NEW.cliente_id,
          'GD Rastreamento — Central Operacional',
          '🔧 Técnico Designado para seu Veículo: ' || COALESCE(NEW.placa, 'Veículo'),
          'O técnico credenciado ' || COALESCE(v_instalador_nome, 'especializado') || ' foi designado para o atendimento do seu veículo ' || COALESCE(NEW.placa, '') || ' (' || COALESCE(NEW.marca, '') || ' ' || COALESCE(NEW.modelo, '') || '). ' ||
            CASE 
              WHEN v_tem_kit_valido THEN 'O kit de rastreador já foi vinculado e preparado para agendamento.'
              ELSE 'Em breve alinharemos os detalhes para instalação.'
            END,
          'instalacao',
          '/login',
          NEW.placa,
          FALSE,
          NOW()
        );
      END IF;
    END IF;
  END IF;

  -- 2.2. Se um kit com IMEI real foi atribuído e já há instalador definido (e não foi o mesmo disparo anterior)
  IF v_mudou_kit AND NOT v_mudou_instalador THEN
    IF NEW.instalador_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema
        WHERE destinatario_user_id = NEW.instalador_id
          AND tipo = 'instalacao'
          AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
          AND created_at > NOW() - INTERVAL '30 seconds'
      ) THEN
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id,
          remetente_nome,
          titulo,
          mensagem,
          tipo,
          url,
          placa,
          lida,
          created_at
        ) VALUES (
          NEW.instalador_id,
          'GD Rastreamento — Central Operacional',
          '📦 Kit Rastreador Vinculado: ' || COALESCE(NEW.placa, 'Veículo'),
          'O operador vinculou o rastreador (IMEI ' || NEW.rastreador_imei || ') ao veículo ' || COALESCE(NEW.placa, '') || '. Equipamento disponível para conferência física e agendamento.',
          'instalacao',
          '/instalacao',
          NEW.placa,
          FALSE,
          NOW()
        );
      END IF;
    END IF;

    -- Notifica o Cliente Titular
    IF v_cliente_user_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema
        WHERE destinatario_user_id = v_cliente_user_id
          AND tipo = 'instalacao'
          AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
          AND created_at > NOW() - INTERVAL '30 seconds'
      ) THEN
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id,
          destinatario_cliente_id,
          remetente_nome,
          titulo,
          mensagem,
          tipo,
          url,
          placa,
          lida,
          created_at
        ) VALUES (
          v_cliente_user_id,
          NEW.cliente_id,
          'GD Rastreamento — Central Operacional',
          '📦 Rastreador Preparado: ' || COALESCE(NEW.placa, 'Veículo'),
          'O rastreador foi vinculado ao seu veículo ' || COALESCE(NEW.placa, '') || '. O equipamento já está liberado para o técnico realizar a conferência e o agendamento.',
          'instalacao',
          '/login',
          NEW.placa,
          FALSE,
          NOW()
        );
      END IF;
    END IF;
  END IF;

  -- 2.3. Se a instalação foi concluída com sucesso
  IF v_concluiu_instalacao THEN
    IF v_cliente_user_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema
        WHERE destinatario_user_id = v_cliente_user_id
          AND tipo = 'instalacao'
          AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
          AND created_at > NOW() - INTERVAL '30 seconds'
      ) THEN
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id,
          destinatario_cliente_id,
          remetente_nome,
          titulo,
          mensagem,
          tipo,
          url,
          placa,
          lida,
          created_at
        ) VALUES (
          v_cliente_user_id,
          NEW.cliente_id,
          'GD Rastreamento — Central Operacional',
          '🎉 Instalação Concluída: ' || COALESCE(NEW.placa, 'Veículo'),
          'A instalação do rastreador no veículo ' || COALESCE(NEW.placa, '') || ' foi finalizada com sucesso! Seu veículo já está protegido e pronto para acompanhamento em tempo real.',
          'instalacao',
          '/monitor-gps',
          NEW.placa,
          FALSE,
          NOW()
        );
      END IF;
    END IF;

    -- Notifica Administradores e Operadores
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa,
      lida,
      created_at
    )
    SELECT 
      p.id,
      'GD Rastreamento — Central Operacional',
      '✅ Instalação Concluída: ' || COALESCE(NEW.placa, 'Veículo'),
      'O técnico ' || COALESCE(v_instalador_nome, 'instalador') || ' concluiu a instalação do veículo ' || COALESCE(NEW.placa, '') || ' (Cliente: ' || COALESCE(v_cliente_nome, 'Cliente') || ').',
      'instalacao',
      '/instalacao',
      NEW.placa,
      FALSE,
      NOW()
    FROM public.profiles p
    WHERE p.role IN ('superadmin', 'adm', 'operador')
      AND NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema ns
        WHERE ns.destinatario_user_id = p.id
          AND ns.tipo = 'instalacao'
          AND COALESCE(ns.placa, '') = COALESCE(NEW.placa, '')
          AND ns.created_at > NOW() - INTERVAL '30 seconds'
      );
  END IF;

  RETURN NEW;
END;
$$;

-- 3. Atualizar a RPC instalador_obter_minhas_demandas para contemplar ordens onde o instalador está no cliente
--    ou na ordem de instalação, garantindo que o veículo sempre apareça para o técnico designado
CREATE OR REPLACE FUNCTION public.instalador_obter_minhas_demandas(
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_alvo_id UUID;
  v_ordens JSONB;
  v_agendamentos JSONB;
  v_resumo JSONB;
  v_total_a_receber NUMERIC(10,2);
  v_total_recebido NUMERIC(10,2);
  v_total_agendados_qtd INT;
  v_total_a_agendar_qtd INT;
  v_valor_previsto_agendados NUMERIC(10,2);
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') THEN
    v_alvo_id := COALESCE(p_instalador_id, v_caller_id);
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  -- 1. Coletar Ordens de Instalação Atribuídas (diretamente ou via vínculo do cliente)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', i.id,
      'cliente_id', i.cliente_id,
      'veiculo_id', i.veiculo_id,
      'instalador_id', COALESCE(i.instalador_id, c.instalador_id),
      'placa', COALESCE(i.placa, v.placa, 'A DEFINIR'),
      'marca', COALESCE(i.marca, split_part(v.marca_modelo, ' ', 1), 'Geral'),
      'modelo', COALESCE(i.modelo, v.marca_modelo, 'Veículo'),
      'ano', COALESCE(i.ano, v.ano),
      'cor', COALESCE(i.cor, v.cor),
      'tipo_veiculo', COALESCE(i.tipo_veiculo, v.tipo_veiculo, 'carro'),
      'km_instalacao', COALESCE(i.km_instalacao, 0),
      'tipo_servico', COALESCE(i.tipo_servico, 'instalacao'),
      'valor_instalacao', i.valor_instalacao,
      'status_pagamento', i.status_pagamento,
      'bloqueador_instalado', COALESCE(i.bloqueador_instalado, false),
      'com_bloqueador', COALESCE(i.bloqueador_instalado, false),
      'status', i.status,
      'posicao_instalacao', i.posicao_instalacao,
      'posicaoInstalacao', i.posicao_instalacao,
      'rastreador_id', COALESCE(i.rastreador_id, v.rastreador_id),
      'rastreador_imei', COALESCE(i.rastreador_imei, v.rastreador_imei, 'PENDENTE'),
      'rastreador_modelo', COALESCE(i.rastreador_modelo, 'J16 4G'),
      'chip_iccid', i.chip_iccid,
      'chip_operadora', i.chip_operadora,
      'data_agendamento', COALESCE(i.data_agendamento, c.data_agendamento),
      'hora_agendamento', COALESCE(i.hora_agendamento, c.hora_agendamento),
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', i.local_endereco,
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, false),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'endereco_cliente_informado_em', i.endereco_cliente_informado_em,
      'solicitado_endereco_em', i.solicitado_endereco_em,
      'kit_confirmado_instalador', COALESCE(i.kit_confirmado_instalador, false),
      'kit_confirmado_em', i.kit_confirmado_em,
      'imei_confirmado', i.imei_confirmado,
      'instalador_nome', COALESCE(p.nome, 'Instalador Técnico'),
      'instalador_chave_pix', p.chave_pix,
      'cliente_nome', COALESCE(c.nome_razao_social, 'Cliente'),
      'cliente_telefone', c.telefone,
      'cliente_documento', c.documento,
      'motivo_pendencia_recusa', i.motivo_pendencia_recusa,
      'observacoes', i.observacoes,
      'created_at', i.created_at,
      'updated_at', i.updated_at,
      'concluida_at', i.concluida_at
    ) ORDER BY i.created_at DESC
  ), '[]'::JSONB)
  INTO v_ordens
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.veiculos v ON v.id = i.veiculo_id
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, c.instalador_id)
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR i.instalador_id = v_alvo_id
     OR (i.instalador_id IS NULL AND c.instalador_id = v_alvo_id);

  -- 2. Coletar Clientes Agendados ou Aguardando Agendamento
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'nome_razao_social', c.nome_razao_social,
      'documento', c.documento,
      'telefone', c.telefone,
      'email', c.email,
      'status', c.status,
      'plano', c.plano,
      'tem_fidelidade', c.tem_fidelidade,
      'regra_horimetro', c.regra_horimetro,
      'status_agendamento', COALESCE(c.status_agendamento, 'aguardando_agendamento'),
      'data_agendamento', c.data_agendamento,
      'hora_agendamento', c.hora_agendamento,
      'instalador_id', COALESCE(c.instalador_id, v_alvo_id),
      'instalador', jsonb_build_object(
        'id', p.id,
        'nome', p.nome,
        'endereco_instalacao', p.endereco_instalacao,
        'valor_com_bloqueador', p.valor_instalacao_com_bloqueador,
        'valor_sem_bloqueador', p.valor_instalacao_sem_bloqueador
      ),
      'veiculos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id, 
          'placa', v.placa, 
          'modelo', v.marca_modelo, 
          'tipo_veiculo', v.tipo_veiculo,
          'horimetro_horas', v.horimetro_horas
        ))
        FROM public.veiculos v
        WHERE v.cliente_id = c.id
      ), '[]'::JSONB)
    ) ORDER BY c.created_at DESC
  ), '[]'::JSONB)
  INTO v_agendamentos
  FROM public.clientes c
  LEFT JOIN public.profiles p ON p.id = COALESCE(c.instalador_id, v_alvo_id)
  WHERE (
    (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
    OR c.instalador_id = v_alvo_id
    OR EXISTS (SELECT 1 FROM public.instalacoes inst WHERE inst.cliente_id = c.id AND (inst.instalador_id = v_alvo_id OR (inst.instalador_id IS NULL AND c.instalador_id = v_alvo_id)))
  )
  AND (c.status_agendamento IS DISTINCT FROM 'concluido' OR c.status = 'aguardando_instalacao');

  -- 3. Métricas Financeiras ESTRITAS
  SELECT 
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pendente' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pago' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN valor_instalacao ELSE 0 END), 0.00),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN 1 END),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NULL THEN 1 END)
  INTO 
    v_total_a_receber,
    v_total_recebido,
    v_valor_previsto_agendados,
    v_total_agendados_qtd,
    v_total_a_agendar_qtd
  FROM public.instalacoes
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR instalador_id = v_alvo_id;

  v_resumo := jsonb_build_object(
    'total_ordens', jsonb_array_length(v_ordens),
    'total_agendamentos', jsonb_array_length(v_agendamentos),
    'a_receber', v_total_a_receber,
    'recebido', v_total_recebido,
    'agendados_qtd', v_total_agendados_qtd,
    'a_agendar_qtd', v_total_a_agendar_qtd,
    'valor_previsto_agendados', v_valor_previsto_agendados
  );

  RETURN jsonb_build_object(
    'success', true,
    'ordens', v_ordens,
    'agendamentos', v_agendamentos,
    'resumo', v_resumo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_obter_minhas_demandas(UUID) TO authenticated;

-- 5. Trigger Anti-Duplicação na raiz da tabela public.notificacoes_sistema
-- Barreira física de código (Root Cause First): Impede qualquer gravação de notificação duplicada
-- no intervalo de 30 segundos para o mesmo destinatário com o mesmo tipo e placa/título,
-- independentemente de ser disparada por trigger, RPC ou requisição do frontend.
CREATE OR REPLACE FUNCTION public.trg_anti_duplicacao_notificacoes_sistema()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.notificacoes_sistema
    WHERE (
      (destinatario_user_id IS NOT NULL AND destinatario_user_id = NEW.destinatario_user_id)
      OR
      (destinatario_cliente_id IS NOT NULL AND destinatario_cliente_id = NEW.destinatario_cliente_id)
    )
    AND tipo = NEW.tipo
    AND (
      (NEW.placa IS NOT NULL AND NEW.placa <> '' AND COALESCE(placa, '') = NEW.placa)
      OR
      (COALESCE(titulo, '') = COALESCE(NEW.titulo, ''))
    )
    AND created_at > NOW() - INTERVAL '30 seconds'
  ) THEN
    -- Descarta silenciosamente o insert duplicado na raiz do banco
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_anti_duplicacao_notificacoes_sistema ON public.notificacoes_sistema;
CREATE TRIGGER trg_anti_duplicacao_notificacoes_sistema
  BEFORE INSERT ON public.notificacoes_sistema
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_anti_duplicacao_notificacoes_sistema();

-- Invalidação canônica de cache PostgREST (Zero Schema Cache Error)
NOTIFY pgrst, 'reload schema';

-- =============================================================================
-- ODÔMETRO DEFINITIVO E KM DE VIAGEM (2026-10-11)
-- Inclui: assinatura canônica com p_sinal_gsm, raio WGS-84 local,
--         segmentação de gap >180s, ZVU, sem fator arbitrário.
-- Arquivo: supabase/migrations/20261011100000_hunter_odometro_definitivo_e_km_viagem.sql
-- =============================================================================
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, timestamp with time zone, numeric, numeric, numeric, numeric);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, timestamp with time zone, numeric, numeric, numeric, numeric, integer);
-- =============================================================================
-- HUNTER — ODÔMETRO DEFINITIVO E KM DE VIAGEM (DJR-NEW / 2026-10-11)
-- =============================================================================
-- CAUSAS RAIZ CORRIGIDAS NESTA MIGRATION:
--
-- 1. ASSINATURA ÚNICA E CANÔNICA: elimina todas as versões anteriores da RPC
--    registrar_posicao_gps_com_odometro com assinaturas divergentes que
--    causavam PGRST204 (schema cache miss) quando o gateway enviava p_sinal_gsm.
--    A nova RPC tem assinatura idêntica ao que o gateway já envia.
--
-- 2. HAVERSINE WGS-84 COM RAIO GEOCÊNTRICO LOCAL: substitui raio fixo arbitrário
--    (6.371.000 m ou 6.374.900 m) por raio calculado dinamicamente conforme a
--    latitude média dos dois pontos usando os semi-eixos oficiais WGS-84.
--    Erro de odômetro corrigido: até 0,3% a menos no centro do Brasil.
--
-- 3. SEGMENTAÇÃO DE GAP TEMPORAL (> 180 s): se Δt entre pacotes for superior a
--    180 segundos (perda de GPRS, túnel, zone morta), a distância geodésica
--    entre os dois pontos não é acumulada — elimina saltos de km em linha reta.
--
-- 4. ZERO DOUBLE-COUNTING: a RPC atualiza km_percorrido na viagem em andamento
--    incrementalmente, pacote a pacote. O gateway NÃO deve mais recalcular
--    km_percorrido no encerramento da viagem (processarCicloIgnicaoViagem).
--    Apenas odometro_km do veículo (acumulado vitalício) continua sendo mantido
--    separadamente e nunca é zerado.
--
-- 5. VALIDAÇÃO CRC IMPLÍCITA: a RPC descarta pontos com coordenadas zero (0,0)
--    ou fora da caixa geográfica do Brasil (-35°N a 5°N, -74°W a -28°W),
--    eliminando posições LBS falsas sem fix GPS.
--
-- 6. FATOR DE SINUOSIDADE VIÁRIA REMOVIDO: o fator 1.06383 era arbitrário e
--    causava superestimação sistemática de ~6,4% no odômetro. O Haversine com
--    raio local WGS-84 já entrega a distância geodésica real. A sinuosidade real
--    é capturada naturalmente pelo sampling de 1 pacote/min da rota real.
--
-- 7. PARÂMETRO p_sinal_gsm RESTAURADO: estava ausente na migration 20261006,
--    causando fallback silencioso no gateway e perda de acumulação de odômetro.
-- =============================================================================

-- ── DROP de todas as versões anteriores (assinaturas divergentes) ──────────
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, timestamp with time zone, numeric, numeric, numeric, numeric);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, timestamp with time zone, numeric, numeric, numeric, numeric, integer);

-- ── Cria a versão canônica definitiva ─────────────────────────────────────
CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  -- Constantes WGS-84 reais (metros)
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;        -- Semi-eixo maior
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;   -- Semi-eixo menor
  -- Parâmetros de filtragem
  c_gap_max_s  CONSTANT NUMERIC          := 180.0;  -- Gap máximo entre pacotes (s)
  c_spike_kmh  CONSTANT NUMERIC          := 195.0;  -- Velocidade calculada de spike (km/h)
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;-- Distância máxima num único pacote (m)

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_novo_odometro      NUMERIC(12, 3);
  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_a_hav              DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_raio_local         DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
BEGIN
  -- ── 1. Trava atômica do veículo ──────────────────────────────────────────
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, ultima_atualizacao
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  -- ── 2. Validação Geográfica (Brasil) — descarta LBS / Fix ausente ────────
  -- Rejeita coordenadas zeradas ou fora da caixa geográfica do Brasil
  IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
    v_descartado := TRUE;
    v_motivo_descarte := 'coordenada_zero';
  ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
     OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
    -- Fora do Brasil: aceita mas não acumula odômetro (pode ser veículo em trânsito internacional)
    -- Apenas grava posição e atualiza status
    v_descartado := TRUE;
    v_motivo_descarte := 'fora_brasil';
  END IF;

  -- ── 3. Cálculo Geodésico (somente se coordenadas válidas e anterior existe) ──
  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    -- ── 3a. Raio geocêntrico local WGS-84 (latitude média dos dois pontos) ─
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_raio_local  := sqrt(
      (((c_a * c_a * v_cos_lat)^2) + ((c_b * c_b * v_sin_lat)^2))
      /
      (((c_a * v_cos_lat)^2)       + ((c_b * v_sin_lat)^2))
    );

    -- ── 3b. Haversine ───────────────────────────────────────────────────────
    v_dlat    := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon    := radians(p_longitude - v_veiculo.ultima_longitude);
    v_a_hav   := sin(v_dlat / 2.0)^2
               + cos(radians(v_veiculo.ultima_latitude))
               * cos(radians(p_latitude))
               * sin(v_dlon / 2.0)^2;
    v_dist_metros := v_raio_local * 2.0 * atan2(sqrt(v_a_hav), sqrt(1.0 - v_a_hav));

    -- ── 3c. Intervalo temporal (para detecção de gap e spike) ───────────────
    -- Busca último ponto gravado para calcular Δt real entre pacotes
    SELECT data_hora_gps, velocidade
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0; -- Assumir 60s no primeiro ponto
    END IF;

    -- ── 3d. Filtros de Qualidade ────────────────────────────────────────────

    -- GAP TEMPORAL: Δt > 180s → não acumula (túnel / perda de GPRS)
    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';

    -- SPIKE GEODÉSICO: velocidade calculada > 195 km/h com velocidade de hardware < 160 km/h
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    -- ZERO VELOCITY UPDATE (ZVU): parado com drift menor que limiar
    IF NOT v_descartado THEN
      IF p_velocidade <= 2.5 AND v_dist_metros < 15.0 THEN
        -- GPS em drift estático: ignora deslocamento
        v_descartado      := TRUE;
        v_motivo_descarte := 'zvu_drift_' || round(v_dist_metros::NUMERIC, 1) || 'm';
      END IF;
    END IF;

    -- DISTÂNCIA MÁXIMA IMPLAUSÍVEL (> 15 km num único pacote)
    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausive_' || round(v_dist_metros) || 'm';
    END IF;

    -- ── 3e. Limiar mínimo dinâmico de acumulação ────────────────────────────
    IF NOT v_descartado THEN
      -- Em movimento (> 3 km/h): captura deslocamentos a partir de 1,5 m (curvas lentas)
      -- Parado/lento (≤ 3 km/h): exige pelo menos 10 m para descartar oscilação de antena
      v_limiar_m := CASE WHEN p_velocidade > 3.0 THEN 1.5 ELSE 10.0 END;

      IF v_dist_metros >= v_limiar_m THEN
        -- Acumula distância geodésica real sem fator de correção arbitrário
        v_delta_km      := (v_dist_metros / 1000.0);
        v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);
      ELSE
        -- Deslocamento abaixo do limiar (jitter de antena)
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'jitter_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  -- ── 4. Status operacional ─────────────────────────────────────────────────
  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  -- ── 5. Grava posição histórica ────────────────────────────────────────────
  -- Sempre grava (mesmo pontos descartados para fins de auditoria de rota)
  -- exceto coordenadas absolutamente zeradas
  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_odometro,   -- Odômetro acumulado real no momento
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm
    )
    ON CONFLICT DO NOTHING;  -- Idempotente: evita duplicatas por retry do gateway
  END IF;

  -- ── 6. Atualiza veículo (dispara Realtime via WebSocket) ──────────────────
  UPDATE public.veiculos
  SET
    ultima_latitude          = p_latitude,
    ultima_longitude         = p_longitude,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_odometro,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  -- ── 7. Acumula km_percorrido na viagem em andamento (incremental, atômico) ─
  -- IMPORTANTE: apenas a RPC faz este acúmulo. O gateway NÃO deve
  -- recalcular km_percorrido no encerramento da viagem via Haversine sobre
  -- todos os pontos — isso causava double-counting. O encerramento da viagem
  -- apenas consolida status e velocidades, sem alterar km_percorrido.
  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido    = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 3),
        velocidade_maxima= GREATEST(COALESCE(velocidade_maxima, 0), ROUND(p_velocidade)),
        atualizado_em    = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso',          true,
    'novo_odometro',    v_novo_odometro,
    'delta_km',         ROUND(v_delta_km::NUMERIC, 4),
    'dist_metros',      ROUND(v_dist_metros::NUMERIC, 2),
    'descartado',       v_descartado,
    'motivo_descarte',  v_motivo_descarte,
    'delta_sec',        ROUND(v_delta_sec::NUMERIC, 1),
    'raio_local_m',     ROUND(v_raio_local::NUMERIC),
    'status_operacional', v_status_op
  );
END;
$$;

-- ── Permissões ────────────────────────────────────────────────────────────────
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO anon;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO service_role;

-- ── Invalida cache PostgREST ──────────────────────────────────────────────────
NOTIFY pgrst, 'reload schema';

-- =============================================================================
-- ODOMETRIA DE ALTA ACUIDADE COM FUSÃO INERCIAL E FIX GNSS ESTREITO (2026-10-11)
-- =============================================================================
ALTER TABLE public.telemetria_posicoes
  ADD COLUMN IF NOT EXISTS gps_fixado BOOLEAN DEFAULT TRUE;

ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS gps_fixado BOOLEAN DEFAULT TRUE;

DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer, boolean);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer);

CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL,
  p_gps_fixado            BOOLEAN     DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;
  c_gap_max_s  CONSTANT NUMERIC          := 180.0;
  c_spike_kmh  CONSTANT NUMERIC          := 195.0;
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;
  c_zvu_m      CONSTANT DOUBLE PRECISION := 3.0;

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_dist_geom          DOUBLE PRECISION := 0.0;
  v_dist_trap_m        DOUBLE PRECISION := 0.0;
  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_novo_odometro      NUMERIC(12, 3);
  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_a_hav              DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_raio_local         DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_delta_rumo         INT              := 0;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
  v_fusao_aplicada     BOOLEAN          := FALSE;
BEGIN
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, ultima_atualizacao
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  IF NOT COALESCE(p_gps_fixado, TRUE) THEN
    v_descartado      := TRUE;
    v_motivo_descarte := 'sem_fix_gnss_lbs';
  END IF;

  IF NOT v_descartado THEN
    IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'coordenada_zero';
    ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
       OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'fora_brasil';
    END IF;
  END IF;

  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_raio_local  := sqrt(
      (((c_a * c_a * v_cos_lat)^2) + ((c_b * c_b * v_sin_lat)^2))
      /
      (((c_a * v_cos_lat)^2)       + ((c_b * v_sin_lat)^2))
    );

    v_dlat    := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon    := radians(p_longitude - v_veiculo.ultima_longitude);
    v_a_hav   := sin(v_dlat / 2.0)^2
               + cos(radians(v_veiculo.ultima_latitude))
               * cos(radians(p_latitude))
               * sin(v_dlon / 2.0)^2;
    v_dist_geom   := v_raio_local * 2.0 * atan2(sqrt(v_a_hav), sqrt(1.0 - v_a_hav));
    v_dist_metros := v_dist_geom;

    SELECT data_hora_gps, velocidade, rumo
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0;
    END IF;

    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    IF NOT v_descartado THEN
      IF (p_velocidade IS NULL OR p_velocidade <= 0.5) OR v_dist_metros < c_zvu_m THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'zvu_estrito_' || round(v_dist_metros::NUMERIC, 1) || 'm';
      END IF;
    END IF;

    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausivel_' || round(v_dist_metros) || 'm';
    END IF;

    IF NOT v_descartado AND v_delta_sec > 0.5 AND v_delta_sec <= c_gap_max_s AND p_velocidade > 2.5 THEN
      v_dist_trap_m := ((p_velocidade + COALESCE(v_ultima_telem.velocidade, p_velocidade)) / 7.2) * v_delta_sec;

      IF v_ultima_telem.rumo IS NOT NULL AND p_rumo IS NOT NULL THEN
        v_delta_rumo := ABS(p_rumo - v_ultima_telem.rumo);
        IF v_delta_rumo > 180 THEN
          v_delta_rumo := 360 - v_delta_rumo;
        END IF;
      ELSE
        v_delta_rumo := 0;
      END IF;

      IF v_delta_rumo >= 8 AND v_dist_trap_m > v_dist_geom THEN
        IF v_dist_trap_m <= (v_dist_geom * 1.35) THEN
          v_dist_metros    := v_dist_trap_m;
          v_fusao_aplicada := TRUE;
        ELSE
          v_dist_metros    := v_dist_geom * 1.35;
          v_fusao_aplicada := TRUE;
        END IF;
      END IF;
    END IF;

    IF NOT v_descartado THEN
      v_limiar_m := CASE WHEN p_velocidade > 3.0 THEN 1.5 ELSE 5.0 END;
      IF v_dist_metros >= v_limiar_m THEN
        v_delta_km      := (v_dist_metros / 1000.0);
        v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);
      ELSE
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'limiar_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm,
      gps_fixado
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_odometro,
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm,
      COALESCE(p_gps_fixado, TRUE)
    )
    ON CONFLICT DO NOTHING;
  END IF;

  UPDATE public.veiculos
  SET
    ultima_latitude          = p_latitude,
    ultima_longitude         = p_longitude,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_odometro,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    gps_fixado               = COALESCE(p_gps_fixado, TRUE),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido    = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 3),
        velocidade_maxima= GREATEST(COALESCE(velocidade_maxima, 0), ROUND(p_velocidade)),
        atualizado_em    = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso',          true,
    'novo_odometro',    v_novo_odometro,
    'delta_km',         ROUND(v_delta_km::NUMERIC, 4),
    'dist_metros',      ROUND(v_dist_metros::NUMERIC, 2),
    'dist_geom',        ROUND(v_dist_geom::NUMERIC, 2),
    'dist_trap',        ROUND(v_dist_trap_m::NUMERIC, 2),
    'fusao_aplicada',   v_fusao_aplicada,
    'delta_rumo',       v_delta_rumo,
    'descartado',       v_descartado,
    'motivo_descarte',  v_motivo_descarte,
    'delta_sec',        ROUND(v_delta_sec::NUMERIC, 1),
    'raio_local_m',     ROUND(v_raio_local::NUMERIC),
    'gps_fixado',       COALESCE(p_gps_fixado, TRUE),
    'status_operacional', v_status_op
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO anon;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO service_role;

NOTIFY pgrst, 'reload schema';

-- =============================================================================
-- HUNTER — CALIBRAÇÃO INDIVIDUAL DE ODÔMETRO POR VEÍCULO E MOTOR J16 4G
-- Versão da Migração: 20261011140000_hunter_calibracao_individual_veiculo_e_odometria_j16.sql
-- =============================================================================
-- PROTOCOLO J16 / GT06 — AUDITORIA, OTIMIZAÇÃO E CALIBRAÇÃO VEICULAR (DJR-NEW)
--
-- 1. COLUNAS DE CALIBRAÇÃO INDIVIDUAL EM VEICULOS:
--    - fator_calibracao_odometro NUMERIC(8, 6) DEFAULT 1.000000 (neutro)
--    - versao_algoritmo_odometro TEXT DEFAULT 'v2.1-geodesica-fusao-inercial'
--    - hodometro_painel_km NUMERIC(12, 2)
--
-- 2. TABELA PÚBLICA veiculo_calibracoes_odometro:
--    Registra cada aferição de campo (leitura inicial/final do painel físico
--    vs leitura inicial/final do GD Rastreamento), calculando diferença,
--    erro percentual e histórico de calibração por veículo e dispositivo.
--
-- 3. RLS ESTRITO:
--    Isolamento total de dados por cliente_id no Supabase.
--
-- 4. RPCS:
--    - registrar_calibracao_odometro_veiculo
--    - obter_calibracoes_odometro_veiculo
--    - atualização da registrar_posicao_gps_com_odometro com fator individual
-- =============================================================================

-- ── 1. Colunas de Calibração e Versão em Veículos e Viagens ───────────────────
ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS fator_calibracao_odometro NUMERIC(8, 6) DEFAULT 1.000000,
  ADD COLUMN IF NOT EXISTS versao_algoritmo_odometro TEXT DEFAULT 'v2.1-geodesica-fusao-inercial',
  ADD COLUMN IF NOT EXISTS hodometro_painel_km NUMERIC(12, 2);

ALTER TABLE public.viagens_trajetos
  ADD COLUMN IF NOT EXISTS distance_raw_km NUMERIC(10, 3),
  ADD COLUMN IF NOT EXISTS pontos_descartados INT DEFAULT 0;

-- ── 2. Tabela de Sessões de Calibração por Veículo ────────────────────────────
CREATE TABLE IF NOT EXISTS public.veiculo_calibracoes_odometro (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  veiculo_id UUID NOT NULL REFERENCES public.veiculos(id) ON DELETE CASCADE,
  cliente_id UUID REFERENCES public.clientes(id) ON DELETE CASCADE,
  rastreador_id UUID REFERENCES public.rastreadores(id) ON DELETE SET NULL,
  hodometro_inicial_painel_km NUMERIC(12, 2) NOT NULL,
  hodometro_final_painel_km NUMERIC(12, 2) NOT NULL,
  odometro_inicial_sigo_km NUMERIC(12, 3) NOT NULL,
  odometro_final_sigo_km NUMERIC(12, 3) NOT NULL,
  distancia_painel_km NUMERIC(12, 3) NOT NULL,
  distancia_sigo_km NUMERIC(12, 3) NOT NULL,
  diferenca_km NUMERIC(12, 3) NOT NULL,
  erro_percentual NUMERIC(8, 4) NOT NULL,
  fator_correcao_calculado NUMERIC(8, 6) NOT NULL,
  fator_correcao_aplicado NUMERIC(8, 6) DEFAULT 1.000000,
  tendencia TEXT NOT NULL, -- 'EXATO', 'SUPERESTIMADO', 'SUBESTIMADO'
  versao_algoritmo TEXT NOT NULL DEFAULT 'v2.1-geodesica-fusao-inercial',
  configuracao_j16 TEXT DEFAULT 'TIMER,15,3600# | ANGLE,3,15#',
  quantidade_percursos INT DEFAULT 1,
  condicoes_percurso TEXT,
  observacoes TEXT,
  criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  criado_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_calibracoes_veiculo_data
  ON public.veiculo_calibracoes_odometro(veiculo_id, criado_em DESC);

CREATE INDEX IF NOT EXISTS idx_calibracoes_cliente
  ON public.veiculo_calibracoes_odometro(cliente_id);

-- ── 3. RLS Estrito na Tabela de Calibrações ───────────────────────────────────
ALTER TABLE public.veiculo_calibracoes_odometro ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "veiculo_calibracoes_odometro_select_policy" ON public.veiculo_calibracoes_odometro;
DROP POLICY IF EXISTS "veiculo_calibracoes_odometro_insert_policy" ON public.veiculo_calibracoes_odometro;
DROP POLICY IF EXISTS "veiculo_calibracoes_odometro_update_policy" ON public.veiculo_calibracoes_odometro;
DROP POLICY IF EXISTS "veiculo_calibracoes_odometro_delete_policy" ON public.veiculo_calibracoes_odometro;

CREATE POLICY "veiculo_calibracoes_odometro_select_policy"
  ON public.veiculo_calibracoes_odometro
  FOR SELECT
  TO authenticated, service_role
  USING (
    auth.role() = 'service_role'
    OR EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (p.role IN ('admin', 'superadmin', 'operador') OR p.email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'))
    )
    OR EXISTS (
      SELECT 1 FROM public.veiculos v
      WHERE v.id = veiculo_calibracoes_odometro.veiculo_id
        AND v.cliente_id IN (
          SELECT c.id FROM public.clientes c
          WHERE c.user_id = auth.uid() OR c.email = (SELECT email FROM auth.users WHERE id = auth.uid())
        )
    )
  );

CREATE POLICY "veiculo_calibracoes_odometro_insert_policy"
  ON public.veiculo_calibracoes_odometro
  FOR INSERT
  TO authenticated, service_role
  WITH CHECK (
    auth.role() = 'service_role'
    OR EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (p.role IN ('admin', 'superadmin', 'operador') OR p.email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'))
    )
  );

CREATE POLICY "veiculo_calibracoes_odometro_update_policy"
  ON public.veiculo_calibracoes_odometro
  FOR UPDATE
  TO authenticated, service_role
  USING (
    auth.role() = 'service_role'
    OR EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (p.role IN ('admin', 'superadmin') OR p.email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'))
    )
  );

CREATE POLICY "veiculo_calibracoes_odometro_delete_policy"
  ON public.veiculo_calibracoes_odometro
  FOR DELETE
  TO authenticated, service_role
  USING (
    auth.role() = 'service_role'
    OR EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (p.role IN ('admin', 'superadmin') OR p.email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'))
    )
  );

GRANT ALL ON TABLE public.veiculo_calibracoes_odometro TO authenticated, service_role;
GRANT SELECT ON TABLE public.veiculo_calibracoes_odometro TO anon;

-- ── 4. RPC para Registrar Calibração com Validação e Cálculo Preciso ───────────
CREATE OR REPLACE FUNCTION public.registrar_calibracao_odometro_veiculo(
  p_veiculo_id                  UUID,
  p_hodometro_inicial_painel    NUMERIC,
  p_hodometro_final_painel      NUMERIC,
  p_odometro_inicial_sigo       NUMERIC,
  p_odometro_final_sigo         NUMERIC,
  p_aplicar_fator               BOOLEAN DEFAULT FALSE,
  p_configuracao_j16            TEXT DEFAULT 'TIMER,15,3600# | ANGLE,3,15#',
  p_condicoes_percurso          TEXT DEFAULT NULL,
  p_observacoes                 TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_veiculo             RECORD;
  v_dist_painel         NUMERIC(12, 3);
  v_dist_sigo           NUMERIC(12, 3);
  v_diferenca_km        NUMERIC(12, 3);
  v_erro_pct            NUMERIC(8, 4);
  v_fator_calculado     NUMERIC(8, 6);
  v_fator_aplicar       NUMERIC(8, 6) := 1.000000;
  v_tendencia           TEXT := 'EXATO';
  v_calibracao_id       UUID;
BEGIN
  -- Busca e trava linha do veículo
  SELECT id, cliente_id, rastreador_id, placa, marca_modelo, odometro_km, fator_calibracao_odometro
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado.');
  END IF;

  -- Validações de consistência lógica das leituras
  IF p_hodometro_final_painel < p_hodometro_inicial_painel THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Hodômetro final do painel não pode ser menor que o inicial.');
  END IF;

  IF p_odometro_final_sigo < p_odometro_inicial_sigo THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Odômetro final do GD Rastreamento não pode ser menor que o inicial.');
  END IF;

  v_dist_painel := ROUND((p_hodometro_final_painel - p_hodometro_inicial_painel)::NUMERIC, 3);
  v_dist_sigo   := ROUND((p_odometro_final_sigo - p_odometro_inicial_sigo)::NUMERIC, 3);

  IF v_dist_painel <= 0.001 THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'A distância do painel para calibração deve ser maior que zero (mínimo de 1 km recomendado).');
  END IF;

  IF v_dist_sigo <= 0.001 THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'A distância registrada pelo GD Rastreamento deve ser maior que zero.');
  END IF;

  -- Cálculo da diferença e erro percentual conforme especificação formal:
  -- diferença_km = distância_SIGO − distância_hodômetro
  -- erro_percentual = 100 × abs(diferença_km) / distância_hodômetro
  v_diferenca_km := ROUND((v_dist_sigo - v_dist_painel)::NUMERIC, 3);
  v_erro_pct     := ROUND(((ABS(v_diferenca_km) / v_dist_painel) * 100.0)::NUMERIC, 4);

  -- Fator de correção individual: fator = distância_painel / distância_sigo
  v_fator_calculado := ROUND((v_dist_painel / v_dist_sigo)::NUMERIC, 6);

  IF v_diferenca_km > 0.05 THEN
    v_tendencia := 'SUPERESTIMADO';
  ELSIF v_diferenca_km < -0.05 THEN
    v_tendencia := 'SUBESTIMADO';
  ELSE
    v_tendencia := 'EXATO';
  END IF;

  -- Se solicitado pelo operador e dentro dos limites físicos de segurança (0.85 a 1.15)
  IF p_aplicar_fator THEN
    IF v_fator_calculado BETWEEN 0.850000 AND 1.150000 THEN
      v_fator_aplicar := v_fator_calculado;
      UPDATE public.veiculos
      SET
        fator_calibracao_odometro = v_fator_aplicar,
        hodometro_painel_km       = p_hodometro_final_painel,
        ultima_atualizacao        = NOW()
      WHERE id = p_veiculo_id;
    ELSE
      v_fator_aplicar := COALESCE(v_veiculo.fator_calibracao_odometro, 1.000000);
    END IF;
  ELSE
    v_fator_aplicar := COALESCE(v_veiculo.fator_calibracao_odometro, 1.000000);
  END IF;

  -- Insere na tabela de calibrações
  INSERT INTO public.veiculo_calibracoes_odometro (
    veiculo_id,
    cliente_id,
    rastreador_id,
    hodometro_inicial_painel_km,
    hodometro_final_painel_km,
    odometro_inicial_sigo_km,
    odometro_final_sigo_km,
    distancia_painel_km,
    distancia_sigo_km,
    diferenca_km,
    erro_percentual,
    fator_correcao_calculado,
    fator_correcao_aplicado,
    tendencia,
    versao_algoritmo,
    configuracao_j16,
    condicoes_percurso,
    observacoes,
    criado_por
  ) VALUES (
    p_veiculo_id,
    v_veiculo.cliente_id,
    v_veiculo.rastreador_id,
    p_hodometro_inicial_painel,
    p_hodometro_final_painel,
    p_odometro_inicial_sigo,
    p_odometro_final_sigo,
    v_dist_painel,
    v_dist_sigo,
    v_diferenca_km,
    v_erro_pct,
    v_fator_calculado,
    v_fator_aplicar,
    v_tendencia,
    'v2.1-geodesica-fusao-inercial',
    COALESCE(p_configuracao_j16, 'TIMER,15,3600# | ANGLE,3,15#'),
    p_condicoes_percurso,
    p_observacoes,
    auth.uid()
  )
  RETURNING id INTO v_calibracao_id;

  RETURN jsonb_build_object(
    'sucesso',                  true,
    'calibracao_id',            v_calibracao_id,
    'veiculo_id',               p_veiculo_id,
    'placa',                    v_veiculo.placa,
    'distancia_painel_km',      v_dist_painel,
    'distancia_sigo_km',        v_dist_sigo,
    'diferenca_km',             v_diferenca_km,
    'erro_percentual',          v_erro_pct,
    'tendencia',                v_tendencia,
    'fator_calculado',          v_fator_calculado,
    'fator_aplicado',           v_fator_aplicar,
    'fator_atualizado_veiculo', p_aplicar_fator
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_calibracao_odometro_veiculo TO authenticated, service_role;

-- ── 5. RPC para Listar Calibrações de um Veículo ─────────────────────────────
CREATE OR REPLACE FUNCTION public.obter_calibracoes_odometro_veiculo(p_veiculo_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_resultado JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_to_json(c) ORDER BY c.criado_em DESC), '[]'::JSONB)
  INTO v_resultado
  FROM public.veiculo_calibracoes_odometro c
  WHERE c.veiculo_id = p_veiculo_id;

  RETURN v_resultado;
END;
$$;

GRANT EXECUTE ON FUNCTION public.obter_calibracoes_odometro_veiculo TO authenticated, service_role, anon;

-- ── 6. Atualização da RPC registrar_posicao_gps_com_odometro com Fator Individual ──
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer, boolean);

CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL,
  p_gps_fixado            BOOLEAN     DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  -- Constantes WGS-84 reais (metros)
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;        -- Semi-eixo maior
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;   -- Semi-eixo menor
  -- Parâmetros de filtragem física
  c_gap_max_s  CONSTANT NUMERIC          := 180.0;  -- Gap máximo entre pacotes (s)
  c_spike_kmh  CONSTANT NUMERIC          := 195.0;  -- Velocidade calculada de spike (km/h)
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;-- Distância máxima num único pacote (m)
  c_zvu_m      CONSTANT DOUBLE PRECISION := 3.0;    -- Limiar de ZVU estrito (erro circular CEP)

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_dist_geom          DOUBLE PRECISION := 0.0;
  v_dist_trap_m        DOUBLE PRECISION := 0.0;
  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_novo_odometro      NUMERIC(12, 3);
  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_a_hav              DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_raio_local         DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_delta_rumo         INT              := 0;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
  v_fusao_aplicada     BOOLEAN          := FALSE;
  v_fator_veiculo      NUMERIC(8, 6)    := 1.000000;
BEGIN
  -- ── 1. Trava atômica do veículo ──────────────────────────────────────────
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, ultima_atualizacao,
         fator_calibracao_odometro
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  -- Fator de calibração individual do veículo (com blindagem 0.85 a 1.15)
  IF v_veiculo.fator_calibracao_odometro IS NOT NULL
     AND v_veiculo.fator_calibracao_odometro BETWEEN 0.850000 AND 1.150000 THEN
    v_fator_veiculo := v_veiculo.fator_calibracao_odometro;
  ELSE
    v_fator_veiculo := 1.000000;
  END IF;

  -- ── 2. Validação Estrita de Fix GNSS (Módulo 1) ───────────────────────────
  -- Se o J16 reportar Course Status sem Fix GNSS (Bit 12 = 0), descarta da odometria
  IF NOT COALESCE(p_gps_fixado, TRUE) THEN
    v_descartado      := TRUE;
    v_motivo_descarte := 'sem_fix_gnss_lbs';
  END IF;

  -- ── 3. Validação Geográfica (Brasil) ──────────────────────────────────────
  IF NOT v_descartado THEN
    IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'coordenada_zero';
    ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
       OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'fora_brasil';
    END IF;
  END IF;

  -- ── 4. Cálculo Geodésico WGS-84 com Raio Local (Módulo 3) ────────────────
  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    -- 4a. Raio geocêntrico local WGS-84 na latitude média do deslocamento
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_raio_local  := sqrt(
      (((c_a * c_a * v_cos_lat)^2) + ((c_b * c_b * v_sin_lat)^2))
      /
      (((c_a * v_cos_lat)^2)       + ((c_b * v_sin_lat)^2))
    );

    -- 4b. Distância Geodésica Haversine Elipsoidal
    v_dlat    := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon    := radians(p_longitude - v_veiculo.ultima_longitude);
    v_a_hav   := sin(v_dlat / 2.0)^2
               + cos(radians(v_veiculo.ultima_latitude))
               * cos(radians(p_latitude))
               * sin(v_dlon / 2.0)^2;
    v_dist_geom   := v_raio_local * 2.0 * atan2(sqrt(v_a_hav), sqrt(1.0 - v_a_hav));
    v_dist_metros := v_dist_geom;

    -- 4c. Intervalo temporal real (Δt) e busca de rumo/velocidade anteriores
    SELECT data_hora_gps, velocidade, rumo
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0;
    END IF;

    -- 4d. Filtro de Gaps Temporais Anômalos (> 180s)
    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';

    -- 4e. Spike Geodésico (> 195 km/h sem respaldo de velocidade de hardware)
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    -- 4f. Zero-Velocity Update (ZVU Estrito): velocidade = 0 ou deslocamento < 3m
    IF NOT v_descartado THEN
      IF (p_velocidade IS NULL OR p_velocidade <= 0.5) OR v_dist_metros < c_zvu_m THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'zvu_estrito_' || round(v_dist_metros::NUMERIC, 1) || 'm';
      END IF;
    END IF;

    -- 4g. Distância máxima implausível (> 15 km num único pacote)
    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausivel_' || round(v_dist_metros) || 'm';
    END IF;

    -- 4h. Integração Numérica Trapezoidal de Velocidade e Fusão Inercial em Curvas
    IF NOT v_descartado AND v_delta_sec > 0.5 AND v_delta_sec <= c_gap_max_s AND p_velocidade > 2.5 THEN
      v_dist_trap_m := ((p_velocidade + COALESCE(v_ultima_telem.velocidade, p_velocidade)) / 7.2) * v_delta_sec;

      -- Variação angular de rumo entre os pacotes
      IF v_ultima_telem.rumo IS NOT NULL AND p_rumo IS NOT NULL THEN
        v_delta_rumo := ABS(p_rumo - v_ultima_telem.rumo);
        IF v_delta_rumo > 180 THEN
          v_delta_rumo := 360 - v_delta_rumo;
        END IF;
      ELSE
        v_delta_rumo := 0;
      END IF;

      -- Critério de Fusão Inercial:
      -- Em curvas (Δrumo >= 8° e v > 3 km/h), a corda seca geodésica subestima o arco real da pista.
      IF v_delta_rumo >= 8 AND v_dist_trap_m > v_dist_geom THEN
        IF v_dist_trap_m <= (v_dist_geom * 1.35) THEN
          v_dist_metros    := v_dist_trap_m;
          v_fusao_aplicada := TRUE;
        ELSE
          v_dist_metros    := v_dist_geom * 1.35;
          v_fusao_aplicada := TRUE;
        END IF;
      END IF;
    END IF;

    -- 4i. Acumulação no Odômetro Vitalício com Fator Individual
    IF NOT v_descartado THEN
      v_limiar_m := CASE WHEN p_velocidade > 3.0 THEN 1.5 ELSE 5.0 END;
      IF v_dist_metros >= v_limiar_m THEN
        v_delta_km      := (v_dist_metros / 1000.0) * v_fator_veiculo;
        v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);
      ELSE
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'limiar_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  -- ── 5. Determinação do Status Operacional ──────────────────────────────────
  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  -- ── 6. Persistência Histórica em telemetria_posicoes ───────────────────────
  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm,
      gps_fixado
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_odometro,
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm,
      COALESCE(p_gps_fixado, TRUE)
    )
    ON CONFLICT DO NOTHING;
  END IF;

  -- ── 7. Atualização de Estado no Veículo ────────────────────────────────────
  UPDATE public.veiculos
  SET
    ultima_latitude          = p_latitude,
    ultima_longitude         = p_longitude,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_odometro,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    gps_fixado               = COALESCE(p_gps_fixado, TRUE),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  -- ── 8. Acumulação Atômica em Viagem Ativa (viagens_trajetos) ───────────────
  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido    = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 3),
        velocidade_maxima= GREATEST(COALESCE(velocidade_maxima, 0), ROUND(p_velocidade)),
        atualizado_em    = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso',          true,
    'novo_odometro',    v_novo_odometro,
    'delta_km',         ROUND(v_delta_km::NUMERIC, 4),
    'dist_metros',      ROUND(v_dist_metros::NUMERIC, 2),
    'dist_geom',        ROUND(v_dist_geom::NUMERIC, 2),
    'dist_trap',        ROUND(v_dist_trap_m::NUMERIC, 2),
    'fusao_aplicada',   v_fusao_aplicada,
    'fator_veiculo',    v_fator_veiculo,
    'delta_rumo',       v_delta_rumo,
    'descartado',       v_descartado,
    'motivo_descarte',  v_motivo_descarte,
    'delta_sec',        ROUND(v_delta_sec::NUMERIC, 1),
    'raio_local_m',     ROUND(v_raio_local::NUMERIC),
    'gps_fixado',       COALESCE(p_gps_fixado, TRUE),
    'status_operacional', v_status_op
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO anon;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO service_role;

-- ── 8. Limpeza de Voltagens Falsas em Veículos Sem Comunicação ──────────────
-- Regra Pétrea: NADA NO SISTEMA PODE SER FALSO!
UPDATE public.veiculos
SET 
  voltagem = NULL,
  bateria_veiculo_v = NULL
WHERE ultima_atualizacao IS NULL;

ALTER TABLE public.veiculos ALTER COLUMN voltagem SET DEFAULT NULL;
ALTER TABLE public.veiculos ALTER COLUMN bateria_veiculo_v SET DEFAULT NULL;

-- ── 9. Invalidação Canônica de Cache PostgREST ────────────────────────────────
NOTIFY pgrst, 'reload schema';

-- ── 10. Suporte a Duplo Odômetro no Cockpit (Servidor WGS-84 vs MCU J16) ───────
ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS odometro_hardware_km NUMERIC(12, 2) DEFAULT NULL;

UPDATE public.veiculos
SET odometro_hardware_km = odometro_km
WHERE odometro_hardware_km IS NULL AND odometro_km > 0;

-- ── 11. Exclusão Segura de Rastreadores em Estoque ─────────────────────────────
CREATE OR REPLACE FUNCTION public.excluir_rastreador_estoque(
  p_rastreador_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rast RECORD;
  v_veiculo RECORD;
  v_inst RECORD;
BEGIN
  -- 1. Localiza o rastreador
  SELECT * INTO v_rast FROM public.rastreadores WHERE id = p_rastreador_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Equipamento não localizado no banco de dados.'
    );
  END IF;

  -- 2. Salvaguarda: Verifica se há veículo atrelado
  SELECT placa, marca_modelo INTO v_veiculo 
  FROM public.veiculos 
  WHERE rastreador_id = p_rastreador_id 
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Não é possível excluir: o rastreador está atrelado ao veículo ' || COALESCE(v_veiculo.placa, '') || ' (' || COALESCE(v_veiculo.marca_modelo, '') || '). Desvincule o equipamento do veículo antes de excluir.'
    );
  END IF;

  -- 3. Salvaguarda: Verifica se há instalação em andamento
  SELECT id, status INTO v_inst 
  FROM public.instalacoes 
  WHERE rastreador_id = p_rastreador_id 
    AND status NOT IN ('concluida', 'concluido', 'cancelada', 'cancelado')
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Não é possível excluir: o equipamento está associado a uma ordem de serviço de instalação ativa (' || v_inst.status || ').'
    );
  END IF;

  -- 4. Se o rastreador tiver chip_id vinculado, desvincula o chip antes de apagar
  IF v_rast.chip_id IS NOT NULL THEN
    UPDATE public.chips 
    SET status = 'ativo', 
        updated_at = NOW() 
    WHERE id = v_rast.chip_id;
  END IF;

  -- 5. Limpa referências históricas de instalações concluídas/canceladas
  UPDATE public.instalacoes 
  SET rastreador_id = NULL 
  WHERE rastreador_id = p_rastreador_id;

  -- 6. Remove telemetrias residuais se existirem
  BEGIN
    DELETE FROM public.posicoes_gps WHERE rastreador_id = p_rastreador_id;
  EXCEPTION WHEN OTHERS THEN
    -- Silencioso
  END;

  -- 7. Executa a exclusão do rastreador
  DELETE FROM public.rastreadores WHERE id = p_rastreador_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Rastreador IMEI ' || v_rast.imei || ' excluído com sucesso do estoque.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.excluir_rastreador_estoque(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.excluir_rastreador_estoque(UUID) TO service_role;

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Odômetro Físico Real J16 (MCU), Data da Leitura e Saneamento
-- ─────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS odometro_hardware_km NUMERIC(12, 2) DEFAULT NULL;

ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS odometro_hardware_atualizado_em TIMESTAMPTZ DEFAULT NULL;

NOTIFY pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Canais de Alertas (App e WhatsApp) e Destinatários WhatsApp por Veículo
-- Data: 16/10/2026
-- ─────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.regras_veiculo
ADD COLUMN IF NOT EXISTS canais_alertas JSONB NOT NULL DEFAULT '{"app": true, "whatsapp": true}'::jsonb;

ALTER TABLE public.regras_veiculo
ADD COLUMN IF NOT EXISTS whatsapp_destinatarios JSONB NOT NULL DEFAULT '[]'::jsonb;

CREATE OR REPLACE FUNCTION public.registrar_alerta_seguranca(
  p_veiculo_id UUID,
  p_tipo TEXT,
  p_detalhes TEXT,
  p_gravidade TEXT DEFAULT 'alta',
  p_latitude DOUBLE PRECISION DEFAULT 0.0,
  p_longitude DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade INT DEFAULT 0,
  p_vibracao_g NUMERIC DEFAULT 0.0,
  p_inclinacao_graus INT DEFAULT 0,
  p_cliente_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_cliente_id UUID;
  v_cliente_user_id UUID;
  v_placa TEXT;
  v_ignicao BOOLEAN;
  v_ult_lat DOUBLE PRECISION;
  v_ult_lon DOUBLE PRECISION;
  v_ult_vel NUMERIC;
  v_alertas_ativos JSONB;
  v_canais_alertas JSONB;
  v_whatsapp_destinatarios JSONB;
  v_alerta_existente_id UUID;
  v_novo_alerta_id UUID;
  v_titulo_evento TEXT;
  v_severidade_evento TEXT;
  v_canal_app_ativo BOOLEAN;
  v_canal_whats_ativo BOOLEAN;
BEGIN
  SELECT 
    cliente_id, 
    placa, 
    ultima_latitude, 
    ultima_longitude, 
    velocidade_atual,
    ignicao_status
  INTO 
    v_cliente_id, 
    v_placa, 
    v_ult_lat, 
    v_ult_lon, 
    v_ult_vel,
    v_ignicao
  FROM public.veiculos
  WHERE id = p_veiculo_id;

  IF v_cliente_id IS NULL AND p_cliente_id IS NOT NULL THEN
    v_cliente_id := p_cliente_id;
  END IF;

  IF v_cliente_id IS NULL THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo ou cliente não localizado no sistema.');
  END IF;

  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = v_cliente_id
  LIMIT 1;

  IF (p_latitude IS NULL OR p_longitude IS NULL OR (p_latitude = 0.0 AND p_longitude = 0.0)) THEN
    IF v_ult_lat IS NOT NULL AND v_ult_lon IS NOT NULL AND (v_ult_lat <> 0.0 OR v_ult_lon <> 0.0) THEN
      p_latitude := v_ult_lat;
      p_longitude := v_ult_lon;
      IF (p_velocidade IS NULL OR p_velocidade = 0) AND v_ult_vel IS NOT NULL THEN
        p_velocidade := ROUND(v_ult_vel)::INT;
      END IF;
    END IF;
  END IF;

  SELECT 
    alertas_ativos,
    COALESCE(canais_alertas, '{"app": true, "whatsapp": true}'::jsonb),
    COALESCE(whatsapp_destinatarios, '[]'::jsonb)
  INTO 
    v_alertas_ativos,
    v_canais_alertas,
    v_whatsapp_destinatarios
  FROM public.regras_veiculo
  WHERE veiculo_id = p_veiculo_id
  LIMIT 1;

  v_canal_app_ativo := COALESCE((v_canais_alertas->>'app')::BOOLEAN, true);
  v_canal_whats_ativo := COALESCE((v_canais_alertas->>'whatsapp')::BOOLEAN, true);

  IF p_tipo = 'bateria_desconectada' THEN
    IF v_alertas_ativos IS NOT NULL AND COALESCE(
      (v_alertas_ativos->>'bateria_desconectada')::BOOLEAN,
      (v_alertas_ativos->>'baixa_tensao')::BOOLEAN,
      true
    ) = false THEN
      RETURN jsonb_build_object(
        'sucesso', true, 
        'ignorado_por_preferencia', true,
        'mensagem', 'Notificação de desconexão da bateria desativada pelo cliente nas configurações de proteção do veículo.'
      );
    END IF;
  ELSIF p_tipo = 'baixa_tensao' THEN
    IF v_alertas_ativos IS NOT NULL AND COALESCE(
      (v_alertas_ativos->>'baixa_tensao')::BOOLEAN,
      true
    ) = false THEN
      RETURN jsonb_build_object(
        'sucesso', true, 
        'ignorado_por_preferencia', true,
        'mensagem', 'Notificação de baixa tensão desativada pelo cliente nas configurações do veículo.'
      );
    END IF;
  END IF;

  SELECT id INTO v_alerta_existente_id
  FROM public.alertas_seguranca
  WHERE veiculo_id = p_veiculo_id
    AND tipo = p_tipo
    AND reconhecido = FALSE
    AND created_at >= NOW() - INTERVAL '3 minutes'
  LIMIT 1;

  IF v_alerta_existente_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'sucesso', true,
      'alerta_id', v_alerta_existente_id,
      'duplicado', true
    );
  END IF;

  INSERT INTO public.alertas_seguranca (
    veiculo_id,
    cliente_id,
    tipo,
    gravidade,
    latitude,
    longitude,
    velocidade,
    vibracao_g,
    inclinacao_graus,
    detalhes,
    reconhecido,
    created_at
  ) VALUES (
    p_veiculo_id,
    v_cliente_id,
    p_tipo,
    COALESCE(p_gravidade, 'alta'),
    COALESCE(p_latitude, 0.0),
    COALESCE(p_longitude, 0.0),
    COALESCE(p_velocidade, 0),
    COALESCE(p_vibracao_g, 0.00),
    COALESCE(p_inclinacao_graus, 0),
    p_detalhes,
    FALSE,
    NOW()
  )
  RETURNING id INTO v_novo_alerta_id;

  v_titulo_evento := CASE
    WHEN p_tipo = 'suspeita_jammer' THEN 'Alerta: Suspeita de Jammer / Silenciamento'
    WHEN p_tipo = 'saida_area' THEN 'Alerta: Saída de Cerca Virtual'
    WHEN p_tipo = 'desvio_rota' THEN 'Alerta: Desvio de Rota Monitorada'
    WHEN p_tipo = 'bateria_desconectada' THEN 'Corte / Desconexão da Bateria'
    WHEN p_tipo = 'baixa_tensao' THEN 'Baixa Tensão da Bateria'
    WHEN p_tipo = 'guincho' THEN 'Alerta: Guincho / Reboque Não Autorizado'
    WHEN p_tipo = 'colisao_impacto' AND (COALESCE(v_ignicao, false) = false OR p_detalhes ILIKE '%estacionado%' OR p_detalhes ILIKE '%toque%') THEN 'Alerta: Toque / Vibração no Veículo Estacionado'
    WHEN p_tipo = 'colisao_impacto' THEN 'Alerta: Impacto / Choque Violento'
    WHEN p_tipo = 'capotamento_inclinacao' THEN 'Alerta: Inclinação Excessiva / Capotamento'
    WHEN p_tipo = 'panico' THEN 'Alerta: Botão de Pânico Acionado'
    ELSE 'Alerta de Segurança'
  END;

  v_severidade_evento := CASE
    WHEN p_gravidade = 'critica' THEN 'critico'
    WHEN p_gravidade = 'alta' THEN 'aviso'
    ELSE 'info'
  END;

  BEGIN
    INSERT INTO public.eventos_veiculo (
      veiculo_id,
      cliente_id,
      tipo,
      titulo,
      descricao,
      severidade,
      latitude,
      longitude,
      velocidade,
      data_hora
    ) VALUES (
      p_veiculo_id,
      v_cliente_id,
      p_tipo,
      v_titulo_evento,
      p_detalhes,
      v_severidade_evento,
      p_latitude,
      p_longitude,
      p_velocidade,
      NOW()
    );
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;

  IF v_canal_app_ativo AND v_cliente_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa,
        lida,
        created_at
      ) VALUES (
        v_cliente_user_id,
        v_cliente_id,
        'GD Rastreamento — Central de Segurança',
        v_titulo_evento || ' — ' || COALESCE(v_placa, 'Veículo'),
        p_detalhes,
        p_tipo,
        '/monitor-gps',
        COALESCE(v_placa, ''),
        false,
        NOW()
      );
    EXCEPTION
      WHEN OTHERS THEN NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'alerta_id', v_novo_alerta_id,
    'duplicado', false,
    'latitude', p_latitude,
    'longitude', p_longitude,
    'canal_app', v_canal_app_ativo,
    'canal_whatsapp', v_canal_whats_ativo,
    'whatsapp_destinatarios', v_whatsapp_destinatarios
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'sucesso', false,
    'erro', SQLERRM
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_alerta_seguranca TO authenticated, anon, service_role;

-- ─────────────────────────────────────────────────────────────────────────────
-- MIGRATION: 20261016120000_hunter_cobranca_apos_primeiro_veiculo_ativo.sql
-- Início de cobrança e parcelas contratuais estritamente após a ativação do 1º veículo
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Atualizar admin_gerar_parcelas_contrato: só gera se o cliente possuir ao menos 1 veículo ativo
CREATE OR REPLACE FUNCTION public.admin_gerar_parcelas_contrato(
  p_cliente_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente RECORD;
  v_i INT;
  v_data_ref DATE;
  v_mes_ref INT;
  v_ano_ref INT;
  v_dia_venc INT;
  v_dia_max INT;
  v_dia_final INT;
  v_data_venc DATE;
  v_status_inicial public.status_mensalidade;
  v_geradas INT := 0;
  v_existentes INT := 0;
  v_meses_total INT;
  v_tem_veiculo_ativo BOOLEAN;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem gerar parcelas de contrato.';
  END IF;

  SELECT id, dia_vencimento, valor_mensalidade, meses_contrato, data_inicio_contrato, status
  INTO v_cliente
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.';
  END IF;

  -- Regra Canônica Hunter-Guardian:
  -- O cliente só inicia cobrança e tem parcelas geradas APÓS o primeiro veículo ativo no sistema.
  SELECT EXISTS (
    SELECT 1 FROM public.veiculos v
    WHERE v.cliente_id = p_cliente_id AND v.ativo = TRUE
  ) INTO v_tem_veiculo_ativo;

  IF NOT v_tem_veiculo_ativo OR v_cliente.status = 'aguardando_instalacao' THEN
    RETURN jsonb_build_object(
      'success', TRUE,
      'parcelas_geradas', 0,
      'parcelas_existentes', 0,
      'message', 'Cliente aguardando instalação ou sem veículo ativo. Cobrança de parcelas postergada para a data de ativação.'
    );
  END IF;

  v_meses_total := GREATEST(1, COALESCE(v_cliente.meses_contrato, 12));
  v_dia_venc := COALESCE(v_cliente.dia_vencimento, 10);

  FOR v_i IN 0..(v_meses_total - 1) LOOP
    v_data_ref := (COALESCE(v_cliente.data_inicio_contrato, CURRENT_DATE) + (v_i || ' months')::INTERVAL)::DATE;
    v_mes_ref := EXTRACT(MONTH FROM v_data_ref)::INT;
    v_ano_ref := EXTRACT(YEAR FROM v_data_ref)::INT;

    -- Calcula o último dia válido do mês em questão
    v_dia_max := EXTRACT(DAY FROM (DATE_TRUNC('month', make_date(v_ano_ref, v_mes_ref, 1)) + INTERVAL '1 month - 1 day'))::INT;
    v_dia_final := LEAST(v_dia_venc, v_dia_max);
    v_data_venc := make_date(v_ano_ref, v_mes_ref, v_dia_final);

    IF v_data_venc < CURRENT_DATE THEN
      v_status_inicial := 'vencido';
    ELSE
      v_status_inicial := 'pendente';
    END IF;

    INSERT INTO public.mensalidades (
      cliente_id,
      mes_referencia,
      ano_referencia,
      valor,
      data_vencimento,
      status,
      created_at,
      updated_at
    ) VALUES (
      p_cliente_id,
      v_mes_ref,
      v_ano_ref,
      COALESCE(v_cliente.valor_mensalidade, 79.90),
      v_data_venc,
      v_status_inicial,
      NOW(),
      NOW()
    )
    ON CONFLICT (cliente_id, mes_referencia, ano_referencia) DO NOTHING;

    IF FOUND THEN
      v_geradas := v_geradas + 1;
    ELSE
      v_existentes := v_existentes + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', TRUE,
    'parcelas_geradas', v_geradas,
    'parcelas_existentes', v_existentes,
    'message', v_geradas || ' parcelas geradas com sucesso a partir da data de ativação.'
  );
END;
$$;

-- 2. Atualizar admin_gerar_mensalidades_mes: só gera mensalidades para clientes com ao menos 1 veículo ativo
CREATE OR REPLACE FUNCTION public.admin_gerar_mensalidades_mes(
  p_mes INT,
  p_ano INT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente RECORD;
  v_dia_max INT;
  v_dia_final INT;
  v_data_venc DATE;
  v_status_inicial public.status_mensalidade;
  v_total_clientes INT := 0;
  v_geradas INT := 0;
  v_ja_existentes INT := 0;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem gerar mensalidades em lote.';
  END IF;

  IF p_mes < 1 OR p_mes > 12 THEN
    RAISE EXCEPTION 'Mês de referência inválido: deve estar entre 1 e 12.';
  END IF;

  IF p_ano < 2024 OR p_ano > 2099 THEN
    RAISE EXCEPTION 'Ano de referência inválido.';
  END IF;

  v_dia_max := EXTRACT(DAY FROM (DATE_TRUNC('month', make_date(p_ano, p_mes, 1)) + INTERVAL '1 month - 1 day'))::INT;

  FOR v_cliente IN
    SELECT c.id, c.dia_vencimento, c.valor_mensalidade, c.nome_razao_social
    FROM public.clientes c
    WHERE c.status <> 'bloqueado'
      AND c.status <> 'aguardando_instalacao'
      AND c.valor_mensalidade > 0
      AND EXISTS (
        SELECT 1 FROM public.veiculos v
        WHERE v.cliente_id = c.id
          AND v.ativo = TRUE
      )
  LOOP
    v_total_clientes := v_total_clientes + 1;

    v_dia_final := LEAST(COALESCE(v_cliente.dia_vencimento, 10), v_dia_max);
    v_data_venc := make_date(p_ano, p_mes, v_dia_final);

    IF v_data_venc < CURRENT_DATE THEN
      v_status_inicial := 'vencido';
    ELSE
      v_status_inicial := 'pendente';
    END IF;

    INSERT INTO public.mensalidades (
      cliente_id,
      mes_referencia,
      ano_referencia,
      valor,
      data_vencimento,
      status,
      created_at,
      updated_at
    ) VALUES (
      v_cliente.id,
      p_mes,
      p_ano,
      v_cliente.valor_mensalidade,
      v_data_venc,
      v_status_inicial,
      NOW(),
      NOW()
    )
    ON CONFLICT (cliente_id, mes_referencia, ano_referencia) DO NOTHING;

    IF FOUND THEN
      v_geradas := v_geradas + 1;
    ELSE
      v_ja_existentes := v_ja_existentes + 1;
    END IF;
  END LOOP;

  INSERT INTO public.system_activity_logs (
    user_id,
    acao,
    detalhe,
    created_at
  ) VALUES (
    auth.uid(),
    'GERACAO_MENSALIDADES_LOTE',
    'Competência: ' || LPAD(p_mes::TEXT, 2, '0') || '/' || p_ano::TEXT ||
    ' | Geradas: ' || v_geradas::TEXT ||
    ' | Já existentes: ' || v_ja_existentes::TEXT ||
    ' | Clientes com veículo ativo: ' || v_total_clientes::TEXT,
    NOW()
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'geradas', v_geradas,
    'ja_existentes', v_ja_existentes,
    'total_clientes', v_total_clientes,
    'message', v_geradas || ' mensalidades geradas com sucesso para a competência ' || LPAD(p_mes::TEXT, 2, '0') || '/' || p_ano::TEXT || '.'
  );
END;
$$;

-- 3. Atualizar instalador_concluir_atendimento: ao ativar o veículo e concluir instalação, inicia a cobrança das mensalidades
CREATE OR REPLACE FUNCTION public.instalador_concluir_atendimento(
  p_instalacao_id UUID,
  p_imei_conferido TEXT,
  p_com_bloqueador BOOLEAN,
  p_posicao_instalacao TEXT,
  p_placa TEXT,
  p_marca TEXT,
  p_modelo TEXT,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_tipo_veiculo TEXT DEFAULT 'carro',
  p_km_instalacao INT DEFAULT 0,
  p_horimetro_inicial NUMERIC DEFAULT 0.00,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_inst RECORD;
  v_valor_final NUMERIC(10,2);
  v_veiculo_id UUID;
  v_imei_limpo TEXT;
  v_imei_esperado TEXT;
  v_tem_mensalidades BOOLEAN;
  v_data_ativacao DATE;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  SELECT * INTO v_inst FROM public.instalacoes WHERE id = p_instalacao_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não encontrada.');
  END IF;

  IF v_role NOT IN ('superadmin', 'adm', 'operador') AND v_inst.instalador_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Acesso negado: esta instalação não está atribuída ao seu usuário.');
  END IF;

  -- 1. Validação de IMEI
  v_imei_limpo := regexp_replace(trim(p_imei_conferido), '\D', '', 'g');
  v_imei_esperado := regexp_replace(trim(COALESCE(v_inst.rastreador_imei, '')), '\D', '', 'g');

  IF v_imei_esperado <> '' AND v_imei_limpo <> v_imei_esperado THEN
    RETURN jsonb_build_object(
      'success', false, 
      'divergencia_imei', true,
      'message', 'Rastreador não confere com o disponibilizado para este veículo. IMEI esperado: ' || v_inst.rastreador_imei
    );
  END IF;

  -- 2. Valor de repasse da instalação
  IF p_com_bloqueador THEN
    SELECT COALESCE(valor_instalacao_com_bloqueador, valor_por_instalacao, 80.00)
    INTO v_valor_final
    FROM public.profiles
    WHERE id = v_inst.instalador_id;
  ELSE
    SELECT COALESCE(valor_instalacao_sem_bloqueador, valor_por_instalacao, 50.00)
    INTO v_valor_final
    FROM public.profiles
    WHERE id = v_inst.instalador_id;
  END IF;

  IF v_valor_final IS NULL OR v_valor_final <= 0 THEN
    v_valor_final := CASE WHEN p_com_bloqueador THEN 80.00 ELSE 50.00 END;
  END IF;

  -- 3. Ativar veículo do cliente
  v_veiculo_id := v_inst.veiculo_id;
  IF v_veiculo_id IS NULL THEN
    INSERT INTO public.veiculos (
      cliente_id,
      placa,
      marca_modelo,
      ano,
      cor,
      tipo_veiculo,
      odometro_km,
      horimetro_horas,
      ativo,
      ignicao_status,
      created_at,
      updated_at
    ) VALUES (
      v_inst.cliente_id,
      trim(upper(p_placa)),
      trim(p_marca || ' ' || p_modelo),
      p_ano,
      p_cor,
      p_tipo_veiculo,
      COALESCE(p_km_instalacao, 0),
      COALESCE(p_horimetro_inicial, 0.00),
      TRUE,
      FALSE,
      NOW(),
      NOW()
    ) RETURNING id INTO v_veiculo_id;
  ELSE
    UPDATE public.veiculos
    SET
      placa = trim(upper(p_placa)),
      marca_modelo = trim(p_marca || ' ' || p_modelo),
      ano = COALESCE(p_ano, ano),
      cor = COALESCE(p_cor, cor),
      tipo_veiculo = p_tipo_veiculo,
      odometro_km = CASE WHEN p_km_instalacao > 0 THEN p_km_instalacao ELSE odometro_km END,
      horimetro_horas = CASE WHEN p_horimetro_inicial > 0 THEN p_horimetro_inicial ELSE horimetro_horas END,
      ativo = TRUE,
      updated_at = NOW()
    WHERE id = v_veiculo_id;
  END IF;

  v_data_ativacao := CURRENT_DATE;

  -- 4. Concluir ordem de instalação
  UPDATE public.instalacoes
  SET
    veiculo_id = v_veiculo_id,
    placa = trim(upper(p_placa)),
    marca = trim(p_marca),
    modelo = trim(p_modelo),
    ano = p_ano,
    cor = p_cor,
    tipo_veiculo = p_tipo_veiculo,
    km_instalacao = COALESCE(p_km_instalacao, 0),
    horimetro_inicial = COALESCE(p_horimetro_inicial, 0.00),
    com_bloqueador = p_com_bloqueador,
    tipo_bloqueador = CASE WHEN p_com_bloqueador THEN 'rele_combustivel' ELSE 'sem_bloqueador' END,
    posicao_instalacao = trim(p_posicao_instalacao),
    valor_instalacao = v_valor_final,
    status = 'concluida',
    status_pagamento = 'pendente',
    kit_confirmado_instalador = TRUE,
    imei_confirmado = v_imei_limpo,
    observacoes = COALESCE(p_observacoes, observacoes),
    data_instalacao = v_data_ativacao,
    concluida_at = NOW(),
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  -- 5. Atualizar status do cliente para ativo e fixar data de início do contrato na ativação real
  UPDATE public.clientes
  SET
    status = 'ativo',
    status_agendamento = 'concluido',
    data_inicio_contrato = COALESCE(data_inicio_contrato, v_data_ativacao),
    updated_at = NOW()
  WHERE id = v_inst.cliente_id;

  -- 6. Iniciar geração das parcelas de cobrança a partir da data de ativação (se ainda não geradas)
  SELECT EXISTS (
    SELECT 1 FROM public.mensalidades WHERE cliente_id = v_inst.cliente_id
  ) INTO v_tem_mensalidades;

  IF NOT v_tem_mensalidades THEN
    PERFORM public.admin_gerar_parcelas_contrato(v_inst.cliente_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Instalação concluída com sucesso! Veículo ativado e cobrança iniciada a partir da data de instalação.',
    'instalacao_id', p_instalacao_id,
    'valor_instalacao', v_valor_final,
    'veiculo_id', v_veiculo_id
  );
END;
$$;

-- 4. Atualizar admin_cadastrar_cliente_completo: veículo cadastrado inicia com ativo = FALSE (aguardando instalação)
CREATE OR REPLACE FUNCTION public.admin_cadastrar_cliente_completo(
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_criar_usuario BOOLEAN DEFAULT TRUE,
  p_senha TEXT DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca_modelo TEXT DEFAULT NULL,
  p_km_inicial INT DEFAULT 0,
  p_instalador_id UUID DEFAULT NULL,
  p_meses_contrato INT DEFAULT 12,
  p_data_inicio_contrato DATE DEFAULT CURRENT_DATE,
  p_tipo_renovacao TEXT DEFAULT 'mesma_vigencia',
  p_meses_renovacao INT DEFAULT 12,
  p_foro_comarca TEXT DEFAULT 'Volta Redonda/RJ'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID := NULL;
  v_cliente_id UUID;
  v_veiculo_id UUID;
  v_mod TEXT;
  v_modulos TEXT[];
  v_email_limpo TEXT := LOWER(trim(p_email));
  v_meses_c INT;
  v_data_inicio DATE;
  v_data_fim DATE;
  v_resultado_parcelas JSONB;
BEGIN
  -- 1. Apenas administradores podem cadastrar
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  -- 2. Validacoes basicas do cliente
  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  v_meses_c := GREATEST(1, COALESCE(p_meses_contrato, 12));
  v_data_inicio := COALESCE(p_data_inicio_contrato, CURRENT_DATE);
  v_data_fim := (v_data_inicio + (v_meses_c || ' months')::INTERVAL)::DATE;

  -- 3. Criacao de usuario em auth.users se solicitado
  IF p_criar_usuario THEN
    IF v_email_limpo IS NULL OR v_email_limpo = '' THEN
      RAISE EXCEPTION 'O e-mail e obrigatorio para liberar acesso ao sistema.';
    END IF;

    IF p_senha IS NULL OR length(p_senha) < 6 THEN
      RAISE EXCEPTION 'A senha inicial de acesso deve conter no minimo 6 caracteres.';
    END IF;

    IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_limpo) THEN
      RAISE EXCEPTION 'Ja existe um usuario cadastrado no sistema com este e-mail.';
    END IF;

    v_user_id := gen_random_uuid();

    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, recovery_sent_at, last_sign_in_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, email_change, email_change_token_new, recovery_token
    ) VALUES (
      v_user_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      v_email_limpo,
      extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}',
      jsonb_build_object('nome', trim(p_nome), 'role', 'cliente'),
      now(), now(),
      '', '', '', ''
    );

    IF NOT EXISTS (
      SELECT 1 FROM auth.identities 
      WHERE (provider = 'email' AND provider_id = v_user_id::text)
         OR user_id = v_user_id
    ) THEN
      BEGIN
        INSERT INTO auth.identities (
          id,
          user_id,
          identity_data,
          provider,
          provider_id,
          last_sign_in_at,
          created_at,
          updated_at
        ) VALUES (
          v_user_id::text,
          v_user_id,
          jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
          'email',
          v_user_id::text,
          now(),
          now(),
          now()
        );
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;

    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (v_user_id, trim(p_nome), v_email_limpo, 'cliente', TRUE)
    ON CONFLICT (id) DO UPDATE
    SET nome = EXCLUDED.nome,
        email = EXCLUDED.email,
        role = 'cliente',
        ativo = TRUE,
        updated_at = now();

    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, 'cliente')
    ON CONFLICT (user_id, role) DO NOTHING;

    IF p_plano = 'basico' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades'];
    ELSIF p_plano = 'pro' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    ELSE
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao', 'central-seguranca'];
    END IF;

    FOREACH v_mod IN ARRAY v_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 4. Insercao do Cliente com os dados do Contrato
  v_cliente_id := gen_random_uuid();
  INSERT INTO public.clientes (
    id,
    user_id,
    instalador_id,
    nome_razao_social,
    documento,
    email,
    telefone,
    plano,
    status,
    status_agendamento,
    dia_vencimento,
    valor_mensalidade,
    dias_historico_plano,
    dias_retencao_banco,
    meses_contrato,
    data_inicio_contrato,
    data_fim_contrato,
    tipo_renovacao,
    meses_renovacao,
    foro_comarca,
    created_at,
    updated_at
  ) VALUES (
    v_cliente_id,
    v_user_id,
    p_instalador_id,
    trim(p_nome),
    NULLIF(trim(p_documento), ''),
    NULLIF(v_email_limpo, ''),
    NULLIF(trim(p_telefone), ''),
    p_plano,
    'aguardando_instalacao',
    'aguardando_agendamento',
    COALESCE(p_dia_vencimento, 10),
    COALESCE(p_valor_mensalidade, 79.90),
    COALESCE(p_dias_historico, 7),
    COALESCE(p_dias_retencao, 10),
    v_meses_c,
    v_data_inicio,
    v_data_fim,
    COALESCE(p_tipo_renovacao, 'mesma_vigencia'),
    COALESCE(p_meses_renovacao, v_meses_c),
    COALESCE(p_foro_comarca, 'Volta Redonda/RJ'),
    now(),
    now()
  );

  -- 5. Cadastro do primeiro veiculo se informado (inicia com ativo = FALSE ate a conclusao da instalacao/ativacao)
  IF p_placa IS NOT NULL AND trim(p_placa) <> '' THEN
    v_veiculo_id := gen_random_uuid();
    INSERT INTO public.veiculos (
      id,
      cliente_id,
      placa,
      marca_modelo,
      km_atual,
      ativo,
      bloqueado,
      created_at,
      updated_at
    ) VALUES (
      v_veiculo_id,
      v_cliente_id,
      UPPER(trim(p_placa)),
      COALESCE(trim(p_marca_modelo), 'Veiculo Padrao'),
      COALESCE(p_km_inicial, 0),
      FALSE,
      FALSE,
      now(),
      now()
    );
  END IF;

  -- 6. Tenta gerar parcelas do contrato (admin_gerar_parcelas_contrato somente gera se houver veiculo ativo)
  v_resultado_parcelas := public.admin_gerar_parcelas_contrato(v_cliente_id);

  INSERT INTO public.system_activity_logs (
    user_id,
    acao,
    detalhe,
    created_at
  ) VALUES (
    v_caller_id,
    'CADASTRO_CLIENTE_COM_CONTRATO',
    'Cliente: ' || trim(p_nome) ||
    ' | Contrato: ' || v_meses_c::TEXT || ' meses' ||
    ' | Foro: ' || COALESCE(p_foro_comarca, 'Volta Redonda/RJ') ||
    ' | Parcelas geradas: ' || COALESCE(v_resultado_parcelas->>'parcelas_geradas', '0'),
    NOW()
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Cliente e contrato cadastrados com sucesso. Cobrança de parcelas iniciará após a ativação do primeiro veículo.',
    'cliente_id', v_cliente_id,
    'user_id', v_user_id,
    'meses_contrato', v_meses_c,
    'data_inicio_contrato', v_data_inicio,
    'data_fim_contrato', v_data_fim,
    'parcelas', v_resultado_parcelas
  );
END;
$$;

-- 5. Excluir quaisquer mensalidades prematuras de clientes que ainda estejam sem nenhum veículo ativo
DELETE FROM public.mensalidades
WHERE cliente_id IN (
  SELECT c.id FROM public.clientes c
  WHERE c.status = 'aguardando_instalacao'
     OR NOT EXISTS (
       SELECT 1 FROM public.veiculos v WHERE v.cliente_id = c.id AND v.ativo = TRUE
     )
);

-- 6. Permissões
GRANT EXECUTE ON FUNCTION public.admin_gerar_parcelas_contrato(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_gerar_mensalidades_mes(INT, INT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.instalador_concluir_atendimento(UUID, TEXT, BOOLEAN, TEXT, TEXT, TEXT, TEXT, INT, TEXT, TEXT, INT, NUMERIC, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_cadastrar_cliente_completo(TEXT, TEXT, TEXT, TEXT, public.plano_cliente, INT, NUMERIC, INT, INT, BOOLEAN, TEXT, TEXT, TEXT, INT, UUID, INT, DATE, TEXT, INT, TEXT) TO authenticated;

-- 7. Invalidação de Cache PostgREST Obrigatória (Regra Pétrea)
NOTIFY pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────────
