  tipo TEXT NOT NULL DEFAULT 'ip',
  falhas_acumuladas INT NOT NULL DEFAULT 1,
  bloqueado_ate TIMESTAMPTZ NOT NULL,
  motivo TEXT NOT NULL DEFAULT 'Excesso de tentativas incorretas de autenticação',
