-- ============================================================================
-- CORREÇÃO CRÍTICA: Vinculação do trigger trg_hunter_alertas_telemetria
-- na tabela public.veiculos para que alertas de telemetria (ignição fora do
-- horário, excesso de velocidade, movimento fora do horário, guincho) sejam
-- avaliados automaticamente pelo servidor sempre que o gateway atualizar
-- ignicao_status ou velocidade_atual, independente do app estar aberto.
-- SEM este trigger: Push VAPID e WhatsApp NUNCA disparam para alertas
-- de telemetria porque nenhuma linha é inserida em notificacoes_sistema.
-- ============================================================================
-- ============================================================================
-- MIGRATION: 20261019140000_hunter_alertas_tempo_real_geofence_ignicao_e_otimizacao_bd.sql
-- Sistema: GD Rastreamento | Diretrizes: HUNTER-GUARDIAN e DJR-NEW
-- 
-- CAUSAS-RAÍZES SANADAS INTEGRALMENTE:
-- 1. Latência extrema e atrasos ao salvar no BD:
--    - Ausência de colunas (fator_calibracao_odometro, gps_fixado) causava erro SQL
--      na RPC registrar_posicao_gps_com_odometro a cada pacote, disparando
--      fallbacks em cascata e enfileiramento de requisições.
--    - Trigger trg_sync_veiculo_instalacao executava UPDATE desnecessário em instalacoes
--      a cada atualização de telemetria sem cláusula WHEN de filtragem.
--    - Índices críticos ausentes para busca rápida de áreas seguras e viagens ativas.
-- 2. Alertas de Cerca Virtual / Área Protegida (saída e chegada):
--    - Inexistiam no servidor/BD (estavam apenas em useEffect do frontend).
--    - Agora são avaliados de forma nativa e atômica no Postgres pelo trigger de telemetria.
-- 3. Alertas de Ignição e Deslocamento Fora de Horário:
--    - Ignição ligada agora possui canal canônico em tempo real no servidor.
--    - Deslocamento fora de horário calibrado para detectar movimento e velocidade.
--    - RPC registrar_alerta_seguranca agora insere em notificacoes_sistema para acionar Push e WhatsApp.
-- ============================================================================

-- ── 1. BLINDAGEM DE ESQUEMA: Colunas faltantes em veiculos e telemetria_posicoes ─
ALTER TABLE public.veiculos 
ADD COLUMN IF NOT EXISTS fator_calibracao_odometro NUMERIC(8, 6) DEFAULT 1.000000;

ALTER TABLE public.veiculos 
ADD COLUMN IF NOT EXISTS gps_fixado BOOLEAN DEFAULT TRUE;

ALTER TABLE public.telemetria_posicoes 
ADD COLUMN IF NOT EXISTS gps_fixado BOOLEAN DEFAULT TRUE;

-- ── 2. OTIMIZAÇÃO DE ÍNDICES: Aceleração de consultas críticas ───────────────────
CREATE INDEX IF NOT EXISTS idx_areas_seguras_veiculo_ativo 
ON public.areas_seguras(veiculo_id) 
WHERE ativo = true;

CREATE INDEX IF NOT EXISTS idx_areas_seguras_cliente_ativo 
ON public.areas_seguras(cliente_id) 
WHERE ativo = true;

CREATE INDEX IF NOT EXISTS idx_viagens_veiculo_status_andamento 
ON public.viagens_trajetos(veiculo_id, status) 
WHERE status = 'em_andamento';

CREATE INDEX IF NOT EXISTS idx_instalacoes_cliente_status_pendente 
ON public.instalacoes(cliente_id, status) 
WHERE status NOT IN ('concluida');

-- ── 3. OTIMIZAÇÃO DO TRIGGER trg_sync_veiculo_instalacao (Zero I/O inútil) ─────
DROP TRIGGER IF EXISTS trg_sync_veiculo_instalacao ON public.veiculos;
DROP TRIGGER IF EXISTS trg_sync_veiculo_instalacao_insert ON public.veiculos;
DROP TRIGGER IF EXISTS trg_sync_veiculo_instalacao_update ON public.veiculos;

CREATE TRIGGER trg_sync_veiculo_instalacao_insert
AFTER INSERT ON public.veiculos
FOR EACH ROW
EXECUTE FUNCTION public.trg_sync_veiculo_instalacao();

CREATE TRIGGER trg_sync_veiculo_instalacao_update
AFTER UPDATE ON public.veiculos
FOR EACH ROW
WHEN (
  OLD.placa IS DISTINCT FROM NEW.placa
  OR OLD.marca_modelo IS DISTINCT FROM NEW.marca_modelo
  OR OLD.cliente_id IS DISTINCT FROM NEW.cliente_id
  OR OLD.tipo_veiculo IS DISTINCT FROM NEW.tipo_veiculo
)
EXECUTE FUNCTION public.trg_sync_veiculo_instalacao();

-- ── 4. FUNÇÃO DO TRIGGER DE ALERTAS DE TELEMETRIA COMPLETO E CANÔNICO ───────────
CREATE OR REPLACE FUNCTION public.trigger_avaliar_alertas_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_cliente_user_id      UUID;
  v_velocidade_limite    NUMERIC := 110;
  v_alerta_mov_regras    BOOLEAN := true;
  v_alerta_ign_regras    BOOLEAN := true;
  v_alertas_ativos       JSONB;
  v_horario_proibido     BOOLEAN := false;
  v_hora_inicio_str      TEXT;
  v_hora_fim_str         TEXT;
  v_cooldown_ok          BOOLEAN;
  v_titulo               TEXT;
  v_mensagem             TEXT;
  v_tipo                 TEXT;
  v_gravidade            TEXT;
  v_chave_cooldown       TEXT;
  v_horario_evento_str   TEXT;
  COOLDOWN_PADRAO        CONSTANT INTERVAL := INTERVAL '5 minutes';
  COOLDOWN_IGNICAO       CONSTANT INTERVAL := INTERVAL '2 minutes';
  v_dlat                 DOUBLE PRECISION;
  v_dlon                 DOUBLE PRECISION;
  v_a                    DOUBLE PRECISION;
  v_dist_metros          DOUBLE PRECISION := 0;
  v_area                 RECORD;
  v_dist_area_new        DOUBLE PRECISION;
  v_dist_area_old        DOUBLE PRECISION;
  v_dlat_area            DOUBLE PRECISION;
  v_dlon_area            DOUBLE PRECISION;
BEGIN
  -- Ignora se não há cliente associado ao veículo
  IF NEW.cliente_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Formatação padrão e inegociável da hora exata do evento (Fuso de Brasília)
  v_horario_evento_str := to_char(
    COALESCE(NEW.ultima_atualizacao, now()) AT TIME ZONE 'America/Sao_Paulo',
    'DD/MM/YYYY às HH24:MI:SS'
  );

  -- 1. Busca o user_id do cliente para endereçar Push VAPID
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = NEW.cliente_id
  LIMIT 1;

  -- 2. Busca parâmetros de regras e preferências ativas do veículo
  SELECT 
    COALESCE(limite_velocidade_geral, 110),
    COALESCE(alerta_movimento_nao_autorizado, true),
    COALESCE(alerta_ignicao_fora_horario, true),
    alertas_ativos
  INTO 
    v_velocidade_limite,
    v_alerta_mov_regras,
    v_alerta_ign_regras,
    v_alertas_ativos
  FROM public.regras_veiculo
  WHERE veiculo_id = NEW.id
  LIMIT 1;

  IF NOT FOUND THEN
    v_velocidade_limite := 110;
    v_alerta_mov_regras := true;
    v_alerta_ign_regras := true;
    v_alertas_ativos := '{"movimento_fora_horario":true,"ignicao_fora_horario":true,"ignicao_ligada":true,"saida_area":true,"entrada_area":true,"excesso_velocidade":true,"perda_comunicacao":true,"baixa_tensao":true,"desvio_rota":true,"guincho":true}'::jsonb;
  END IF;

  -- 3. Cálculo geodésico de deslocamento Haversine em metros entre OLD e NEW
  IF OLD.ultima_latitude IS NOT NULL 
     AND OLD.ultima_longitude IS NOT NULL 
     AND NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL
     AND (OLD.ultima_latitude <> 0 OR OLD.ultima_longitude <> 0)
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0)
     AND (OLD.ultima_latitude <> NEW.ultima_latitude OR OLD.ultima_longitude <> NEW.ultima_longitude) THEN
    
    v_dlat := radians(NEW.ultima_latitude - OLD.ultima_latitude);
    v_dlon := radians(NEW.ultima_longitude - OLD.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(OLD.ultima_latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));
  ELSE
    v_dist_metros := 0;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA A: EXCESSO DE VELOCIDADE
  -- ─────────────────────────────────────────────────────────────────────────
  IF COALESCE(NEW.velocidade_atual, 0) > 0 
     AND COALESCE((v_alertas_ativos->>'excesso_velocidade')::BOOLEAN, true) = true THEN

    IF NEW.velocidade_atual > v_velocidade_limite THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'excesso_velocidade'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo    := format('Excesso de Velocidade — %s', COALESCE(NEW.placa, ''));
        v_mensagem  := format(
          'Veículo %s atingiu %s km/h (limite: %s km/h).' || E'\n' || '🕒 Horário: %s',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual),
          ROUND(v_velocidade_limite),
          v_horario_evento_str
        );
        v_tipo      := 'excesso_velocidade';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA B / C: IGNIÇÃO LIGADA (FORA DO HORÁRIO OU NORMAL EM TEMPO REAL)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true AND COALESCE(OLD.ignicao_status, false) = false THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido AND v_alerta_ign_regras = true 
       AND COALESCE((v_alertas_ativos->>'ignicao_fora_horario')::BOOLEAN, true) = true THEN
      
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT hora_inicio::TEXT, hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('Ignição Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor acionado fora do horário habitual configurado (%s às %s).' || E'\n' || 'Veículo: %s' || E'\n' || '🕒 Horário: %s',
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          COALESCE(NEW.placa, ''),
          v_horario_evento_str
        );
        v_tipo      := 'ignicao_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;

    ELSIF NOT v_horario_proibido 
          AND COALESCE((v_alertas_ativos->>'ignicao_ligada')::BOOLEAN, true) = true THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_ligada'
            AND ultimo_at > (now() - COOLDOWN_IGNICAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('Ignição Ligada — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor acionado / chave ligada.' || E'\n' || 'Veículo: %s' || E'\n' || '🕒 Horário: %s',
          COALESCE(NEW.placa, ''),
          v_horario_evento_str
        );
        v_tipo      := 'ignicao_ligada';
        v_gravidade := 'baixa';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA D: DESLOCAMENTO FORA DO HORÁRIO (ignição ligada + em movimento real)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true 
     AND (COALESCE(NEW.velocidade_atual, 0) >= 3 OR v_dist_metros >= 15.0)
     AND v_alerta_mov_regras = true
     AND COALESCE((v_alertas_ativos->>'movimento_fora_horario')::BOOLEAN, true) = true THEN

    IF v_horario_proibido OR public.hunter_horario_proibido(NEW.id) THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'movimento_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('Deslocamento Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s em deslocamento (%s km/h) fora da janela habitual configurada.' || E'\n' || '🕒 Horário: %s',
          COALESCE(NEW.placa, ''),
          ROUND(COALESCE(NEW.velocidade_atual, 0)),
          v_horario_evento_str
        );
        v_tipo      := 'movimento_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA E: GUINCHO / FURTO / REBOQUE NÃO AUTORIZADO
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = false
     AND COALESCE(OLD.ignicao_status, false) = false
     AND (
       COALESCE(NEW.velocidade_atual, 0) >= 15
       OR (COALESCE(NEW.velocidade_atual, 0) >= 10 AND v_dist_metros >= 35.0)
     )
     AND COALESCE((v_alertas_ativos->>'guincho')::BOOLEAN, true) = true THEN

    SELECT (
      NOT EXISTS (
        SELECT 1 FROM public.alertas_telemetria_cooldown
        WHERE veiculo_id = NEW.id
          AND tipo_alerta = 'guincho'
          AND ultimo_at > (now() - COOLDOWN_PADRAO)
      )
    ) INTO v_cooldown_ok;

    IF v_cooldown_ok THEN
      v_titulo   := format('🚨 Veículo em Movimento com Motor Desligado — %s', COALESCE(NEW.placa, ''));
      v_mensagem := format(
        'Veículo %s detectado a %s km/h com ignição desligada. Possível reboque ou furto em andamento.' || E'\n' || '🕒 Horário: %s',
        COALESCE(NEW.placa, ''),
        ROUND(NEW.velocidade_atual),
        v_horario_evento_str
      );
      v_tipo      := 'guincho';
      v_gravidade := 'critica';

      INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
      VALUES (NEW.id, v_tipo, now())
      ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

      INSERT INTO public.alertas_seguranca (
        veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
        velocidade, detalhes, reconhecido, created_at
      ) VALUES (
        NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
        COALESCE(NEW.ultima_latitude, 0),
        COALESCE(NEW.ultima_longitude, 0),
        COALESCE(NEW.velocidade_atual::INT, 0),
        v_mensagem, false, now()
      );

      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id, destinatario_cliente_id,
        titulo, mensagem, tipo, url, placa, lida, created_at
      ) VALUES (
        v_cliente_user_id, NEW.cliente_id,
        v_titulo, v_mensagem, v_tipo, '/monitor-gps',
        COALESCE(NEW.placa, ''), false, now()
      );
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA F: GEOFENCE — SAÍDA E CHEGADA EM ÁREAS PROTEGIDAS / CERCAS VIRTUAIS
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL 
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0)
     AND OLD.ultima_latitude IS NOT NULL 
     AND OLD.ultima_longitude IS NOT NULL 
     AND (OLD.ultima_latitude <> 0 OR OLD.ultima_longitude <> 0) THEN

    FOR v_area IN
      SELECT id, nome, latitude, longitude, raio_metros, regra_entrada, regra_saida
      FROM public.areas_seguras
      WHERE (veiculo_id = NEW.id OR (veiculo_id IS NULL AND cliente_id = NEW.cliente_id))
        AND ativo = true
        AND latitude IS NOT NULL
        AND longitude IS NOT NULL
        AND raio_metros > 0
    LOOP
      v_dlat_area := radians(NEW.ultima_latitude - v_area.latitude);
      v_dlon_area := radians(NEW.ultima_longitude - v_area.longitude);
      v_a := sin(v_dlat_area / 2.0)^2 + cos(radians(v_area.latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon_area / 2.0)^2;
      v_dist_area_new := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));

      v_dlat_area := radians(OLD.ultima_latitude - v_area.latitude);
      v_dlon_area := radians(OLD.ultima_longitude - v_area.longitude);
      v_a := sin(v_dlat_area / 2.0)^2 + cos(radians(v_area.latitude)) * cos(radians(OLD.ultima_latitude)) * sin(v_dlon_area / 2.0)^2;
      v_dist_area_old := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));

      -- F.1) SAÍDA DE ÁREA PROTEGIDA
      IF v_dist_area_old <= v_area.raio_metros AND v_dist_area_new > v_area.raio_metros THEN
        IF (v_area.regra_saida = 'alertar' OR COALESCE((v_alertas_ativos->>'saida_area')::BOOLEAN, true) = true) THEN
          v_chave_cooldown := 'saida_area_' || v_area.id::text;
          SELECT (
            NOT EXISTS (
              SELECT 1 FROM public.alertas_telemetria_cooldown
              WHERE veiculo_id = NEW.id
                AND tipo_alerta = v_chave_cooldown
                AND ultimo_at > (now() - COOLDOWN_PADRAO)
            )
          ) INTO v_cooldown_ok;

          IF v_cooldown_ok THEN
            v_titulo   := format('🚨 Saída de Área Protegida — %s', COALESCE(NEW.placa, ''));
            v_mensagem := format(
              'Veículo %s saiu do limite da cerca virtual %s (distância: %s m).' || E'\n' || '🕒 Horário: %s',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              ROUND(v_dist_area_new),
              v_horario_evento_str
            );
            v_tipo      := 'saida_area';
            v_gravidade := 'alta';

            INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
            VALUES (NEW.id, v_chave_cooldown, now())
            ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

            INSERT INTO public.alertas_seguranca (
              veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
              velocidade, detalhes, reconhecido, created_at
            ) VALUES (
              NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
              COALESCE(NEW.ultima_latitude, 0),
              COALESCE(NEW.ultima_longitude, 0),
              COALESCE(NEW.velocidade_atual::INT, 0),
              v_mensagem, false, now()
            );

            INSERT INTO public.notificacoes_sistema (
              destinatario_user_id, destinatario_cliente_id,
              titulo, mensagem, tipo, url, placa, lida, created_at
            ) VALUES (
              v_cliente_user_id, NEW.cliente_id,
              v_titulo, v_mensagem, v_tipo, '/monitor-gps',
              COALESCE(NEW.placa, ''), false, now()
            );
          END IF;
        END IF;

      -- F.2) ENTRADA / CHEGADA EM ÁREA PROTEGIDA
      ELSIF v_dist_area_old > v_area.raio_metros AND v_dist_area_new <= v_area.raio_metros THEN
        IF (v_area.regra_entrada = 'alertar' OR COALESCE((v_alertas_ativos->>'entrada_area')::BOOLEAN, false) = true) THEN
          v_chave_cooldown := 'entrada_area_' || v_area.id::text;
          SELECT (
            NOT EXISTS (
              SELECT 1 FROM public.alertas_telemetria_cooldown
              WHERE veiculo_id = NEW.id
                AND tipo_alerta = v_chave_cooldown
                AND ultimo_at > (now() - COOLDOWN_PADRAO)
            )
          ) INTO v_cooldown_ok;

          IF v_cooldown_ok THEN
            v_titulo   := format('✅ Chegada na Área Protegida — %s', COALESCE(NEW.placa, ''));
            v_mensagem := format(
              'Veículo %s chegou na área protegida %s.' || E'\n' || '🕒 Horário: %s',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_horario_evento_str
            );
            v_tipo      := 'entrada_area';
            v_gravidade := 'baixa';

            INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
            VALUES (NEW.id, v_chave_cooldown, now())
            ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

            INSERT INTO public.alertas_seguranca (
              veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
              velocidade, detalhes, reconhecido, created_at
            ) VALUES (
              NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
              COALESCE(NEW.ultima_latitude, 0),
              COALESCE(NEW.ultima_longitude, 0),
              COALESCE(NEW.velocidade_atual::INT, 0),
              v_mensagem, false, now()
            );

            INSERT INTO public.notificacoes_sistema (
              destinatario_user_id, destinatario_cliente_id,
              titulo, mensagem, tipo, url, placa, lida, created_at
            ) VALUES (
              v_cliente_user_id, NEW.cliente_id,
              v_titulo, v_mensagem, v_tipo, '/monitor-gps',
              COALESCE(NEW.placa, ''), false, now()
            );
          END IF;
        END IF;
      END IF;

    END LOOP;
  END IF;

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[HUNTER-ALERTAS-TELEMETRIA] Erro ao avaliar alertas para veículo %: %',
    NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

-- ── 5. VINCULAÇÃO DO TRIGGER DE TELEMETRIA COM LATITUDE/LONGITUDE INCLUSAS ─────
DROP TRIGGER IF EXISTS trg_hunter_alertas_telemetria ON public.veiculos;

CREATE TRIGGER trg_hunter_alertas_telemetria
AFTER UPDATE OF velocidade_atual, ignicao_status, ultima_latitude, ultima_longitude, ultima_atualizacao
ON public.veiculos
FOR EACH ROW
WHEN (
  (
    OLD.velocidade_atual IS DISTINCT FROM NEW.velocidade_atual
    OR OLD.ignicao_status IS DISTINCT FROM NEW.ignicao_status
    OR OLD.ultima_latitude IS DISTINCT FROM NEW.ultima_latitude
    OR OLD.ultima_longitude IS DISTINCT FROM NEW.ultima_longitude
  )
  AND NEW.cliente_id IS NOT NULL
  AND NEW.ativo = true
)
EXECUTE FUNCTION public.trigger_avaliar_alertas_telemetria();

-- ── 6. ATUALIZAÇÃO DA RPC registrar_alerta_seguranca COM DISPARO DE NOTIFICAÇÃO ──
CREATE OR REPLACE FUNCTION public.registrar_alerta_seguranca(
  p_veiculo_id            UUID,
  p_tipo                  TEXT,
  p_detalhes              TEXT,
  p_gravidade             TEXT             DEFAULT 'alta',
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            INTEGER          DEFAULT 0,
  p_vibracao_g            NUMERIC          DEFAULT 0.00,
  p_inclinacao_graus      INTEGER          DEFAULT 0,
  p_cliente_id            UUID             DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_cliente_id           UUID;
  v_cliente_user_id      UUID;
  v_placa                TEXT;
  v_alerta_existente_id  UUID;
  v_novo_alerta_id       UUID;
  v_titulo_evento        TEXT;
  v_severidade_evento    TEXT;
BEGIN
  -- 1. Determina cliente_id e placa caso não passados
  SELECT cliente_id, placa INTO v_cliente_id, v_placa
  FROM public.veiculos
  WHERE id = p_veiculo_id;

  IF v_cliente_id IS NULL AND p_cliente_id IS NOT NULL THEN
    v_cliente_id := p_cliente_id;
  END IF;

  IF v_cliente_id IS NULL THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo ou cliente não localizado no sistema.');
  END IF;

  -- Busca o user_id do cliente para entrega de push/notificações
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = v_cliente_id
  LIMIT 1;

  -- 2. Debouncing / Anti-Flood: Evita poluir a central se houver alerta não reconhecido do mesmo tipo nos últimos 3 minutos
  SELECT id INTO v_alerta_existente_id
  FROM public.alertas_seguranca
  WHERE veiculo_id = p_veiculo_id
    AND tipo = p_tipo
    AND reconhecido = FALSE
    AND created_at >= NOW() - INTERVAL '3 minutes'
  LIMIT 1;

  IF v_alerta_existente_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'sucesso', true,
      'alerta_id', v_alerta_existente_id,
      'duplicado', true
    );
  END IF;

  -- 3. Insere na tabela oficial alertas_seguranca
  INSERT INTO public.alertas_seguranca (
    veiculo_id,
    cliente_id,
    tipo,
    gravidade,
    latitude,
    longitude,
    velocidade,
    vibracao_g,
    inclinacao_graus,
    detalhes,
    reconhecido,
    created_at
  ) VALUES (
    p_veiculo_id,
    v_cliente_id,
    p_tipo,
    COALESCE(p_gravidade, 'alta'),
    COALESCE(p_latitude, 0.0),
    COALESCE(p_longitude, 0.0),
    COALESCE(p_velocidade, 0),
    COALESCE(p_vibracao_g, 0.00),
    COALESCE(p_inclinacao_graus, 0),
    p_detalhes,
    FALSE,
    NOW()
  )
  RETURNING id INTO v_novo_alerta_id;

  -- 4. Título padronizado para a Timeline de eventos_veiculo e notificações
  v_titulo_evento := CASE
    WHEN p_tipo = 'suspeita_jammer' THEN 'Alerta: Suspeita de Jammer / Silenciamento'
    WHEN p_tipo = 'saida_area' THEN 'Alerta: Saída de Cerca Virtual'
    WHEN p_tipo = 'entrada_area' THEN 'Alerta: Chegada em Área Segura'
    WHEN p_tipo = 'desvio_rota' THEN 'Alerta: Desvio de Rota Monitorada'
    WHEN p_tipo = 'bateria_desconectada' THEN 'Alerta: Alimentação Principal Desconectada'
    WHEN p_tipo = 'colisao_impacto' THEN 'Alerta: Impacto / Choque Violento'
    WHEN p_tipo = 'capotamento_inclinacao' THEN 'Alerta: Inclinação Excessiva / Capotamento'
    WHEN p_tipo = 'panico' THEN 'Alerta: Botão de Pânico Acionado'
    WHEN p_tipo = 'ignicao_ligada' THEN 'Alerta: Ignição Ligada'
    WHEN p_tipo = 'ignicao_desligada' THEN 'Alerta: Ignição Desligada'
    ELSE 'Alerta Operacional de Segurança'
  END;

  v_severidade_evento := CASE
    WHEN p_gravidade = 'critica' THEN 'critico'
    WHEN p_gravidade = 'alta' THEN 'aviso'
    ELSE 'info'
  END;

  -- 5. Grava também no histórico de eventos_veiculo
  BEGIN
    INSERT INTO public.eventos_veiculo (
      veiculo_id,
      cliente_id,
      tipo,
      titulo,
      descricao,
      severidade,
      latitude,
      longitude,
      velocidade,
      data_hora
    ) VALUES (
      p_veiculo_id,
      v_cliente_id,
      p_tipo,
      v_titulo_evento,
      p_detalhes,
      v_severidade_evento,
      p_latitude,
      p_longitude,
      p_velocidade,
      NOW()
    );
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;

  -- 6. Dispara notificação no sistema (ativa Push VAPID e WhatsApp em tempo real)
  BEGIN
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      destinatario_cliente_id,
      titulo,
      mensagem,
      tipo,
      url,
      placa,
      lida,
      created_at
    ) VALUES (
      v_cliente_user_id,
      v_cliente_id,
      format('%s — %s', v_titulo_evento, COALESCE(v_placa, '')),
      p_detalhes,
      p_tipo,
      '/monitor-gps',
      COALESCE(v_placa, ''),
      false,
      NOW()
    );
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object(
    'sucesso', true,
    'alerta_id', v_novo_alerta_id,
    'duplicado', false
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_alerta_seguranca(UUID, TEXT, TEXT, TEXT, DOUBLE PRECISION, DOUBLE PRECISION, INTEGER, NUMERIC, INTEGER, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.registrar_alerta_seguranca(UUID, TEXT, TEXT, TEXT, DOUBLE PRECISION, DOUBLE PRECISION, INTEGER, NUMERIC, INTEGER, UUID) TO anon;
GRANT EXECUTE ON FUNCTION public.registrar_alerta_seguranca(UUID, TEXT, TEXT, TEXT, DOUBLE PRECISION, DOUBLE PRECISION, INTEGER, NUMERIC, INTEGER, UUID) TO service_role;

-- ── 7. INVALIDAÇÃO OBRIGATÓRIA DE SCHEMA CACHE POSTGREST ──────────────────────
NOTIFY pgrst, 'reload schema';

-- ==============================================================================
-- HUNTER GUARDIAN / DJR-NEW — MIGRATION 20261019160000
-- ÁREAS SEGURAS (GEOFENCE): SUPORTE COMPLETO A REGRAS DE ENTRADA E SAÍDA
-- Permite ao usuário escolher livremente para cada área:
--   - regra_entrada: 'alertar' | 'fora_horario' | 'permitida'
--   - regra_saida:   'alertar' | 'fora_horario' | 'permitida'
-- Avaliação atômica em tempo real no trigger de telemetria com fuso de Brasília.
-- ==============================================================================

ALTER TABLE public.areas_seguras 
  ALTER COLUMN regra_entrada SET DEFAULT 'permitida',
  ALTER COLUMN regra_saida SET DEFAULT 'permitida';

CREATE OR REPLACE FUNCTION public.trigger_avaliar_alertas_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente_user_id   UUID;
  v_velocidade_limite INT := 110;
  v_alerta_mov_regras BOOLEAN := true;
  v_alerta_ign_regras BOOLEAN := true;
  v_alertas_ativos    JSONB;
  v_dist_metros       FLOAT := 0;
  v_dlat              FLOAT;
  v_dlon              FLOAT;
  v_a                 FLOAT;
  v_cooldown_ok       BOOLEAN := false;
  v_horario_proibido  BOOLEAN := false;
  v_hora_inicio_str   TEXT;
  v_hora_fim_str      TEXT;
  v_hora_evento_str   TEXT;
  
  -- Variáveis de geofence / áreas seguras
  v_area              RECORD;
  v_dlat_area         FLOAT;
  v_dlon_area         FLOAT;
  v_dist_area_new     FLOAT;
  v_dist_area_old     FLOAT;
  v_chave_cooldown    TEXT;
  v_agora_brt         TIMESTAMP;
  v_hora_atual        TIME;
  v_dow_atual         INT;
  v_area_fora_horario BOOLEAN;
  
  -- Variáveis de payload do alerta
  v_titulo            TEXT;
  v_mensagem          TEXT;
  v_tipo              TEXT;
  v_gravidade         TEXT;
  
  COOLDOWN_PADRAO     INTERVAL := INTERVAL '5 minutes';
  COOLDOWN_IGNICAO    INTERVAL := INTERVAL '1 minute';
BEGIN
  -- Data/hora canônica oficial no fuso horário de Brasília (UTC-3)
  v_agora_brt := now() AT TIME ZONE 'America/Sao_Paulo';
  v_hora_atual := v_agora_brt::TIME;
  v_dow_atual := EXTRACT(DOW FROM v_agora_brt)::INT; -- 0=Domingo ... 6=Sábado
  v_hora_evento_str := to_char(v_agora_brt, 'DD/MM/YYYY às HH24:MI:SS');

  -- 1. Busca o user_id do cliente proprietário do veículo
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = NEW.cliente_id
  LIMIT 1;

  -- 2. Busca parâmetros de regras e preferências ativas do veículo
  SELECT 
    COALESCE(limite_velocidade_geral, 110),
    COALESCE(alerta_movimento_nao_autorizado, true),
    COALESCE(alerta_ignicao_fora_horario, true),
    alertas_ativos
  INTO 
    v_velocidade_limite,
    v_alerta_mov_regras,
    v_alerta_ign_regras,
    v_alertas_ativos
  FROM public.regras_veiculo
  WHERE veiculo_id = NEW.id
  LIMIT 1;

  IF NOT FOUND THEN
    v_velocidade_limite := 110;
    v_alerta_mov_regras := true;
    v_alerta_ign_regras := true;
    v_alertas_ativos := '{"movimento_fora_horario":true,"ignicao_fora_horario":true,"ignicao_ligada":true,"saida_area":true,"entrada_area":true,"excesso_velocidade":true,"perda_comunicacao":true,"baixa_tensao":true,"desvio_rota":true,"guincho":true}'::jsonb;
  END IF;

  -- 3. Cálculo geodésico de deslocamento Haversine em metros entre OLD e NEW
  IF OLD.ultima_latitude IS NOT NULL 
     AND OLD.ultima_longitude IS NOT NULL 
     AND NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL
     AND (OLD.ultima_latitude <> 0 OR OLD.ultima_longitude <> 0)
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0)
     AND (OLD.ultima_latitude <> NEW.ultima_latitude OR OLD.ultima_longitude <> NEW.ultima_longitude) THEN
    
    v_dlat := radians(NEW.ultima_latitude - OLD.ultima_latitude);
    v_dlon := radians(NEW.ultima_longitude - OLD.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(OLD.ultima_latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));
  ELSE
    v_dist_metros := 0;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA A: EXCESSO DE VELOCIDADE
  -- ─────────────────────────────────────────────────────────────────────────
  IF COALESCE(NEW.velocidade_atual, 0) > 0 
     AND COALESCE((v_alertas_ativos->>'excesso_velocidade')::BOOLEAN, true) = true THEN

    IF NEW.velocidade_atual > v_velocidade_limite THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'excesso_velocidade'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('⚠️ Excesso de Velocidade — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s atingiu %s km/h (limite configurado: %s km/h) em %s.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual),
          v_velocidade_limite,
          v_hora_evento_str
        );
        v_tipo      := 'excesso_velocidade';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA B / C: IGNIÇÃO LIGADA (Fora do Horário ou Imediato)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true AND COALESCE(OLD.ignicao_status, false) = false THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido AND v_alerta_ign_regras = true 
       AND COALESCE((v_alertas_ativos->>'ignicao_fora_horario')::BOOLEAN, true) = true THEN
      
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT hora_inicio::TEXT, hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('Ignição Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor acionado fora do horário habitual configurado (%s às %s) em %s. Veículo: %s.',
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          v_hora_evento_str,
          COALESCE(NEW.placa, '')
        );
        v_tipo      := 'ignicao_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;

    ELSIF NOT v_horario_proibido 
          AND COALESCE((v_alertas_ativos->>'ignicao_ligada')::BOOLEAN, true) = true THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_ligada'
            AND ultimo_at > (now() - COOLDOWN_IGNICAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('Ignição Ligada — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format('Motor acionado / chave ligada em %s. Veículo: %s.', v_hora_evento_str, COALESCE(NEW.placa, ''));
        v_tipo      := 'ignicao_ligada';
        v_gravidade := 'baixa';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA D: DESLOCAMENTO FORA DO HORÁRIO (ignição ligada + em movimento real)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true 
     AND (COALESCE(NEW.velocidade_atual, 0) >= 3 OR v_dist_metros >= 15.0)
     AND v_alerta_mov_regras = true
     AND COALESCE((v_alertas_ativos->>'movimento_fora_horario')::BOOLEAN, true) = true THEN

    IF v_horario_proibido OR public.hunter_horario_proibido(NEW.id) THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'movimento_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT hora_inicio::TEXT, hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('🚨 Deslocamento Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s em movimento fora do horário permitido (%s às %s) em %s. Velocidade: %s km/h.',
          COALESCE(NEW.placa, ''),
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          v_hora_evento_str,
          ROUND(NEW.velocidade_atual)
        );
        v_tipo      := 'movimento_fora_horario';
        v_gravidade := 'critica';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA E: MOVIMENTO COM IGNIÇÃO DESLIGADA (GUINCHO / ARRASTO)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = false
     AND COALESCE(OLD.ignicao_status, false) = false
     AND (
       COALESCE(NEW.velocidade_atual, 0) >= 15
       OR (COALESCE(NEW.velocidade_atual, 0) >= 10 AND v_dist_metros >= 35.0)
     )
     AND COALESCE((v_alertas_ativos->>'guincho')::BOOLEAN, true) = true THEN

    SELECT (
      NOT EXISTS (
        SELECT 1 FROM public.alertas_telemetria_cooldown
        WHERE veiculo_id = NEW.id
          AND tipo_alerta = 'guincho'
          AND ultimo_at > (now() - COOLDOWN_PADRAO)
      )
    ) INTO v_cooldown_ok;

    IF v_cooldown_ok THEN
      v_titulo   := format('🚨 Veículo em Movimento com Motor Desligado — %s', COALESCE(NEW.placa, ''));
      v_mensagem := format(
        'Veículo %s detectado a %s km/h com ignição desligada em %s. Possível reboque ou furto em andamento.',
        COALESCE(NEW.placa, ''),
        ROUND(NEW.velocidade_atual),
        v_hora_evento_str
      );
      v_tipo      := 'guincho';
      v_gravidade := 'critica';

      INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
      VALUES (NEW.id, v_tipo, now())
      ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

      INSERT INTO public.alertas_seguranca (
        veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
        velocidade, detalhes, reconhecido, created_at
      ) VALUES (
        NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
        COALESCE(NEW.ultima_latitude, 0),
        COALESCE(NEW.ultima_longitude, 0),
        COALESCE(NEW.velocidade_atual::INT, 0),
        v_mensagem, false, now()
      );

      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id, destinatario_cliente_id,
        titulo, mensagem, tipo, url, placa, lida, created_at
      ) VALUES (
        v_cliente_user_id, NEW.cliente_id,
        v_titulo, v_mensagem, v_tipo, '/monitor-gps',
        COALESCE(NEW.placa, ''), false, now()
      );
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA F: GEOFENCE — SAÍDA E CHEGADA EM ÁREAS PROTEGIDAS / CERCAS VIRTUAIS
  -- Avaliação atômica por coordenada com suporte completo a regras simétricas
  -- de entrada e saída ('alertar', 'fora_horario', 'permitida')
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL 
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0)
     AND OLD.ultima_latitude IS NOT NULL 
     AND OLD.ultima_longitude IS NOT NULL 
     AND (OLD.ultima_latitude <> 0 OR OLD.ultima_longitude <> 0) THEN

    FOR v_area IN
      SELECT id, nome, latitude, longitude, raio_metros, 
             COALESCE(regra_entrada, 'permitida') AS regra_entrada,
             COALESCE(regra_saida, 'permitida') AS regra_saida,
             hora_inicio, hora_fim, dias_semana
      FROM public.areas_seguras
      WHERE (veiculo_id = NEW.id OR (veiculo_id IS NULL AND cliente_id = NEW.cliente_id))
        AND ativo = true
        AND latitude IS NOT NULL
        AND longitude IS NOT NULL
        AND raio_metros > 0
    LOOP
      -- Distância atual do veículo até o centro da cerca (NEW)
      v_dlat_area := radians(NEW.ultima_latitude - v_area.latitude);
      v_dlon_area := radians(NEW.ultima_longitude - v_area.longitude);
      v_a := sin(v_dlat_area / 2.0)^2 + cos(radians(v_area.latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon_area / 2.0)^2;
      v_dist_area_new := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));

      -- Distância anterior do veículo até o centro da cerca (OLD)
      v_dlat_area := radians(OLD.ultima_latitude - v_area.latitude);
      v_dlon_area := radians(OLD.ultima_longitude - v_area.longitude);
      v_a := sin(v_dlat_area / 2.0)^2 + cos(radians(v_area.latitude)) * cos(radians(OLD.ultima_latitude)) * sin(v_dlon_area / 2.0)^2;
      v_dist_area_old := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));

      -- Determina se o momento atual está fora da janela habitual da área
      v_area_fora_horario := false;
      IF v_area.hora_inicio IS NOT NULL AND v_area.hora_fim IS NOT NULL THEN
        IF v_area.dias_semana IS NOT NULL AND NOT (v_dow_atual = ANY(v_area.dias_semana)) THEN
          v_area_fora_horario := true;
        ELSIF v_area.hora_inicio <= v_area.hora_fim THEN
          IF v_hora_atual < v_area.hora_inicio OR v_hora_atual > v_area.hora_fim THEN
            v_area_fora_horario := true;
          END IF;
        ELSE
          -- Janela noturna que passa pela meia-noite (ex: 22:00 até 06:00)
          IF v_hora_atual < v_area.hora_inicio AND v_hora_atual > v_area.hora_fim THEN
            v_area_fora_horario := true;
          END IF;
        END IF;
      END IF;

      -- ───────────────────────────────────────────────────────────────────────
      -- F.1) SAÍDA DE ÁREA PROTEGIDA (estava dentro e agora está fora)
      -- ───────────────────────────────────────────────────────────────────────
      IF v_dist_area_old <= v_area.raio_metros AND v_dist_area_new > v_area.raio_metros THEN
        IF COALESCE((v_alertas_ativos->>'saida_area')::BOOLEAN, true) = true
           AND (
             v_area.regra_saida = 'alertar'
             OR (v_area.regra_saida = 'fora_horario' AND v_area_fora_horario)
           ) THEN
          
          v_chave_cooldown := 'saida_area_' || v_area.id::text;
          SELECT (
            NOT EXISTS (
              SELECT 1 FROM public.alertas_telemetria_cooldown
              WHERE veiculo_id = NEW.id
                AND tipo_alerta = v_chave_cooldown
                AND ultimo_at > (now() - COOLDOWN_PADRAO)
            )
          ) INTO v_cooldown_ok;

          IF v_cooldown_ok THEN
            v_titulo   := format('🚨 Saída de Área Protegida — %s', COALESCE(NEW.placa, ''));
            IF v_area.regra_saida = 'fora_horario' THEN
              v_mensagem := format(
                'Veículo %s saiu da área protegida "%s" FORA do horário habitual em %s (distância: %s m).',
                COALESCE(NEW.placa, ''),
                v_area.nome,
                v_hora_evento_str,
                ROUND(v_dist_area_new)
              );
              v_gravidade := 'alta';
            ELSE
              v_mensagem := format(
                'Veículo %s saiu do limite da cerca virtual "%s" em %s (distância: %s m).',
                COALESCE(NEW.placa, ''),
                v_area.nome,
                v_hora_evento_str,
                ROUND(v_dist_area_new)
              );
              v_gravidade := 'media';
            END IF;

            v_tipo := 'saida_area';

            INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
            VALUES (NEW.id, v_chave_cooldown, now())
            ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

            INSERT INTO public.alertas_seguranca (
              veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
              velocidade, detalhes, reconhecido, created_at
            ) VALUES (
              NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
              COALESCE(NEW.ultima_latitude, 0),
              COALESCE(NEW.ultima_longitude, 0),
              COALESCE(NEW.velocidade_atual::INT, 0),
              v_mensagem, false, now()
            );

            INSERT INTO public.notificacoes_sistema (
              destinatario_user_id, destinatario_cliente_id,
              titulo, mensagem, tipo, url, placa, lida, created_at
            ) VALUES (
              v_cliente_user_id, NEW.cliente_id,
              v_titulo, v_mensagem, v_tipo, '/monitor-gps',
              COALESCE(NEW.placa, ''), false, now()
            );
          END IF;
        END IF;

      -- ───────────────────────────────────────────────────────────────────────
      -- F.2) ENTRADA / CHEGADA EM ÁREA PROTEGIDA (estava fora e agora está dentro)
      -- ───────────────────────────────────────────────────────────────────────
      ELSIF v_dist_area_old > v_area.raio_metros AND v_dist_area_new <= v_area.raio_metros THEN
        IF COALESCE((v_alertas_ativos->>'entrada_area')::BOOLEAN, true) = true
           AND (
             v_area.regra_entrada = 'alertar'
             OR (v_area.regra_entrada = 'fora_horario' AND v_area_fora_horario)
           ) THEN
          
          v_chave_cooldown := 'entrada_area_' || v_area.id::text;
          SELECT (
            NOT EXISTS (
              SELECT 1 FROM public.alertas_telemetria_cooldown
              WHERE veiculo_id = NEW.id
                AND tipo_alerta = v_chave_cooldown
                AND ultimo_at > (now() - COOLDOWN_PADRAO)
            )
          ) INTO v_cooldown_ok;

          IF v_cooldown_ok THEN
            v_titulo := format('✅ Chegada na Área Protegida — %s', COALESCE(NEW.placa, ''));
            IF v_area.regra_entrada = 'fora_horario' THEN
              v_mensagem := format(
                'Veículo %s chegou na área protegida "%s" FORA do horário habitual em %s.',
                COALESCE(NEW.placa, ''),
                v_area.nome,
                v_hora_evento_str
              );
              v_gravidade := 'media';
            ELSE
              v_mensagem := format(
                'Veículo %s chegou na área protegida "%s" em %s.',
                COALESCE(NEW.placa, ''),
                v_area.nome,
                v_hora_evento_str
              );
              v_gravidade := 'baixa';
            END IF;

            v_tipo := 'entrada_area';

            INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
            VALUES (NEW.id, v_chave_cooldown, now())
            ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

            INSERT INTO public.alertas_seguranca (
              veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
              velocidade, detalhes, reconhecido, created_at
            ) VALUES (
              NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
              COALESCE(NEW.ultima_latitude, 0),
              COALESCE(NEW.ultima_longitude, 0),
              COALESCE(NEW.velocidade_atual::INT, 0),
              v_mensagem, false, now()
            );

            INSERT INTO public.notificacoes_sistema (
              destinatario_user_id, destinatario_cliente_id,
              titulo, mensagem, tipo, url, placa, lida, created_at
            ) VALUES (
              v_cliente_user_id, NEW.cliente_id,
              v_titulo, v_mensagem, v_tipo, '/monitor-gps',
              COALESCE(NEW.placa, ''), false, now()
            );
          END IF;
        END IF;
      END IF;

    END LOOP;
  END IF;

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  -- Defesa em profundidade: telemetria nunca é travada por erro de regra
  RAISE WARNING 'trigger_avaliar_alertas_telemetria falhou: %', SQLERRM;
  RETURN NEW;
END;
$$;

NOTIFY pgrst, 'reload schema';




-- ─────────────────────────────────────────────────────────────────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- MIGRATION: 20261019230000_hunter_anti_repeticao_geofence_e_ciclo_vida_nfs.sql
-- Sistema: GD Rastreamento | Diretrizes: HUNTER-GUARDIAN e DJR-NEW
-- Descrição:
-- 1. Máquina de Estados de Presença de Veículo em Áreas Seguras (veiculo_areas_estado)
--    Garante fisicamente ZERO repetição de alertas de saída e entrada.
--    "Enviou uma para, até ocorrer novo evento."
-- 2. Colunas de ciclo de vida e notificações temporais de Notas Fiscais
--    (48h -> 24h -> 6h -> 30m -> expurgo definitivo sem recuperação)
-- 3. Preferência de notificações de NF do cliente com ciência expressa de expurgo
-- 4. Função RPC hunter_processar_ciclo_vida_nfs() para execução periódica
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Tabela de Máquina de Estados para Geofence (Presença DENTRO / FORA)
CREATE TABLE IF NOT EXISTS public.veiculo_areas_estado (
  veiculo_id UUID NOT NULL REFERENCES public.veiculos(id) ON DELETE CASCADE,
  area_id UUID NOT NULL REFERENCES public.areas_seguras(id) ON DELETE CASCADE,
  estado TEXT NOT NULL CHECK (estado IN ('dentro', 'fora')),
  distancia_metros FLOAT NOT NULL DEFAULT 0,
  ultimo_evento_tipo TEXT, -- 'saida' ou 'entrada'
  ultimo_evento_em TIMESTAMPTZ DEFAULT now(),
  notificacao_enviada BOOLEAN DEFAULT false,
  whatsapp_enviado BOOLEAN DEFAULT false,
  updated_at TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (veiculo_id, area_id)
);

CREATE INDEX IF NOT EXISTS idx_veiculo_areas_estado_veiculo 
  ON public.veiculo_areas_estado(veiculo_id);

CREATE INDEX IF NOT EXISTS idx_veiculo_areas_estado_area 
  ON public.veiculo_areas_estado(area_id);

ALTER TABLE public.veiculo_areas_estado ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "veiculo_areas_estado_leitura_autenticada" ON public.veiculo_areas_estado;
CREATE POLICY "veiculo_areas_estado_leitura_autenticada"
  ON public.veiculo_areas_estado
  FOR SELECT
  TO authenticated
  USING (true);

DROP POLICY IF EXISTS "veiculo_areas_estado_service_role" ON public.veiculo_areas_estado;
CREATE POLICY "veiculo_areas_estado_service_role"
  ON public.veiculo_areas_estado
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

GRANT ALL ON public.veiculo_areas_estado TO authenticated, service_role;

-- 2. Inicialização dos estados para veículos e áreas existentes
INSERT INTO public.veiculo_areas_estado (veiculo_id, area_id, estado, distancia_metros, updated_at)
SELECT 
  v.id AS veiculo_id,
  a.id AS area_id,
  CASE 
    WHEN (
      6371000.0 * 2.0 * atan2(
        sqrt(
          sin(radians(COALESCE(v.ultima_latitude, 0) - a.latitude) / 2.0)^2 + 
          cos(radians(a.latitude)) * cos(radians(COALESCE(v.ultima_latitude, 0))) * 
          sin(radians(COALESCE(v.ultima_longitude, 0) - a.longitude) / 2.0)^2
        ),
        sqrt(GREATEST(0.0, 1.0 - (
          sin(radians(COALESCE(v.ultima_latitude, 0) - a.latitude) / 2.0)^2 + 
          cos(radians(a.latitude)) * cos(radians(COALESCE(v.ultima_latitude, 0))) * 
          sin(radians(COALESCE(v.ultima_longitude, 0) - a.longitude) / 2.0)^2
        )))
      )
    ) <= a.raio_metros THEN 'dentro'
    ELSE 'fora'
  END AS estado,
  (
    6371000.0 * 2.0 * atan2(
      sqrt(
        sin(radians(COALESCE(v.ultima_latitude, 0) - a.latitude) / 2.0)^2 + 
        cos(radians(a.latitude)) * cos(radians(COALESCE(v.ultima_latitude, 0))) * 
        sin(radians(COALESCE(v.ultima_longitude, 0) - a.longitude) / 2.0)^2
      ),
      sqrt(GREATEST(0.0, 1.0 - (
        sin(radians(COALESCE(v.ultima_latitude, 0) - a.latitude) / 2.0)^2 + 
        cos(radians(a.latitude)) * cos(radians(COALESCE(v.ultima_latitude, 0))) * 
        sin(radians(COALESCE(v.ultima_longitude, 0) - a.longitude) / 2.0)^2
      )))
    )
  ) AS distancia_metros,
  now() AS updated_at
FROM public.veiculos v
CROSS JOIN public.areas_seguras a
WHERE (a.veiculo_id = v.id OR (a.veiculo_id IS NULL AND a.cliente_id = v.cliente_id))
  AND a.ativo = true
  AND a.latitude IS NOT NULL
  AND a.longitude IS NOT NULL
  AND v.ativo = true
ON CONFLICT (veiculo_id, area_id) DO NOTHING;

-- 3. Atualizar a função atômica trigger_avaliar_alertas_telemetria
CREATE OR REPLACE FUNCTION public.trigger_avaliar_alertas_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente_user_id   UUID;
  v_velocidade_limite INT := 110;
  v_alerta_mov_regras BOOLEAN := true;
  v_alerta_ign_regras BOOLEAN := true;
  v_alertas_ativos    JSONB;
  v_dist_metros       FLOAT := 0;
  v_dlat              FLOAT;
  v_dlon              FLOAT;
  v_a                 FLOAT;
  v_cooldown_ok       BOOLEAN := false;
  v_horario_proibido  BOOLEAN := false;
  v_hora_inicio_str   TEXT;
  v_hora_fim_str      TEXT;
  v_hora_evento_str   TEXT;
  
  -- Variáveis de geofence / áreas seguras
  v_area              RECORD;
  v_dlat_area         FLOAT;
  v_dlon_area         FLOAT;
  v_dist_area_new     FLOAT;
  v_agora_brt         TIMESTAMP;
  v_hora_atual        TIME;
  v_dow_atual         INT;
  v_area_fora_horario BOOLEAN;
  v_estado_anterior   TEXT;
  v_novo_estado       TEXT;
  
  -- Variáveis de payload do alerta
  v_titulo            TEXT;
  v_mensagem          TEXT;
  v_tipo              TEXT;
  v_gravidade         TEXT;
  
  COOLDOWN_PADRAO     INTERVAL := INTERVAL '5 minutes';
BEGIN
  -- Data/hora canônica oficial no fuso horário de Brasília (UTC-3)
  v_agora_brt := now() AT TIME ZONE 'America/Sao_Paulo';
  v_hora_atual := v_agora_brt::TIME;
  v_dow_atual := EXTRACT(DOW FROM v_agora_brt)::INT; -- 0=Domingo ... 6=Sábado
  v_hora_evento_str := to_char(v_agora_brt, 'DD/MM/YYYY às HH24:MI:SS');

  -- 1. Busca o user_id do cliente proprietário do veículo
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = NEW.cliente_id
  LIMIT 1;

  -- 2. Busca parâmetros de regras e preferências ativas do veículo
  SELECT 
    COALESCE(limite_velocidade_geral, 110),
    COALESCE(alerta_movimento_nao_autorizado, true),
    COALESCE(alerta_ignicao_fora_horario, true),
    alertas_ativos
  INTO 
    v_velocidade_limite,
    v_alerta_mov_regras,
    v_alerta_ign_regras,
    v_alertas_ativos
  FROM public.regras_veiculo
  WHERE veiculo_id = NEW.id
  LIMIT 1;

  IF NOT FOUND THEN
    v_velocidade_limite := 110;
    v_alerta_mov_regras := true;
    v_alerta_ign_regras := true;
    v_alertas_ativos := '{"movimento_fora_horario":true,"ignicao_fora_horario":true,"ignicao_ligada":true,"saida_area":true,"entrada_area":true,"excesso_velocidade":true,"perda_comunicacao":true,"baixa_tensao":true,"desvio_rota":true,"guincho":true}'::jsonb;
  END IF;

  -- 3. Cálculo geodésico de deslocamento Haversine em metros entre OLD e NEW
  IF OLD.ultima_latitude IS NOT NULL 
     AND OLD.ultima_longitude IS NOT NULL 
     AND NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL
     AND (OLD.ultima_latitude <> 0 OR OLD.ultima_longitude <> 0)
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0)
     AND (OLD.ultima_latitude <> NEW.ultima_latitude OR OLD.ultima_longitude <> NEW.ultima_longitude) THEN
    
    v_dlat := radians(NEW.ultima_latitude - OLD.ultima_latitude);
    v_dlon := radians(NEW.ultima_longitude - OLD.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(OLD.ultima_latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));
  ELSE
    v_dist_metros := 0;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA A: EXCESSO DE VELOCIDADE
  -- ─────────────────────────────────────────────────────────────────────────
  IF COALESCE(NEW.velocidade_atual, 0) > 0 
     AND COALESCE((v_alertas_ativos->>'excesso_velocidade')::BOOLEAN, true) = true THEN

    IF NEW.velocidade_atual > v_velocidade_limite THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'excesso_velocidade'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('⚠️ Excesso de Velocidade — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s atingiu %s km/h (limite configurado: %s km/h) em %s.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual),
          v_velocidade_limite,
          v_hora_evento_str
        );
        v_tipo      := 'excesso_velocidade';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA B: IGNIÇÃO LIGADA (Fora do Horário)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true AND COALESCE(OLD.ignicao_status, false) = false THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido AND v_alerta_ign_regras = true 
       AND COALESCE((v_alertas_ativos->>'ignicao_fora_horario')::BOOLEAN, true) = true THEN
      
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT hora_inicio::TEXT, hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('Ignição Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor acionado fora do horário habitual configurado (%s às %s) em %s. Veículo: %s.',
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          v_hora_evento_str,
          COALESCE(NEW.placa, '')
        );
        v_tipo      := 'ignicao_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA D: DESLOCAMENTO FORA DO HORÁRIO
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true 
     AND (COALESCE(NEW.velocidade_atual, 0) >= 3 OR v_dist_metros >= 15.0)
     AND v_alerta_mov_regras = true
     AND COALESCE((v_alertas_ativos->>'movimento_fora_horario')::BOOLEAN, true) = true THEN

    IF v_horario_proibido OR public.hunter_horario_proibido(NEW.id) THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'movimento_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT hora_inicio::TEXT, hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('🚨 Deslocamento Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s em movimento fora do horário permitido (%s às %s) em %s. Velocidade: %s km/h.',
          COALESCE(NEW.placa, ''),
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          v_hora_evento_str,
          ROUND(NEW.velocidade_atual)
        );
        v_tipo      := 'movimento_fora_horario';
        v_gravidade := 'critica';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA E: GUINCHO / ARRASTO
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = false
     AND COALESCE(OLD.ignicao_status, false) = false
     AND (
       COALESCE(NEW.velocidade_atual, 0) >= 15
       OR (COALESCE(NEW.velocidade_atual, 0) >= 10 AND v_dist_metros >= 35.0)
     )
     AND COALESCE((v_alertas_ativos->>'guincho')::BOOLEAN, true) = true THEN

    SELECT (
      NOT EXISTS (
        SELECT 1 FROM public.alertas_telemetria_cooldown
        WHERE veiculo_id = NEW.id
          AND tipo_alerta = 'guincho'
          AND ultimo_at > (now() - COOLDOWN_PADRAO)
      )
    ) INTO v_cooldown_ok;

    IF v_cooldown_ok THEN
      v_titulo   := format('🚨 Veículo em Movimento com Motor Desligado — %s', COALESCE(NEW.placa, ''));
      v_mensagem := format(
        'Veículo %s detectado a %s km/h com ignição desligada em %s. Possível reboque ou furto em andamento.',
        COALESCE(NEW.placa, ''),
        ROUND(NEW.velocidade_atual),
        v_hora_evento_str
      );
      v_tipo      := 'guincho';
      v_gravidade := 'critica';

      INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
      VALUES (NEW.id, v_tipo, now())
      ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

      INSERT INTO public.alertas_seguranca (
        veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
        velocidade, detalhes, reconhecido, created_at
      ) VALUES (
        NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
        COALESCE(NEW.ultima_latitude, 0),
        COALESCE(NEW.ultima_longitude, 0),
        COALESCE(NEW.velocidade_atual::INT, 0),
        v_mensagem, false, now()
      );

      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id, destinatario_cliente_id,
        titulo, mensagem, tipo, url, placa, lida, created_at
      ) VALUES (
        v_cliente_user_id, NEW.cliente_id,
        v_titulo, v_mensagem, v_tipo, '/monitor-gps',
        COALESCE(NEW.placa, ''), false, now()
      );
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA F: GEOFENCE COM MÁQUINA DE ESTADOS FÍSICA (ZERO REPETIÇÃO)
  -- Regra Pétrea: "Enviou uma para, até ocorrer novo evento."
  -- Só dispara saída se estado_anterior = 'dentro' E dist > raio + 15m (histerese).
  -- Transita para 'fora' e NUNCA MAIS repete saída enquanto permanecer 'fora'.
  -- Só dispara entrada se estado_anterior = 'fora' E dist <= raio.
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL 
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0) THEN

    FOR v_area IN
      SELECT id, nome, latitude, longitude, raio_metros, 
             COALESCE(regra_entrada, 'permitida') AS regra_entrada,
             COALESCE(regra_saida, 'permitida') AS regra_saida,
             hora_inicio, hora_fim, dias_semana
      FROM public.areas_seguras
      WHERE (veiculo_id = NEW.id OR (veiculo_id IS NULL AND cliente_id = NEW.cliente_id))
        AND ativo = true
        AND latitude IS NOT NULL
        AND longitude IS NOT NULL
        AND raio_metros > 0
    LOOP
      -- Distância geodésica do veículo até o centro da cerca virtual
      v_dlat_area := radians(NEW.ultima_latitude - v_area.latitude);
      v_dlon_area := radians(NEW.ultima_longitude - v_area.longitude);
      v_a := sin(v_dlat_area / 2.0)^2 + cos(radians(v_area.latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon_area / 2.0)^2;
      v_dist_area_new := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));

      -- Determina se o momento atual está fora da janela habitual da área
      v_area_fora_horario := false;
      IF v_area.hora_inicio IS NOT NULL AND v_area.hora_fim IS NOT NULL THEN
        IF v_area.dias_semana IS NOT NULL AND NOT (v_dow_atual = ANY(v_area.dias_semana)) THEN
          v_area_fora_horario := true;
        ELSIF v_area.hora_inicio <= v_area.hora_fim THEN
          IF v_hora_atual < v_area.hora_inicio OR v_hora_atual > v_area.hora_fim THEN
            v_area_fora_horario := true;
          END IF;
        ELSE
          IF v_hora_atual < v_area.hora_inicio AND v_hora_atual > v_area.hora_fim THEN
            v_area_fora_horario := true;
          END IF;
        END IF;
      END IF;

      -- Consulta estado persistente na máquina de estados
      SELECT estado INTO v_estado_anterior
      FROM public.veiculo_areas_estado
      WHERE veiculo_id = NEW.id AND area_id = v_area.id;

      -- Se não existir registro prévio, inicializa de forma neutra sem disparo
      IF v_estado_anterior IS NULL THEN
        IF v_dist_area_new <= v_area.raio_metros THEN
          v_estado_anterior := 'dentro';
        ELSE
          v_estado_anterior := 'fora';
        END IF;

        INSERT INTO public.veiculo_areas_estado (
          veiculo_id, area_id, estado, distancia_metros, updated_at
        ) VALUES (
          NEW.id, v_area.id, v_estado_anterior, v_dist_area_new, now()
        ) ON CONFLICT (veiculo_id, area_id) DO NOTHING;
      END IF;

      -- ───────────────────────────────────────────────────────────────────────
      -- F.1) TRANSIÇÃO PARA SAÍDA: DE 'dentro' PARA 'fora'
      -- Histerese de segurança: requer dist > raio_metros + 15m para não oscilar na borda
      -- ───────────────────────────────────────────────────────────────────────
      IF v_estado_anterior = 'dentro' AND v_dist_area_new > (v_area.raio_metros + 15.0) THEN
        -- Atualiza imediatamente o estado na máquina para 'fora' (bloqueia repetições)
        UPDATE public.veiculo_areas_estado
        SET estado = 'fora',
            distancia_metros = v_dist_area_new,
            ultimo_evento_tipo = 'saida',
            ultimo_evento_em = now(),
            notificacao_enviada = true,
            whatsapp_enviado = false,
            updated_at = now()
        WHERE veiculo_id = NEW.id AND area_id = v_area.id;

        -- Avalia se deve emitir o alerta único de saída
        IF COALESCE((v_alertas_ativos->>'saida_area')::BOOLEAN, true) = true
           AND (
             v_area.regra_saida = 'alertar'
             OR (v_area.regra_saida = 'fora_horario' AND v_area_fora_horario)
           ) THEN

          v_titulo := format('🚨 Saída de Área Protegida — %s', COALESCE(NEW.placa, ''));
          IF v_area.regra_saida = 'fora_horario' THEN
            v_mensagem := format(
              'Veículo %s saiu da área protegida "%s" FORA do horário habitual em %s (distância: %s m).',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_hora_evento_str,
              ROUND(v_dist_area_new)
            );
            v_gravidade := 'alta';
          ELSE
            v_mensagem := format(
              'Veículo %s saiu do limite da cerca virtual "%s" em %s (distância: %s m).',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_hora_evento_str,
              ROUND(v_dist_area_new)
            );
            v_gravidade := 'media';
          END IF;

          v_tipo := 'saida_area';

          INSERT INTO public.alertas_seguranca (
            veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
            velocidade, detalhes, reconhecido, created_at
          ) VALUES (
            NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
            COALESCE(NEW.ultima_latitude, 0),
            COALESCE(NEW.ultima_longitude, 0),
            COALESCE(NEW.velocidade_atual::INT, 0),
            v_mensagem, false, now()
          );

          INSERT INTO public.notificacoes_sistema (
            destinatario_user_id, destinatario_cliente_id,
            titulo, mensagem, tipo, url, placa, lida, created_at
          ) VALUES (
            v_cliente_user_id, NEW.cliente_id,
            v_titulo, v_mensagem, v_tipo, '/monitor-gps',
            COALESCE(NEW.placa, ''), false, now()
          );
        END IF;

      -- ───────────────────────────────────────────────────────────────────────
      -- F.2) TRANSIÇÃO PARA ENTRADA: DE 'fora' PARA 'dentro'
      -- ───────────────────────────────────────────────────────────────────────
      ELSIF v_estado_anterior = 'fora' AND v_dist_area_new <= v_area.raio_metros THEN
        -- Atualiza imediatamente o estado na máquina para 'dentro' (bloqueia repetições)
        UPDATE public.veiculo_areas_estado
        SET estado = 'dentro',
            distancia_metros = v_dist_area_new,
            ultimo_evento_tipo = 'entrada',
            ultimo_evento_em = now(),
            notificacao_enviada = true,
            whatsapp_enviado = false,
            updated_at = now()
        WHERE veiculo_id = NEW.id AND area_id = v_area.id;

        -- Avalia se deve emitir o alerta único de entrada
        IF COALESCE((v_alertas_ativos->>'entrada_area')::BOOLEAN, true) = true
           AND (
             v_area.regra_entrada = 'alertar'
             OR (v_area.regra_entrada = 'fora_horario' AND v_area_fora_horario)
           ) THEN

          v_titulo := format('✅ Chegada em Área Protegida — %s', COALESCE(NEW.placa, ''));
          IF v_area.regra_entrada = 'fora_horario' THEN
            v_mensagem := format(
              'Veículo %s entrou na área protegida "%s" FORA do horário habitual em %s.',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_hora_evento_str
            );
            v_gravidade := 'alta';
          ELSE
            v_mensagem := format(
              'Veículo %s entrou na cerca virtual "%s" em %s.',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_hora_evento_str
            );
            v_gravidade := 'baixa';
          END IF;

          v_tipo := 'entrada_area';

          INSERT INTO public.alertas_seguranca (
            veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
            velocidade, detalhes, reconhecido, created_at
          ) VALUES (
            NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
            COALESCE(NEW.ultima_latitude, 0),
            COALESCE(NEW.ultima_longitude, 0),
            COALESCE(NEW.velocidade_atual::INT, 0),
            v_mensagem, false, now()
          );

          INSERT INTO public.notificacoes_sistema (
            destinatario_user_id, destinatario_cliente_id,
            titulo, mensagem, tipo, url, placa, lida, created_at
          ) VALUES (
            v_cliente_user_id, NEW.cliente_id,
            v_titulo, v_mensagem, v_tipo, '/monitor-gps',
            COALESCE(NEW.placa, ''), false, now()
          );
        END IF;

      ELSE
        -- Mantém a distância atualizada na máquina de estados sem transição
        UPDATE public.veiculo_areas_estado
        SET distancia_metros = v_dist_area_new,
            updated_at = now()
        WHERE veiculo_id = NEW.id AND area_id = v_area.id;
      END IF;

    END LOOP;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trigger_avaliar_alertas_telemetria falhou: %', SQLERRM;
  RETURN NEW;
END;
$$;

-- 4. Colunas de Notificações e Ciclo de Vida Temporal de Notas Fiscais
ALTER TABLE public.motorista_abastecimentos
  ADD COLUMN IF NOT EXISTS nf_alerta_pronta_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS nf_alerta_24h_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS nf_alerta_6h_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS nf_alerta_30m_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS nf_expirado_em TIMESTAMPTZ;

ALTER TABLE public.motorista_despesas
  ADD COLUMN IF NOT EXISTS nf_alerta_pronta_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS nf_alerta_24h_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS nf_alerta_6h_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS nf_alerta_30m_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS nf_expirado_em TIMESTAMPTZ;

ALTER TABLE public.clientes
  ADD COLUMN IF NOT EXISTS notificar_nf_pendente BOOLEAN DEFAULT true,
  ADD COLUMN IF NOT EXISTS ciencia_expurgo_sem_notificacao_nf BOOLEAN DEFAULT false,
  ADD COLUMN IF NOT EXISTS ciencia_expurgo_em TIMESTAMPTZ;

-- Índices parciais de altíssima performance para consultas de NFs pendentes (Zero Abuso de Egress)
CREATE INDEX IF NOT EXISTS idx_abastecimentos_nf_pendente
  ON public.motorista_abastecimentos(nf_upload_em)
  WHERE nf_foto_url IS NOT NULL AND nf_baixado = false AND nf_expirado = false;

CREATE INDEX IF NOT EXISTS idx_despesas_nf_pendente
  ON public.motorista_despesas(nf_upload_em)
  WHERE nf_foto_url IS NOT NULL AND nf_baixado = false AND nf_expirado = false;

-- 5. Função RPC atômica para processamento temporal do ciclo de vida das NFs
CREATE OR REPLACE FUNCTION public.hunter_processar_ciclo_vida_nfs()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_rec RECORD;
  v_agora TIMESTAMPTZ := now();
  v_cliente RECORD;
  v_horas_passadas FLOAT;
  v_alertas_enviados INT := 0;
  v_expurgadas INT := 0;
  v_titulo TEXT;
  v_msg TEXT;
BEGIN
  -- A) Processa NFs de Abastecimentos pendentes de download
  FOR v_rec IN
    SELECT a.id, a.veiculo_id, a.nf_foto_url, a.nf_numero, a.nf_upload_em,
           a.nf_alerta_pronta_em, a.nf_alerta_24h_em, a.nf_alerta_6h_em, a.nf_alerta_30m_em,
           v.placa, v.cliente_id,
           COALESCE(c.notificar_nf_pendente, true) AS notificar,
           c.user_id AS cliente_user_id
    FROM public.motorista_abastecimentos a
    JOIN public.veiculos v ON v.id = a.veiculo_id
    LEFT JOIN public.clientes c ON c.id = v.cliente_id
    WHERE a.nf_foto_url IS NOT NULL
      AND a.nf_baixado = false
      AND a.nf_expirado = false
      AND a.nf_upload_em IS NOT NULL
  LOOP
    v_horas_passadas := EXTRACT(EPOCH FROM (v_agora - v_rec.nf_upload_em)) / 3600.0;

    -- Se o cliente desativou notificações de NF
    IF v_rec.notificar = false THEN
      -- Se passou de 48h sem download, expurga diretamente
      IF v_horas_passadas >= 48.0 THEN
        UPDATE public.motorista_abastecimentos
        SET nf_expirado = true,
            nf_expirado_em = v_agora,
            nf_foto_url = NULL
        WHERE id = v_rec.id;
        v_expurgadas := v_expurgadas + 1;
      END IF;
    ELSE
      -- Cliente com notificações ativas:
      -- Estágio 4: Expurgo definitivo aos 78.5h (48h + 24h + 6h + 30m)
      IF v_horas_passadas >= 78.5 THEN
        UPDATE public.motorista_abastecimentos
        SET nf_expirado = true,
            nf_expirado_em = v_agora,
            nf_foto_url = NULL
        WHERE id = v_rec.id;
        v_expurgadas := v_expurgadas + 1;

      -- Estágio 3: Alerta de exclusão em 30min (passados 78h)
      ELSIF v_horas_passadas >= 78.0 AND v_rec.nf_alerta_30m_em IS NULL THEN
        v_titulo := format('⚠️ Último Aviso: Exclusão de NF em 30 min — %s', COALESCE(v_rec.placa, ''));
        v_msg := format('A Nota Fiscal vinculada ao veículo %s será excluída definitivamente em 30 minutos por ausência de download.', COALESCE(v_rec.placa, ''));
        
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_rec.cliente_user_id, v_rec.cliente_id,
          v_titulo, v_msg, 'alerta_nf_expurgo_30m', '/motoristas',
          COALESCE(v_rec.placa, ''), false, now()
        );

        UPDATE public.motorista_abastecimentos
        SET nf_alerta_30m_em = v_agora
        WHERE id = v_rec.id;
        v_alertas_enviados := v_alertas_enviados + 1;

      -- Estágio 2: Alerta de exclusão em 6h (passados 72h)
      ELSIF v_horas_passadas >= 72.0 AND v_rec.nf_alerta_6h_em IS NULL THEN
        v_titulo := format('⏰ Alerta: Exclusão de NF em 6 horas — %s', COALESCE(v_rec.placa, ''));
        v_msg := format('A Nota Fiscal vinculada ao veículo %s não foi baixada e será excluída do sistema em 6 horas.', COALESCE(v_rec.placa, ''));
        
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_rec.cliente_user_id, v_rec.cliente_id,
          v_titulo, v_msg, 'alerta_nf_expurgo_6h', '/motoristas',
          COALESCE(v_rec.placa, ''), false, now()
        );

        UPDATE public.motorista_abastecimentos
        SET nf_alerta_6h_em = v_agora
        WHERE id = v_rec.id;
        v_alertas_enviados := v_alertas_enviados + 1;

      -- Estágio 1: Alerta de exclusão em 24h (passadas 48h sem download)
      ELSIF v_horas_passadas >= 48.0 AND v_rec.nf_alerta_24h_em IS NULL THEN
        v_titulo := format('📄 Alerta: Exclusão de NF em 24 horas — %s', COALESCE(v_rec.placa, ''));
        v_msg := format('O prazo inicial de 48h para download da Nota Fiscal do veículo %s expirou. Restam 24h antes da exclusão permanente.', COALESCE(v_rec.placa, ''));
        
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_rec.cliente_user_id, v_rec.cliente_id,
          v_titulo, v_msg, 'alerta_nf_expurgo_24h', '/motoristas',
          COALESCE(v_rec.placa, ''), false, now()
        );

        UPDATE public.motorista_abastecimentos
        SET nf_alerta_24h_em = v_agora
        WHERE id = v_rec.id;
        v_alertas_enviados := v_alertas_enviados + 1;
      END IF;
    END IF;
  END LOOP;

  -- B) Processa NFs de Despesas pendentes de download
  FOR v_rec IN
    SELECT d.id, d.veiculo_id, d.nf_foto_url, d.nf_numero, d.nf_upload_em,
           d.nf_alerta_pronta_em, d.nf_alerta_24h_em, d.nf_alerta_6h_em, d.nf_alerta_30m_em,
           v.placa, v.cliente_id,
           COALESCE(c.notificar_nf_pendente, true) AS notificar,
           c.user_id AS cliente_user_id
    FROM public.motorista_despesas d
    JOIN public.veiculos v ON v.id = d.veiculo_id
    LEFT JOIN public.clientes c ON c.id = v.cliente_id
    WHERE d.nf_foto_url IS NOT NULL
      AND d.nf_baixado = false
      AND d.nf_expirado = false
      AND d.nf_upload_em IS NOT NULL
  LOOP
    v_horas_passadas := EXTRACT(EPOCH FROM (v_agora - v_rec.nf_upload_em)) / 3600.0;

    IF v_rec.notificar = false THEN
      IF v_horas_passadas >= 48.0 THEN
        UPDATE public.motorista_despesas
        SET nf_expirado = true,
            nf_expirado_em = v_agora,
            nf_foto_url = NULL
        WHERE id = v_rec.id;
        v_expurgadas := v_expurgadas + 1;
      END IF;
    ELSE
      IF v_horas_passadas >= 78.5 THEN
        UPDATE public.motorista_despesas
        SET nf_expirado = true,
            nf_expirado_em = v_agora,
            nf_foto_url = NULL
        WHERE id = v_rec.id;
        v_expurgadas := v_expurgadas + 1;

      ELSIF v_horas_passadas >= 78.0 AND v_rec.nf_alerta_30m_em IS NULL THEN
        v_titulo := format('⚠️ Último Aviso: Exclusão de NF em 30 min — %s', COALESCE(v_rec.placa, ''));
        v_msg := format('A Nota Fiscal de despesa vinculada ao veículo %s será excluída definitivamente em 30 minutos por ausência de download.', COALESCE(v_rec.placa, ''));
        
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_rec.cliente_user_id, v_rec.cliente_id,
          v_titulo, v_msg, 'alerta_nf_expurgo_30m', '/motoristas',
          COALESCE(v_rec.placa, ''), false, now()
        );

        UPDATE public.motorista_despesas
        SET nf_alerta_30m_em = v_agora
        WHERE id = v_rec.id;
        v_alertas_enviados := v_alertas_enviados + 1;

      ELSIF v_horas_passadas >= 72.0 AND v_rec.nf_alerta_6h_em IS NULL THEN
        v_titulo := format('⏰ Alerta: Exclusão de NF em 6 horas — %s', COALESCE(v_rec.placa, ''));
        v_msg := format('A Nota Fiscal de despesa vinculada ao veículo %s não foi baixada e será excluída do sistema em 6 horas.', COALESCE(v_rec.placa, ''));
        
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_rec.cliente_user_id, v_rec.cliente_id,
          v_titulo, v_msg, 'alerta_nf_expurgo_6h', '/motoristas',
          COALESCE(v_rec.placa, ''), false, now()
        );

        UPDATE public.motorista_despesas
        SET nf_alerta_6h_em = v_agora
        WHERE id = v_rec.id;
        v_alertas_enviados := v_alertas_enviados + 1;

      ELSIF v_horas_passadas >= 48.0 AND v_rec.nf_alerta_24h_em IS NULL THEN
        v_titulo := format('📄 Alerta: Exclusão de NF em 24 horas — %s', COALESCE(v_rec.placa, ''));
        v_msg := format('O prazo inicial de 48h para download da Nota Fiscal de despesa do veículo %s expirou. Restam 24h antes da exclusão permanente.', COALESCE(v_rec.placa, ''));
        
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_rec.cliente_user_id, v_rec.cliente_id,
          v_titulo, v_msg, 'alerta_nf_expurgo_24h', '/motoristas',
          COALESCE(v_rec.placa, ''), false, now()
        );

        UPDATE public.motorista_despesas
        SET nf_alerta_24h_em = v_agora
        WHERE id = v_rec.id;
        v_alertas_enviados := v_alertas_enviados + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'sucesso', true,
    'alertas_enviados', v_alertas_enviados,
    'expurgadas', v_expurgadas,
    'processado_em', v_agora
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.hunter_processar_ciclo_vida_nfs() TO authenticated, service_role;

-- ═════════════════════════════════════════════════════════════════════════════
-- FIX LOGIN MOTORISTAS & OUTRAS TABELAS (Erro "Database error querying schema")
-- E ATUALIZAÇÃO DA LÓGICA DE ALERTAS (CICLO DE IGNIÇÃO E GEOFENCE ESTRITA)
-- ═════════════════════════════════════════════════════════════════════════════

-- 1. Saneamento de todas as contas já existentes em auth.users (ex: fafa@dario.local)
UPDATE auth.users 
SET 
  confirmation_token = COALESCE(confirmation_token, ''),
  recovery_token = COALESCE(recovery_token, ''),
  email_change_token_new = COALESCE(email_change_token_new, ''),
  email_change = COALESCE(email_change, ''),
  email_change_token_current = COALESCE(email_change_token_current, ''),
  phone_change = COALESCE(phone_change, ''),
  phone_change_token = COALESCE(phone_change_token, ''),
  reauthentication_token = COALESCE(reauthentication_token, '')
WHERE 
  confirmation_token IS NULL
  OR recovery_token IS NULL
  OR email_change_token_new IS NULL
  OR email_change IS NULL
  OR email_change_token_current IS NULL
  OR phone_change IS NULL
  OR phone_change_token IS NULL
  OR reauthentication_token IS NULL;

-- 2. Trigger global BEFORE INSERT OR UPDATE ON auth.users para imunização perpétua
DO $$
BEGIN
  CREATE OR REPLACE FUNCTION auth.trg_sanitizar_auth_users_nulls()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $fn$
  BEGIN
    NEW.confirmation_token := COALESCE(NEW.confirmation_token, '');
    NEW.recovery_token := COALESCE(NEW.recovery_token, '');
    NEW.email_change_token_new := COALESCE(NEW.email_change_token_new, '');
    NEW.email_change := COALESCE(NEW.email_change, '');
    NEW.email_change_token_current := COALESCE(NEW.email_change_token_current, '');
    NEW.phone_change := COALESCE(NEW.phone_change, '');
    NEW.phone_change_token := COALESCE(NEW.phone_change_token, '');
    NEW.reauthentication_token := COALESCE(NEW.reauthentication_token, '');
    
    IF NEW.raw_app_meta_data IS NULL THEN
      NEW.raw_app_meta_data := '{"provider":"email","providers":["email"]}'::jsonb;
    END IF;

    IF NEW.aud IS NULL OR trim(NEW.aud) = '' THEN
      NEW.aud := 'authenticated';
    END IF;

    IF NEW.role IS NULL OR trim(NEW.role) = '' THEN
      NEW.role := 'authenticated';
    END IF;

    RETURN NEW;
  END;
  $fn$;

  DROP TRIGGER IF EXISTS trg_auth_users_sanitizar_nulls ON auth.users;
  CREATE TRIGGER trg_auth_users_sanitizar_nulls
    BEFORE INSERT OR UPDATE ON auth.users
    FOR EACH ROW EXECUTE FUNCTION auth.trg_sanitizar_auth_users_nulls();
EXCEPTION WHEN OTHERS THEN
  -- Em ambientes Supabase onde DDL no schema auth é restrito a superuser, prossegue sem erro
  NULL;
END $$;

-- 3. Recriar a função canônica public.cadastrar_motorista com padrão estrito GoTrue
CREATE OR REPLACE FUNCTION public.cadastrar_motorista(
  p_cliente_id      UUID,
  p_nome            TEXT,
  p_email           TEXT,
  p_senha           TEXT,
  p_cpf             TEXT          DEFAULT NULL,
  p_telefone        TEXT          DEFAULT NULL,
  p_data_nascimento DATE          DEFAULT NULL,
  p_cnh_numero      TEXT          DEFAULT NULL,
  p_cnh_categoria   TEXT          DEFAULT NULL,
  p_cnh_validade    DATE          DEFAULT NULL,
  p_cnh_primeira    DATE          DEFAULT NULL,
  p_cnh_renach      TEXT          DEFAULT NULL,
  p_cnh_observacoes TEXT          DEFAULT NULL,
  p_cnh_foto_url    TEXT          DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = extensions, public, auth, pg_temp
AS $$
DECLARE
  v_caller_id   UUID := auth.uid();
  v_user_id     UUID;
  v_motorista   UUID;
  v_enc_pw      TEXT;
  v_email_limpo TEXT;
  v_nome_limpo  TEXT;
BEGIN
  v_email_limpo := LOWER(TRIM(p_email));
  v_nome_limpo  := TRIM(p_nome);

  -- 1. Verificar autorização do chamador (dono do cliente ou adm/superadm)
  IF NOT EXISTS (
    SELECT 1 FROM public.clientes WHERE id = p_cliente_id AND user_id = v_caller_id
  ) AND NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_caller_id AND role IN ('superadmin','adm')
  ) THEN
    RAISE EXCEPTION 'Acesso negado: cliente nao autorizado.';
  END IF;

  -- 2. Validações básicas
  IF v_nome_limpo IS NULL OR v_nome_limpo = '' THEN
    RAISE EXCEPTION 'Nome do motorista e obrigatorio.';
  END IF;
  IF v_email_limpo IS NULL OR v_email_limpo = '' THEN
    RAISE EXCEPTION 'E-mail do motorista e obrigatorio.';
  END IF;
  IF p_senha IS NULL OR length(p_senha) < 6 THEN
    RAISE EXCEPTION 'Senha deve ter no minimo 6 caracteres.';
  END IF;
  IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_limpo) THEN
    RAISE EXCEPTION 'Ja existe um usuario com este e-mail.';
  END IF;

  -- 3. Criar usuário no auth com senha criptografada via pgcrypto e todas as colunas do GoTrue preenchidas
  v_user_id := gen_random_uuid();
  v_enc_pw  := extensions.crypt(p_senha, extensions.gen_salt('bf', 10));

  INSERT INTO auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, recovery_sent_at, last_sign_in_at,
    raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token
  ) VALUES (
    v_user_id,
    '00000000-0000-0000-0000-000000000000',
    'authenticated',
    'authenticated',
    v_email_limpo,
    v_enc_pw,
    now(), now(), now(),
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('nome', v_nome_limpo, 'role', 'motorista', 'cliente_id', p_cliente_id),
    now(), now(),
    '', '', '', '', '', '', '', ''
  );

  -- 4. Criar identity canônica para login por e-mail no GoTrue
  IF NOT EXISTS (
    SELECT 1 FROM auth.identities 
    WHERE (provider = 'email' AND provider_id = v_user_id::text)
       OR user_id = v_user_id
  ) THEN
    BEGIN
      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id,
        last_sign_in_at, created_at, updated_at
      ) VALUES (
        v_user_id::text,
        v_user_id,
        jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
        'email',
        v_user_id::text,
        now(), now(), now()
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  -- 5. Criar profile com role motorista
  INSERT INTO public.profiles (
    id, nome, email, role, ativo, primeiro_acesso, cliente_id, telefone
  ) VALUES (
    v_user_id,
    v_nome_limpo,
    v_email_limpo,
    'motorista'::public.hunter_role,
    true,
    false,
    p_cliente_id,
    p_telefone
  )
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      email = EXCLUDED.email,
      role = 'motorista'::public.hunter_role,
      ativo = true,
      cliente_id = EXCLUDED.cliente_id,
      telefone = EXCLUDED.telefone;

  -- 6. Criar vínculo em user_roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_user_id, 'motorista'::public.hunter_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  -- 7. Criar registro do motorista
  INSERT INTO public.motoristas (
    cliente_id, user_id, nome, email, cpf, telefone, data_nascimento,
    cnh_numero, cnh_categoria, cnh_validade, cnh_primeira_habilitacao,
    cnh_renach, cnh_observacoes, cnh_foto_url, acesso_mapa, ativo
  ) VALUES (
    p_cliente_id,
    v_user_id,
    v_nome_limpo,
    v_email_limpo,
    NULLIF(trim(COALESCE(p_cpf, '')), ''),
    NULLIF(trim(COALESCE(p_telefone, '')), ''),
    p_data_nascimento,
    NULLIF(trim(COALESCE(p_cnh_numero, '')), ''),
    NULLIF(trim(COALESCE(p_cnh_categoria, '')), ''),
    p_cnh_validade,
    p_cnh_primeira,
    NULLIF(trim(COALESCE(p_cnh_renach, '')), ''),
    NULLIF(trim(COALESCE(p_cnh_observacoes, '')), ''),
    NULLIF(trim(COALESCE(p_cnh_foto_url, '')), ''),
    false,
    true
  ) RETURNING id INTO v_motorista;

  RETURN jsonb_build_object(
    'motorista_id', v_motorista,
    'user_id',      v_user_id
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION '[HUNTER-MOTORISTA] Erro ao cadastrar motorista: %', SQLERRM;
END;
$$;

GRANT EXECUTE ON FUNCTION public.cadastrar_motorista(
  UUID, TEXT, TEXT, TEXT, TEXT, TEXT, DATE, TEXT, TEXT, DATE, DATE, TEXT, TEXT, TEXT
) TO authenticated, service_role;

-- 4. Recriar public.trigger_avaliar_alertas_telemetria
CREATE OR REPLACE FUNCTION public.trigger_avaliar_alertas_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente_user_id   UUID;
  v_velocidade_limite INT := 110;
  v_alerta_mov_regras BOOLEAN := true;
  v_alerta_ign_regras BOOLEAN := true;
  v_alertas_ativos    JSONB;
  v_dist_metros       FLOAT := 0;
  v_dlat              FLOAT;
  v_dlon              FLOAT;
  v_a                 FLOAT;
  v_cooldown_ok       BOOLEAN := false;
  v_horario_proibido  BOOLEAN := false;
  v_hora_inicio_str   TEXT;
  v_hora_fim_str      TEXT;
  v_hora_evento_str   TEXT;
  
  -- Variáveis de geofence / áreas seguras
  v_area              RECORD;
  v_dlat_area         FLOAT;
  v_dlon_area         FLOAT;
  v_dist_area_new     FLOAT;
  v_agora_brt         TIMESTAMP;
  v_hora_atual        TIME;
  v_dow_atual         INT;
  v_area_fora_horario BOOLEAN;
  v_estado_anterior   TEXT;
  v_tolerancia        FLOAT;
  v_raio_saida        FLOAT;
  v_raio_entrada      FLOAT;
  
  -- Variáveis de payload do alerta
  v_titulo            TEXT;
  v_mensagem          TEXT;
  v_tipo              TEXT;
  v_gravidade         TEXT;
  
  COOLDOWN_PADRAO     INTERVAL := INTERVAL '5 minutes';
BEGIN
  -- Data/hora canônica oficial no fuso horário de Brasília (UTC-3)
  v_agora_brt := now() AT TIME ZONE 'America/Sao_Paulo';
  v_hora_atual := v_agora_brt::TIME;
  v_dow_atual := EXTRACT(DOW FROM v_agora_brt)::INT;
  v_hora_evento_str := to_char(v_agora_brt, 'DD/MM/YYYY às HH24:MI:SS');

  -- RESET DO CICLO DE IGNIÇÃO / DESLOCAMENTO NA CHAVE DESLIGADA
  IF NEW.ignicao_status = false THEN
    DELETE FROM public.alertas_telemetria_cooldown
    WHERE veiculo_id = NEW.id
      AND tipo_alerta IN ('movimento_fora_horario', 'ignicao_fora_horario');
  END IF;

  -- 1. Busca user_id do cliente titular
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = NEW.cliente_id
  LIMIT 1;

  -- 2. Busca parâmetros de regras e preferências ativas do veículo
  SELECT 
    COALESCE(limite_velocidade_geral, 110),
    COALESCE(alerta_movimento_nao_autorizado, true),
    COALESCE(alerta_ignicao_fora_horario, true),
    alertas_ativos
  INTO 
    v_velocidade_limite,
    v_alerta_mov_regras,
    v_alerta_ign_regras,
    v_alertas_ativos
  FROM public.regras_veiculo
  WHERE veiculo_id = NEW.id
  LIMIT 1;

  IF NOT FOUND THEN
    v_velocidade_limite := 110;
    v_alerta_mov_regras := true;
    v_alerta_ign_regras := true;
    v_alertas_ativos := '{"movimento_fora_horario":true,"ignicao_fora_horario":true,"ignicao_ligada":true,"saida_area":true,"entrada_area":true,"excesso_velocidade":true,"perda_comunicacao":true,"baixa_tensao":true,"desvio_rota":true,"guincho":true}'::jsonb;
  END IF;

  -- 3. Cálculo geodésico de deslocamento Haversine em metros entre OLD e NEW
  IF OLD.ultima_latitude IS NOT NULL 
     AND OLD.ultima_longitude IS NOT NULL 
     AND NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL
     AND (OLD.ultima_latitude <> 0 OR OLD.ultima_longitude <> 0)
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0)
     AND (OLD.ultima_latitude <> NEW.ultima_latitude OR OLD.ultima_longitude <> NEW.ultima_longitude) THEN
    
    v_dlat := radians(NEW.ultima_latitude - OLD.ultima_latitude);
    v_dlon := radians(NEW.ultima_longitude - OLD.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(OLD.ultima_latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));
  ELSE
    v_dist_metros := 0;
  END IF;

  -- ALERTA A: EXCESSO DE VELOCIDADE
  IF COALESCE(NEW.velocidade_atual, 0) > 0 
     AND COALESCE((v_alertas_ativos->>'excesso_velocidade')::BOOLEAN, true) = true THEN

    IF NEW.velocidade_atual > v_velocidade_limite THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'excesso_velocidade'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('⚠️ Excesso de Velocidade — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s atingiu %s km/h (limite configurado: %s km/h) em %s.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual),
          v_velocidade_limite,
          v_hora_evento_str
        );
        v_tipo      := 'excesso_velocidade';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ALERTA B: IGNIÇÃO LIGADA FORA DO HORÁRIO (TRANSIÇÃO OFF -> ON)
  IF NEW.ignicao_status = true 
     AND COALESCE(OLD.ignicao_status, false) = false
     AND v_alerta_ign_regras = true
     AND COALESCE((v_alertas_ativos->>'ignicao_fora_horario')::BOOLEAN, true) = true THEN

    IF v_horario_proibido OR public.hunter_horario_proibido(NEW.id) THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_PADRAO)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT hora_inicio::TEXT, hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('🚨 Ignição Acionada Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor do veículo %s acionado fora do horário permitido (%s às %s) em %s.',
          COALESCE(NEW.placa, ''),
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          v_hora_evento_str
        );
        v_tipo      := 'ignicao_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ALERTA D: DESLOCAMENTO FORA DO HORÁRIO (1x POR CICLO DE CHAVE LIGADA)
  IF NEW.ignicao_status = true 
     AND (COALESCE(NEW.velocidade_atual, 0) >= 3 OR v_dist_metros >= 15.0)
     AND v_alerta_mov_regras = true
     AND COALESCE((v_alertas_ativos->>'movimento_fora_horario')::BOOLEAN, true) = true THEN

    IF v_horario_proibido OR public.hunter_horario_proibido(NEW.id) THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'movimento_fora_horario'
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT hora_inicio::TEXT, hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('🚨 Deslocamento Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s em movimento fora do horário permitido (%s às %s) em %s. Velocidade: %s km/h.',
          COALESCE(NEW.placa, ''),
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          v_hora_evento_str,
          ROUND(NEW.velocidade_atual)
        );
        v_tipo      := 'movimento_fora_horario';
        v_gravidade := 'critica';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ALERTA E: GUINCHO / ARRASTO COM MOTOR DESLIGADO
  IF NEW.ignicao_status = false
     AND COALESCE(OLD.ignicao_status, false) = false
     AND (
       COALESCE(NEW.velocidade_atual, 0) >= 15
       OR (COALESCE(NEW.velocidade_atual, 0) >= 10 AND v_dist_metros >= 35.0)
     )
     AND COALESCE((v_alertas_ativos->>'guincho')::BOOLEAN, true) = true THEN

    SELECT (
      NOT EXISTS (
        SELECT 1 FROM public.alertas_telemetria_cooldown
        WHERE veiculo_id = NEW.id
          AND tipo_alerta = 'guincho'
          AND ultimo_at > (now() - COOLDOWN_PADRAO)
      )
    ) INTO v_cooldown_ok;

    IF v_cooldown_ok THEN
      v_titulo   := format('🚨 Veículo em Movimento com Motor Desligado — %s', COALESCE(NEW.placa, ''));
      v_mensagem := format(
        'Veículo %s detectado a %s km/h com ignição desligada em %s. Possível reboque ou furto em andamento.',
        COALESCE(NEW.placa, ''),
        ROUND(NEW.velocidade_atual),
        v_hora_evento_str
      );
      v_tipo      := 'guincho';
      v_gravidade := 'critica';

      INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
      VALUES (NEW.id, v_tipo, now())
      ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

      INSERT INTO public.alertas_seguranca (
        veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
        velocidade, detalhes, reconhecido, created_at
      ) VALUES (
        NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
        COALESCE(NEW.ultima_latitude, 0),
        COALESCE(NEW.ultima_longitude, 0),
        COALESCE(NEW.velocidade_atual::INT, 0),
        v_mensagem, false, now()
      );

      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id, destinatario_cliente_id,
        titulo, mensagem, tipo, url, placa, lida, created_at
      ) VALUES (
        v_cliente_user_id, NEW.cliente_id,
        v_titulo, v_mensagem, v_tipo, '/monitor-gps',
        COALESCE(NEW.placa, ''), false, now()
      );
    END IF;
  END IF;

  -- ALERTA F: GEOFENCE COM MÁQUINA DE ESTADOS FÍSICA (ZERO REPETIÇÃO)
  IF NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL 
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0) THEN

    FOR v_area IN
      SELECT id, nome, latitude, longitude, raio_metros, 
             COALESCE(tolerancia_metros, 30) AS tolerancia_metros,
             COALESCE(regra_entrada, 'permitida') AS regra_entrada,
             COALESCE(regra_saida, 'permitida') AS regra_saida,
             hora_inicio, hora_fim, dias_semana
      FROM public.areas_seguras
      WHERE (veiculo_id = NEW.id OR (veiculo_id IS NULL AND cliente_id = NEW.cliente_id))
        AND ativo = true
        AND latitude IS NOT NULL
        AND longitude IS NOT NULL
        AND raio_metros > 0
    LOOP
      v_dlat_area := radians(NEW.ultima_latitude - v_area.latitude);
      v_dlon_area := radians(NEW.ultima_longitude - v_area.longitude);
      v_a := sin(v_dlat_area / 2.0)^2 + cos(radians(v_area.latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon_area / 2.0)^2;
      v_dist_area_new := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));

      v_tolerancia := GREATEST(COALESCE(v_area.tolerancia_metros, 30.0), 20.0);
      v_raio_saida := v_area.raio_metros + v_tolerancia;
      v_raio_entrada := v_area.raio_metros;

      v_area_fora_horario := false;
      IF v_area.hora_inicio IS NOT NULL AND v_area.hora_fim IS NOT NULL THEN
        IF v_area.dias_semana IS NOT NULL AND NOT (v_dow_atual = ANY(v_area.dias_semana)) THEN
          v_area_fora_horario := true;
        ELSIF v_area.hora_inicio <= v_area.hora_fim THEN
          IF v_hora_atual < v_area.hora_inicio OR v_hora_atual > v_area.hora_fim THEN
            v_area_fora_horario := true;
          END IF;
        ELSE
          IF v_hora_atual < v_area.hora_inicio AND v_hora_atual > v_area.hora_fim THEN
            v_area_fora_horario := true;
          END IF;
        END IF;
      END IF;

      SELECT estado INTO v_estado_anterior
      FROM public.veiculo_areas_estado
      WHERE veiculo_id = NEW.id AND area_id = v_area.id;

      IF v_estado_anterior IS NULL THEN
        IF v_dist_area_new <= v_raio_entrada THEN
          v_estado_anterior := 'dentro';
        ELSE
          v_estado_anterior := 'fora';
        END IF;

        INSERT INTO public.veiculo_areas_estado (
          veiculo_id, area_id, estado, distancia_metros, updated_at
        ) VALUES (
          NEW.id, v_area.id, v_estado_anterior, v_dist_area_new, now()
        ) ON CONFLICT (veiculo_id, area_id) DO NOTHING;
      END IF;

      -- F.1) TRANSIÇÃO PARA SAÍDA: DE 'dentro' PARA 'fora'
      IF v_estado_anterior = 'dentro' AND v_dist_area_new > v_raio_saida THEN
        UPDATE public.veiculo_areas_estado
        SET estado = 'fora',
            distancia_metros = v_dist_area_new,
            ultimo_evento_tipo = 'saida_area',
            ultimo_evento_em = now(),
            notificacao_enviada = true,
            whatsapp_enviado = false,
            updated_at = now()
        WHERE veiculo_id = NEW.id AND area_id = v_area.id;

        IF COALESCE((v_alertas_ativos->>'saida_area')::BOOLEAN, true) = true
           AND (
             v_area.regra_saida = 'alertar'
             OR (v_area.regra_saida = 'fora_horario' AND v_area_fora_horario)
           ) THEN

          v_titulo := format('🚨 Saída de Área Protegida — %s', COALESCE(NEW.placa, ''));
          IF v_area.regra_saida = 'fora_horario' THEN
            v_mensagem := format(
              'Veículo %s saiu da área protegida "%s" FORA do horário habitual em %s (distância: %s m).',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_hora_evento_str,
              ROUND(v_dist_area_new)
            );
            v_gravidade := 'alta';
          ELSE
            v_mensagem := format(
              'Veículo %s saiu da área monitorada "%s" em %s (distância: %s m).',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_hora_evento_str,
              ROUND(v_dist_area_new)
            );
            v_gravidade := 'media';
          END IF;

          v_tipo := 'saida_area';

          INSERT INTO public.alertas_seguranca (
            veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
            velocidade, detalhes, reconhecido, created_at
          ) VALUES (
            NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
            COALESCE(NEW.ultima_latitude, 0),
            COALESCE(NEW.ultima_longitude, 0),
            COALESCE(NEW.velocidade_atual::INT, 0),
            v_mensagem, false, now()
          );

          INSERT INTO public.notificacoes_sistema (
            destinatario_user_id, destinatario_cliente_id,
            titulo, mensagem, tipo, url, placa, lida, created_at
          ) VALUES (
            v_cliente_user_id, NEW.cliente_id,
            v_titulo, v_mensagem, v_tipo, '/monitor-gps',
            COALESCE(NEW.placa, ''), false, now()
          );
        END IF;

      -- F.2) TRANSIÇÃO PARA ENTRADA: DE 'fora' PARA 'dentro'
      ELSIF v_estado_anterior = 'fora' AND v_dist_area_new <= v_raio_entrada THEN
        UPDATE public.veiculo_areas_estado
        SET estado = 'dentro',
            distancia_metros = v_dist_area_new,
            ultimo_evento_tipo = 'entrada_area',
            ultimo_evento_em = now(),
            notificacao_enviada = true,
            whatsapp_enviado = false,
            updated_at = now()
        WHERE veiculo_id = NEW.id AND area_id = v_area.id;

        IF COALESCE((v_alertas_ativos->>'entrada_area')::BOOLEAN, true) = true
           AND (
             v_area.regra_entrada = 'alertar'
             OR (v_area.regra_entrada = 'fora_horario' AND v_area_fora_horario)
           ) THEN

          v_titulo := format('✅ Chegada em Área Protegida — %s', COALESCE(NEW.placa, ''));
          IF v_area.regra_entrada = 'fora_horario' THEN
            v_mensagem := format(
              'Veículo %s entrou na área protegida "%s" FORA do horário habitual em %s.',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_hora_evento_str
            );
            v_gravidade := 'alta';
          ELSE
            v_mensagem := format(
              'Veículo %s entrou na área monitorada "%s" em %s.',
              COALESCE(NEW.placa, ''),
              v_area.nome,
              v_hora_evento_str
            );
            v_gravidade := 'baixa';
          END IF;

          v_tipo := 'entrada_area';

          INSERT INTO public.alertas_seguranca (
            veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
            velocidade, detalhes, reconhecido, created_at
          ) VALUES (
            NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
            COALESCE(NEW.ultima_latitude, 0),
            COALESCE(NEW.ultima_longitude, 0),
            COALESCE(NEW.velocidade_atual::INT, 0),
            v_mensagem, false, now()
          );

          INSERT INTO public.notificacoes_sistema (
            destinatario_user_id, destinatario_cliente_id,
            titulo, mensagem, tipo, url, placa, lida, created_at
          ) VALUES (
            v_cliente_user_id, NEW.cliente_id,
            v_titulo, v_mensagem, v_tipo, '/monitor-gps',
            COALESCE(NEW.placa, ''), false, now()
          );
        END IF;

      ELSE
        UPDATE public.veiculo_areas_estado
        SET distancia_metros = v_dist_area_new,
            updated_at = now()
        WHERE veiculo_id = NEW.id AND area_id = v_area.id;
      END IF;

    END LOOP;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trigger_avaliar_alertas_telemetria falhou: %', SQLERRM;
  RETURN NEW;
END;
$$;

-- ==============================================================================
-- HUNTER / GD RASTREAMENTO — BLINDAGEM ANTI-REPETIÇÃO DE NOTIFICAÇÕES E RELATÓRIO
-- Protocolo Canônico: 1 Único Relatório Gerencial por Dia (Horário Agendado)
-- Resolução Definitiva de Deduplicação Global e Janela de Horário
-- ==============================================================================

-- 1. Aprimoramento da Função de Trigger trg_anti_duplicacao_notificacoes_sistema
CREATE OR REPLACE FUNCTION public.trg_anti_duplicacao_notificacoes_sistema()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  -- 1.1. Regra Canônica para Relatórios Gerenciais e Notificações Matinais Agendadas:
  -- Disparo estritamente único por dia civil (janela de 20 horas)
  IF (NEW.tipo IN ('gerencial', 'relatorio') OR NEW.titulo ILIKE '%Relatório%') THEN
    IF EXISTS (
      SELECT 1 FROM public.notificacoes_sistema
      WHERE (tipo IN ('gerencial', 'relatorio') OR titulo ILIKE '%Relatório%')
        AND created_at > NOW() - INTERVAL '20 hours'
    ) THEN
      -- Descarta silenciosamente o insert duplicado do relatório
      RETURN NULL;
    END IF;
    RETURN NEW;
  END IF;

  -- 1.2. Regra para Notificações Globais do Sistema (destinatário nulo)
  IF (NEW.destinatario_user_id IS NULL AND NEW.destinatario_cliente_id IS NULL) THEN
    IF EXISTS (
      SELECT 1 FROM public.notificacoes_sistema
      WHERE destinatario_user_id IS NULL
        AND destinatario_cliente_id IS NULL
        AND tipo = NEW.tipo
        AND COALESCE(titulo, '') = COALESCE(NEW.titulo, '')
        AND created_at > NOW() - INTERVAL '5 minutes'
    ) THEN
      RETURN NULL;
    END IF;
    RETURN NEW;
  END IF;

  -- 1.3. Regra para Notificações Direcionadas por Destinatário (Usuário ou Cliente)
  IF EXISTS (
    SELECT 1 FROM public.notificacoes_sistema
    WHERE (
      (NEW.destinatario_user_id IS NOT NULL AND destinatario_user_id = NEW.destinatario_user_id)
      OR
      (NEW.destinatario_cliente_id IS NOT NULL AND destinatario_cliente_id = NEW.destinatario_cliente_id)
    )
    AND tipo = NEW.tipo
    AND (
      (NEW.placa IS NOT NULL AND NEW.placa <> '' AND COALESCE(placa, '') = NEW.placa)
      OR
      (COALESCE(titulo, '') = COALESCE(NEW.titulo, ''))
    )
    AND created_at > NOW() - INTERVAL '60 seconds'
  ) THEN
    -- Descarta silenciosamente o insert duplicado na raiz do banco
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_anti_duplicacao_notificacoes_sistema ON public.notificacoes_sistema;
CREATE TRIGGER trg_anti_duplicacao_notificacoes_sistema
  BEFORE INSERT ON public.notificacoes_sistema
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_anti_duplicacao_notificacoes_sistema();

-- 2. Garantia de Existência de Registro Canônico em relatorio_gerencial_config
INSERT INTO public.relatorio_gerencial_config (
  ativo,
