-- ─────────────────────────────────────────────────────────────────────────────
-- MIGRATION: 20261021015000_hunter_garantir_login_motorista_e_auto_cura_identities.sql
-- Sistema: GD Rastreamento | Diretrizes: HUNTER-GUARDIAN e DJR-NEW
-- Descrição:
-- 1. Auto-cura atômica de motoristas órfãos (user_id IS NULL) e sincronização de auth.identities
-- 2. Criação da RPC canônica public.garantir_login_motorista() para SuperADM e Clientes
-- 3. Atualização de public.cadastrar_motorista() com proteção contra duplicidade órfã
-- 4. Atualização de public.admin_redefinir_senha() com garantia de identities no GoTrue v2
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
  r_mot RECORD;
  v_uid UUID;
  v_enc TEXT;
BEGIN
  -- 1.1 Sincronizar motoristas que já têm conta em auth.users mas estavam com user_id NULL
  FOR r_mot IN 
    SELECT m.id AS mot_id, m.email, u.id AS user_id
    FROM public.motoristas m
    JOIN auth.users u ON LOWER(TRIM(m.email)) = LOWER(TRIM(u.email))
    WHERE m.user_id IS NULL
  LOOP
    UPDATE public.motoristas SET user_id = r_mot.user_id WHERE id = r_mot.mot_id;
  END LOOP;

  -- 1.2 Auto-provisionar motoristas órfãos que não possuem usuário em auth.users
  FOR r_mot IN 
    SELECT m.id AS mot_id, m.nome, m.email, m.cliente_id
    FROM public.motoristas m
    WHERE m.user_id IS NULL 
       OR NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = m.user_id)
  LOOP
    v_uid := gen_random_uuid();
    v_enc := extensions.crypt('Mudar@123', extensions.gen_salt('bf', 10));

    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, recovery_sent_at, last_sign_in_at,
      raw_app_meta_data, raw_user_meta_data,
      created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change,
      email_change_token_current, phone_change, phone_change_token, reauthentication_token
    ) VALUES (
      v_uid,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      LOWER(TRIM(r_mot.email)),
      v_enc,
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      jsonb_build_object('nome', r_mot.nome, 'role', 'motorista', 'cliente_id', r_mot.cliente_id),
      now(), now(),
      '', '', '', '', '', '', '', ''
    )
    ON CONFLICT (id) DO NOTHING;

    -- auth.identities
    BEGIN
      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id,
        last_sign_in_at, created_at, updated_at
      ) VALUES (
        v_uid::text,
        v_uid,
        jsonb_build_object('sub', v_uid::text, 'email', LOWER(TRIM(r_mot.email)), 'email_verified', true),
        'email',
        v_uid::text,
        now(), now(), now()
      )
      ON CONFLICT DO NOTHING;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    -- Vincular motorista
    UPDATE public.motoristas SET user_id = v_uid WHERE id = r_mot.mot_id;

    -- Profile
    INSERT INTO public.profiles (id, nome, email, role, ativo, primeiro_acesso)
    VALUES (v_uid, r_mot.nome, LOWER(TRIM(r_mot.email)), 'motorista'::public.hunter_role, true, false)
    ON CONFLICT (id) DO UPDATE
    SET role = 'motorista'::public.hunter_role, ativo = true;

    -- User Role
    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_uid, 'motorista'::public.hunter_role)
    ON CONFLICT DO NOTHING;
  END LOOP;

  -- 1.3 Garantir que TODOS os usuários de auth.users possuem identidade em auth.identities
  FOR r_mot IN 
    SELECT u.id, u.email
    FROM auth.users u
    WHERE NOT EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = u.id)
  LOOP
    BEGIN
      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id,
        last_sign_in_at, created_at, updated_at
      ) VALUES (
        r_mot.id::text,
        r_mot.id,
        jsonb_build_object('sub', r_mot.id::text, 'email', LOWER(TRIM(r_mot.email)), 'email_verified', true),
        'email',
        r_mot.id::text,
        now(), now(), now()
      )
      ON CONFLICT DO NOTHING;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.garantir_login_motorista(
  p_motorista_id UUID,
  p_nova_senha   TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = extensions, public, auth, pg_temp
AS $$
DECLARE
  v_caller_id   UUID := auth.uid();
  v_mot         RECORD;
  v_user_id     UUID;
  v_enc_pw      TEXT;
  v_email_limpo TEXT;
BEGIN
  -- 1. Validar senha
  IF p_nova_senha IS NULL OR length(p_nova_senha) < 6 THEN
    RAISE EXCEPTION 'A nova senha deve ter no minimo 6 caracteres.';
  END IF;

  -- 2. Localizar o motorista
  SELECT * INTO v_mot FROM public.motoristas WHERE id = p_motorista_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Motorista nao encontrado no sistema.';
  END IF;

  -- 3. Validação de Autorização (SuperADM, ADM ou Dono do Cliente)
CREATE OR REPLACE FUNCTION public.garantir_login_motorista(
  p_motorista_id UUID,
  p_nova_senha   TEXT DEFAULT NULL,
  p_novo_email   TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = extensions, public, auth, pg_temp
AS $$
DECLARE
  v_caller_id   UUID := auth.uid();
  v_mot         RECORD;
  v_user_id     UUID;
  v_enc_pw      TEXT;
  v_email_alvo  TEXT;
  v_email_antigo TEXT;
BEGIN
  -- 1. Localizar o motorista
  SELECT * INTO v_mot FROM public.motoristas WHERE id = p_motorista_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Motorista não encontrado no sistema.';
  END IF;

  -- 2. Validação de Autorização (SuperADM, ADM ou Dono do Cliente)
  IF NOT EXISTS (
    SELECT 1 FROM public.clientes WHERE id = v_mot.cliente_id AND user_id = v_caller_id
  ) AND NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_caller_id AND role IN ('superadmin', 'adm')
  ) THEN
    RAISE EXCEPTION 'Acesso negado: você não tem permissão para alterar o acesso deste motorista.';
  END IF;

  v_email_antigo := LOWER(TRIM(v_mot.email));

  -- 3. Tratar e-mail alvo (atual ou novo)
  IF p_novo_email IS NOT NULL AND TRIM(p_novo_email) <> '' THEN
    v_email_alvo := LOWER(TRIM(p_novo_email));
    
    -- Validação de formato de e-mail
    IF v_email_alvo !~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
      RAISE EXCEPTION 'O e-mail informado possui formato inválido.';
    END IF;

    -- Verificar se já existe outro motorista com esse novo e-mail
    IF EXISTS (
      SELECT 1 FROM public.motoristas 
      WHERE LOWER(TRIM(email)) = v_email_alvo AND id <> p_motorista_id
    ) THEN
      RAISE EXCEPTION 'Este e-mail já está em uso por outro motorista no sistema.';
    END IF;

    -- Verificar se já existe outro usuário em auth.users com esse novo e-mail
    IF EXISTS (
      SELECT 1 FROM auth.users 
      WHERE LOWER(TRIM(email)) = v_email_alvo 
        AND id <> COALESCE(v_mot.user_id, '00000000-0000-0000-0000-000000000000'::UUID)
    ) THEN
      RAISE EXCEPTION 'Este e-mail já está vinculado a outra conta de usuário no sistema.';
    END IF;
  ELSE
    v_email_alvo := v_email_antigo;
  END IF;

  -- 4. Tratar criptografia de senha se informada
  IF p_nova_senha IS NOT NULL AND TRIM(p_nova_senha) <> '' THEN
    IF length(TRIM(p_nova_senha)) < 6 THEN
      RAISE EXCEPTION 'A nova senha deve ter no mínimo 6 caracteres.';
    END IF;
    v_enc_pw := extensions.crypt(TRIM(p_nova_senha), extensions.gen_salt('bf', 10));
  ELSE
    v_enc_pw := NULL;
  END IF;

  -- 5. Verificar se já existe auth.users vinculado ou por e-mail antigo/novo
  v_user_id := v_mot.user_id;
  IF v_user_id IS NULL THEN
    SELECT id INTO v_user_id FROM auth.users WHERE LOWER(TRIM(email)) IN (v_email_antigo, v_email_alvo) LIMIT 1;
  END IF;

  IF v_user_id IS NOT NULL AND EXISTS (SELECT 1 FROM auth.users WHERE id = v_user_id) THEN
    -- Atualizar auth.users existente
    UPDATE auth.users
    SET email = v_email_alvo,
        encrypted_password = COALESCE(v_enc_pw, encrypted_password),
        email_confirmed_at = COALESCE(email_confirmed_at, now()),
        updated_at = now()
    WHERE id = v_user_id;
  ELSE
    -- Criar novo usuário em auth.users
    v_user_id := gen_random_uuid();
    IF v_enc_pw IS NULL THEN
      v_enc_pw := extensions.crypt('Mudar@123', extensions.gen_salt('bf', 10));
    END IF;

    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, recovery_sent_at, last_sign_in_at,
      raw_app_meta_data, raw_user_meta_data,
      created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change,
      email_change_token_current, phone_change, phone_change_token, reauthentication_token
    ) VALUES (
      v_user_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      v_email_alvo,
      v_enc_pw,
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      jsonb_build_object('nome', v_mot.nome, 'role', 'motorista', 'cliente_id', v_mot.cliente_id),
      now(), now(),
      '', '', '', '', '', '', '', ''
    );
  END IF;

  -- 6. Atualizar public.motoristas (e-mail e user_id)
  UPDATE public.motoristas 
  SET email = v_email_alvo,
      user_id = v_user_id, 
      updated_at = now() 
  WHERE id = p_motorista_id;

  -- 7. Garantir identidade atualizada em auth.identities
  BEGIN
    INSERT INTO auth.identities (
      id, user_id, identity_data, provider, provider_id,
      last_sign_in_at, created_at, updated_at
    ) VALUES (
      v_user_id::text,
      v_user_id,
      jsonb_build_object('sub', v_user_id::text, 'email', v_email_alvo, 'email_verified', true),
      'email',
      v_user_id::text,
      now(), now(), now()
    )
    ON CONFLICT (id) DO UPDATE
    SET identity_data = jsonb_build_object('sub', v_user_id::text, 'email', v_email_alvo, 'email_verified', true),
        updated_at = now();
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  -- 8. Garantir Profile sincronizado
  INSERT INTO public.profiles (
    id, nome, email, role, ativo, primeiro_acesso, telefone
  ) VALUES (
    v_user_id,
    v_mot.nome,
    v_email_alvo,
    'motorista'::public.hunter_role,
    true,
    false,
    v_mot.telefone
  )
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      email = v_email_alvo,
      role = 'motorista'::public.hunter_role,
      ativo = true;

  -- 9. Garantir User Role
  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_user_id, 'motorista'::public.hunter_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  RETURN jsonb_build_object(
    'status', 'success',
    'message', 'Dados de acesso do motorista atualizados com sucesso.',
    'user_id', v_user_id,
    'email', v_email_alvo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.garantir_login_motorista(UUID, TEXT, TEXT) TO authenticated, service_role;

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Suprimir Informação "A agendar" para Instalações Realizadas (DJR-NEW)
-- ─────────────────────────────────────────────────────────────────────────────
UPDATE public.clientes
SET status_agendamento = 'concluido', updated_at = NOW()
WHERE status = 'ativo' AND (status_agendamento IS NULL OR status_agendamento = 'aguardando_agendamento');

CREATE OR REPLACE FUNCTION public.trg_fn_sincronizar_agendamento_cliente_ao_instalar()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
BEGIN
  IF NEW.status = 'concluida' OR NEW.concluida_at IS NOT NULL THEN
    IF NEW.cliente_id IS NOT NULL THEN
      UPDATE public.clientes
      SET 
        status = 'ativo',
        status_agendamento = 'concluido',
        updated_at = NOW()
      WHERE id = NEW.cliente_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sincronizar_agendamento_cliente_ao_instalar ON public.instalacoes;

CREATE TRIGGER trg_sincronizar_agendamento_cliente_ao_instalar
AFTER INSERT OR UPDATE OF status, concluida_at ON public.instalacoes
FOR EACH ROW
EXECUTE FUNCTION public.trg_fn_sincronizar_agendamento_cliente_ao_instalar();

