ON public.user_module_access
FOR ALL
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role IN ('superadmin', 'adm')
  )
)
WITH CHECK (
  EXISTS (
