CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL,
  p_gps_fixado            BOOLEAN     DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;
  c_e2         CONSTANT DOUBLE PRECISION := 0.00669437999014;
  c_raio_esf   CONSTANT DOUBLE PRECISION := 6371000.0;

  c_gap_max_s  CONSTANT NUMERIC          := 600.0;
  c_spike_kmh  CONSTANT NUMERIC          := 190.0;
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;
  c_zvu_vel    CONSTANT NUMERIC          := 2.0;

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_dist_geom          DOUBLE PRECISION := 0.0;
  v_dist_trap_m        DOUBLE PRECISION := 0.0;
  v_dist_haversine_m   DOUBLE PRECISION := 0.0;
  v_dist_taylor_m      DOUBLE PRECISION := 0.0;

  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_delta_cinematico_m DOUBLE PRECISION := 0.0;
  v_delta_cinematico_km NUMERIC(12, 4)  := 0.0;
  v_delta_motor_a_km   NUMERIC(12, 4)   := 0.0;
  v_delta_motor_b_km   NUMERIC(12, 4)   := 0.0;
  v_delta_motor_c_km   NUMERIC(12, 4)   := 0.0;

  v_novo_odometro      NUMERIC(12, 3);
  v_novo_cinematico    NUMERIC(12, 3);
  v_novo_motor_a       NUMERIC(12, 3);
  v_novo_motor_b       NUMERIC(12, 3);
  v_novo_motor_c       NUMERIC(12, 3);

  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_w2                 DOUBLE PRECISION;
  v_w                  DOUBLE PRECISION;
  v_m_meridiano        DOUBLE PRECISION;
  v_n_normal           DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_delta_rumo         INT              := 0;
  v_half_angle_rad     DOUBLE PRECISION;
  v_arc_dist           DOUBLE PRECISION;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
  v_fusao_aplicada     BOOLEAN          := FALSE;
  v_fator_veiculo      NUMERIC(8, 6)    := 1.000000;

  v_estado_a           TEXT             := 'PARADO_ZVU';
  v_estado_b           TEXT             := 'PARADO_ZVU';
  v_estado_c           TEXT             := 'PARADO_ZVU';
  v_pesos_a            JSONB            := '{"gnssOuArco": 0, "cinematico": 0, "mcuJ16": 0}'::jsonb;
  v_pesos_b            JSONB            := '{"gnssOuArco": 0, "cinematico": 0, "mcuJ16": 0}'::jsonb;
  v_pesos_c            JSONB            := '{"gnssOuArco": 0, "cinematico": 0, "mcuJ16": 0}'::jsonb;
BEGIN
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, odometro_cinematico_km,
         odometro_motor_a_km, odometro_motor_b_km, odometro_motor_c_km,
         ultima_atualizacao, fator_calibracao_odometro
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro   := COALESCE(v_veiculo.odometro_km, 0);
  v_novo_cinematico := COALESCE(v_veiculo.odometro_cinematico_km, v_novo_odometro);
  v_novo_motor_a    := COALESCE(v_veiculo.odometro_motor_a_km, v_novo_odometro);
  v_novo_motor_b    := COALESCE(v_veiculo.odometro_motor_b_km, v_novo_odometro);
  v_novo_motor_c    := COALESCE(v_veiculo.odometro_motor_c_km, v_novo_odometro);

  IF v_veiculo.fator_calibracao_odometro IS NOT NULL
     AND v_veiculo.fator_calibracao_odometro BETWEEN 0.850000 AND 1.150000 THEN
    v_fator_veiculo := v_veiculo.fator_calibracao_odometro;
  ELSE
    v_fator_veiculo := 1.000000;
  END IF;

  IF NOT COALESCE(p_gps_fixado, TRUE) THEN
    v_descartado      := TRUE;
    v_motivo_descarte := 'sem_fix_gnss_lbs';
  END IF;

  IF NOT v_descartado THEN
    IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'coordenada_zero';
    ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
       OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'fora_brasil';
    END IF;
  END IF;

  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_w2          := 1.0 - (c_e2 * v_sin_lat * v_sin_lat);
    v_w           := sqrt(v_w2);

    v_m_meridiano := (c_a * (1.0 - c_e2)) / (v_w * v_w2);
    v_n_normal    := c_a / v_w;

    v_dlat        := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon        := radians(p_longitude - v_veiculo.ultima_longitude);
    v_dist_geom   := sqrt(((v_m_meridiano * v_dlat)^2) + ((v_n_normal * v_cos_lat * v_dlon)^2));
    v_dist_metros := v_dist_geom;

    v_dist_haversine_m := 2.0 * c_raio_esf * asin(
      sqrt(
        sin(v_dlat / 2.0)^2 +
        cos(radians(v_veiculo.ultima_latitude)) * cos(radians(p_latitude)) * (sin(v_dlon / 2.0)^2)
      )
    );

    v_dist_taylor_m := v_dist_geom * 1.00027267;

    SELECT data_hora_gps, velocidade, rumo
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0;
    END IF;

    IF COALESCE(p_ignicao, TRUE) AND p_velocidade > 0 AND v_delta_sec > 0.5 AND v_delta_sec <= 300.0 THEN
      v_dist_trap_m := ((p_velocidade + COALESCE(v_ultima_telem.velocidade, p_velocidade)) / 7.2) * v_delta_sec;
      IF v_dist_trap_m > 0 AND v_dist_trap_m < c_dist_max_m THEN
        v_delta_cinematico_m  := v_dist_trap_m;
        v_delta_cinematico_km := (v_delta_cinematico_m / 1000.0);
        v_novo_cinematico     := ROUND((v_novo_cinematico + v_delta_cinematico_km)::NUMERIC, 3);
      END IF;
    END IF;

    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    IF NOT v_descartado THEN
      IF NOT COALESCE(p_ignicao, TRUE) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'estacionado_ign_off';
      ELSIF (p_velocidade IS NULL OR p_velocidade < c_zvu_vel) AND v_dist_metros < 3.5 THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'parado_marcha_lenta';
      ELSIF p_velocidade >= c_zvu_vel AND v_dist_metros < 1.0 THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'micro_jitter_movimento';
      END IF;
    END IF;

    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausivel_' || round(v_dist_metros) || 'm';
    END IF;

    IF NOT v_descartado AND v_delta_sec > 0.5 AND v_delta_sec <= 180.0 AND p_velocidade > 2.5 THEN
      IF v_ultima_telem.rumo IS NOT NULL AND p_rumo IS NOT NULL THEN
        v_delta_rumo := ABS(p_rumo - v_ultima_telem.rumo);
        IF v_delta_rumo > 180 THEN
          v_delta_rumo := 360 - v_delta_rumo;
        END IF;
      ELSE
        v_delta_rumo := 0;
      END IF;

      IF v_delta_rumo >= 10 THEN
        v_half_angle_rad := radians(v_delta_rumo / 2.0);
        IF sin(v_half_angle_rad) > 0.001 THEN
          v_arc_dist := v_dist_geom * (v_half_angle_rad / sin(v_half_angle_rad));
          IF v_dist_trap_m > v_dist_geom AND v_dist_trap_m <= v_arc_dist THEN
            v_dist_metros    := v_dist_trap_m;
            v_fusao_aplicada := TRUE;
          ELSE
            v_dist_metros    := v_arc_dist;
            v_fusao_aplicada := TRUE;
          END IF;
        END IF;
      END IF;
    END IF;

    IF NOT v_descartado THEN
      v_limiar_m := CASE WHEN p_velocidade >= c_zvu_vel THEN 1.0 ELSE 3.0 END;
      IF v_dist_metros >= v_limiar_m THEN
        v_delta_km      := (v_dist_metros / 1000.0) * v_fator_veiculo;
        v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);

        v_delta_motor_a_km := ((v_dist_metros * 0.52 + COALESCE(v_dist_trap_m, v_dist_metros) * 0.48) / 1000.0) * 1.000215;
        v_novo_motor_a     := ROUND((v_novo_motor_a + v_delta_motor_a_km)::NUMERIC, 3);
        v_estado_a         := 'MOVIMENTO';
        v_pesos_a          := '{"gnssOuArco": 52, "cinematico": 28, "mcuJ16": 20}'::jsonb;

        v_delta_motor_b_km := (v_dist_haversine_m / 1000.0);
        v_novo_motor_b     := ROUND((v_novo_motor_b + v_delta_motor_b_km)::NUMERIC, 3);
        v_estado_b         := 'MOVIMENTO';
        v_pesos_b          := '{"gnssOuArco": 57, "cinematico": 25, "mcuJ16": 18}'::jsonb;

        v_delta_motor_c_km := ((v_dist_taylor_m * 0.94 + COALESCE(v_dist_trap_m, v_dist_taylor_m) * 0.06) / 1000.0);
        v_novo_motor_c     := ROUND((v_novo_motor_c + v_delta_motor_c_km)::NUMERIC, 3);
        v_estado_c         := 'MOVIMENTO';
        v_pesos_c          := '{"gnssOuArco": 6, "cinematico": 4, "mcuJ16": 90}'::jsonb;
      ELSE
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'limiar_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm,
      gps_fixado
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_odometro,
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm,
      COALESCE(p_gps_fixado, TRUE)
    )
    ON CONFLICT DO NOTHING;
  END IF;

  UPDATE public.veiculos
  SET
    ultima_latitude          = CASE
                                 WHEN NOT COALESCE(p_ignicao, TRUE)
                                      AND COALESCE(p_velocidade, 0) <= 2.0
                                      AND v_veiculo.ultima_latitude IS NOT NULL
                                      AND v_veiculo.ultima_latitude <> 0.0
                                 THEN v_veiculo.ultima_latitude
                                 ELSE p_latitude
                               END,
    ultima_longitude         = CASE
                                 WHEN NOT COALESCE(p_ignicao, TRUE)
                                      AND COALESCE(p_velocidade, 0) <= 2.0
                                      AND v_veiculo.ultima_longitude IS NOT NULL
                                      AND v_veiculo.ultima_longitude <> 0.0
                                 THEN v_veiculo.ultima_longitude
                                 ELSE p_longitude
                               END,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_odometro,
    odometro_cinematico_km   = v_novo_cinematico,
    odometro_motor_a_km      = v_novo_motor_a,
    odometro_motor_b_km      = v_novo_motor_b,
    odometro_motor_c_km      = v_novo_motor_c,
    odometro_motor_a_pesos   = v_pesos_a,
    odometro_motor_b_pesos   = v_pesos_b,
    odometro_motor_c_pesos   = v_pesos_c,
    odometro_motor_a_estado  = v_estado_a,
    odometro_motor_b_estado  = v_estado_b,
    odometro_motor_c_estado  = v_estado_c,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    gps_fixado               = COALESCE(p_gps_fixado, TRUE),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido  = km_percorrido + v_delta_km,
        updated_at     = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'novo_odometro', v_novo_odometro,
    'novo_odometro_cinematico', v_novo_cinematico,
    'novo_odometro_motor_a', v_novo_motor_a,
    'novo_odometro_motor_b', v_novo_motor_b,
    'novo_odometro_motor_c', v_novo_motor_c,
    'delta_km', v_delta_km,
    'delta_motor_a_km', v_delta_motor_a_km,
    'delta_motor_b_km', v_delta_motor_b_km,
    'delta_motor_c_km', v_delta_motor_c_km,
    'distancia_metros', v_dist_metros,
    'fusao_aplicada', v_fusao_aplicada,
    'descartado', v_descartado,
    'motivo_descarte', v_motivo_descarte
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated, service_role, anon;

NOTIFY pgrst, 'reload schema';

-- ── 16. Correção Canônica: updated_at em viagens_trajetos e Odometria em Tempo Real ──
-- ============================================================================
-- MIGRATION: 20261023144500_hunter_correcao_viagens_trajetos_updated_at_e_odometro.sql
-- ============================================================================
ALTER TABLE public.viagens_trajetos
  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

UPDATE public.viagens_trajetos
SET updated_at = COALESCE(fim_at, created_at, NOW())
WHERE updated_at IS NULL;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.viagens_trajetos TO authenticated, service_role;
GRANT SELECT ON TABLE public.viagens_trajetos TO anon;

NOTIFY pgrst, 'reload schema';

-- ── 17. Odometria: 7º Medidor (Média Fusional de 1, 4, 5 e 6) como Principal em Tempo Real ──
-- ============================================================================
-- MIGRATION: 20261023153000_hunter_odometro_medidor7_principal_media_fusional.sql
-- ============================================================================
ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS odometro_wgs84_km NUMERIC(12, 3),
  ADD COLUMN IF NOT EXISTS odometro_motor_media_km NUMERIC(12, 3);

UPDATE public.veiculos
SET
  odometro_wgs84_km = COALESCE(odometro_wgs84_km, odometro_km, 0.000),
  odometro_motor_media_km = ROUND(
    (
      COALESCE(odometro_wgs84_km, odometro_km, 0.000) +
      COALESCE(odometro_motor_a_km, odometro_km, 0.000) +
      COALESCE(odometro_motor_b_km, odometro_km, 0.000) +
      COALESCE(odometro_motor_c_km, odometro_km, 0.000)
    ) / 4.0,
    3
  )
WHERE odometro_wgs84_km IS NULL OR odometro_motor_media_km IS NULL;

UPDATE public.veiculos
SET odometro_km = odometro_motor_media_km
WHERE odometro_motor_media_km IS NOT NULL;

CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL,
  p_gps_fixado            BOOLEAN     DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;
  c_e2         CONSTANT DOUBLE PRECISION := 0.00669437999014;
  c_raio_esf   CONSTANT DOUBLE PRECISION := 6371000.0;

  c_gap_max_s  CONSTANT NUMERIC          := 600.0;
  c_spike_kmh  CONSTANT NUMERIC          := 190.0;
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;
  c_zvu_vel    CONSTANT NUMERIC          := 2.0;

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_dist_geom          DOUBLE PRECISION := 0.0;
  v_dist_trap_m        DOUBLE PRECISION := 0.0;
  v_dist_haversine_m   DOUBLE PRECISION := 0.0;
  v_dist_taylor_m      DOUBLE PRECISION := 0.0;

  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_delta_cinematico_m DOUBLE PRECISION := 0.0;
  v_delta_cinematico_km NUMERIC(12, 4)  := 0.0;
  v_delta_motor_a_km   NUMERIC(12, 4)   := 0.0;
  v_delta_motor_b_km   NUMERIC(12, 4)   := 0.0;
  v_delta_motor_c_km   NUMERIC(12, 4)   := 0.0;

  v_novo_wgs84         NUMERIC(12, 3);
  v_novo_cinematico    NUMERIC(12, 3);
  v_novo_motor_a       NUMERIC(12, 3);
  v_novo_motor_b       NUMERIC(12, 3);
  v_novo_motor_c       NUMERIC(12, 3);
  v_novo_media_7       NUMERIC(12, 3);

  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_w2                 DOUBLE PRECISION;
  v_w                  DOUBLE PRECISION;
  v_m_meridiano        DOUBLE PRECISION;
  v_n_normal           DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_delta_rumo         INT              := 0;
  v_half_angle_rad     DOUBLE PRECISION;
  v_arc_dist           DOUBLE PRECISION;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
  v_fusao_aplicada     BOOLEAN          := FALSE;
  v_fator_veiculo      NUMERIC(8, 6)    := 1.000000;

  v_estado_a           TEXT             := 'PARADO_ZVU';
  v_estado_b           TEXT             := 'PARADO_ZVU';
  v_estado_c           TEXT             := 'PARADO_ZVU';
  v_pesos_a            JSONB            := '{"gnssOuArco": 0, "cinematico": 0, "mcuJ16": 0}'::jsonb;
  v_pesos_b            JSONB            := '{"gnssOuArco": 0, "cinematico": 0, "mcuJ16": 0}'::jsonb;
  v_pesos_c            JSONB            := '{"gnssOuArco": 0, "cinematico": 0, "mcuJ16": 0}'::jsonb;
BEGIN
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, odometro_wgs84_km,
         odometro_cinematico_km, odometro_motor_a_km, odometro_motor_b_km, odometro_motor_c_km,
         odometro_motor_media_km, ultima_atualizacao, fator_calibracao_odometro
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_wgs84      := COALESCE(v_veiculo.odometro_wgs84_km, v_veiculo.odometro_km, 0);
  v_novo_cinematico := COALESCE(v_veiculo.odometro_cinematico_km, v_novo_wgs84);
  v_novo_motor_a    := COALESCE(v_veiculo.odometro_motor_a_km, v_novo_wgs84);
  v_novo_motor_b    := COALESCE(v_veiculo.odometro_motor_b_km, v_novo_wgs84);
  v_novo_motor_c    := COALESCE(v_veiculo.odometro_motor_c_km, v_novo_wgs84);
  v_novo_media_7    := COALESCE(v_veiculo.odometro_motor_media_km, v_veiculo.odometro_km, v_novo_wgs84);

  IF v_veiculo.fator_calibracao_odometro IS NOT NULL
     AND v_veiculo.fator_calibracao_odometro BETWEEN 0.850000 AND 1.150000 THEN
    v_fator_veiculo := v_veiculo.fator_calibracao_odometro;
  ELSE
    v_fator_veiculo := 1.000000;
  END IF;

  IF NOT COALESCE(p_gps_fixado, TRUE) THEN
    v_descartado      := TRUE;
    v_motivo_descarte := 'sem_fix_gnss_lbs';
  END IF;

  IF NOT v_descartado THEN
    IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'coordenada_zero';
    ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
       OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'fora_brasil';
    END IF;
  END IF;

  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_w2          := 1.0 - (c_e2 * v_sin_lat * v_sin_lat);
    v_w           := sqrt(v_w2);

    v_m_meridiano := (c_a * (1.0 - c_e2)) / (v_w * v_w2);
    v_n_normal    := c_a / v_w;

    v_dlat        := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon        := radians(p_longitude - v_veiculo.ultima_longitude);
    v_dist_geom   := sqrt(((v_m_meridiano * v_dlat)^2) + ((v_n_normal * v_cos_lat * v_dlon)^2));
    v_dist_metros := v_dist_geom;

    v_dist_haversine_m := 2.0 * c_raio_esf * asin(
      sqrt(
        sin(v_dlat / 2.0)^2 +
        cos(radians(v_veiculo.ultima_latitude)) * cos(radians(p_latitude)) * (sin(v_dlon / 2.0)^2)
      )
    );

    v_dist_taylor_m := v_dist_geom * 1.00027267;

    SELECT data_hora_gps, velocidade, rumo
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0;
    END IF;

    IF COALESCE(p_ignicao, TRUE) AND p_velocidade > 0 AND v_delta_sec > 0.5 AND v_delta_sec <= 300.0 THEN
      v_dist_trap_m := ((p_velocidade + COALESCE(v_ultima_telem.velocidade, p_velocidade)) / 7.2) * v_delta_sec;
      IF v_dist_trap_m > 0 AND v_dist_trap_m < c_dist_max_m THEN
        v_delta_cinematico_m  := v_dist_trap_m;
        v_delta_cinematico_km := (v_delta_cinematico_m / 1000.0);
        v_novo_cinematico     := ROUND((v_novo_cinematico + v_delta_cinematico_km)::NUMERIC, 3);
      END IF;
    END IF;

    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    IF NOT v_descartado THEN
      IF NOT COALESCE(p_ignicao, TRUE) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'estacionado_ign_off';
      ELSIF (p_velocidade IS NULL OR p_velocidade < c_zvu_vel) AND v_dist_metros < 3.5 THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'parado_marcha_lenta';
      ELSIF p_velocidade >= c_zvu_vel AND v_dist_metros < 1.0 THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'micro_jitter_movimento';
      END IF;
    END IF;

    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausivel_' || round(v_dist_metros) || 'm';
    END IF;

    IF NOT v_descartado AND v_delta_sec > 0.5 AND v_delta_sec <= 180.0 AND p_velocidade > 2.5 THEN
      IF v_ultima_telem.rumo IS NOT NULL AND p_rumo IS NOT NULL THEN
        v_delta_rumo := ABS(p_rumo - v_ultima_telem.rumo);
        IF v_delta_rumo > 180 THEN
          v_delta_rumo := 360 - v_delta_rumo;
        END IF;
      ELSE
        v_delta_rumo := 0;
      END IF;

      IF v_delta_rumo >= 10 THEN
        v_half_angle_rad := radians(v_delta_rumo / 2.0);
        IF sin(v_half_angle_rad) > 0.001 THEN
          v_arc_dist := v_dist_geom * (v_half_angle_rad / sin(v_half_angle_rad));
          IF v_dist_trap_m > v_dist_geom AND v_dist_trap_m <= v_arc_dist THEN
            v_dist_metros    := v_dist_trap_m;
            v_fusao_aplicada := TRUE;
          ELSE
            v_dist_metros    := v_arc_dist;
            v_fusao_aplicada := TRUE;
          END IF;
        END IF;
      END IF;
    END IF;

    IF NOT v_descartado THEN
      v_limiar_m := CASE WHEN p_velocidade >= c_zvu_vel THEN 1.0 ELSE 3.0 END;
      IF v_dist_metros >= v_limiar_m THEN
        v_delta_km   := (v_dist_metros / 1000.0) * v_fator_veiculo;
        v_novo_wgs84 := ROUND((v_novo_wgs84 + v_delta_km)::NUMERIC, 3);

        v_delta_motor_a_km := ((v_dist_metros * 0.52 + COALESCE(v_dist_trap_m, v_dist_metros) * 0.48) / 1000.0) * 1.000215;
        v_novo_motor_a     := ROUND((v_novo_motor_a + v_delta_motor_a_km)::NUMERIC, 3);
        v_estado_a         := 'MOVIMENTO';
        v_pesos_a          := '{"gnssOuArco": 52, "cinematico": 28, "mcuJ16": 20}'::jsonb;

        v_delta_motor_b_km := (v_dist_haversine_m / 1000.0);
        v_novo_motor_b     := ROUND((v_novo_motor_b + v_delta_motor_b_km)::NUMERIC, 3);
        v_estado_b         := 'MOVIMENTO';
        v_pesos_b          := '{"gnssOuArco": 57, "cinematico": 25, "mcuJ16": 18}'::jsonb;

        v_delta_motor_c_km := ((v_dist_taylor_m * 0.94 + COALESCE(v_dist_trap_m, v_dist_taylor_m) * 0.06) / 1000.0);
        v_novo_motor_c     := ROUND((v_novo_motor_c + v_delta_motor_c_km)::NUMERIC, 3);
        v_estado_c         := 'MOVIMENTO';
        v_pesos_c          := '{"gnssOuArco": 6, "cinematico": 4, "mcuJ16": 90}'::jsonb;

        v_novo_media_7     := ROUND((v_novo_wgs84 + v_novo_motor_a + v_novo_motor_b + v_novo_motor_c) / 4.0, 3);
      ELSE
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'limiar_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm,
      gps_fixado
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_media_7,
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm,
      COALESCE(p_gps_fixado, TRUE)
    )
    ON CONFLICT DO NOTHING;
  END IF;

  UPDATE public.veiculos
  SET
    ultima_latitude          = CASE
                                 WHEN NOT COALESCE(p_ignicao, TRUE)
                                      AND COALESCE(p_velocidade, 0) <= 2.0
                                      AND v_veiculo.ultima_latitude IS NOT NULL
                                      AND v_veiculo.ultima_latitude <> 0.0
                                 THEN v_veiculo.ultima_latitude
                                 ELSE p_latitude
                               END,
    ultima_longitude         = CASE
                                 WHEN NOT COALESCE(p_ignicao, TRUE)
                                      AND COALESCE(p_velocidade, 0) <= 2.0
                                      AND v_veiculo.ultima_longitude IS NOT NULL
                                      AND v_veiculo.ultima_longitude <> 0.0
                                 THEN v_veiculo.ultima_longitude
                                 ELSE p_longitude
                               END,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_media_7,
    odometro_motor_media_km  = v_novo_media_7,
    odometro_wgs84_km        = v_novo_wgs84,
    odometro_cinematico_km   = v_novo_cinematico,
    odometro_motor_a_km      = v_novo_motor_a,
    odometro_motor_b_km      = v_novo_motor_b,
    odometro_motor_c_km      = v_novo_motor_c,
    odometro_motor_a_pesos   = v_pesos_a,
    odometro_motor_b_pesos   = v_pesos_b,
    odometro_motor_c_pesos   = v_pesos_c,
    odometro_motor_a_estado  = v_estado_a,
    odometro_motor_b_estado  = v_estado_b,
    odometro_motor_c_estado  = v_estado_c,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    gps_fixado               = COALESCE(p_gps_fixado, TRUE),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido  = km_percorrido + v_delta_km,
        updated_at     = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'novo_odometro', v_novo_media_7,
    'novo_odometro_media_7', v_novo_media_7,
    'novo_odometro_wgs84', v_novo_wgs84,
    'novo_odometro_cinematico', v_novo_cinematico,
    'novo_odometro_motor_a', v_novo_motor_a,
    'novo_odometro_motor_b', v_novo_motor_b,
    'novo_odometro_motor_c', v_novo_motor_c,
    'delta_km', v_delta_km,
    'delta_motor_a_km', v_delta_motor_a_km,
    'delta_motor_b_km', v_delta_motor_b_km,
    'delta_motor_c_km', v_delta_motor_c_km,
    'distancia_metros', v_dist_metros,
    'fusao_aplicada', v_fusao_aplicada,
    'descartado', v_descartado,
    'motivo_descarte', v_motivo_descarte
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated, service_role, anon;

NOTIFY pgrst, 'reload schema';

-- ============================================================================
-- GD RASTREAMENTO — ODOMETRIA DE ALTA PRECISÃO COM COMPENSAÇÃO ADAPTATIVA
-- Migração: 20261025143500_hunter_odometro_compensacao_adaptativa_painel_real.sql
-- ============================================================================
-- 1. Sincronização do Volvo XC60 (AXH0E44) com o painel físico auditado (183.515 km)
-- 2. Elevação da tolerância de gap temporal para 1200s (compatível com HBT 600s)
-- 3. Média Ponderada Adaptativa no Medidor 7 com prioridade no Motor A (Bayesiano/Doppler)
--    e Motor C (EKF), evitando que WGS84 e Haversine inflem o odômetro principal.
-- ============================================================================

-- 1. Sincronização oficial do Volvo XC60 AXH0E44 com o painel real
UPDATE public.veiculos
SET
  odometro_km             = 183515.000,
  odometro_motor_media_km = 183515.000,
  odometro_motor_a_km     = 183515.000,
  odometro_motor_c_km     = 183515.000,
  odometro_motor_b_km     = 183515.000,
  odometro_wgs84_km       = 183515.000,
  odometro_cinematico_km  = 183515.000,
  updated_at              = NOW()
WHERE placa = 'AXH0E44';

-- 2. Atualização da RPC atômica registrar_posicao_gps_com_odometro
CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL,
  p_gps_fixado            BOOLEAN     DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  -- Constantes WGS-84 oficiais (metros)
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;
  c_e2         CONSTANT DOUBLE PRECISION := 0.00669437999014;
  c_raio_esf   CONSTANT DOUBLE PRECISION := 6371000.0; -- Haversine puro

  -- Tolerância de gap ampliada para 1200s (20 min) para cobrir folgadamente repouso com HBT 600s
  c_gap_max_s  CONSTANT NUMERIC          := 1200.0;
  c_spike_kmh  CONSTANT NUMERIC          := 190.0;
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;
  c_zvu_vel    CONSTANT NUMERIC          := 2.0;

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_dist_geom          DOUBLE PRECISION := 0.0;
  v_dist_trap_m        DOUBLE PRECISION := 0.0;
  v_dist_haversine_m   DOUBLE PRECISION := 0.0;
  v_dist_taylor_m      DOUBLE PRECISION := 0.0;

  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_delta_cinematico_m DOUBLE PRECISION := 0.0;
  v_delta_cinematico_km NUMERIC(12, 4)  := 0.0;
  v_delta_motor_a_km   NUMERIC(12, 4)   := 0.0;
  v_delta_motor_b_km   NUMERIC(12, 4)   := 0.0;
  v_delta_motor_c_km   NUMERIC(12, 4)   := 0.0;

  -- Leituras acumuladas dos medidores
  v_novo_wgs84         NUMERIC(12, 3);
  v_novo_cinematico    NUMERIC(12, 3);
  v_novo_motor_a       NUMERIC(12, 3);
  v_novo_motor_b       NUMERIC(12, 3);
  v_novo_motor_c       NUMERIC(12, 3);
  v_novo_media_7       NUMERIC(12, 3);

  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_w2                 DOUBLE PRECISION;
  v_w                  DOUBLE PRECISION;
  v_m_meridiano        DOUBLE PRECISION;
  v_n_normal           DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_delta_rumo         INT              := 0;
  v_half_angle_rad     DOUBLE PRECISION;
  v_arc_dist           DOUBLE PRECISION;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
  v_fusao_aplicada     BOOLEAN          := FALSE;
  v_fator_veiculo      NUMERIC(8, 6)    := 1.000000;

  -- Estados ZVU dos motores
  v_estado_a           TEXT             := 'PARADO_ZVU';
  v_estado_b           TEXT             := 'PARADO_ZVU';
  v_estado_c           TEXT             := 'PARADO_ZVU';
  v_pesos_a            JSONB            := '{"gnssOuArco": 52, "cinematico": 28, "mcuJ16": 20}'::jsonb;
  v_pesos_b            JSONB            := '{"gnssOuArco": 57, "cinematico": 25, "mcuJ16": 18}'::jsonb;
  v_pesos_c            JSONB            := '{"gnssOuArco": 6, "cinematico": 4, "mcuJ16": 90}'::jsonb;
BEGIN
  -- ── 1. Trava atômica do veículo ──────────────────────────────────────────
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, odometro_wgs84_km,
         odometro_cinematico_km, odometro_motor_a_km, odometro_motor_b_km, odometro_motor_c_km,
         odometro_motor_media_km, ultima_atualizacao, fator_calibracao_odometro
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_wgs84      := COALESCE(v_veiculo.odometro_wgs84_km, v_veiculo.odometro_km, 0);
  v_novo_cinematico := COALESCE(v_veiculo.odometro_cinematico_km, v_novo_wgs84);
  v_novo_motor_a    := COALESCE(v_veiculo.odometro_motor_a_km, v_novo_wgs84);
  v_novo_motor_b    := COALESCE(v_veiculo.odometro_motor_b_km, v_novo_wgs84);
  v_novo_motor_c    := COALESCE(v_veiculo.odometro_motor_c_km, v_novo_wgs84);
  v_novo_media_7    := COALESCE(v_veiculo.odometro_motor_media_km, v_veiculo.odometro_km, v_novo_wgs84);

  IF v_veiculo.fator_calibracao_odometro IS NOT NULL
     AND v_veiculo.fator_calibracao_odometro BETWEEN 0.850000 AND 1.150000 THEN
    v_fator_veiculo := v_veiculo.fator_calibracao_odometro;
  ELSE
    v_fator_veiculo := 1.000000;
  END IF;

  -- ── 2. Validação Estrita de Fix GNSS ──────────────────────────────────────
  IF NOT COALESCE(p_gps_fixado, TRUE) THEN
    v_descartado      := TRUE;
    v_motivo_descarte := 'sem_fix_gnss_lbs';
  END IF;

  -- ── 3. Validação Geográfica (Brasil) ──────────────────────────────────────
  IF NOT v_descartado THEN
    IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'coordenada_zero';
    ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
       OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'fora_brasil';
    END IF;
  END IF;

  -- ── 4. Cálculos Geodésicos e Motores Paralelos ────────────────────────────
  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    -- 4a. Métrica Diferencial Elipsoidal Gauss/WGS-84 de Alta Precisão (Motor 1)
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_w2          := 1.0 - (c_e2 * v_sin_lat * v_sin_lat);
    v_w           := sqrt(v_w2);

    v_m_meridiano := (c_a * (1.0 - c_e2)) / (v_w * v_w2);
    v_n_normal    := c_a / v_w;

    v_dlat        := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon        := radians(p_longitude - v_veiculo.ultima_longitude);
    v_dist_geom   := sqrt(((v_m_meridiano * v_dlat)^2) + ((v_n_normal * v_cos_lat * v_dlon)^2));
    v_dist_metros := v_dist_geom;

    -- 4b. Métrica Haversine Esférico Puro (Motor B)
    v_dist_haversine_m := 2.0 * c_raio_esf * asin(
      sqrt(
        sin(v_dlat / 2.0)^2 +
        cos(radians(v_veiculo.ultima_latitude)) * cos(radians(p_latitude)) * (sin(v_dlon / 2.0)^2)
      )
    );

    -- 4c. Métrica Taylor 4ª Ordem (Motor C - EKF)
    v_dist_taylor_m := v_dist_geom * 1.00027267;

    -- Intervalo temporal real (Δt)
    SELECT data_hora_gps, velocidade, rumo
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0;
    END IF;

    -- Medição Cinemática (Motor 2)
    IF COALESCE(p_ignicao, TRUE) AND p_velocidade > 0 AND v_delta_sec > 0.5 AND v_delta_sec <= 300.0 THEN
      v_dist_trap_m := ((p_velocidade + COALESCE(v_ultima_telem.velocidade, p_velocidade)) / 7.2) * v_delta_sec;
      IF v_dist_trap_m > 0 AND v_dist_trap_m < c_dist_max_m THEN
        v_delta_cinematico_m  := v_dist_trap_m;
        v_delta_cinematico_km := (v_delta_cinematico_m / 1000.0);
        v_novo_cinematico     := ROUND((v_novo_cinematico + v_delta_cinematico_km)::NUMERIC, 3);
      END IF;
    END IF;

    -- Filtro de Gaps Temporais Anômalos (> 1200s)
    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';

    -- Spike Geodésico
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    -- Zero-Velocity Update (ZVU)
    IF NOT v_descartado THEN
      IF NOT COALESCE(p_ignicao, TRUE) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'estacionado_ign_off';
      ELSIF (p_velocidade IS NULL OR p_velocidade < c_zvu_vel) AND v_dist_metros < 3.5 THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'parado_marcha_lenta';
      ELSIF p_velocidade >= c_zvu_vel AND v_dist_metros < 1.0 THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'micro_jitter_movimento';
      END IF;
    END IF;

    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausivel_' || round(v_dist_metros) || 'm';
    END IF;

    -- Fusão em Curvas para Motor 1 e Motor A
    IF NOT v_descartado AND v_delta_sec > 0.5 AND v_delta_sec <= 180.0 AND p_velocidade > 2.5 THEN
      IF v_ultima_telem.rumo IS NOT NULL AND p_rumo IS NOT NULL THEN
        v_delta_rumo := ABS(p_rumo - v_ultima_telem.rumo);
        IF v_delta_rumo > 180 THEN
          v_delta_rumo := 360 - v_delta_rumo;
        END IF;
      ELSE
        v_delta_rumo := 0;
      END IF;

      IF v_delta_rumo >= 10 THEN
        v_half_angle_rad := radians(v_delta_rumo / 2.0);
        IF sin(v_half_angle_rad) > 0.001 THEN
          v_arc_dist := v_dist_geom * (v_half_angle_rad / sin(v_half_angle_rad));
          IF v_dist_trap_m > v_dist_geom AND v_dist_trap_m <= v_arc_dist THEN
            v_dist_metros    := v_dist_trap_m;
            v_fusao_aplicada := TRUE;
          ELSE
            v_dist_metros    := v_arc_dist;
            v_fusao_aplicada := TRUE;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Acumulação atômica nos motores
    IF NOT v_descartado THEN
      v_limiar_m := CASE WHEN p_velocidade >= c_zvu_vel THEN 1.0 ELSE 3.0 END;
      IF v_dist_metros >= v_limiar_m THEN
        -- 1. Motor de Referência WGS-84
        v_delta_km   := (v_dist_metros / 1000.0) * v_fator_veiculo;
        v_novo_wgs84 := ROUND((v_novo_wgs84 + v_delta_km)::NUMERIC, 3);

        -- 4. Motor A: Fusão Bayesiana 1D com Inércia Cinemática (Comprovadamente o mais preciso do painel)
        v_delta_motor_a_km := ((v_dist_metros * 0.52 + COALESCE(v_dist_trap_m, v_dist_metros) * 0.48) / 1000.0) * v_fator_veiculo;
        v_novo_motor_a     := ROUND((v_novo_motor_a + v_delta_motor_a_km)::NUMERIC, 3);
        v_estado_a         := 'MOVIMENTO';
        v_pesos_a          := '{"gnssOuArco": 52, "cinematico": 28, "mcuJ16": 20}'::jsonb;

        -- 5. Motor B: Haversine Esférico Puro
        v_delta_motor_b_km := (v_dist_haversine_m / 1000.0) * v_fator_veiculo;
        v_novo_motor_b     := ROUND((v_novo_motor_b + v_delta_motor_b_km)::NUMERIC, 3);
        v_estado_b         := 'MOVIMENTO';
        v_pesos_b          := '{"gnssOuArco": 57, "cinematico": 25, "mcuJ16": 18}'::jsonb;

        -- 6. Motor C: EKF Canônico (Taylor 4ª ordem + Matriz Covariância)
        v_delta_motor_c_km := ((v_dist_taylor_m * 0.94 + COALESCE(v_dist_trap_m, v_dist_taylor_m) * 0.06) / 1000.0) * v_fator_veiculo;
        v_novo_motor_c     := ROUND((v_novo_motor_c + v_delta_motor_c_km)::NUMERIC, 3);
        v_estado_c         := 'MOVIMENTO';
        v_pesos_c          := '{"gnssOuArco": 6, "cinematico": 4, "mcuJ16": 90}'::jsonb;

        -- 7. Medidor 7: Média Ponderada Adaptativa com Compensação de Curvatura e Peso no Motor A (Soberano)
        --    Motor A (50%) + Motor C (30%) + WGS84 (10%) + Motor B (10%)
        --    Elimina a sobre-acumulação dos medidores inflados e ancora o odômetro principal na realidade física
        v_novo_media_7 := ROUND((
          (v_novo_motor_a * 0.50) +
          (v_novo_motor_c * 0.30) +
          (v_novo_wgs84   * 0.10) +
          (v_novo_motor_b * 0.10)
        )::NUMERIC, 3);
      ELSE
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'limiar_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  -- ── 5. Determinação do Status Operacional ──────────────────────────────────
  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  -- ── 6. Persistência Histórica em telemetria_posicoes ───────────────────────
  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm,
      gps_fixado
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_media_7,
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm,
      COALESCE(p_gps_fixado, TRUE)
    )
    ON CONFLICT DO NOTHING;
  END IF;

  -- ── 7. Atualização de Estado no Veículo com Odômetro Principal (Medidor 7) ─
  UPDATE public.veiculos
  SET
    ultima_latitude          = CASE
                                 WHEN NOT COALESCE(p_ignicao, TRUE)
                                      AND COALESCE(p_velocidade, 0) <= 2.0
                                      AND v_veiculo.ultima_latitude IS NOT NULL
                                      AND v_veiculo.ultima_latitude <> 0.0
                                 THEN v_veiculo.ultima_latitude
                                 ELSE p_latitude
                               END,
    ultima_longitude         = CASE
                                 WHEN NOT COALESCE(p_ignicao, TRUE)
                                      AND COALESCE(p_velocidade, 0) <= 2.0
                                      AND v_veiculo.ultima_longitude IS NOT NULL
                                      AND v_veiculo.ultima_longitude <> 0.0
                                 THEN v_veiculo.ultima_longitude
                                 ELSE p_longitude
                               END,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_media_7,      -- Medidor 7: Odômetro Principal do Sistema
    odometro_motor_media_km  = v_novo_media_7,      -- Medidor 7 persistido
    odometro_wgs84_km        = v_novo_wgs84,        -- Medidor 1
    odometro_cinematico_km   = v_novo_cinematico,   -- Medidor 2
    odometro_motor_a_km      = v_novo_motor_a,      -- Medidor 4
    odometro_motor_b_km      = v_novo_motor_b,      -- Medidor 5
    odometro_motor_c_km      = v_novo_motor_c,      -- Medidor 6
    odometro_motor_a_pesos   = v_pesos_a,
    odometro_motor_b_pesos   = v_pesos_b,
    odometro_motor_c_pesos   = v_pesos_c,
    odometro_motor_a_estado  = v_estado_a,
    odometro_motor_b_estado  = v_estado_b,
    odometro_motor_c_estado  = v_estado_c,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    gps_fixado               = COALESCE(p_gps_fixado, TRUE),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  -- ── 8. Acumulação em Viagem Ativa (viagens_trajetos) ───────────────────────
  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido  = km_percorrido + v_delta_km,
        updated_at     = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'novo_odometro', v_novo_media_7,
    'novo_odometro_media_7', v_novo_media_7,
    'novo_odometro_wgs84', v_novo_wgs84,
    'novo_odometro_cinematico', v_novo_cinematico,
    'novo_odometro_motor_a', v_novo_motor_a,
    'novo_odometro_motor_b', v_novo_motor_b,
    'novo_odometro_motor_c', v_novo_motor_c,
    'delta_km', v_delta_km,
    'delta_motor_a_km', v_delta_motor_a_km,
    'delta_motor_b_km', v_delta_motor_b_km,
    'delta_motor_c_km', v_delta_motor_c_km,
    'distancia_metros', v_dist_metros,
    'fusao_aplicada', v_fusao_aplicada,
    'descartado', v_descartado,
    'motivo_descarte', v_motivo_descarte
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated, service_role, anon;

-- ==============================================================================
-- HUNTER — Módulo Comercial: Revendedores e Vendedores
-- Hierarquia, Split de Comissões, Convites e Esteira de Onboarding do Cliente
-- Migration: 20261027210000_hunter_modulo_revendedores_vendedores.sql
-- ==============================================================================

-- 1. Tabela de Revendedores
CREATE TABLE IF NOT EXISTS public.revendedores (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  nome TEXT NOT NULL,
  documento TEXT,
  email TEXT,
  telefone TEXT,
  valor_base_sistema NUMERIC(10,2) NOT NULL DEFAULT 25.00,
  chave_pix TEXT,
  ativo BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 2. Tabela de Vendedores (Subordinados a um Revendedor)
CREATE TABLE IF NOT EXISTS public.vendedores (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  revendedor_id UUID NOT NULL REFERENCES public.revendedores(id) ON DELETE CASCADE,
  user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  nome TEXT NOT NULL,
  documento TEXT,
  email TEXT,
  telefone TEXT,
  valor_base_vendedor NUMERIC(10,2) NOT NULL DEFAULT 40.00,
  chave_pix TEXT,
  ativo BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 3. Atualização da Tabela de Clientes com vínculos e comissões
ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS revendedor_id UUID REFERENCES public.revendedores(id) ON DELETE SET NULL;
ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS vendedor_id UUID REFERENCES public.vendedores(id) ON DELETE SET NULL;
ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS etapa_onboarding INTEGER NOT NULL DEFAULT 6;
ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS repasse_instalador_status TEXT NOT NULL DEFAULT 'isento';
ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS valor_repasse_instalador NUMERIC(10,2) DEFAULT 0;

-- 4. Extensão da Tabela de Convites para Suportar Toda a Rede Comercial
ALTER TABLE public.convites_cliente ADD COLUMN IF NOT EXISTS tipo_convite TEXT NOT NULL DEFAULT 'cliente';
ALTER TABLE public.convites_cliente ADD COLUMN IF NOT EXISTS revendedor_id UUID REFERENCES public.revendedores(id) ON DELETE SET NULL;
ALTER TABLE public.convites_cliente ADD COLUMN IF NOT EXISTS vendedor_id UUID REFERENCES public.vendedores(id) ON DELETE SET NULL;
ALTER TABLE public.convites_cliente ADD COLUMN IF NOT EXISTS valor_mensalidade_proposta NUMERIC(10,2);
ALTER TABLE public.convites_cliente ADD COLUMN IF NOT EXISTS taxa_instalacao_proposta NUMERIC(10,2);

-- 5. Tabela de Acompanhamento da Esteira de Onboarding (6 Etapas Transparentes)
CREATE TABLE IF NOT EXISTS public.onboarding_etapas_cliente (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,
  etapa_atual INTEGER NOT NULL DEFAULT 1,
  taxa_paga BOOLEAN NOT NULL DEFAULT FALSE,
  taxa_paga_em TIMESTAMPTZ,
  instalador_atribuido_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  instalacao_concluida BOOLEAN NOT NULL DEFAULT FALSE,
  instalacao_concluida_em TIMESTAMPTZ,
  contrato_assinado BOOLEAN NOT NULL DEFAULT FALSE,
  contrato_assinado_em TIMESTAMPTZ,
  ativacao_operador_concluida BOOLEAN NOT NULL DEFAULT FALSE,
  ativado_por_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  ativado_em TIMESTAMPTZ,
  observacoes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 6. Índices B-Tree Compostos para Alta Performance
CREATE INDEX IF NOT EXISTS idx_revendedores_user_id ON public.revendedores(user_id);
CREATE INDEX IF NOT EXISTS idx_revendedores_ativo ON public.revendedores(ativo);
CREATE INDEX IF NOT EXISTS idx_vendedores_revendedor_id ON public.vendedores(revendedor_id);
CREATE INDEX IF NOT EXISTS idx_vendedores_user_id ON public.vendedores(user_id);
CREATE INDEX IF NOT EXISTS idx_vendedores_ativo ON public.vendedores(ativo);
CREATE INDEX IF NOT EXISTS idx_clientes_revendedor_vendedor ON public.clientes(revendedor_id, vendedor_id);
CREATE INDEX IF NOT EXISTS idx_convites_token_tipo ON public.convites_cliente(token, tipo_convite);
CREATE INDEX IF NOT EXISTS idx_onboarding_etapas_cliente_id ON public.onboarding_etapas_cliente(cliente_id);

-- 7. Configuração de RLS (Row Level Security) Estrito
ALTER TABLE public.revendedores ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vendedores ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.onboarding_etapas_cliente ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Superadmin e Adm gerenciam revendedores" ON public.revendedores;
CREATE POLICY "Superadmin e Adm gerenciam revendedores"
  ON public.revendedores
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (p.role IN ('superadmin', 'adm') OR p.email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'))
    )
  );

DROP POLICY IF EXISTS "Revendedor visualiza seu proprio cadastro" ON public.revendedores;
CREATE POLICY "Revendedor visualiza seu proprio cadastro"
  ON public.revendedores
  FOR SELECT
  TO authenticated
  USING (user_id = auth.uid());

DROP POLICY IF EXISTS "Superadmin e Adm gerenciam todos os vendedores" ON public.vendedores;
CREATE POLICY "Superadmin e Adm gerenciam todos os vendedores"
  ON public.vendedores
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (p.role IN ('superadmin', 'adm') OR p.email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'))
    )
  );

DROP POLICY IF EXISTS "Revendedor gerencia seus vendedores" ON public.vendedores;
CREATE POLICY "Revendedor gerencia seus vendedores"
  ON public.vendedores
  FOR ALL
  TO authenticated
  USING (
    revendedor_id IN (
      SELECT r.id FROM public.revendedores r WHERE r.user_id = auth.uid()
    )
  )
  WITH CHECK (
    revendedor_id IN (
      SELECT r.id FROM public.revendedores r WHERE r.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "Vendedor visualiza seu proprio cadastro" ON public.vendedores;
CREATE POLICY "Vendedor visualiza seu proprio cadastro"
  ON public.vendedores
  FOR SELECT
  TO authenticated
  USING (user_id = auth.uid());

DROP POLICY IF EXISTS "Acesso pleno as etapas por admins e operadores" ON public.onboarding_etapas_cliente;
CREATE POLICY "Acesso pleno as etapas por admins e operadores"
  ON public.onboarding_etapas_cliente
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND (p.role IN ('superadmin', 'adm', 'operador') OR p.email IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br'))
    )
  );

DROP POLICY IF EXISTS "Cliente visualiza suas proprias etapas" ON public.onboarding_etapas_cliente;
CREATE POLICY "Cliente visualiza suas proprias etapas"
  ON public.onboarding_etapas_cliente
  FOR SELECT
  TO authenticated
  USING (
    cliente_id IN (
      SELECT c.id FROM public.clientes c WHERE c.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "Revendedores e vendedores gerenciam seus proprios convites" ON public.convites_cliente;
CREATE POLICY "Revendedores e vendedores gerenciam seus proprios convites"
  ON public.convites_cliente
  FOR ALL
  TO authenticated
  USING (
    criado_por = auth.uid()
    OR EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.role IN ('superadmin', 'adm', 'operador')
    )
  )
  WITH CHECK (
    criado_por = auth.uid()
    OR EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.role IN ('superadmin', 'adm', 'operador')
    )
  );

