  ON public.convites_cliente
  FOR ALL
  TO authenticated
  USING (
    criado_por = auth.uid()
    OR revendedor_id IN (SELECT id FROM public.revendedores WHERE user_id = auth.uid())
    OR vendedor_id IN (SELECT id FROM public.vendedores WHERE user_id = auth.uid())
  )
  WITH CHECK (
    criado_por = auth.uid()
    OR revendedor_id IN (SELECT id FROM public.revendedores WHERE user_id = auth.uid())
    OR vendedor_id IN (SELECT id FROM public.vendedores WHERE user_id = auth.uid())
  );

