    dre_whatsapp_horario = COALESCE(NULLIF(TRIM(p_horario), ''), '09:00'),
    dre_whatsapp_telefone = TRIM(p_telefone),
    updated_at = NOW()
  WHERE id = v_rev_id;

  RETURN jsonb_build_object('sucesso', true);
END;
$$;

